(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["\u0625"] = {"atoms": {"إ.ت.1": {"x": [[135, "كتاب الإبانة عن أصول الديانة\rللشيخ العلامة\rأبي الحسن علي بن إسماعيل الأشعري رحمه الله"], [137, "بسم الله الرّحمن الرّحيم\rقال السيد الإمام أبو الحسن علي بن إسماعيل الأشعري البصري رحمه الله: الحمد لله الواحد، العزيز الماجد، المتفرد بالتوحيد، والمتمجد بالتمجيد، الذي لا تبلغه صفات العبيد، ليس له منازع ولا نديد، وهو المبدئ والمعيد، الفعال لما يريد، جل عن اتخاذ الصواحب والأولاد، وتقدس عن ملابسة الأجناس والأرجاس، ليست له صورة تقال، ولا حد يضرب له المثال، لم يزل بصفاته أولا قديرا، ولا يزال عالما خبيرا، استوفى الأشياء علمه، ونفذت فيها إرادته، ولم تعزب عنه خفيات الأمور، ولم تغيره سوالف صروف الدهور، ولم يلحقه في خلق شيء مما خلق كلال ولا تعب، ولا مسه لغوب ولا نصب، خلق الأشياء بقدرته، ودبرها بمشيئته، وقهرها بجبروته، وذللها بعزته، فذل لعظمته المتكبرون، واستكان لعز ربوبيته المتعظمون، وانقطع دون الرسوخ في علمه العالمون، وذلت له الرقاب، وحارت في ملكوته فطن ذوي الألباب، وقامت بحكمته السموات السبع واستقرت الأرض المهاد، وثبتت الجبال الرواسي، وجرت الرياح اللواقح، وسار في جو السماء السحاب، وقامت على حدودها البحار، وهو الله الواحد القهار.\rفنحمده كما حمد نفسه وكما هو أهله ومستحقه، وكما حمده الحامدون من جميع خلقه.\rونستعينه استعانة من فوض أمره إليه، وأقر أنه لا منجأ ولا ملجأ منه إلا إليه، ونستغفره استغفار مقر بذنبه معترف بخطيئته.\rونشهد أن لا إله إلا الله وحده لا شريك له إقرارا بوحدانيته وإخلاصا لربوبيته، وأنه العالم بما تبطنه الضمائر وتنطوي عليه السرائر، وما تخفيه النفوس وما تجن البحار، وما تواري الأسراب، وما تغيض الأرحام وما تزداد، وكل شيء عنده بمقدار، لا توارى عنه كلمة ولا تغيب عنه غائبة، وما تسقط‍ من ورقة"], [138, "إلا يعلمها ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين، ويعلم ما يعمل العاملون وما ينقلب إليه المنقلبون، ونستهديه بالهدى ونسأله التوفيق لمجانبة الردى.\rونشهد أن محمدا صلّى الله عليه وسلّم عبده ورسوله ونبيه وأمينه وصفيه، أرسله إلى خلقه بالنور الساطع، والسراج اللامع، والحجج الظاهرة، والبراهين والآيات الباهرة، والأعاجيب القاهرة، فبلغ رسالة ربه ونصح لأمته، وجاهد في الله حق جهاده، حتى تمت كلمة الله عز وجل وظهر أمره، وانقاد الناس للحق خاضعين حتى أتاه اليقين، لا وانيا ولا مقصرا؛ فصلوات الله عليه من قائد إلى هدى مبين، وعلى أهل بيته الطيبين، وعلى أصحابه المنتخبين، وعلى أزواجه أمهات المؤمنين، عرفنا الله به الشرائع والأحكام، والحلال والحرام، وبيّن لنا به شريعة الإسلام حتى انجلت عنا طخياء الظلم، وانحسرت عنا به الشبهات، وانكشفت عنا به الغيابات، وظهرت لنا به البينات، جاءنا بكتاب عزيز لا يأتيه الباطل من بين يديه ولا من خلفه تنزيل من حكيم حميد، جمع فيه علم الأولين والآخرين، وأكمل به الفرائض والدين، فهو صراط‍ الله المستقيم وحبله المتين، فمن تمسك به نجا، ومن تخلف ضل وغوى، وفي الجهل تردى، وحث الله في كتابه على التمسك بسنة رسوله عليه السّلام فقال عز وجل: {وَما آتاكُمُ الرَّسُولُ فَخُذُوهُ وَما نَهاكُمْ عَنْهُ فَانْتَهُوا (1) و قال عز وجل: {فَلْيَحْذَرِ الَّذِينَ يُخالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذابٌ أَلِيمٌ} (2) و قال: {وَلَوْ رَدُّوهُ إِلَى الرَّسُولِ وَإِلى أُولِي الْأَمْرِ مِنْهُمْ لَعَلِمَهُ الَّذِينَ يَسْتَنْبِطُونَهُ مِنْهُمْ} (3) و قال: {فَإِنْ تَنازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ\r__________\r(1) الحشر: 7.\r(2) النور: 63.\r(3) النساء: 83."], [139, "إِلَى اللهِ وَالرَّسُولِ} (1) يقول: إلى كتاب الله وسنة نبيه، وقال: {وَما يَنْطِقُ عَنِ الْهَوى (3) إِنْ هُوَ إِلاّ وَحْيٌ يُوحى} وقال: {قُلْ ما يَكُونُ لِي أَنْ أُبَدِّلَهُ مِنْ تِلْقاءِ نَفْسِي إِنْ أَتَّبِعُ إِلاّ ما يُوحى إِلَيَّ} (2) و قال: {إِنَّما كانَ قَوْلَ الْمُؤْمِنِينَ إِذا دُعُوا إِلَى اللهِ وَرَسُولِهِ لِيَحْكُمَ بَيْنَهُمْ أَنْ يَقُولُوا سَمِعْنا وَأَطَعْنا} (3)، فأمرهم أن يسمعوا قوله ويطيعوا أمره ويحذروا مخالفته، وقال: {قُلْ أَطِيعُوا اللهَ وَأَطِيعُوا الرَّسُولَ} (4) فأمرهم بطاعة رسوله كما أمرهم بطاعته ودعاهم إلى التمسك بسنة نبيه كما أمرهم بالعمل بكتابه، فنبذ كثير ممن غلبت عليه شقوته واستحوذ عليهم الشيطان سنن نبي الله عليه السّلام وراء ظهورهم، ومالوا إلى أسلاف لهم قلدوهم دينهم ودانوا بديانتهم، وأبطلوا سنن نبي الله عليه السّلام ودفعوها وأنكروها وجحدوها افتراء منهم على الله، قد ضلوا وما كانوا مهتدين.\rأوصيكم عباد الله بتقوى الله عز وجل وأحذركم الدنيا فإنها حلوة خضرة تغر أهلها وتخدع ساكنها؛ قال الله تعالى: {وَاضْرِبْ لَهُمْ مَثَلَ الْحَياةِ الدُّنْيا كَماءٍ أَنْزَلْناهُ مِنَ السَّماءِ فَاخْتَلَطَ‍ بِهِ نَباتُ الْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ الرِّياحُ وَكانَ اللهُ عَلى كُلِّ شَيْءٍ مُقْتَدِرًا (45)} (5) من كان فيها في حبرة أعقبته بعدها عبرة، ومن أعطته من سرائها بطنا أعقبته من ضرائها ظهرا، غرارة غرور ما فيها؛ فانية فان ما عليها؛ كما حكم عليها ربها بقوله إذ يقول: {كُلُّ مَنْ عَلَيْها فانٍ} (6) فاعملوا رحمكم الله للحياة الدائمة ولخلود الأبد؛ فإن الدنيا تنقضي عن أهلها وتبقى\r__________\r(1) النساء: 59.\r(2) يونس: 15.\r(3) النور: 51.\r(4) النور: 54.\r(5) الكهف: 45.\r(6) الرحمن: 26."], [140, "الأعمال قلائد في رقاب أهلها.\rواعلموا أنكم ميتون ثم إنكم من بعد موتكم إلى ربكم راجعون: {لِيَجْزِيَ الَّذِينَ أَساؤُا بِما عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى} (1) فكونوا بطاعة ربكم عاملين وعما نهاكم عنه منتهين.\r***\r__________\r(1) النجم: 31."], [141, "باب في إبانة قول أهل الزيغ والبدعة\r"]], "pg": [135, 141]}, "إ.ت.2": {"x": [[141, "أما بعد: فإن كثيرا من الزائغين عن الحق من المعتزلة وأهل القدر مالت بهم أهواؤهم إلى تقليد رؤسائهم، ومن مضى من أسلافهم فتأولوا القرآن على آرائهم تأويلا لم ينزل الله به سلطانا، ولا أوضح به برهانا، ولا نقلوه عن رسول رب العالمين ولا عن السلف المتقدمين، وخالفوا روايات الصحابة عليهم السّلام عن نبي الله صلوات الله عليه في رؤية الله عز وجل بالأبصار، وقد جاءت في ذلك الروايات من الجهات المختلفات وتواترت بها الآثار وتتابعت بها الأخبار، وأنكروا شفاعة رسول الله صلّى الله عليه وسلّم للمذنبين، ودفعوا الروايات في ذلك عن المتقدمين، وجحدوا عذاب القبر وأن الكفار في قبورهم يعذبون، وقد أجمع على ذلك الصحابة والتابعون.\rوتكلموا بخلق القرآن نظيرا لقول إخوانهم من المشركين الذين قالوا: إن هذا إلا قول البشر، وأثبتوا أن العباد يخلقون الشر نظيرا لقول المجوس الذين أثبتوا خالقين: أحدهما يخلق الخير والآخر يخلق الشر.\rوزعمت القدرية أن الله عز وجل يخلق الخير والشيطان يخلق الشر، وزعموا أن الله عز وجل يشاء ما لا يكون، ويكون ما لا يشاء خلافا لما أجمع عليه المسلمون من أن ما شاء الله كان وما لم يشأ لم يكن، وردّا لقول الله عز وجل: {وَما تَشاؤُنَ إِلاّ أَنْ يَشاءَ اللهُ} (1) فأخبر أنا لا نشاء شيئا إلا وقد شاء الله أن نشاءه، ولقوله تعالى: {وَلَوْ شاءَ اللهُ مَا اقْتَتَلُوا} (2) ولقوله تعالى: {وَلَوْ شِئْنا لَآتَيْنا كُلَّ نَفْسٍ هُداها} (3) و لقوله تعالى: {فَعّالٌ لِما يُرِيدُ} (1) و لقوله تعالى مخبرا عن\r__________\r(1) الإنسان: 30.\r(2) البقرة: 253.\r(3) السجدة: 13."], [142, "شعيب أنه قال: {وَما يَكُونُ لَنا أَنْ نَعُودَ فِيها إِلاّ أَنْ يَشاءَ اللهُ رَبُّنا وَسِعَ رَبُّنا كُلَّ شَيْءٍ عِلْمًا} (2).\rولهذا سماهم رسول الله صلّى الله عليه وسلّم مجوس هذه الأمة (3) لأنهم دانوا بديانة المجوس وضاهوا أقاويلهم، وزعموا أن للخير والشر خالقين كما زعمت المجوس ذلك، وأنه يكون من الشرور ما لا يشاؤه الله كما قالت المجوس، وأنهم يملكون الضر والنفع لأنفسهم دون الله ردّا لقول الله عز وجل لنبيه عليه السّلام: قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعًا وَلا ضَرًّا إِلاّ ما شاءَ اللهُ (4) و إعراضا عن القرآن وعما أجمع عليه أهل الإسلام، وزعموا أنهم ينفردون بالقدرة على أعمالهم دون ربهم فأثبتوا لأنفسهم الغنى عن الله عز وجل ووصفوا أنفسهم بالقدرة على ما يصفون الله عز وجل بالقدرة عليه كما أثبتت المجوس للشيطان من القدرة على الشر ما لم يثبتوه لله عز وجل؛ فكانوا مجوس هذه الأمة؛ إذ دانوا بديانة المجوس وتمسكوا بأقاويلهم ومالوا إلى أضاليلهم وقنطوا الناس من رحمة الله، وأيسوهم من روحه.\rوحكموا على العصاة بالنار والخلود فيها خلافا لقول الله تعالى: {وَيَغْفِرُ ما دُونَ ذلِكَ لِمَنْ يَشاءُ} (5)، وزعموا أن من دخل النار لا يخرج منها خلافا لما جاءت به الرواية عن رسول الله صلّى الله عليه وسلّم أن الله عز وجل يخرج قوما من النار بعد أن\r__________\r=\r(1) البروج: 16.\r(2) الأعراف: 89.\r(3) أخرجه أبو داود ح (4691)، والحاكم في المستدرك ح (286) من حديث ابن عمر به، وقال الحاكم: «حديث صحيح على شرط‍ الشيخين إن صح سماع أبي حازم من ابن عمر، ولم يخرجاه». اه‍.\r(4) الأعراف: 188.\r(5) النساء: 48."], [143, "امتحشوا فيها وصاروا حمما (1).\rودفعوا أن يكون لله وجه مع قوله عز وجل: {وَيَبْقى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالْإِكْرامِ} (2)؛ وأنكروا أن يكون له يدان مع قوله: {لِما خَلَقْتُ بِيَدَيَّ} (3)؛ وأنكروا أن يكون له عينان مع قوله: {تَجْرِي بِأَعْيُنِنا} (4)؛ وأنكروا أن يكون لله علم مع قوله: {أَنْزَلَهُ بِعِلْمِهِ} (5)؛ وأنكروا أن يكون لله قوة مع قوله: {ذُو الْقُوَّةِ الْمَتِينُ} (6)؛ ونفوا ما روي عن النبي صلّى الله عليه وسلّم أن الله عز وجل ينزل كل ليلة إلى سماء الدنيا (7)، وغير ذلك مما رواه الثقات عن رسول الله صلّى الله عليه وسلّم، وكذلك جميع أهل البدع من الجهمية والمرجئة والحرورية أهل الزيغ فيما ابتدعوا خالفوا الكتاب والسنة، وما كان عليه النبي عليه السّلام وأصحابه، وأجمعت عليه الأمة كفعل المعتزلة والقدرية، وأنا ذاكر ذلك بابا بابا وشيئا شيئا، إن شاء الله وبه المعونة.\r***\r__________\r(1) أخرجه البخاري ح (6560)، ومسلم ح (184) من حديث أبي سعيد الخدري به.\r(2) الرحمن: 27.\r(3) ص: 75.\r(4) القمر: 14.\r(5) النساء: 166.\r(6) الذاريات: 58.\r(7) أخرجه البخاري ح (1145)، ومسلم ح (758) من حديث أبي هريرة به."], [144, "باب في إبانة قول أهل الحق والسنة\r"]], "pg": [141, 144]}, "إ.ت.3": {"x": [[144, "فإن قال لنا قائل: قد أنكرتم قول المعتزلة والقدرية والجهمية والحرورية والرافضة والمرجئة فعرفونا قولكم الذي به تقولون وديانتكم التي بها تدينون.\rقيل له: قولنا الذي نقول به وديانتنا التي ندين بها: التمسك بكتاب ربنا عز وجل وبسنة نبينا عليه السّلام وما روي عن الصحابة والتابعين وأئمة الحديث ونحن بذلك معتصمون؛ وبما كان يقول به أبو عبد الله أحمد بن محمد بن حنبل - نضر الله وجهه ورفع درجته وأجزل مثوبته - قائلون، ولمن خالف قوله مخالفون؛ لأنه الإمام الفاضل والرئيس الكامل الذي أبان الله به الحق ورفع به الضلال وأوضح به المنهاج وقمع به بدع المبتدعين وزيغ الزائغين وشك الشاكين؛ فرحمة الله عليه من إمام مقدم وخليل معظم مفخم.\rوجملة قولنا: إنا نقر بالله وملائكته وكتبه ورسله وبما جاءوا به من عند الله وما رواه الثقات عن رسول الله صلّى الله عليه وسلّم، لا نرد من ذلك شيئا، وأن الله عز وجل إله واحد لا إله إلا هو فرد صمد لم يتخذ صاحبة ولا ولدا، وأن محمدا عبده ورسوله أرسله بالهدى ودين الحق، وأن الجنة حق والنار حق، وأن الساعة آتية لا ريب فيها، وأن الله يبعث من في القبور، وأن الله مستو على عرشه كما قال: {الرَّحْمنُ عَلَى الْعَرْشِ اسْتَوى} (1) وأن له وجها كما قال: {وَيَبْقى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالْإِكْرامِ} (2) و أن له يدين بلا كيف كما قال: {خَلَقْتُ بِيَدَيَّ} (3) و كما قال: {بَلْ يَداهُ مَبْسُوطَتانِ} (4) و أن له عينا بلا كيف كما قال: {تَجْرِي\r__________\r(1) طه: 5.\r(2) الرحمن: 27.\r(3) ص: 75.\r(4) المائدة: 64."], [145, "بِأَعْيُنِنا} (1)، وأن من زعم أن أسماء الله غيره كان ضالاّ، وأن لله علما كما قال: {أَنْزَلَهُ بِعِلْمِهِ} (2) وكما قال: {وَما تَحْمِلُ مِنْ أُنْثى وَلا تَضَعُ إِلاّ بِعِلْمِهِ} (3)، ونثبت لله السمع والبصر ولا ننفي ذلك كما نفته المعتزلة والجهمية والخوارج، ونثبت أن لله قوة كما قال: {أَوَلَمْ يَرَوْا أَنَّ اللهَ الَّذِي خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً} (4).\rونقول: إن كلام الله غير مخلوق وإنه لم يخلق شيئا إلا وقد قال له: كن فيكون؛ كما قال: {إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} (5)، وأنه لا يكون في الأرض شيء من خير وشر إلا ما شاء الله، وأن الأشياء تكون بمشيئة الله عز وجل، وأن أحدا لا يستطيع أن يفعل شيئا قبل أن يفعله الله، ولا يستغني عن الله ولا يقدر على الخروج من علم الله عز وجل، وأنه لا خالق إلا الله، وأن أعمال العبد مخلوقة لله مقدرة كما قال: {وَاللهُ خَلَقَكُمْ وَما تَعْمَلُونَ} (6)، وأن العباد لا يقدرون أن يخلقوا شيئا وهم يخلقون كما قال: {هَلْ مِنْ خالِقٍ غَيْرُ اللهِ} (7) و كما قال: {لا يَخْلُقُونَ شَيْئًا وَهُمْ يُخْلَقُونَ} (8) و كما قال: {أَفَمَنْ يَخْلُقُ كَمَنْ لا يَخْلُقُ} (9) و كما قال: {أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ أَمْ هُمُ الْخالِقُونَ (35)} (10) و هذا في كتاب الله كثير.\r__________\r(1) القمر: 14.\r(2) النساء: 166.\r(3) فاطر: 11.\r(4) فصلت: 15.\r(5) النحل: 40.\r(6) الصافات: 96.\r(7) فاطر: 3.\r(8) النحل: 20.\r(9) النحل: 17.\r(10) الطور: 35."], [146, "وأن الله وفق المؤمنين لطاعته ولطف بهم ونظر إليهم وأصلحهم وهداهم، وأضل الكافرين ولم يهدهم ولم يلطف بهم بالإيمان كما زعم أهل الزيغ والطغيان، ولو لطف بهم وأصلحهم لكانوا صالحين ولو هداهم لكانوا مهتدين، وأن الله يقدر أن يصلح الكافرين ويلطف بهم حتى يكونوا مؤمنين ولكن أراد أن يكونوا كافرين كما علم وخذلهم وطبع على قلوبهم.\rوأن الخير والشر بقضاء الله وقدره وأنا نؤمن بقضاء الله وقدره خيره وشرّه، حلوه ومرّه، ونعلم أن ما أخطأنا لم يكن ليصيبنا وأن ما أصابنا لم يكن ليخطئنا، وأن العباد لا يملكون لأنفسهم ضرّا ولا نفعا إلا بالله كما قال عز وجل، ونلجئ أمورنا إلى الله ونثبت الحاجة والفقر في كل وقت إليه.\rونقول: إن كلام الله غير مخلوق وأن من قال بخلق القرآن فهو كافر، وندين بأن الله تعالى يرى في الآخرة بالأبصار كما يرى القمر ليلة البدر، يراه المؤمنون كما جاءت الروايات عن رسول الله صلّى الله عليه وسلّم (1)؛ ونقول: إن الكافرين محجوبون عنه إذا رآه المؤمنون في الجنة كما قال عز وجل: {كَلاّ إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ (2)، وأن موسى عليه السّلام سأل الله عز وجل الرؤية في الدنيا وأن الله سبحانه تجلى للجبل فجعله دكّا فأعلم بذلك موسى أنه لا يراه في الدنيا.\rوندين بأن لا نكفر أحدا من أهل القبلة بذنب يرتكبه كالزنا والسرقة وشرب الخمور كما دانت بذلك الخوارج وزعمت أنهم كافرون، ونقول: إن من عمل كبيرة من هذه الكبائر مثل الزنا والسرقة وما أشبههما مستحلاّ لها غير معتقد لتحريمها كان كافرا.\r__________\r(1) أخرجه البخاري ح (554)، ومسلم ح (633) من حديث جرير بن عبد الله به.\r(2) المطففين: 15."], [147, "ونقول: إن الإسلام أوسع من الإيمان وليس كل إسلام إيمانا، وندين بأن الله عز وجل يقلب القلوب بين إصبعين من أصابع الله عز وجل (1)، وأنه عز وجل يضع السموات على إصبع والأرضين على إصبع (2) كما جاءت الرواية عن رسول الله صلّى الله عليه وسلّم، وندين بأن لا ننزل أحدا من أهل التوحيد والمتمسكين بالإيمان جنة ولا نارا إلا من شهد له رسول الله صلّى الله عليه وسلّم بالجنة، ونرجو الجنة للمذنبين ونخاف عليهم أن يكونوا بالنار معذبين.\rونقول: إن الله عز وجل يخرج قوما من النار بعد أن امتحشوا بشفاعة رسول الله صلّى الله عليه وسلّم تصديقا لما جاءت به الروايات عن رسول الله صلّى الله عليه وسلّم (3)، ونؤمن بعذاب القبر وبالحوض، وأن الميزان حق، والصراط‍ حق، والبعث بعد الموت حق، وأن الله عز وجل يوقف العباد في الموقف ويحاسب المؤمنين، وأن الإيمان قول وعمل يزيد وينقص، ونسلم الروايات الصحيحة عن رسول الله صلّى الله عليه وسلّم رواها الثقات عدل عن عدل حتى ينتهي إلى رسول الله صلّى الله عليه وسلّم.\rوندين بحب السلف الذين اختارهم الله عز وجل لصحبة نبيه عليه السّلام، ونثني عليهم بما أثنى الله به عليهم، ونتولاهم أجمعين.\rونقول: إن الإمام الفاضل بعد رسول الله صلّى الله عليه وسلّم أبو بكر الصديق رضوان الله عليه، وأن الله أعز به الدين وأظهره على المرتدين، وقدمه المسلمون بالإمامة كما قدمه رسول الله صلّى الله عليه وسلّم للصلاة، وسموه بأجمعهم: خليفة رسول الله صلّى الله عليه وسلّم؛ ثم عمر بن الخطاب رضي الله عنه، ثم عثمان بن عفان رضي الله عنه، وأن الذين قاتلوه قاتلوه ظلما وعدوانا، ثم علي بن أبي طالب رضي الله عنه؛ فهؤلاء الأئمة بعد رسول الله صلّى الله عليه وسلّم،\r__________\r(1) أخرجه مسلم ح (2654) من حديث عبد الله بن عمرو بن العاص.\r(2) أخرجه البخاري ح (4811)، ومسلم ح (2786) من حديث عبد الله بن مسعود.\r(3) متفق عليه، وقد تقدم تخريجه."], [148, "وخلافتهم خلافة النبوة.\rونشهد بالجنة للعشرة الذين شهد لهم رسول الله صلّى الله عليه وسلّم بها، ونتولى سائر أصحاب النبي صلّى الله عليه وسلّم ونكف عما شجر بينهم، وندين الله بأن الأئمة الأربعة خلفاء راشدون مهديون، فضلاء لا يوازيهم في الفضل غيرهم.\rونصدق بجميع الروايات التي يثبتها أهل النقل من النزول إلى السماء الدنيا، وأن الرب عز وجل يقول: هل من سائل، هل من مستغفر (1)، وسائر ما نقلوه وأثبتوه خلافا لما قال أهل الزيغ والتضليل، ونعول فيما اختلفنا فيه على كتاب ربنا وسنة نبينا وإجماع المسلمين وما كان في معناه، ولا نبتدع في دين الله ما لم يأذن لنا، ولا نقول على الله ما لا نعلم.\rونقول: إن الله عز وجل يجيء يوم القيامة كما قال: {وَجاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا} (2) و أن الله عز وجل يقرب من عباده كيف شاء كما قال: {وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ} (3) و كما قال: {ثُمَّ دَنا فَتَدَلّى (8) فَكانَ قابَ قَوْسَيْنِ أَوْ أَدْنى} (4).\rومن ديننا أن نصلي الجمعة والأعياد وسائر الصلوات والجماعات خلف كل بر وغيره؛ كما روي أن عبد الله بن عمر كان يصلي خلف الحجاج.\rوأن المسح على الخفين سنة في الحضر والسفر خلافا لقول من أنكر ذلك.\rونرى الدعاء لأئمة المسلمين بالصلاح والإقرار بإمامتهم وتضليل من رأى الخروج عليهم إذا ظهر منهم ترك الاستقامة، وندين بإنكار الخروج عليهم بالسيف وترك القتال في الفتنة، ونقر بخروج الدجال كما جاءت به الرواية عن\r__________\r(1) متفق عليه، وقد تقدم تخريجه.\r(2) الفجر: 22.\r(3) ق: 16.\r(4) النجم: 8 - 9."], [149, "رسول الله صلّى الله عليه وسلّم (1).\rونؤمن بعذاب القبر ونكير ومنكر ومساءلتهما المدفونين بقبورهم؛ ونصدق بحديث المعراج، ونصحح كثيرا من الرؤيا في المنام، ونقر أن لذلك تفسيرا.\rونرى الصدقة عن موتى المسلمين والدعاء لهم، ونؤمن بأن الله ينفعهم بذلك.\rونصدق بأن في الدنيا سحرة وسحرا، وأن السحر كائن موجود في الدنيا.\rوندين بالصلاة على من مات من أهل القبلة برهم وفاجرهم وتوارثهم.\rونقر أن الجنة والنار مخلوقتان، وأن من مات أو قتل فبأجله مات أو قتل.\rوأن الأرزاق من قبل الله عز وجل يرزقها عباده حلالا وحراما.\rوأن الشيطان يوسوس للإنسان ويشككه ويتخبطه خلافا لقول المعتزلة والجهمية، كما قال الله عز وجل: {اَلَّذِينَ يَأْكُلُونَ الرِّبا لا يَقُومُونَ إِلاّ كَما يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطانُ مِنَ الْمَسِّ} (2) و كما قال: {مِنْ شَرِّ الْوَسْواسِ الْخَنّاسِ (4) اَلَّذِي يُوَسْوِسُ فِي صُدُورِ النّاسِ (5) مِنَ الْجِنَّةِ وَالنّاسِ (6)} (3).\rونقول: إن الصالحين يجوز أن يخصهم الله عز وجل بآيات يظهرها عليهم.\rوقولنا في أطفال المشركين: إن الله يؤجج لهم في الآخرة نارا ثم يقول لهم:\rاقتحموها كما جاءت بذلك الرواية.\rوندين الله عز وجل بأنه يعلم ما العباد عاملون وإلى ما هم صائرون، وما كان وما يكون وما لا يكون أن لو كان كيف كان يكون، وبطاعة الأئمة ونصيحة المسلمين.\rونرى مفارقة كل داعية إلى بدعة ومجانبة أهل الأهواء، وسنحتج لما ذكرناه من قولنا وما بقي منه مما لم نذكره بابا بابا وشيئا شيئا، إن شاء الله تعالى.\r__________\r(1) أخرجه البخاري ح (3452)، ومسلم ح (2935، 2934) من حديث حذيفة بن اليمان وأبي مسعود الأنصاري.\r(2) البقرة: 275.\r(3) الناس: 4 - 5."]], "pg": [144, 149]}, "إ.1.1": {"x": [[150, "باب الكلام في إثبات رؤية الله تعالى بالأبصار في الآخرة\rقال الله عز وجل: {وُجُوهٌ يَوْمَئِذٍ ناضِرَةٌ (1) يعني مشرقة إِلى رَبِّها ناظِرَةٌ} (2) يعني رائية، وليس يخلو النظر من وجوه نحن ذاكروها:\rإما أن يكون الله عز وجل عنى نظر الاعتبار لقوله تعالى: {أَفَلا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ} (3) أو يكون عنى نظر الانتظار لقوله: {ما يَنْظُرُونَ إِلاّ صَيْحَةً واحِدَةً} (4) أو أن يكون عنى نظر تعطف كقوله تعالى: {وَلا يَنْظُرُ إِلَيْهِمْ يَوْمَ الْقِيامَةِ} (5) أو يكون عنى نظر الرؤية: فلا يجوز أن يكون الله عز وجل عنى نظر التفكر والاعتبار لأن الآخرة ليست بدار اعتبار، ولا يجوز أن يكون عنى نظر الانتظار لأن النظر إذا ذكر مع ذكر الوجه فمعناه نظر العينين اللتين في الوجه، كما إذا ذكر أهل اللسان نظر القلب فقالوا: «انظر في هذا الأمر بقلبك» لم يكن معناه نظر العينين، ولذلك إذا ذكر النظر مع الوجه لم يكن معناه نظر الانتظار الذي بالقلب، وأيضا فإن نظر الانتظار لا يكون في الجنة لأن الانتظار معه تنغيص وتكدير، وأهل الجنة في ما لا عين رأت ولا أذن سمعت من العيش السليم والنعيم المقيم، وإذا كان هذا هكذا لم يجز أن يكونوا منتظرين لأنهم كلما خطر ببالهم شيء أتوا به مع خطوره ببالهم، وإذا كان ذلك كذلك فلا يجوز أن يكون الله عز وجل أراد نظر التعطف؛ لأن الخلق لا يجوز أن يتعطفوا على\r__________\r(1) القيامة: 22.\r(2) القيامة: 23.\r(3) الغاشية: 17.\r(4) يس: 49.\r(5) آل عمران: 77."], [151, "خالقهم؛ وإذا فسدت الأقسام الثلاثة صح القسم الرابع من أقسام النظر وهو أن معنى قوله: {إِلى رَبِّها ناظِرَةٌ} أنها رائية ترى ربهاعز وجل.\rومما يبطل قول المعتزلة أن الله عز وجل أراد بقوله: {إِلى رَبِّها ناظِرَةٌ} نظر الانتظار أنه قال: {إِلى رَبِّها ناظِرَةٌ} ونظر الانتظار لا يكون مقرونا بقوله: (إلى) لأنه لا يجوز عند العرب أن يقولوا في نظر الانتظار «إلى» ألا ترى أن الله عز وجل لما قال: {ما يَنْظُرُونَ إِلاّ صَيْحَةً واحِدَةً} لم يقل «إلى»، إذ كان معناه الانتظار، وقال عن بلقيس: {فَناظِرَةٌ بِمَ يَرْجِعُ الْمُرْسَلُونَ} (1) فلما أرادت الانتظار لم تقل «إلى»، وقال امرؤ القيس:\rفإنكما إن تنظراني ساعة ... من الدهر تنفعني لدى أم جندب\rفلما أراد الانتظار لم يقل «إلى»، فلما قال عز وجل: {إِلى رَبِّها ناظِرَةٌ} علمنا أنه لم يرد الانتظار، وإنما أراد نظر الرؤية، ولما قرن الله النظر بذكر الوجه أراد نظر العينين اللتين في الوجه كما قال: {قَدْ نَرى تَقَلُّبَ وَجْهِكَ فِي السَّماءِ فَلَنُوَلِّيَنَّكَ} (2) فذكر الوجه، وإنما أراد تقلب عينيه نحو السماء ينتظر نزول الملك عليه بصرف الله له عن قبلة بيت المقدس إلى الكعبة.\rفإن قال قائل: لم لا قلتم إن قوله: {إِلى رَبِّها ناظِرَةٌ} إنما أراد: إلى ثواب ربها ناظرة؟\rقيل له: ثواب الله عز وجل غيره، والله تعالى قال: {إِلى رَبِّها ناظِرَةٌ} ولم يقل: إلى غيره ناظرة، والقرآن على ظاهره، وليس لنا أن نزيله عن ظاهره إلا لحجة وإلا فهو على ظاهره؛ ألا ترى أن الله عز وجل لما قال: «صلوا لي واعبدوني»، لم\r__________\r(1) النمل: 35.\r(2) البقرة: 144."], [152, "يجز أن يقول قائل: إنه أراد غيره، ويزيل الكلام عن ظاهره؛ فلذلك لما قال: إِلى رَبِّها ناظِرَةٌ لم يجز لنا أن نزيل القرآن عن ظاهره بغير حجة.\rثم يقال للمعتزلة: إن جاز لكم أن تزعموا أن قول الله عز وجل: {إِلى رَبِّها ناظِرَةٌ} إنما أراد به أنها إلى غيره ناظرة؛ فلم لا جاز لغيركم أن يقول: إن قول الله عز وجل: {لا تُدْرِكُهُ الْأَبْصارُ} (1) أراد بها: لا تدرك غيره ولم يرد أنها لا تدركه، وهذا ما لا يقدرون على الفرق فيه.\rودليل آخر: ومما يدل على أن الله تعالى يرى بالأبصار قول موسى: {رَبِّ أَرِنِي أَنْظُرْ إِلَيْكَ} (2) و لا يجوز أن يكون موسى عليه السّلام الذي قد ألبسه الله تعالى جلباب النبيين وعصمه بما عصم به المرسلين قد سأل ربه ما يستحيل عليه، وإذا لم يجز ذلك على موسى فقد علمنا أنه لم يسأل ربه مستحيلا، وأن الرؤية جائزة على ربنا عز وجل، ولو كانت الرؤية مستحيلة على ربنا - كما زعمت المعتزلة - ولم يعلم ذلك موسى عليه السّلام وعلموا هم لكانوا على قولهم أعلم بالله من موسى عليه السّلام، وهذا ما لا يدعيه مسلم.\rفإن قال قائل: ألستم تعلمون حكم الله في الظهار اليوم، ولم يكن نبي الله عليه السّلام يعلم ذلك قبل أن ينزل؟\rقيل له: لم يكن يعلم نبي الله صلّى الله عليه وسلّم ذلك قبل أن يلزم الله العباد حكم الظهار، فلما لزمهم الحكم به أعلم نبيه قبلهم ثم أعلم نبيّ الله عباد الله ذلك، ولم يأت عليه وقت لزمه حكمه فلم يعلمه عليه السّلام، وأنتم زعمتم أن موسى كان قد لزمه أن يعلم حكم الرؤية وأنها مستحيلة عليه، وإذا لم يعلم ذلك وقت أن لزمه علمه\r__________\r(1) الأنعام: 103.\r(2) الأعراف: 143."], [153, "علمتموه أنتم الآن لزمكم بجهلكم أنكم بما لزمكم العلم به الآن أعلم من موسى عليه السّلام بما لزمه العلم به، وهذا خروج عن دين المسلمين.\rودليل آخر: مما يدل على جواز رؤية الله تعالى بالأبصار قول الله تعالى لموسى: {فَإِنِ اسْتَقَرَّ مَكانَهُ فَسَوْفَ تَرانِي} (1) فلما كان الله عز وجل قادرا على أن يجعل الجبل مستقرّا كان قادرا على الأمر الذي لو فعله لرآه موسى؛ فدل ذلك على أن الله تعالى قادر على أن يري عباده نفسه وأنه جائز رؤيته.\rفإن قال: فلم لا قلتم إن قول الله تعالى: {فَإِنِ اسْتَقَرَّ مَكانَهُ فَسَوْفَ تَرانِي} تبعيد للرؤية؟\rقيل له: لو أراد الله عز وجل تبعيد الرؤية لقرن الكلام بما يستحيل وقوعه ولم يقرنه بما يجوز وقوعه، فلما قرنه باستقرار الجبل وذلك أمر مقدور لله سبحانه دل ذلك على أنه جائز أن يرى الله عز وجل، أ لا ترى أن الخنساء لما أرادت تبعيد صلحها لمن كان حربا لأخيها قرنت الكلام بمستحيل فقالت:\rولا أصالح قوما كنت حربهم ... حتى تعود بياضا حلكة القار\rوالله عز وجل إنما خاطب العرب بلغتها ونحن نرجع إلى ما نجده مفهوما في كلامها ومعقولا في خطابها؛ فلما قرن الله الرؤية بأمر مقدور جائز علمنا أن رؤية الله بالأبصار جائزة غير مستحيلة.\rودليل آخر: قال عز وجل: {لِلَّذِينَ أَحْسَنُوا الْحُسْنى وَزِيادَةٌ} (2)، قال أهل التأويل: النظر إلى الله عز وجل، ولم ينعم الله عز وجل أهل جنانه بأفضل من نظرهم\r__________\r(1) الأعراف: 143.\r(2) يونس: 26."], [154, "إليه ورؤيتهم له وقال عز وجل: {وَلَدَيْنا مَزِيدٌ} (1) قيل: النظر إلى الله عز وجل، وقال: {تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُ سَلامٌ} (2)، وإذا لقيه المؤمنون رأوه، وقال الله: {كَلاّ إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ} (3)، فحجبهم عن رؤيته ولا يحجب عنها المؤمنين.\rسؤال: فإن قال قائل: فما معنى قوله: {لا تُدْرِكُهُ الْأَبْصارُ} (4)؟.\rقيل له: يحتمل أن يكون لا تدركه في الدنيا وتدركه في الآخرة؛ لأن رؤية الله تعالى أفضل اللذات، وأفضل اللذات يكون في أفضل الدارين؛ ويحتمل أن يكون الله عز وجل أراد بقوله: {لا تُدْرِكُهُ الْأَبْصارُ} يعني لا تدركه أبصار الكافرين المكذبين، وذلك أن كتاب الله يصدق بعضه بعضا؛ فلما قال في آية: «إن الوجوه تنظر إليه يوم القيامة»، وقال في آية أخرى: «إن الأبصار لا تدركه» علمنا أنه إنما أراد: أبصار الكفار لا تدركه.\rمسألة والجواب عنها: فإن قال قائل: قد استكبر الله سؤال السائلين له أن يرى بالأبصار فقال: {يَسْئَلُكَ أَهْلُ الْكِتابِ أَنْ تُنَزِّلَ عَلَيْهِمْ كِتابًا مِنَ السَّماءِ فَقَدْ سَأَلُوا مُوسى أَكْبَرَ مِنْ ذلِكَ فَقالُوا أَرِنَا اللهَ جَهْرَةً} (5)؟.\rفيقال لهم: إن بني إسرائيل سألوا رؤية الله عز وجل على طريق الإنكار لنبوة موسى وترك الإيمان به حتى ترى الله إلا أنهم قالوا: لن نؤمن حتى نرى الله جهرة، فلما سألوه الرؤية على طريق ترك الإيمان بموسى حتى يريهم الله نفسه استعظم الله سؤالهم من غير أن تكون الرؤية مستحيلة عليه، كما استعظم الله\r__________\r(1) ق: 35.\r(2) الأحزاب: 44.\r(3) المطففين: 15.\r(4) الأنعام: 103.\r(5) النساء: 153."], [155, "سؤال أهل الكتاب أن ينزل عليهم كتابا من السماء من غير أن يكون ذلك مستحيلا، ولكن لأنهم أبوا أن يؤمنوا بنبي الله حتى ينزل عليهم من السماء كتابا.\rدليل آخر: ومما يدل على رؤية الله عز وجل بالأبصار ما روته الجماعات من الجهات المختلفات عن رسول الله صلّى الله عليه وسلّم أنه قال: «ترون ربّكم كما ترون القمر ليلة البدر لا تضارّون في رؤيته» (1)، والرؤية إذا أطلقت إطلاقا ومثلت برؤية العيان لم يكن معناها إلا رؤية العيان، ورويت الرؤية عن رسول الله صلّى الله عليه وسلّم من طرق مختلفة، عدة رواتها أكثر من عدة خبر الرجم، ومن عدة من روى أن النبي صلّى الله عليه وآله وسلّمو اله وسلم قال: «لا وصية لوارث» (2) و من عدة رواة المسح على الخفين (3)، ومن\r__________\r(1) أخرجه البخاري ومسلم من حديث جرير بن عبد الله، وقد تقدم تخريجه. وأخرجه البخاري ح (7440، 4581)، ومسلم ح (183) من حديث أبي سعيد الخدري. وأخرجه البخاري ح (7438، 6574، 806)، ومسلم ح (2968، 182) من حديث أبي هريرة.\r(2) أخرجه أبو داود ح (3565، 2870)، والترمذي ح (2120)، وابن ماجه ح (2713) من حديث أبي أمامة به، وفي إسناده إسماعيل بن عياش، قال الترمذي: «حديث حسن صحيح، وقد روي عن أبي أمامة عن النبي صلّى الله عليه وسلّم من غير هذا الوجه، ورواية إسماعيل بن عياش عن أهل العراق وأهل الحجاز ليس بذلك فيما تفرد به، لأنه روى عنه مناكير، وروايته عن أهل الشام أصح، هكذا قال محمد بن إسمعيل». اه‍. وأخرجه الترمذي ح (2121)، والنسائي ح (3643، 3641) من حديث عمرو بن خارجة، وقال الترمذي: «حديث حسن صحيح». اه‍. وأخرجه ابن ماجه ح (2714) من حديث أنس، وفي الباب عن عمرو بن شعيب عن أبيه عن جده، وعن جابر، وعن علي، قال ابن حجر في فتح الباري (372/ 5): «لا يخلو إسناد كل منها عن مقال، لكن مجموعها يقتضي أن للحديث أصلا، بل جنح الشافعي في الأم إلى أن هذا المتن متواتر، فقال: وجدنا أهل الفتيا ومن حفظنا عنهم من أهل العلم بالمغازي من قريش وغيرهم لا يختلفون في أن النبي صلّى الله عليه وسلّم قال عام الفتح: لا وصية لوارث، ويؤثرون عمن حفظوه عنه ممن لقوه من أهل العلم، فكان نقل كافة عن كافة فهو أقوى من نقل واحد». اه‍. وينظر نصب الراية (476/ 4)، والتلخيص الحبير (92/ 3).\r(3) أخرجه البخاري ح (387)، ومسلم ح (272) من حديث جرير، وأخرجه البخاري ح (182)، ومسلم ح (274) من حديث المغيرة بن شعبة، وأخرجه البخاري ح (202) من حديث سعد بن أبي وقاص، وأخرجه البخاري ح (204) من حديث عمرو بن أمية الضمري، ="], [156, "عدة رواة قول رسول الله صلّى الله عليه وسلّم: «لا تنكح المرأة على عمتها ولا خالتها» (1) و إذا كان الرجم وما ذكرناه سننا عند المعتزلة كانت الرؤية أولى أن تكون سنة لكثرة رواتها ونقلتها يرويها خلف عن سلف، وحديث «أنى أراه؟» لا حجة فيه لأنه عند ما سأل سائل النبي صلّى الله عليه وسلّم عن رؤية الله عز وجل في الدنيا وقال له: هل رأيت ربك؟ فقال: «نور أنى أراه؟» (2)؛ لأن العين لا تدرك في الدنيا الأنوار المخلوقة على حقائقها؛ لأن الإنسان لو حدق بنظره إلى عين الشمس فأدام النظر إلى عينها لذهب أكثر نور بصره؛ فإذا كان الله عز وجل حكم في الدنيا بأن لا تقوم العين بالنظر إلى عين الشمس فأحرى أن لا يثبت البصر للنظر إلى الله عز وجل في الدنيا إلا أن يقويه الله عز وجل، فرؤية الله سبحانه في الدنيا قد اختلف فيها.\rوقد روي عن أصحاب رسول الله صلّى الله عليه وسلّم أن الله عز وجل تراه العيون في الآخرة، وما روي عن أحد منهم أن الله عز وجل لا تراه العيون في الآخرة؛ فلما كانوا على هذا مجمعين وبه قائلين - وإن كانوا في رؤيته في الدنيا مختلفين - ثبتت الرؤية في الآخرة إجماعا، وإن كانت في الدنيا مختلفا فيها، ونحن إنما قصدنا إلى إثبات رؤية الله في الآخرة على أن هذه الرواية على المعتزلة لا لهم؛ لأنهم ينكرون أن الله نور في الحقيقة فإذا احتجوا بخبر هم له تاركون وعنه منحرفون كانوا محجوجين.\rدليل آخر: ومما يدل على رؤية الله عز وجل بالأبصار أنه ليس موجود إلا\r__________\r=\rوأخرجه مسلم ح (273) من حديث سعد بن أبي وقاص. وفي الباب عن غيرهم، ينظر نصب الراية (151/ 1 - 152).\r(1) أخرجه البخاري ح (5111)، ومسلم ح (1408) من حديث أبي هريرة. وأخرجه البخاري ح (5108) من حديث جابر. وفي الباب عن جماعة من الصحابة، ينظر التلخيص الحبير (167/ 3).\r(2) أخرجه مسلم ح (291/ 178) من حديث أبي ذر به."], [157, "وجائز أن يريناه الله عز وجل، وإنما لا يجوز أن يرى المعدوم، فلما كان الله عز وجل موجودا مثبتا كان غير مستحيل أن يرينا نفسه عز وجل وإنما أراد من نفى رؤية الله عز وجل بالأبصار التعطيل، فلما لم يمكنهم أن يظهروا التعطيل صراحا أظهروا ما يئول بهم إلى التعطيل والجحود - تعالى الله عن ذلك علوّا كبيرا.\rدليل آخر: ومما يدل على رؤية الله سبحانه بالأبصار أن الله عز وجل يرى الأشياء، وإذا كان للأشياء رائيا فلا يرى الأشياء من لا يرى نفسه، وإذا كان لنفسه رائيا فجائز أن يرينا نفسه، وذلك أن من لا يعلم نفسه لا يعلم شيئا، فلما كان الله عز وجل عالما بالأشياء كان عالما بنفسه؛ فلذلك من لا يرى نفسه لا يرى الأشياء، فلما كان الله عز وجل رائيا للأشياء كان رائيا لنفسه، وإذا كان رائيا لها فجائز أن يرينا نفسه، كما أنه لما كان عالما بنفسه جاز أن يعلمناها، وقد قال الله تعالى: {إِنَّنِي مَعَكُما أَسْمَعُ وَأَرى} (1)؛ فأخبر أنه سمع كلامهما ورآهما، ومن زعم أن الله عز وجل لا يجوز أن يرى بالأبصار يلزمه أن لا يجوز أن يكون الله عز وجل رائيا ولا عالما ولا قادرا؛ لأن العالم القادر الرائي جائز أن يرى.\rفإن قال قائل: قول النبي صلّى الله عليه وسلّم: «ترون ربكم» يعني تعلمون ربكم اضطرارا.\rقيل له: إن النبي صلّى الله عليه وسلّم قال لأصحابه هذا على سبيل البشارة فقال: فكيف بكم إذا رأيتم الله عز وجل، ولا يجوز أن يبشرهم بأمر يشركهم فيه الكفار على أن النبي صلّى الله عليه وسلّم قال: «ترون ربكم» وليس يعني رؤية دون رؤية بل ذلك عام في رؤية العين ورؤية القلب.\rدليل آخر: أن المسلمين اتفقوا على أن الجنة فيها ما لا عين رأت ولا أذن سمعت ولا خطر على قلب بشر من العيش السليم والنعيم المقيم، وليس نعيم في\r__________\r(1) طه: 46."], [158, "الجنة أفضل من رؤية الله عز وجل بالأبصار، وأكثر من عبد الله عز وجل عبده للنظر إلى وجهه؛ فإذا لم يكن بعد رؤية الله أفضل من رؤية نبيه صلّى الله عليه وسلّم وكانت رؤية نبي الله أفضل لذات الجنة كانت رؤية الله عز وجل أفضل من رؤية نبيه عليه السّلام، وإذا كان ذلك كذلك لم يحرم الله أنبياءه المرسلين وملائكته المقربين وجماعة المؤمنين والصديقين النظر إلى وجهه عز وجل، وذلك أن الرؤية لا تؤثر في المرئي؛ لأن رؤية الرائي تقوم به، فإذا كان هذا هكذا وكانت الرؤية غير مؤثرة في المرئي لم توجب تشبيها ولا انقلابا عن حقيقة، ولم يستحل على الله عز وجل أن يري عباده المؤمنين نفسه في جنانه.\r***"], [159, "باب في الرؤية\r"]], "pg": [150, 159]}, "إ.1.2": {"x": [[159, "احتجت المعتزلة في أن الله عز وجل لا يرى بالأبصار بقوله عز وجل: {لا تُدْرِكُهُ الْأَبْصارُ وَهُوَ يُدْرِكُ الْأَبْصارَ} (1) قالوا: فلما عطف الله عز وجل بقوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} على قوله: {لا تُدْرِكُهُ الْأَبْصارُ} وكان قوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} على العموم أنه يدركها في الدنيا والآخرة وأنه يراها في الدنيا والآخرة كان قوله: {لا تُدْرِكُهُ الْأَبْصارُ} دليلا على أنه لا تراه الأبصار في الدنيا والآخرة وكان في عموم قوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} لأن أحد الكلامين معطوف على الآخر.\rقيل لهم: فيجب إذا كان عموم القولين واحدا وكانت الأبصار أبصار العيون وأبصار القلوب؛ لأن الله عز وجل قال: {فَإِنَّها لا تَعْمَى الْأَبْصارُ وَلكِنْ تَعْمَى الْقُلُوبُ الَّتِي فِي الصُّدُورِ} (2) و قال: {أُولِي الْأَيْدِي وَالْأَبْصارِ} (3) أي فهي بالأبصار؛ فأراد أبصار القلوب، وهي التي يفضل بها المؤمنون الكافرين، ويقول أهل اللغة: فلان بصير بصناعته، يريدون بصر العلم، ويقولون: قد أبصرته بقلبي كما يقولون: قد أبصرته بعيني، فإذا كان البصر بصر العيون وبصر القلوب ثم أوجبوا علينا أن يكون قوله: {لا تُدْرِكُهُ الْأَبْصارُ} في العموم كقوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} لأن أحد الكلامين معطوف على الآخر وجب عليهم بحجتهم أن الله عز وجل لا يدرك بأبصار العيون ولا بأبصار القلوب؛ لأن قوله: {لا تُدْرِكُهُ الْأَبْصارُ} في العموم كقوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ}، وإذا لم يكن عندهم هكذا فقد وجب أن يكون قوله: {لا تُدْرِكُهُ الْأَبْصارُ} أخص من\r__________\r(1) الأنعام: 103.\r(2) الحج: 46.\r(3) ص: 45."], [160, "قوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} وانتقض احتجاجهم.\rوقيل لهم: إنكم زعمتم أنه لو كان قوله: {لا تُدْرِكُهُ الْأَبْصارُ} خاصّا في وقت دون وقت لكان قوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} خاصّا في وقت دون وقت، وكان قوله: {لَيْسَ كَمِثْلِهِ شَيْءٌ} (1) و قوله: {لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ} (2) و قوله: {لا يَظْلِمُ النّاسَ شَيْئًا} (3) في وقت دون وقت.\rفإن جعلتم قوله: {لا تُدْرِكُهُ الْأَبْصارُ} خاصّا رجع احتجاجكم عليكم، وقيل لكم: إذا كان قوله: لا تُدْرِكُهُ الْأَبْصارُ خاصّا ولم يجب خصوص هذه الآيات فلم أنكرتم أن يكون قوله عز وجل: {لا تُدْرِكُهُ الْأَبْصارُ} إنما أراد في الدنيا دون الآخرة كما أن قوله: {لا تُدْرِكُهُ الْأَبْصارُ} أراد بعض الأبصار دون بعض، ولا يوجب ذلك تخصيص هذه الآيات التي عارضتمونا بها.\rفإن قالوا: قوله: {لا تُدْرِكُهُ الْأَبْصارُ} يوجب أنه لا يدرك بها في الدنيا والآخرة، وليس ينفي ذلك أن نراه بقلوبنا ونبصره بها ولا ندركه بها.\rقيل لهم: فما أنكرتم أن يكون لا ندركه بأبصار العيون ولا يوجب إذا لم ندركه بها أن لا نراه بها؛ فرؤيتنا له بالعيون وإبصارنا له بها ليس بإدراك له بها كما أن إبصارنا له بالقلوب ورؤيتنا له بها ليس بإدراك له بها.\rفإن قالوا: رؤية البصر هي إدراك البصر، قيل لهم: ما الفرق بينكم وبين من قال: إن رؤية القلب وإبصاره هو إدراكه وإحاطته؛ فإذا كان علم القلب بالله عز وجل وإبصار القلب له رؤيته إياه ليس بإحاطة ولا إدراك فما أنكرتم أن تكون\r__________\r(1) الشورى: 11.\r(2) البقرة: 255.\r(3) يونس: 44."], [161, "رؤية العيون وإبصارها لله عز وجل ليس بإحاطة ولا إدراك.\rجواب: ويقال لهم: إذا كان قول الله عز وجل: {لا تُدْرِكُهُ الْأَبْصارُ} في العموم كقوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} لأن أحد الكلامين معطوف على الآخر فخبرونا: أليست الأبصار والعيون لا تدركه رؤية ولا لمسا ولا ذوقا ولا على وجه من الوجوه؟ فمن قولهم: نعم فيقال لهم: أخبرونا عن قوله عز وجل: {وَهُوَ يُدْرِكُ الْأَبْصارَ} أتزعمون أنه يدركها لمسا وذوقا بأن يلمسها؟.\rفمن قولهم: لا، فيقال لهم: فقد انتقض قولكم: إن قوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} في العموم كقوله: {لا تُدْرِكُهُ الْأَبْصارُ}.\rسؤال: إن قال قائل منهم: إن البصر في الحقيقة هو بصر العين لا بصر القلب، قيل له: ولم زعمت هذا وقد سمى أهل اللغة بصر القلب بصرا كما سموا بصر العين بصرا، وإن جاز لك ما قلته جاز لغيركم أن يزعم أن البصر في الحقيقة هو بصر القلب دون العين، وإذا لم يجز هذا فقد وجب أن البصر بصر العين وبصر القلب.\rجواب: ويقال لهم: حدثونا عن قول الله عز وجل: {وَهُوَ يُدْرِكُ الْأَبْصارَ} ما معناه؟ فإن قالوا: معنى (يدرك الأبصار) أنه يعلمها، قيل لهم: وإذا كان أحد الكلامين معطوفا على الآخر وكان قوله عز وجل: {وَهُوَ يُدْرِكُ الْأَبْصارَ معناه يعلمها فقد وجب أن يكون قوله: لا تُدْرِكُهُ الْأَبْصارُ لا تعلمه، وهذا نفي للعلم لا لرؤية الأبصار.\rفإن قالوا: معنى قوله: {وَهُوَ يُدْرِكُ الْأَبْصارَ} أنه يراها رؤية ليس معناها العلم، قيل لهم: فالأبصار التي في العيون يجوز أن ترى؟ فإن قالوا: «نعم» نقضوا قولهم: إنا لا نرى بالبصر إلا من جنس ما نرى الساعة؛ فإن جاز أن يرى الله وكل ما ليس من جنس المرئيات وهو الإبصار في العين فلم لا يجوز أن يرى نفسه وإن لم يكن من جنس المرئيات، ولم لا يجوز أن يرينا نفسه وإن لم يكن من"], [162, "جنس المرئيات.\rويقال لهم: حدثونا إذا رأينا شيئا فبصرناه أو إنما يراه الرائي دون البصر؟ فمن قولهم: إنه محال أن يرى البصر الذي في العين فيقال لهم: الآية تنفي أن تراه الأبصار، ولا تنفي أن يراه المبصرون، وإنما قال الله عز وجل: {لا تُدْرِكُهُ الْأَبْصارُ} فهذا لا يدل على أن المبصرين لا يرونه على ظاهرالآية.\r***"], [163, "باب الكلام في أن القرآن كلام الله غير مخلوق\r"]], "pg": [159, 163]}, "إ.2.1": {"x": [[163, "إن سأل سائل عن الدليل على أن القرآن كلام الله غير مخلوق، قيل له: الدليل على ذلك قوله عز وجل: {وَمِنْ آياتِهِ أَنْ تَقُومَ السَّماءُ وَالْأَرْضُ بِأَمْرِهِ} (1) و أمر الله هو كلامه وقوله؛ فلما أمرهما بالقيام فقامتا لا يهويان كان قيامهما بأمره، وقال عز وجل: {أَلا لَهُ الْخَلْقُ وَالْأَمْرُ} (2) فالخلق جميع ما خلق داخل فيه؛ لأن الكلام إذا كان لفظه عامّا فحقيقته أنه عام، ولا يجوز لنا أن نزيل الكلام عن حقيقته بغير حجة ولا برهان، فلما قال: {أَلا لَهُ الْخَلْقُ} كان هذا في جميع الخلق، ولما قال: {وَالْأَمْرُ} ذكر أمرا غير جميع الخلق؛ فدل ما وصفنا على أن أمر الله غير مخلوق.\rفإن قال قائل: أليس قد قال الله تعالى: {مَنْ كانَ عَدُوًّا للهِ وَمَلائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكالَ} (3)؟ قيل له: نحن نخص القرآن بالإجماع وبالدليل فلما ذكر الله عز وجل نفسه وملائكته ولم يدخل في ذكر الملائكة جبريل وميكال وإن كانا من الملائكة ثم ذكرهما بعد ذلك كأنه قال: الملائكة إلا جبريل وميكال، ثم ذكرهما بعد ذكر الملائكة فقال: {وَجِبْرِيلَ وَمِيكالَ}، ولما قال: {أَلا لَهُ الْخَلْقُ وَالْأَمْرُ} ولم يخص قوله: {الْخَلْقُ} دليل كان قوله: {أَلا لَهُ الْخَلْقُ} في جميع الخلق، ثم قال بعد ذكره الخلق: {وَالْأَمْرُ} فأبان الأمر من الخلق، وأمر الله كلامه، وهذا يوجب أن كلام الله غير مخلوق، وقال عز وجل: {للهِ الْأَمْرُ مِنْ قَبْلُ وَمِنْ بَعْدُ} (4) يعني من قبل أن يخلق الخلق ومن بعد ذلك، وهذا يوجب أن الأمر غير مخلوق.\r__________\r(1) الروم: 25.\r(2) الأعراف: 54.\r(3) البقرة: 98.\r(4) الروم: 4."], [164, "دليل آخر: ومما يدل من كتاب الله على أن كلامه غير مخلوق قوله عز وجل: {إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} (1)، فلو كان القرآن مخلوقا لوجب أن يكون مقولا له: كن فيكون، ولو كان الله عز وجل قائلا للقول: (كن) كان للقول قول، وهذا يوجب أحد أمرين: إما أن يئول الأمر إلى أن قول الله غير مخلوق أو يكون كل قول واقع بقول لا إلى غاية، وذلك محال، وإذا استحال ذلك صح وثبت أن لله عز وجل قولا غير مخلوق.\rسؤال: فإن قال قائل: معنى قول الله أن يقول له: كن فيكون: إنما يكونه فيكون، قيل: الظاهر أن يقول له، ولا يجوز أن يكون قول الله للأشياء كلها كوني هو الأشياء؛ لأن هذا يوجب أن تكون الأشياء كلها كلام الله عز وجل، ومن قال ذلك أعظم الفرية لأنه يلزمه أن يكون كل شيء في العالم من إنسان وفرس وحمار وغير ذلك كلام الله، وفي هذا ما فيه.\rفلما استحال ذلك صح أن قول الله للأشياء كوني غيرها، وإذا كان غير المخلوقات فقد خرج كلام الله عز وجل عن أن يكون مخلوقا، ويلزم من أثبت كلام الله مخلوقا أن يثبت أن الله غير متكلم ولا قائل، وذلك فاسد كما يفسد أن يكون علم الله مخلوقا وأن يكون الله غير عالم؛ فلما كان الله عز وجل لم يزل عالما إذ لم يجز أن يكون لم يزل بخلاف العلم موصوفا استحال أن يكون لم يزل بخلاف العلم موصوفا؛ لأن خلاف الكلام الذي لا يكون معه كلام سكوت أو آفة، كما أن خلاف العلم الذي لا يكون معه علم جهل أو شك أو آفة، ويستحيل أن يوصف ربناعز وجل بخلاف العلم، ولذلك يستحيل أن يوصف بخلاف الكلام من السكوت والآفات؛ فوجب لذلك أن يكون لم يزل متكلما كما وجب\r__________\r(1) النحل: 40."]], "pg": [163, 164]}, "إ.2.2": {"x": [[165, "أن يكون لم يزل عالما.\rدليل آخر: وقال الله عز وجل: {قُلْ لَوْ كانَ الْبَحْرُ مِدادًا لِكَلِماتِ رَبِّي لَنَفِدَ الْبَحْرُ قَبْلَ أَنْ تَنْفَدَ كَلِماتُ رَبِّي} (1) فلو كانت البحار مدادا كتبت لنفدت البحار وتكسرت الأقلام ولم يلحق الفناء كلمات ربي كما لا يلحق الفناء علم الله عز وجل، ومن فني كلامه لحقته الآفات وجرى عليه السكوت، فلما لم يجز ذلك على ربناعز وجل صح أنه لم يزل متكلما، لأنه لو لم يكن متكلما وجب السكوت والآفات وتعالى ربنا عن قول الجهمية علوّا كبيرا.\r\rفصل: الجهينة\rوزعمت الجهمية كما زعمت النصارى؛ لأن النصارى زعمت أن كلمة الله حواها بطن مريم وزادت الجهمية عليهم فزعمت أن كلام الله مخلوق حل في شجرة وكانت الشجرة حاوية له، فلزمهم أن تكون الشجرة بذلك الكلام متكلما، ووجب عليهم أن مخلوقا من المخلوقين كلم موسى وأن الشجرة قالت: يا موسى {إِنَّنِي أَنَا اللهُ لا إِلهَ إِلاّ أَنَا فَاعْبُدْنِي} (2)، فلو كان كلام الله مخلوقا في شجرة لكان المخلوق قال: يا موسى! إِنَّنِي أَنَا اللهُ لا إِلهَ إِلاّ أَنَا فَاعْبُدْنِي، وقد قال الله عز وجل: {وَلكِنْ حَقَّ الْقَوْلُ مِنِّي لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنّاسِ أَجْمَعِينَ} (3) و كلام الله عز وجل من الله لا يجوز أن يكون كلامه الذي هو منه مخلوقا في شجرة مخلوقة كما لا يجوز أن يكون علمه الذي هو منه مخلوقا في غيره - تعالى الله عن ذلك علوّا كبيرا.\rجواب: ويقال لهم: كما لا يجوز أن يخلق الله عز وجل إرادته في بعض\r__________\r(1) الكهف: 109.\r(2) طه: 14.\r(3) السجدة: 13."]], "pg": [165, 165]}, "إ.2.3": {"x": [[166, "المخلوقات كذلك لا يجوز أن يخلق كلامه في بعض المخلوقات، ولو كانت إرادة الله مخلوقة في بعض المخلوقات لكان ذلك المخلوق هو المريد لها وذلك يستحيل، وكذلك يستحيل أن يخلق الله كلامه في مخلوق؛ لأن هذا يوجب أن ذلك المخلوق متكلم به، ويستحيل أن يكون كلام الله عز وجل كلاما للمخلوق.\rدليل آخر: ومما يبطل قولهم أن الله عز وجل قال مخبرا عن المشركين أنهم قالوا: {إِنْ هذا إِلاّ قَوْلُ الْبَشَرِ (25)} (1) يعني القرآن؛ فمن زعم أن القرآن مخلوق فقد جعله قولا للبشر، وهذا ما أنكره الله على المشركين، وأيضا فلو لم يكن الله متكلما حتى خلق الخلق ثم تكلم بعد ذلك لكانت الأشياء قد كانت لا عن أمره ولا عن قوله ولم يكن قائلا لها: كوني، وهذا رد للقرآن، والخروج عما عليه جمهور أهل الإسلام.\r\rفصل قول الجهمية: إن كلام الله مخلوق\rواعلموا - رحمكم الله - أن قول الجهمية: إن كلام الله مخلوق يلزمهم به أن يكون الله عز وجل لم يزل كالأصنام التي لا تنطق ولا تتكلم لو كان لم يزل غير متكلم؛ لأن الله عز وجل يخبر عن إبراهيم أنه قال لقومه لما قالوا له: {أَأَنْتَ فَعَلْتَ هذا بِآلِهَتِنا يا إِبْراهِيمُ (62) قالَ بَلْ فَعَلَهُ كَبِيرُهُمْ هذا فَسْئَلُوهُمْ إِنْ كانُوا يَنْطِقُونَ (63)} (2) فاحتج عليهم بأن الأصنام إذا لم تكن ناطقة متكلمة لم تكن آلهة، وأن الإله لا يكون غير ناطق ولا متكلم، فلما كانت الأصنام التي لا يستحيل أن يحييها الله وينطقها لا تكون آلهة فكيف يجوز أن يكون من يستحيل عليه الكلام في قدمه إلها - تعالى الله عن ذلك علوّا كبيرا، وإذا لم يجز أن يكون الله سبحانه في قدمه بمرتبة دون مرتبة الأصنام التي لا تنطق فقد وجب أن يكون لم يزل متكلما.\r__________\r(1) المدثر: 25.\r(2) الأنبياء: 62 - 63."], [167, "دليل آخر: وقد قال الله تعالى مخبرا عن نفسه أنه يقول: {لِمَنِ الْمُلْكُ الْيَوْمَ} (1) و جاءت الرواية أنه يقول هذا القول فلا يرد عليه أحد شيئا فيقول: {اللهُ الْواحِدُ الْقَهّارُ}؛ فإذا كان عز وجل قائلا مع فناء الأشياء إذ لا إنسان ولا ملك ولا حي ولا جان ولا شجر ولا مدر فقد صح أن كلام الله عز وجل خارج عن الخلق؛ لأنه يوجد ولا شيء من المخلوقات موجود.\rدليل آخر: وقد قال الله عز وجل: {وَكَلَّمَ اللهُ مُوسى تَكْلِيمًا} (2) و التكليم هو المشافهة بالكلام، ولا يجوز أن يكون كلام المتكلم حالاّ في غيره مخلوقا في شيء سواه كما لا يجوز ذلك في العلم.\rدليل آخر: وقال الله عز وجل: {قُلْ هُوَ اللهُ أَحَدٌ (1) اَللهُ الصَّمَدُ (2) لَمْ يَلِدْ وَلَمْ يُولَدْ (3) وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} (3) فكيف يكون القرآن مخلوقا وأسماء الله في القرآن؟، هذا يوجب أن تكون أسماء الله مخلوقة ولو كانت أسماؤه مخلوقة لكانت وحدانيته مخلوقة، وكذلك علمه وقدرته - تعالى الله عن ذلك علوّا كبيرا.\rدليل آخر: وقد قال الله تعالى: {تَبارَكَ اسْمُ رَبِّكَ} (4) و لا يقال للمخلوق:\rتبارك؛ فدل هذا على أن أسماء الله غير مخلوقة، وقال: {وَيَبْقى وَجْهُ رَبِّكَ} (5) فكما لا يجوز أن يكون وجه ربنا مخلوقا فكذلك لا تكون أسماؤه مخلوقة.\rدليل آخر: وقد قال الله عز وجل: {شَهِدَ اللهُ أَنَّهُ لا إِلهَ إِلاّ هُوَ وَالْمَلائِكَةُ وَأُولُوا الْعِلْمِ قائِمًا بِالْقِسْطِ‍} (6) و لا بد أن يكون شهد بهذه الشهادة وسمعها من\r__________\r(1) غافر: 16.\r(2) النساء: 164.\r(3) الإخلاص: 1 - 4.\r(4) الرحمن: 78.\r(5) الرحمن: 27.\r(6) آل عمران: 18."], [168, "نفسه؛ لأنه إن كان سمعها من مخلوق فليست شهادة له، وإذا كانت شهادة له وقد شهد بها فلا يخلو أن يكون شهد بها قبل كون المخلوقات أو بعد كون المخلوقات؛ فإن كان شهد بها بعد كون المخلوقات فلم تسبق شهادته لنفسه بإلهية الخلق، وكيف يكون ذلك كذلك وهذا يوجب أن التوحيد لم يكن يشهد به شاهد قبل الخلق؟ ولو استحالت الشهادة بالوحدانية قبل كون الخلق لاستحال إثبات التوحيد ووجوده، وأن يكون واحدا قبل الخلق لأن ما تستحيل الشهادة عليه فمستحيل؛ وإن كانت شهادته لنفسه بالتوحيد قبل الخلق فقد بطل أن يكون كلام الله عز وجل مخلوقا لأن كلامه شهادته.\rدليل آخر: ومما يدل على بطلان قول الجهمية وأن القرآن كلام الله غير مخلوق أن أسماء الله من القرآن، وقد قال عز وجل: {سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى (1) اَلَّذِي خَلَقَ فَسَوّى} (1) و لا يجوز أن يكون {اسْمَ رَبِّكَ الْأَعْلَى (1) الَّذِي خَلَقَ فَسَوّى} مخلوقا كما لا يجوز أن يكون {جَدُّ رَبِّنا} مخلوقا؛ قال الله في سورة الجن تَعالى جَدُّ رَبِّنا (2)، وكما لا يجوز أن تكون عظمته مخلوقة كذلك لا يجوز أن تكون كلامه مخلوقا.\rدليل آخر: وقد قال الله عز وجل: {وَما كانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللهُ إِلا وَحْيًا أَوْ مِنْ وَراءِ حِجابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ ما يَشاءُ} (3) فلو كان كلام الله لا يوجد إلا مخلوقا في شيء مخلوق لم يكن لاشتراط‍ هذه الوجوه معنى؛ لأن الكلام قد سمعه جميع الخلق ووجدوه بزعم الجهمية مخلوقا في غير الله عز وجل، وهذا يوجب إسقاط‍ مرتبة النبيين صلوات الله عليهم، ويجب عليهم إذا زعموا أن\r__________\r(1) الأعلى: 1 - 2.\r(2) الجن: 3.\r(3) الشورى: 51."], [169, "كلام الله لموسى خلقه في شجرة أن يكون من سمع كلام الله عز وجل من ملك أو من نبي أتى به من عند الله أفضل مرتبة في سماع الكلام من موسى؛ لأنهم سمعوه من نبي ولم يسمعه موسى من الله عز وجل وإنما سمعه من شجرة، وأن يزعموا أن اليهودي إذا سمع كلام الله من النبي أفضل مرتبة في هذا المعنى من موسى بن عمران؛ لأن اليهودي سمعه من نبي من أنبياء الله وموسى سمعه مخلوقا في شجرة، ولو كان مخلوقا في شجرة لم يكن مكلما لموسى من وراء حجاب؛ لأن من حضر الشجرة من الجن والإنس قد سمعوا الكلام من ذلك المكان، وكان سبيل موسى وغيره في ذلك سواء في أنه ليس كلام الله له من وراء حجاب.\rجواب: ثم يقال لهم: إذا زعمتم أن معنى أن الله عز وجل كلم موسى أنه خلق كلاما كلمه به في الشجرة، وقد خلق الله عندكم في الذراع كلاما لأن الذراع قالت لرسول الله صلّى الله عليه وسلّم: لا تأكلني فإني مسمومة (1)، فلزمكم أن ذلك الكلام الذي سمع النبي كلام الله عز وجل؛ فإن استحال أن يكون الله تكلم بذلك الكلام المخلوق فما أنكرتم من أنه مستحيل أن يخلق الله عز وجل كلامه في شجرة؛ لأن كلام المخلوق لا يكون كلاما؛ فإن كان كلام الله وكان معنى أن الله تكلم عندكم أنه خلق الكلام فيلزمكم أن يكون الله متكلما بالكلام الذي خلقه في الذراع.\rفإن أجابوا إلى ذلك قيل لهم: فالله عز وجل على قولكم هو القائل: لا تأكلني فإني مسمومة - تعالى الله عن قولكم وافترائكم عليه علوّا كبيرا.\rوإن قالوا: لا يجوز أن يكون كلام الله مخلوقا في ذراع، قيل لهم: وكذلك لا يجوز أن يكون كلام الله مخلوقا في شجرة.\r__________\r(1) أخرجه الطبراني في الكبير (35/ 2) من حديث عروة بن الزبير مرسلا. وقال الهيثمي في المجمع (225/ 6): «رواه الطبراني مرسلا، وفيه ابن لهيعة وفيه ضعف، وحديثه حسن». اه‍."], [170, "جواب: ثم يسألون عن الكلام الذي أنطق الله به الذئب لما أخبر عن نبوة النبي صلّى الله عليه وسلّم؛ فقال لهم: إذا كان الله عز وجل يتكلم بكلام يخلقه في غيره فما أنكرتم أن يكون الكلام الذي سمعه من الذئب كلاما لله، ويكون إعجازه يدل على أنه كلام الله، وفي هذا ما يجب عليهم أن الذئب لم يتكلم به وأنه كلام الله عز وجل؛ لأن كون الكلام من الذئب معجز كما أن كونه من الشجرة معجز؛ فإن كان الذئب متكلما بذلك الكلام المنقول فما أنكرتم أن الشجرة متكلمة بالكلام إن كان خلق في شجرة، وأن يكون المخلوق فيه قال: يا موسى! إني أنا الله عز وجل - تعالى الله عن ذلك علوّا كبيرا.\rجواب: ثم يقال لهم: إذا كان كلام الله عز وجل مخلوقا في غيره عندكم فما يؤمنكم أن يكون كل كلام تسمعونه مخلوقا في شيء - وهو حق - أن يكون كلام الله عز وجل.\rفإن قالوا: لا تكون الشجرة متكلمة لأن المتكلم لا يكون إلا حيّا، قيل لهم: ولا يجوز خلق الكلام في شجرة لأن من خلق الكلام فيه لا يكون إلا حيّا؛ فإن جاز أن يخلق الكلام فيما ليس بحي، فلم لا يجوز أن يتكلم من ليس بحي، ويقال لهم: ألا قلتم: إنه يقول: من ليس بحي؛ لأنه عز وجل أخبر أن السموات والأرض قالتا: أتينا طائعين.\rجواب: ثم يقال لهم: أليس قد قال الله عز وجل لإبليس: {"]], "pg": [166, 170]}, "إ.2.4": {"x": [[170, "وَإِنَّ عَلَيْكَ لَعْنَتِي إِلى يَوْمِ الدِّينِ} (1) فلا بد من نعم، ويقال لهم: فإذا كان كلام الله مخلوقا وكانت المخلوقات فانيات فيلزمكم إذا أفنى الله عز وجل الأشياء أن تكون اللعنة على إبليس قد فنيت؛ فيكون إبليس غير ملعون، وهذا ترك لدين المسلمين ورد لقول\r__________\r(1) ص: 78."], [171, "الله عز وجل: {وَإِنَّ عَلَيْكَ لَعْنَتِي إِلى يَوْمِ الدِّينِ}، وإذا كانت اللعنة باقية على إبليس إلى يوم الدين وهو يوم الجزاء وهو يوم القيامة؛ لأن الله عز وجل قال: {مالِكِ يَوْمِ الدِّينِ} (1) يعني يوم الجزاء ثم هي أبدا في النار، واللعنة كلام الله، وهو قوله: {عَلَيْكَ لَعْنَتِي} فقد وجب أن يكون كلام الله عز وجل لا يجوز عليه الفناء وأنه غير مخلوق؛ لأن المخلوقات يجوز عليها العدم؛ فإذا لم يجز ذلك على كلام الله عز وجل فهو غير مخلوق.\r\rالرد على الجهمية:\rثم يقال لهم: إذا كان غضب الله غير مخلوق وكذلك رضاه وسخطه فلم لا قلتم: إن كلامه غير مخلوق، ومن زعم أن غضب الله مخلوق لزمه أن غضب الله وسخطه على الكافرين يفنى، وأن رضاه عن الملائكة والنبيين يفنى حتى لا يكون راضيا عن أوليائه ولا ساخطا على أعدائه، وهذا هو الخروج عن الإسلام.\rويقال: خبرونا عن قول الله عز وجل: {إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} (2) أتزعمون أن قوله لشيء: «كن» مخلوق مراد لله.\rفإن قالوا: لا، قيل لهم: فما أنكرتم أن يكون كلام الله الذي هو القرآن غير مخلوق كما زعمتم أن قول الله للشيء: «كن» غير مخلوق.\rوإن زعموا أن قول الله للشيء: «كن» مخلوق، قيل لهم: فإن زعمتم أنه مخلوق مراد فقد قال الله عز وجل: {إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} فيلزمكم أن قوله للشيء: «كن» قد قال له: «كن»، وفي هذا ما يوجب أحد أمرين: إما أن يكون قول الله لغيره: «كن» غير مخلوق، أو يكون لكل قول\r__________\r(1) الفاتحة: 4.\r(2) النحل: 40."], [172, "قول لا إلى غاية، وذلك محال.\rفإن قالوا: إن لله قولا غير مخلوق، قيل لهم: فلم أنكرتم أن تكون إرادة الله للإيمان غير مخلوقة؟.\rثم يقال لهم: ما العلة لما قلتم: إن قول الله للشيء: «كن» غير مخلوق؟ فإن قالوا: لأن القول لا يقال له: كن، فيقال لهم: والقرآن غير مخلوق لأنه قول الله، والله لا يقول لقوله: كن.\r\rالرد على الجهمية:\rويقال لهم: أليس لم يزل الله عالما بأوليائه وأعدائه، فلا بد من نعم، قيل لهم: فهل تقولون إنه لم يزل مريدا للتفرقة بين أوليائه وأعدائه؟ فإن قالوا: نعم، قيل لهم: فإذا كانت إرادة الله لم تزل فهي غير مخلوقة، وإذا كانت إرادته غير مخلوقة فلم لا قلتم: إن كلامه غير مخلوق؟ فإن قالوا: لا، نقول: لم يزل مريدا للتفريق بين أوليائه وأعدائه فقد زعموا أن الله لا يريد التفريق بين أوليائه وأعدائه، ونسبوه سبحانه إلى النقص - تعالى عن قول القدرية علوّا كبيرا.\rجواب: ويقال لهم: إن الشيء المخلوق إما أن يكون بدنا من الأبدان شخصا من الأشخاص، أو يكون نعتا من نعوت الأشخاص، فلا يجوز أن يكون كلام الله شخصا؛ لأن الأشخاص يجوز عليها الأكل والشرب والنكاح، ولا يجوز ذلك على كلام الله عز وجل، ولا يجوز أن يكون كلام الله نعتا لشخص مخلوق؛ لأن النعوت لا تبقى طرفة عين لأنها لا تحتمل البقاء، وهذا يوجب أن يكون كلام الله قد فني ومضى، فلما لم يجز أن يكون شخصا ولا نعتا لشخص لم يجز أن يكون مخلوقا، على أن الأشخاص يجوز أن تموت؛ فمن أثبت كلام الله شخصا مخلوقا لزمه أن يجوز الموت على كلام الله عز وجل وذلك مما لا يجوز، وأيضا فلا يجوز أن يكون كلام الله مخلوقا في شخص مخلوق كما لا يجوز أن يكون نعتا"], [173, "لشخص مخلوق، ولو كان مخلوقا في شخص ككلام الإنسان مفعولا فيه كان لا يمكن التفريق بين كلام الله وكلام الخلق إذا كانا مخلوقين في شخص مخلوق كما لا يجوز أن يكون علمه مخلوقا في شخص مخلوق.\rجواب: ويقال لهم أيضا: لو كان كلام الله مخلوقا لكان جسما أو نعتا لجسم، ولو كان جسما لجاز أن يكون متكلما، والله قادر على قلبهما، وفي هذا ما يلزمهم ويجب عليهم أن يجوزوا أن يقلب الله القرآن إنسانا أو جنيّا أو شيطانا - تعالى الله عز وجل أن يكون كلامه كذلك، ولو كان نعتا لجسم كالنعوت فالله قادر أن يجعلها أجساما فكان يجب على الجهمية أن يجوزوا أن يجعل القرآن جسما متجسدا يأكل ويشرب، وأن يجعله إنسانا ويميته، وهذا ما لا يجوز على كلامه عز وجل.\r***"], [174, "باب ما ذكر من الرواية في القرآن\rمسألة: "]], "pg": [170, 174]}, "إ.2.5": {"x": [[164, "قول لا إلى غاية، وذلك محال، وإذا استحال ذلك صح وثبت أن لله عز وجل قولا غير مخلوق.\rسؤال: فإن قال قائل: معنى قول الله أن يقول له: كن فيكون: إنما يكونه فيكون، قيل: الظاهر أن يقول له، ولا يجوز أن يكون قول الله للأشياء كلها كوني هو الأشياء؛ لأن هذا يوجب أن تكون الأشياء كلها كلام الله عز وجل، ومن قال ذلك أعظم الفرية لأنه يلزمه أن يكون كل شيء في العالم من إنسان وفرس وحمار وغير ذلك كلام الله، وفي هذا ما فيه.\rفلما استحال ذلك صح أن قول الله للأشياء كوني غيرها، وإذا كان غير المخلوقات فقد خرج كلام الله عز وجل عن أن يكون مخلوقا، ويلزم من أثبت كلام الله مخلوقا أن يثبت أن الله غير متكلم ولا قائل، وذلك فاسد كما يفسد أن يكون علم الله مخلوقا وأن يكون الله غير عالم؛ فلما كان الله عز وجل لم يزل عالما إذ لم يجز أن يكون لم يزل بخلاف العلم موصوفا استحال أن يكون لم يزل بخلاف العلم موصوفا؛ لأن خلاف الكلام الذي لا يكون معه كلام سكوت أو آفة، كما أن خلاف العلم الذي لا يكون معه علم جهل أو شك أو آفة، ويستحيل أن يوصف ربناعز وجل بخلاف العلم، ولذلك يستحيل أن يوصف بخلاف الكلام من السكوت والآفات؛ فوجب لذلك أن يكون لم يزل متكلما كما وجب\r__________\r(1) النحل: 40."], [165, "أن يكون لم يزل عالما.\rدليل آخر: وقال الله عز وجل: {قُلْ لَوْ كانَ الْبَحْرُ مِدادًا لِكَلِماتِ رَبِّي لَنَفِدَ الْبَحْرُ قَبْلَ أَنْ تَنْفَدَ كَلِماتُ رَبِّي} (1) فلو كانت البحار مدادا كتبت لنفدت البحار وتكسرت الأقلام ولم يلحق الفناء كلمات ربي كما لا يلحق الفناء علم الله عز وجل، ومن فني كلامه لحقته الآفات وجرى عليه السكوت، فلما لم يجز ذلك على ربناعز وجل صح أنه لم يزل متكلما، لأنه لو لم يكن متكلما وجب السكوت والآفات وتعالى ربنا عن قول الجهمية علوّا كبيرا.\r\rفصل: الجهينة\rوزعمت الجهمية كما زعمت النصارى؛ لأن النصارى زعمت أن كلمة الله حواها بطن مريم وزادت الجهمية عليهم فزعمت أن كلام الله مخلوق حل في شجرة وكانت الشجرة حاوية له، فلزمهم أن تكون الشجرة بذلك الكلام متكلما، ووجب عليهم أن مخلوقا من المخلوقين كلم موسى وأن الشجرة قالت: يا موسى {إِنَّنِي أَنَا اللهُ لا إِلهَ إِلاّ أَنَا فَاعْبُدْنِي} (2)، فلو كان كلام الله مخلوقا في شجرة لكان المخلوق قال: يا موسى! إِنَّنِي أَنَا اللهُ لا إِلهَ إِلاّ أَنَا فَاعْبُدْنِي، وقد قال الله عز وجل: {وَلكِنْ حَقَّ الْقَوْلُ مِنِّي لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنّاسِ أَجْمَعِينَ} (3) و كلام الله عز وجل من الله لا يجوز أن يكون كلامه الذي هو منه مخلوقا في شجرة مخلوقة كما لا يجوز أن يكون علمه الذي هو منه مخلوقا في غيره - تعالى الله عن ذلك علوّا كبيرا.\rجواب: ويقال لهم: كما لا يجوز أن يخلق الله عز وجل إرادته في بعض\r__________\r(1) الكهف: 109.\r(2) طه: 14.\r(3) السجدة: 13."], [166, "المخلوقات كذلك لا يجوز أن يخلق كلامه في بعض المخلوقات، ولو كانت إرادة الله مخلوقة في بعض المخلوقات لكان ذلك المخلوق هو المريد لها وذلك يستحيل، وكذلك يستحيل أن يخلق الله كلامه في مخلوق؛ لأن هذا يوجب أن ذلك المخلوق متكلم به، ويستحيل أن يكون كلام الله عز وجل كلاما للمخلوق.\rدليل آخر: ومما يبطل قولهم أن الله عز وجل قال مخبرا عن المشركين أنهم قالوا: {إِنْ هذا إِلاّ قَوْلُ الْبَشَرِ (25)} (1) يعني القرآن؛ فمن زعم أن القرآن مخلوق فقد جعله قولا للبشر، وهذا ما أنكره الله على المشركين، وأيضا فلو لم يكن الله متكلما حتى خلق الخلق ثم تكلم بعد ذلك لكانت الأشياء قد كانت لا عن أمره ولا عن قوله ولم يكن قائلا لها: كوني، وهذا رد للقرآن، والخروج عما عليه جمهور أهل الإسلام.\r\rفصل قول الجهمية: إن كلام الله مخلوق\rواعلموا - رحمكم الله - أن قول الجهمية: إن كلام الله مخلوق يلزمهم به أن يكون الله عز وجل لم يزل كالأصنام التي لا تنطق ولا تتكلم لو كان لم يزل غير متكلم؛ لأن الله عز وجل يخبر عن إبراهيم أنه قال لقومه لما قالوا له: {أَأَنْتَ فَعَلْتَ هذا بِآلِهَتِنا يا إِبْراهِيمُ (62) قالَ بَلْ فَعَلَهُ كَبِيرُهُمْ هذا فَسْئَلُوهُمْ إِنْ كانُوا يَنْطِقُونَ (63)} (2) فاحتج عليهم بأن الأصنام إذا لم تكن ناطقة متكلمة لم تكن آلهة، وأن الإله لا يكون غير ناطق ولا متكلم، فلما كانت الأصنام التي لا يستحيل أن يحييها الله وينطقها لا تكون آلهة فكيف يجوز أن يكون من يستحيل عليه الكلام في قدمه إلها - تعالى الله عن ذلك علوّا كبيرا، وإذا لم يجز أن يكون الله سبحانه في قدمه بمرتبة دون مرتبة الأصنام التي لا تنطق فقد وجب أن يكون لم يزل متكلما.\r__________\r(1) المدثر: 25.\r(2) الأنبياء: 62 - 63."], [167, "دليل آخر: وقد قال الله تعالى مخبرا عن نفسه أنه يقول: {لِمَنِ الْمُلْكُ الْيَوْمَ} (1) و جاءت الرواية أنه يقول هذا القول فلا يرد عليه أحد شيئا فيقول: {اللهُ الْواحِدُ الْقَهّارُ}؛ فإذا كان عز وجل قائلا مع فناء الأشياء إذ لا إنسان ولا ملك ولا حي ولا جان ولا شجر ولا مدر فقد صح أن كلام الله عز وجل خارج عن الخلق؛ لأنه يوجد ولا شيء من المخلوقات موجود.\rدليل آخر: وقد قال الله عز وجل: {وَكَلَّمَ اللهُ مُوسى تَكْلِيمًا} (2) و التكليم هو المشافهة بالكلام، ولا يجوز أن يكون كلام المتكلم حالاّ في غيره مخلوقا في شيء سواه كما لا يجوز ذلك في العلم.\rدليل آخر: وقال الله عز وجل: {قُلْ هُوَ اللهُ أَحَدٌ (1) اَللهُ الصَّمَدُ (2) لَمْ يَلِدْ وَلَمْ يُولَدْ (3) وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} (3) فكيف يكون القرآن مخلوقا وأسماء الله في القرآن؟، هذا يوجب أن تكون أسماء الله مخلوقة ولو كانت أسماؤه مخلوقة لكانت وحدانيته مخلوقة، وكذلك علمه وقدرته - تعالى الله عن ذلك علوّا كبيرا.\rدليل آخر: وقد قال الله تعالى: {تَبارَكَ اسْمُ رَبِّكَ} (4) و لا يقال للمخلوق:\rتبارك؛ فدل هذا على أن أسماء الله غير مخلوقة، وقال: {وَيَبْقى وَجْهُ رَبِّكَ} (5) فكما لا يجوز أن يكون وجه ربنا مخلوقا فكذلك لا تكون أسماؤه مخلوقة.\rدليل آخر: وقد قال الله عز وجل: {شَهِدَ اللهُ أَنَّهُ لا إِلهَ إِلاّ هُوَ وَالْمَلائِكَةُ وَأُولُوا الْعِلْمِ قائِمًا بِالْقِسْطِ‍} (6) و لا بد أن يكون شهد بهذه الشهادة وسمعها من\r__________\r(1) غافر: 16.\r(2) النساء: 164.\r(3) الإخلاص: 1 - 4.\r(4) الرحمن: 78.\r(5) الرحمن: 27.\r(6) آل عمران: 18."], [168, "نفسه؛ لأنه إن كان سمعها من مخلوق فليست شهادة له، وإذا كانت شهادة له وقد شهد بها فلا يخلو أن يكون شهد بها قبل كون المخلوقات أو بعد كون المخلوقات؛ فإن كان شهد بها بعد كون المخلوقات فلم تسبق شهادته لنفسه بإلهية الخلق، وكيف يكون ذلك كذلك وهذا يوجب أن التوحيد لم يكن يشهد به شاهد قبل الخلق؟ ولو استحالت الشهادة بالوحدانية قبل كون الخلق لاستحال إثبات التوحيد ووجوده، وأن يكون واحدا قبل الخلق لأن ما تستحيل الشهادة عليه فمستحيل؛ وإن كانت شهادته لنفسه بالتوحيد قبل الخلق فقد بطل أن يكون كلام الله عز وجل مخلوقا لأن كلامه شهادته.\rدليل آخر: ومما يدل على بطلان قول الجهمية وأن القرآن كلام الله غير مخلوق أن أسماء الله من القرآن، وقد قال عز وجل: {سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى (1) اَلَّذِي خَلَقَ فَسَوّى} (1) و لا يجوز أن يكون {اسْمَ رَبِّكَ الْأَعْلَى (1) الَّذِي خَلَقَ فَسَوّى} مخلوقا كما لا يجوز أن يكون {جَدُّ رَبِّنا} مخلوقا؛ قال الله في سورة الجن تَعالى جَدُّ رَبِّنا (2)، وكما لا يجوز أن تكون عظمته مخلوقة كذلك لا يجوز أن تكون كلامه مخلوقا.\rدليل آخر: وقد قال الله عز وجل: {وَما كانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللهُ إِلا وَحْيًا أَوْ مِنْ وَراءِ حِجابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ ما يَشاءُ} (3) فلو كان كلام الله لا يوجد إلا مخلوقا في شيء مخلوق لم يكن لاشتراط‍ هذه الوجوه معنى؛ لأن الكلام قد سمعه جميع الخلق ووجدوه بزعم الجهمية مخلوقا في غير الله عز وجل، وهذا يوجب إسقاط‍ مرتبة النبيين صلوات الله عليهم، ويجب عليهم إذا زعموا أن\r__________\r(1) الأعلى: 1 - 2.\r(2) الجن: 3.\r(3) الشورى: 51."], [169, "كلام الله لموسى خلقه في شجرة أن يكون من سمع كلام الله عز وجل من ملك أو من نبي أتى به من عند الله أفضل مرتبة في سماع الكلام من موسى؛ لأنهم سمعوه من نبي ولم يسمعه موسى من الله عز وجل وإنما سمعه من شجرة، وأن يزعموا أن اليهودي إذا سمع كلام الله من النبي أفضل مرتبة في هذا المعنى من موسى بن عمران؛ لأن اليهودي سمعه من نبي من أنبياء الله وموسى سمعه مخلوقا في شجرة، ولو كان مخلوقا في شجرة لم يكن مكلما لموسى من وراء حجاب؛ لأن من حضر الشجرة من الجن والإنس قد سمعوا الكلام من ذلك المكان، وكان سبيل موسى وغيره في ذلك سواء في أنه ليس كلام الله له من وراء حجاب.\rجواب: ثم يقال لهم: إذا زعمتم أن معنى أن الله عز وجل كلم موسى أنه خلق كلاما كلمه به في الشجرة، وقد خلق الله عندكم في الذراع كلاما لأن الذراع قالت لرسول الله صلّى الله عليه وسلّم: لا تأكلني فإني مسمومة (1)، فلزمكم أن ذلك الكلام الذي سمع النبي كلام الله عز وجل؛ فإن استحال أن يكون الله تكلم بذلك الكلام المخلوق فما أنكرتم من أنه مستحيل أن يخلق الله عز وجل كلامه في شجرة؛ لأن كلام المخلوق لا يكون كلاما؛ فإن كان كلام الله وكان معنى أن الله تكلم عندكم أنه خلق الكلام فيلزمكم أن يكون الله متكلما بالكلام الذي خلقه في الذراع.\rفإن أجابوا إلى ذلك قيل لهم: فالله عز وجل على قولكم هو القائل: لا تأكلني فإني مسمومة - تعالى الله عن قولكم وافترائكم عليه علوّا كبيرا.\rوإن قالوا: لا يجوز أن يكون كلام الله مخلوقا في ذراع، قيل لهم: وكذلك لا يجوز أن يكون كلام الله مخلوقا في شجرة.\r__________\r(1) أخرجه الطبراني في الكبير (35/ 2) من حديث عروة بن الزبير مرسلا. وقال الهيثمي في المجمع (225/ 6): «رواه الطبراني مرسلا، وفيه ابن لهيعة وفيه ضعف، وحديثه حسن». اه‍."], [170, "جواب: ثم يسألون عن الكلام الذي أنطق الله به الذئب لما أخبر عن نبوة النبي صلّى الله عليه وسلّم؛ فقال لهم: إذا كان الله عز وجل يتكلم بكلام يخلقه في غيره فما أنكرتم أن يكون الكلام الذي سمعه من الذئب كلاما لله، ويكون إعجازه يدل على أنه كلام الله، وفي هذا ما يجب عليهم أن الذئب لم يتكلم به وأنه كلام الله عز وجل؛ لأن كون الكلام من الذئب معجز كما أن كونه من الشجرة معجز؛ فإن كان الذئب متكلما بذلك الكلام المنقول فما أنكرتم أن الشجرة متكلمة بالكلام إن كان خلق في شجرة، وأن يكون المخلوق فيه قال: يا موسى! إني أنا الله عز وجل - تعالى الله عن ذلك علوّا كبيرا.\rجواب: ثم يقال لهم: إذا كان كلام الله عز وجل مخلوقا في غيره عندكم فما يؤمنكم أن يكون كل كلام تسمعونه مخلوقا في شيء - وهو حق - أن يكون كلام الله عز وجل.\rفإن قالوا: لا تكون الشجرة متكلمة لأن المتكلم لا يكون إلا حيّا، قيل لهم: ولا يجوز خلق الكلام في شجرة لأن من خلق الكلام فيه لا يكون إلا حيّا؛ فإن جاز أن يخلق الكلام فيما ليس بحي، فلم لا يجوز أن يتكلم من ليس بحي، ويقال لهم: ألا قلتم: إنه يقول: من ليس بحي؛ لأنه عز وجل أخبر أن السموات والأرض قالتا: أتينا طائعين.\rجواب: ثم يقال لهم: أليس قد قال الله عز وجل لإبليس: {وَإِنَّ عَلَيْكَ لَعْنَتِي إِلى يَوْمِ الدِّينِ} (1) فلا بد من نعم، ويقال لهم: فإذا كان كلام الله مخلوقا وكانت المخلوقات فانيات فيلزمكم إذا أفنى الله عز وجل الأشياء أن تكون اللعنة على إبليس قد فنيت؛ فيكون إبليس غير ملعون، وهذا ترك لدين المسلمين ورد لقول\r__________\r(1) ص: 78."], [171, "الله عز وجل: {وَإِنَّ عَلَيْكَ لَعْنَتِي إِلى يَوْمِ الدِّينِ}، وإذا كانت اللعنة باقية على إبليس إلى يوم الدين وهو يوم الجزاء وهو يوم القيامة؛ لأن الله عز وجل قال: {مالِكِ يَوْمِ الدِّينِ} (1) يعني يوم الجزاء ثم هي أبدا في النار، واللعنة كلام الله، وهو قوله: {عَلَيْكَ لَعْنَتِي} فقد وجب أن يكون كلام الله عز وجل لا يجوز عليه الفناء وأنه غير مخلوق؛ لأن المخلوقات يجوز عليها العدم؛ فإذا لم يجز ذلك على كلام الله عز وجل فهو غير مخلوق.\r\rالرد على الجهمية:\rثم يقال لهم: إذا كان غضب الله غير مخلوق وكذلك رضاه وسخطه فلم لا قلتم: إن كلامه غير مخلوق، ومن زعم أن غضب الله مخلوق لزمه أن غضب الله وسخطه على الكافرين يفنى، وأن رضاه عن الملائكة والنبيين يفنى حتى لا يكون راضيا عن أوليائه ولا ساخطا على أعدائه، وهذا هو الخروج عن الإسلام.\rويقال: خبرونا عن قول الله عز وجل: {إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} (2) أتزعمون أن قوله لشيء: «كن» مخلوق مراد لله.\rفإن قالوا: لا، قيل لهم: فما أنكرتم أن يكون كلام الله الذي هو القرآن غير مخلوق كما زعمتم أن قول الله للشيء: «كن» غير مخلوق.\rوإن زعموا أن قول الله للشيء: «كن» مخلوق، قيل لهم: فإن زعمتم أنه مخلوق مراد فقد قال الله عز وجل: {إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} فيلزمكم أن قوله للشيء: «كن» قد قال له: «كن»، وفي هذا ما يوجب أحد أمرين: إما أن يكون قول الله لغيره: «كن» غير مخلوق، أو يكون لكل قول\r__________\r(1) الفاتحة: 4.\r(2) النحل: 40."], [172, "قول لا إلى غاية، وذلك محال.\rفإن قالوا: إن لله قولا غير مخلوق، قيل لهم: فلم أنكرتم أن تكون إرادة الله للإيمان غير مخلوقة؟.\rثم يقال لهم: ما العلة لما قلتم: إن قول الله للشيء: «كن» غير مخلوق؟ فإن قالوا: لأن القول لا يقال له: كن، فيقال لهم: والقرآن غير مخلوق لأنه قول الله، والله لا يقول لقوله: كن.\r\rالرد على الجهمية:\rويقال لهم: أليس لم يزل الله عالما بأوليائه وأعدائه، فلا بد من نعم، قيل لهم: فهل تقولون إنه لم يزل مريدا للتفرقة بين أوليائه وأعدائه؟ فإن قالوا: نعم، قيل لهم: فإذا كانت إرادة الله لم تزل فهي غير مخلوقة، وإذا كانت إرادته غير مخلوقة فلم لا قلتم: إن كلامه غير مخلوق؟ فإن قالوا: لا، نقول: لم يزل مريدا للتفريق بين أوليائه وأعدائه فقد زعموا أن الله لا يريد التفريق بين أوليائه وأعدائه، ونسبوه سبحانه إلى النقص - تعالى عن قول القدرية علوّا كبيرا.\rجواب: ويقال لهم: إن الشيء المخلوق إما أن يكون بدنا من الأبدان شخصا من الأشخاص، أو يكون نعتا من نعوت الأشخاص، فلا يجوز أن يكون كلام الله شخصا؛ لأن الأشخاص يجوز عليها الأكل والشرب والنكاح، ولا يجوز ذلك على كلام الله عز وجل، ولا يجوز أن يكون كلام الله نعتا لشخص مخلوق؛ لأن النعوت لا تبقى طرفة عين لأنها لا تحتمل البقاء، وهذا يوجب أن يكون كلام الله قد فني ومضى، فلما لم يجز أن يكون شخصا ولا نعتا لشخص لم يجز أن يكون مخلوقا، على أن الأشخاص يجوز أن تموت؛ فمن أثبت كلام الله شخصا مخلوقا لزمه أن يجوز الموت على كلام الله عز وجل وذلك مما لا يجوز، وأيضا فلا يجوز أن يكون كلام الله مخلوقا في شخص مخلوق كما لا يجوز أن يكون نعتا"], [173, "لشخص مخلوق، ولو كان مخلوقا في شخص ككلام الإنسان مفعولا فيه كان لا يمكن التفريق بين كلام الله وكلام الخلق إذا كانا مخلوقين في شخص مخلوق كما لا يجوز أن يكون علمه مخلوقا في شخص مخلوق.\rجواب: ويقال لهم أيضا: لو كان كلام الله مخلوقا لكان جسما أو نعتا لجسم، ولو كان جسما لجاز أن يكون متكلما، والله قادر على قلبهما، وفي هذا ما يلزمهم ويجب عليهم أن يجوزوا أن يقلب الله القرآن إنسانا أو جنيّا أو شيطانا - تعالى الله عز وجل أن يكون كلامه كذلك، ولو كان نعتا لجسم كالنعوت فالله قادر أن يجعلها أجساما فكان يجب على الجهمية أن يجوزوا أن يجعل القرآن جسما متجسدا يأكل ويشرب، وأن يجعله إنسانا ويميته، وهذا ما لا يجوز على كلامه عز وجل.\r***"], [174, "باب ما ذكر من الرواية في القرآن\rمسألة: "]], "pg": [164, 174]}, "إ.2.6": {"x": [[174, "قال أبو بكر: أتيت أنا والعباس بن عبد العظيم العنبري أبا عبد الله أحمد بن حنبل؛ فسأل العباس بن عبد العظيم أبا عبد الله فقال له: قوم هاهنا قد حدثوا يقولون: القرآن لا مخلوق ولا غير مخلوق، فقال: هؤلاء أضر من الجهمية على الناس، ويلكم فإن لم تقولوا ليس مخلوقا فقولوا: مخلوق، قال أبو عبد الله: هؤلاء قوم سوء، فقال العباس: ما تقول يا أبا عبد الله؟ فقال: الذي أعتقد وأذهب إليه ولا أشك فيه أن القرآن غير مخلوق، ثم قال: سبحان الله، ومن شك في هذا؟ ثم تكلم أبو عبد الله مستعظما للشك في ذلك فقال: سبحان الله، أفي هذا شك؟ قال الله تبارك وتعالى {أَلا لَهُ الْخَلْقُ وَالْأَمْرُ} (1) و قال تعالى: {الرَّحْمنُ (1) عَلَّمَ الْقُرْآنَ (2) خَلَقَ الْإِنْسانَ} (2)، ففرق بين الإنسان وبين القرآن، فقال: علّم خلق؛ فجعل يعيدها علّم خلق أي فرّق بينهما.\rقال أبو عبد الله: القرآن من علم الله؛ ألا تراه يقول: {عَلَّمَ الْقُرْآنَ}، والقرآن فيه أسماء الله عز وجل، أي شيء يقولون؟ ألا يقولون: إن أسماء الله غير مخلوقة لم يزل الله قديرا عليما عزيزا حكيما سميعا بصيرا، لسنا نشك أن أسماء الله عز وجل غير مخلوقة، لسنا نشك أن علم الله غير مخلوق؛ فالقرآن من علم الله وفيه أسماء الله؛ فلا نشك أنه غير مخلوق، وهو كلام الله عز وجل ولم يزل الله به متكلما، ثم قال: وأي كفر أكفر من هذا؟ أو أي كفر أشر من هذا؟ إذا زعموا أن القرآن مخلوق فقد زعموا أن أسماء الله مخلوقة، وأن علم الله مخلوق، ولكن الناس يتهاونون بهذا ويقولون: إنما يقولون: القرآن مخلوق، ويتهاونون ويظنون أنه\r__________\r(1) الأعراف: 54.\r(2) الرحمن: 1 - 3."], [175, "هين، ولا يدرون ما فيه وهو الكفر، وأنا أكره أن أبوح بهذا لكل أحد وهم يسألون وأنا أكره الكلام في هذا، فبلغني أنهم يدعون أني أمسك، فقلت له: فمن قال: القرآن مخلوق، ولا يقول: إن أسماء الله مخلوقة ولا علمه ولم يزد على هذا أقول: هو كافر، فقال: هكذا هو عندنا.\rثم قال أبو عبد الله: نحن لا نحتاج أن نشك في هذا؛ القرآن عندنا فيه أسماء الله، وهو من علم الله؛ فمن قال: إنه مخلوق فهو عندنا كافر، فجعلت أردد عليه، فقال لي العباس وهو يسمع: سبحان الله أما يكفيك دون هذا؟ فقال أبو عبد الله: بلى.\rوذكر الحسين بن عبد الأول قال: سمعت وكيعا يقول: من قال: القرآن مخلوق فهو مرتد يستتاب فإن تاب وإلا قتل.\rوذكر محمد بن الصباح البزار قال علي بن الحسين بن سفيان قال: سمعت ابن المبارك يقول: إنا نستطيع أن نحكي كلام اليهود والنصارى، ولا نستطيع أن نحكي كلام الجهمية، قال محمد يقول: نخاف أن نكفر ولا نعلم.\rوذكر هارون بن إسحاق الهمداني عن أبي نعيم عن سليمان بن عيسى القاري عن سفيان الثوري قال لي حماد بن أبي سليمان: بلغ أبا حنيفة المشرك أني منه بريء (1). قال سليمان: ثم قال سفيان: لأنه كان يقول: القرآن مخلوق، وذكر سفيان بن وكيع قال سمعت عمر بن حماد بن أبي حنيفة قال أخبرني أبي قال: الكلام الذي استتاب منه ابن أبي ليلى أبا حنيفة هو قوله: القرآن مخلوق، قال: فتاب منه وطاف به في الخلق، قال أبي: فقلت له: كيف صرت إلى هذا؟ قال: خفت والله أن يقدم عليّ فأعطيته التقية.\rوذكر هارون بن إسحاق قال: سمعت إسماعيل بن أبي الحكم يذكر عن\r__________\r(1) أخرجه اللالكائي في شرح أصول اعتقاد أهل السنة (239/ 2)."], [176, "عمر بن عبيد الطنافسي أن حمادا - يعني ابن أبي سليمان - بعث إلى أبي حنيفة: إني بريء مما تقول إلا أن تتوب، وكان عنده ابن أبي عنبة قال: فقال: أخبرني جارك أن أبا حنيفة دعاه إلى ما استتيب منه بعد ما استتيب.\rوذكر عن أبي يوسف قال: ناظرت أبا حنيفة شهرين حتى رجع عن خلق القرآن، وقال سليمان بن حرب: القرآن غير مخلوق، وأخبر به من كتاب الله تعالى؛ قال الله عز وجل: {وَلا يُكَلِّمُهُمُ اللهُ وَلا يَنْظُرُ إِلَيْهِمْ} (1) و كلام الله ونظره واحد يعني غير مخلوق.\rوذكر الحسين بن عبد الأول: قال محمد بن (الحسين بن أبي يزيد) (2) الهمداني عن (عمرو بن قيس عن أبي قيس الملائي) (3) عن عطية عن أبي سعيد الخدري قال: "]], "pg": [174, 176]}, "إ.2.7": {"x": [[176, "قال رسول الله صلّى الله عليه وسلّم: «فضل كلام الله عزّ وجلّ على سائر الكلام كفضل الله على خلقه» (4).\rفهذا يثبت أن القرآن كلام الله عز وجل، وما كان كلاما لله لم يكن خلقا لله، وقد بيّن الله أن القرآن كلامه بقوله عز وجل: {حَتّى يَسْمَعَ كَلامَ اللهِ} (5) و دل على ذلك في مواضع من كتابه، وقد قال الله عز وجل مخبرا أن الله كلم موسى تكليما.\rوروى وكيع عن الأعمش عن خيثمة عن عدي بن حاتم قال: قال رسول\r__________\r(1) آل عمران: 77.\r(2) الصواب: «الحسن بن أبي يزيد».\r(3) الصواب: «عمرو بن قيس أبي عبد الله الملائي».\r(4) أخرجه الترمذي ح (2926) من طريق شهاب بن عباد عن محمد بن الحسن بن أبي يزيد به، وقال: «حديث حسن غريب». اه‍. قال ابن حجر فى الفتح (66/ 9): «رجاله ثقات إلا عطية العوفى ففيه ضعف». اه‍.\r(5) التوبة: 6."], [177, "الله صلّى الله عليه وسلّم: «ما منكم من أحد إلا سيكلمه ربّه ليس بينه وبينه ترجمان» (1). ومما يبين أن الله عز وجل متكلم وأن له كلاما ما رواه عفان قال حماد بن سلمة عن الأشعث الحدّاني عن شهر بن حوشب قال: فضل كلام الله عز وجل على سائر الكلام كفضل الله على خلقه (2).\rوروى يعلى بن المنهال السعدي قال إسحاق بن سليمان الرازي: قال الجراح بن الضحاك الكندي عن علقمة بن مرثد عن أبي عبد الرحمن السلمي عن عثمان بن عفان رضي الله عنه قال: قال رسول الله صلّى الله عليه وسلّم: «"]], "pg": [176, 177]}, "إ.2.8": {"x": [[177, "أفضلكم من تعلّم القرآن وعلّمه» (3)، وقال: «إن فضل القرآن على سائر الكلام كفضل الله على خلقه» (4). وذلك أنه منه.\rوذكر سنيد بن داود قال أبو سفيان عن معمر عن قتادة قوله تعالى: {وَلَوْ أَنَّ ما فِي الْأَرْضِ مِنْ شَجَرَةٍ أَقْلامٌ وَالْبَحْرُ يَمُدُّهُ مِنْ بَعْدِهِ سَبْعَةُ أَبْحُرٍ ما نَفِدَتْ كَلِماتُ اللهِ} (5) ... الآية، وذكر هارون بن معروف: قال جرير بن منصور عن هلال بن يساف عن فروة بن نوفل قال: كنت جارا لخباب بن الأرت فقال لي: يا هذا تقرب\r__________\r(1) أخرجه ابن ماجه ح (1843) من طريق وكيع به.\rوأخرجه البخاري ح (7512، 7443، 6539)، ومسلم ح (67/ 1016) من طرق أخرى عن الأعمش به.\r(2) أخرجه الدارمي في سننه ح (3357) من طريق سليمان بن حرب، وأبو داود في المراسيل ح (537) من طريق موسى بن إسماعيل، كلاهما عن حماد بن سلمة عن أشعث الحداني عن شهر بن حوشب عن النبي صلّى الله عليه وسلّم مرسلا.\r(3) أخرجه البخاري ح (5028) من طريق سفيان الثوري عن علقمة بن مرثد به.\r(4) أخرجه الترمذي ح (2926)، والبيهقي في الشعب ح (2015) من حديث أبي سعيد الخدري، واللفظ‍ للبيهقي، وقال الترمذي: «حديث حسن غريب». اه‍. وقال ابن حجر فى الفتح (66/ 9): «رجاله ثقات إلا عطية العوفى ففيه ضعف». اه‍.\r(5) لقمان: 27."], [178, "إلى الله عز وجل بما استطعت، ولن يتقرب إلى الله بشيء أحب إليه من كلامه (1).\rوروي عن ابن عباس في قوله عز وجل: {قُرْآنًا عَرَبِيًّا غَيْرَ ذِي عِوَجٍ} (2) قال: غير مخلوق (3). وذكر الليث بن يحيى قال: حدثني إبراهيم بن أبي الأشعث قال: سمعت مؤمل بن إسماعيل عن الثوري قال: من زعم أن القرآن مخلوق فقد كفر، وصحت الرواية عن جعفر بن محمد أن القرآن لا خالق ولا مخلوق (4)، وروي ذلك عن عمه زيد بن علي وعن جده علي بن الحسين (5).\rومن قال: إن القرآن غير مخلوق وأن من قال بخلقه كافر من العلماء وحملة الآثار ونقلة الأخبار لا يحصون كثرة منهم: الحمادان والثوري وعبد العزيز بن أبي سلمة ومالك بن أنس والشافعي وأصحابه والليث بن سعد وسفيان بن عيينة وهشام وعيسى بن يونس وحفص بن غياث وسعد بن عامر وعبد الرحمن بن مهدي وأبو بكر بن عياش ووكيع وأبو عاصم النبيل ويعلى بن عبيد ومحمد بن يوسف وبشر بن المفضل وعبد الله بن داود وسلام بن أبي مطيع وابن المبارك وعلي بن عاصم وأحمد بن يونس وأبو نعيم وقبيصة بن عقبة وسليمان بن داود وأبو عبيد القاسم بن سلام ويزيد بن هارون وغيرهم، ولو تتبعنا ذكر من يقول بذلك لطال الكلام بذكرهم، وفيما ذكرنا من ذلك مقنع، والحمد لله رب العالمين.\r__________\r(1) أخرجه البيهقي في الشعب ح (2020) من طريق إسحاق بن راهويه عن جرير به.\r(2) الزمر: 28.\r(3) أخرجه الآجري في الشريعة (ص 75)، والبيهقي في الأسماء والصفات ح (518).\r(4) أخرجه عبد الله بن أحمد في السنة ح (134، 133، 132)، واللالكائي في شرح أصول اعتقاد أهل السنة (241/ 2 - 243).\r(5) أخرجه عبد الله بن أحمد في مسنده ح (135)، واللالكائي في شرح أصول اعتقاد أهل السنة (237/ 2)."], [179, "وقد احتججنا لصحة قولنا: إن القرآن غير مخلوق من كتاب الله عز وجل وما تضمنه من البرهان وأوضحه من البيان، ولم نجد أحدا ممن تحمل عنه الآثار وتنقل عنه الأخبار ويأتم به المؤتمون من أهل العلم يقول بخلق القرآن، وإنما قال ذلك رعاع الناس وجهال من جهالهم لا موقع لقولهم، والحجاج الذي قدمناه في ذلك يأتي على كثير من قولهم ودفع باطلهم، والحمد لله على قوة الحق حمدا كثيرا.\r***"]], "pg": [177, 179]}, "إ.2.9": {"x": [[180, "باب الكلام على من وقف في القرآن وقال: لا أقول إنه مخلوق ولا أقول إنه غير مخلوق\rجواب: يقال لهم: لم زعمتم ذلك وقلتموه؟ فإن قالوا: قلنا ذلك لأن الله لم يقل في كتابه إنه مخلوق ولا قاله رسول الله صلّى الله عليه وسلّم ولا أجمع المسلمون عليه، ولم يقل في كتابه إنه غير مخلوق ولا قال ذلك رسوله ولا أجمع عليه المسلمون؛ فوقفنا لذلك، ولم نقل: إنه مخلوق ولا إنه غير مخلوق؛ يقال لهم: فهل قال الله عز وجل لكم في كتابه: قفوا فيه ولا تقولوا: إنه غير مخلوق، وقال لكم رسول الله صلّى الله عليه وسلّم: توقفوا عن أن تقولوا: إنه غير مخلوق، وهل أجمع المسلمون على التوقف عن القول إنه غير مخلوق؟ فإن قالوا: «نعم» بهتوا، وإن قالوا: «لا»، قيل لهم: فلا تقفوا عن أن تقولوا غير مخلوق بمثل الحجة التي بها ألزمتم أنفسكم التوقف.\rثم يقال لهم: ولم أبيتم أن يكون في كتاب الله ما يدل على أن القرآن غير مخلوق؟ فإن قالوا: لم نجده، قيل لهم: ولم زعمتم أنكم إذا لم تجدوه في القرآن فليس موجودا فيه، ثم إنا نوجدهم ذلك ونتلو عليهم الآيات التي احتججنا بها في كتابنا هذا، واستدللنا على أن القرآن غير مخلوق كقوله عز وجل: {أَلا لَهُ الْخَلْقُ وَالْأَمْرُ} وكقوله: {إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ} وكقوله: {قُلْ لَوْ كانَ الْبَحْرُ مِدادًا لِكَلِماتِ رَبِّي} وسائر ما احتججنا في ذلك من آي القرآن، ويقال لهم: يلزمكم أن تقفوا في كل ما اختلف الناس فيه ولا تقدموا في ذلك على قول، فإن جاز لكم أن تقولوا ببعض تآويل المسلمين إذا دل على صحتها دليل فلم لا قلتم إن القرآن غير مخلوق بالحجج التي ذكرناها في كتابنا هذا قبل هذا الموضع.\rسؤال: فإن قال قائل: حدثونا: أتقولون إن كلام الله في اللوح المحفوظ؟ قيل له: كذلك نقول؛ لأن الله عز وجل قال: {بَلْ هُوَ قُرْآنٌ مَجِيدٌ (21) فِي لَوْحٍ"], [181, "مَحْفُوظٍ‍} (1) فالقرآن في اللوح المحفوظ‍ وهو في صدور الذين أوتوا العلم؛ قال الله عز وجل: {بَلْ هُوَ آياتٌ بَيِّناتٌ فِي صُدُورِ الَّذِينَ أُوتُوا الْعِلْمَ} (2) وهو متلو بالألسنة قال الله تعالى: {لا تُحَرِّكْ بِهِ لِسانَكَ} (3) و القرآن مكتوب في مصاحفنا في الحقيقة محفوظ‍ في صدورنا في الحقيقة متلو بألسنتنا في الحقيقة مسموع لنا في الحقيقة كما قال عز وجل: {فَأَجِرْهُ حَتّى يَسْمَعَ كَلامَ اللهِ}.\rسؤال: فإن قال: حدثونا عن اللفظ‍ بالقرآن كيف تقولون فيه؟ قيل له: القرآن يقرأ في الحقيقة ويتلى ولا يجوز أن يقال: يلفظ‍ به؛ لأن القائل لا يجوز له أن يقول: إنه كلام ملفوظ‍ به؛ لأن العرب إذا قال قائلهم: «لفظت باللقمة من فمي» معناه رميت بها، وكلام الله عز وجل لا يقال: يلفظ‍ به وإنما يقال: يقرأ ويتلى ويكتب ويحفظ‍، وإنما قال قوم: لفظنا بالقرآن؛ ليثبتوا أنه مخلوق ويزينوا بدعتهم وقولهم بخلقه فدلسوا كفرهم على من لم يقف على معناهم، فلما وقفنا على معناهم أنكرنا قولهم، ولا يجوز أن يقال: إن شيئا من القرآن مخلوق؛ لأن القرآن بكامله غير مخلوق.\rسؤال: إن قال قائل: أليس قد قال الله تعالى: {ما يَأْتِيهِمْ مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ إِلاَّ اسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ} (4) قيل له: الذكر الذي عناه الله عز وجل ليس هو القرآن بل هو كلام الرسول عليه السّلام ووعظه إياهم، وقد قال الله تعالى لنبيه: {وَذَكِّرْ فَإِنَّ الذِّكْرى تَنْفَعُ الْمُؤْمِنِينَ} (5) وقد قال الله تعالى: {ذِكْرًا (10) رَسُولًا} (6) فسمى الرسول ذكرا، والرسول محدث، وأيضا فإن الله عز وجل قال:\r__________\r(1) البروج: 21 - 22.\r(2) العنكبوت: 49.\r(3) القيامة: 16.\r(4) الأنبياء: 2.\r(5) الذاريات: 55.\r(6) الطلاق: 10 - 11."], [182, "{ما يَأْتِيهِمْ مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ إِلاَّ اسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ} (1) يخبر أنهم لا يأتيهم ذكر محدث إلا استمعوه وهم يلعبون، ولم يقل: لا يأتيهم ذكر إلا كان محدثا، وإذا لم يقل هذا لم يوجب أن يكون القرآن محدثا، ولو قال قائل: ما يأتيهم رجل من التميميين يدعوهم إلى الحق إلا أعرضوا عنه - لم يوجب هذا القول أنه لا يأتيهم رجل إلا كان تميميّا، فكذلك القول فيما سألونا عنه.\rسؤال: وإن سألونا عن قول الله عز وجل {قُرْآنًا عَرَبِيًّا} (2) قيل لهم: الله عز وجل أنزله وليس مخلوقا، فإن قالوا: فقد قال الله: {وَأَنْزَلْنَا الْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ} (3) و الحديد مخلوق، قيل لهم: الحديد جسم موات وليس يجب إذا كان القرآن منزلا أن يكون جسما مواتا، ولذلك لا يجب إذا كان القرآن منزلا أن يكون مخلوقا وإن كان الحديد مخلوقا.\rجواب: ويقال لهم: قد أمرنا الله عز وجل أن نستعيذ به وهو غير مخلوق، وأمر أن نستعيذ بكلمات الله التامات، وإذا لم نؤمر أن نستعيذ بمخلوق من المخلوقات، وأمرنا أن نستعيذ بكلام الله فقد وجب أن كلام الله غير مخلوق.\r***\r__________\r(1) الأنبياء: 2.\r(2) الزمر: 28.\r(3) الحديد: 25."], [183, "باب ذكر الاستواء على العرش\r"]], "pg": [180, 183]}, "إ.3.1": {"x": [[183, "إن قال قائل: ما تقولون في الاستواء؟ قيل له: نقول: إن الله عز وجل مستو على عرشه كما قال: {الرَّحْمنُ عَلَى الْعَرْشِ اسْتَوى} (1) و قد قال الله عز وجل: {إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ} (2) وقال: {بَلْ رَفَعَهُ اللهُ إِلَيْهِ} (3) و قال عز وجل: {يُدَبِّرُ الْأَمْرَ مِنَ السَّماءِ إِلَى الْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ} (4) وقال حكاية عن فرعون: {يا هامانُ ابْنِ لِي صَرْحًا لَعَلِّي أَبْلُغُ الْأَسْبابَ (36) أَسْبابَ السَّماواتِ فَأَطَّلِعَ إِلى إِلهِ مُوسى وَإِنِّي لَأَظُنُّهُ كاذِبًا} (5) كذب موسى عليه السّلام في قوله: إن الله عز وجل فوق السموات، وقال عز وجل: {أَأَمِنْتُمْ مَنْ فِي السَّماءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ} (6) فالسموات فوقها العرش؛ فلما كان العرش فوق السموات قال: {أَأَمِنْتُمْ مَنْ فِي السَّماءِ} لأنه مستو على العرش الذي فوق السموات، وكل ما علا فهو سماء؛ فالعرش أعلى السموات، وليس إذا قال: {أَأَمِنْتُمْ مَنْ فِي السَّماءِ} يعني جميع السموات، وإنما أراد العرش الذي هو أعلى السموات، ألا ترى أن الله عز وجل ذكر السموات فقال: {وَجَعَلَ الْقَمَرَ فِيهِنَّ نُورًا} (7)، ولم يرد أن القمر يملؤهن جميعا وأنه فيهن جميعا، ورأينا المسلمين جميعا يرفعون أيديهم إذا دعوا نحو السماء لأن الله عز وجل مستو على العرش الذي هو فوق السموات، فلو لا أن الله عز وجل على العرش لم يرفعوا أيديهم نحو العرش كما لا يحطونها\r__________\r(1) طه: 5.\r(2) فاطر: 10.\r(3) النساء: 158.\r(4) السجدة: 5.\r(5) غافر: 36 - 37.\r(6) الملك: 16.\r(7) نوح: 16."], [184, "إذا دعوا إلى الأرض.\rسؤال: وقد قال قائلون من المعتزلة والجهمية والحرورية: إن قول الله عز وجل: {الرَّحْمنُ عَلَى الْعَرْشِ اسْتَوى} (1) أنه استولى وملك وقهر، وأن الله عز وجل في كل مكان، وجحدوا أن يكون الله عز وجل على عرشه كما قال أهل الحق، وذهبوا في الاستواء إلى القدرة؛ ولو كان هذا كما ذكروه كان لا فرق بين العرش والأرض السابعة؛ فالله سبحانه قادر عليها وعلى الحشوش وعلى كل ما في العالم؛ فلو كان الله مستويا على العرش بمعنى الاستيلاء وهوعز وجل مستول على الأشياء كلها لكان مستويا على العرش وعلى الأرض وعلى السماء وعلى الحشوش والأقذار؛ لأنه قادر على الأشياء مستول عليها، وإذا كان قادرا على الأشياء كلها ولم يجز عند أحد من المسلمين أن يقول: إن الله عز وجل مستو على الحشوش والأخلية لم يجز أن يكون الاستواء على العرش الاستيلاء الذي هو عام في الأشياء كلها، ووجب أن يكون معناه استواء يختص العرش دون الأشياء كلها، وزعمت المعتزلة والحرورية والجهمية أن الله عز وجل في كل مكان فلزمهم أنه في بطن مريم وفي الحشوش والأخلية، وهذا خلاف الدين - تعالى الله عن قولهم.\rجواب: ويقال لهم: إذا لم يكن مستويا على العرش بمعنى يختص العرش دون غيره كما قال ذلك أهل العلم ونقلة الآثار وحملة الأخبار، وكان الله عز وجل في كل مكان فهو تحت الأرض التي السماء فوقها، وإذا كان تحت الأرض والأرض فوقه والسماء فوق الأرض ففي هذا ما يلزمكم أن تقولوا: إن الله تحت التحت والأشياء فوقه، وإنه فوق الفوق والأشياء تحته، وفي هذا ما يوجب أنه تحت ما هو فوقه وفوق ما هو تحته، وهذا المحال المتناقض - تعالى الله عن افترائكم عليه علوّا كبيرا.\r__________\r(1) طه: 5."], [185, "دليل آخر: ومما يؤكد أن الله عز وجل مستو على عرشه دون الأشياء كلها ما نقله أهل الرواية عن رسول الله صلّى الله عليه وسلّم، روى عفان عن حماد بن سلمة قال: ثنا عمرو بن دينار عن نافع بن جبير عن أبيه أن النبي صلّى الله عليه وسلّم قال: «ينزل الله عز وجل كلّ ليلة إلى السماء الدنيا فيقول: هل من سائل فأعطيه؟ هل من مستغفر فأغفر له؟ حتّى يطلع الفجر» (1)، وروى عبد الله بن بكر قال: ثنا هشام بن أبي عبد الله عن يحيى بن أبي كثير عن أبي جعفر أنه سمع أبا هريرة قال: قال رسول الله صلّى الله عليه وسلّم: «"]], "pg": [183, 185]}, "إ.3.2": {"x": [[185, "إذا بقي ثلث الليل ينزل الله تبارك وتعالى فيقول: من ذا الذي يدعوني فأستجيب له؟ من ذا الذي يستكشف الضّرّ فأكشفه عنه؟ من ذا الذي يسترزقني فأرزقه؟ حتّى ينفجر الفجر» (2).\rوروى عبد الله بن بكر السهمي قال: ثنا هشام بن أبي عبد الله عن يحيى بن أبي كثير عن هلال بن أبي ميمونة قال: "]], "pg": [185, 185]}, "إ.3.3": {"x": [[185, "ثنا عطاء بن يسار أن رفاعة الجهني حدثه قال: قفلنا مع رسول الله صلّى الله عليه وسلّم حتى إذا كنا بالكديد - أو قال بقديد - فحمد الله وأثنى عليه ثم قال: «إذا مضى ثلث الليل - أو قال: ثلثا الليل - نزل الله عز وجل إلى السماء فيقول: من ذا الذي يدعوني أستجب له؟ من ذا الذي يستغفرني أغفر له؟ من ذا الذي يسألني أعطه؟ حتّى ينفجر الفجر» (3).\r__________\r(1) أخرجه أحمد في مسنده (81/ 4) من طريق عفان ومن طريق أسود بن عامر، والنسائي في الكبرى ح (10321) من طريق يحيى بن حسان، ثلاثتهم عن حماد بن سلمة به. وقال الهيثمي في المجمع (235/ 10): «رواه أحمد والبزار وأبو يعلى ورجالهم رجال الصحيح». اه‍.\r(2) أخرجه أحمد في مسنده (521، 258/ 2)، والنسائي في السنن الكبرى ح (10311، 10310) من طرق عن هشام بن أبي عبد الله به. وقال الهيثمي في المجمع (236/ 10): «رواه أحمد ورجاله رجال الصحيح». اه‍.\r(3) أخرجه ابن ماجه ح (1367)، وأحمد في مسنده (16/ 4)، وصححه ابن حبان ح (212) من طرق عن يحيى بن أبي كثير به."], [186, "دليل آخر: وقال الله عز وجل: {يَخافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ} (1) و قال تَعْرُجُ الْمَلائِكَةُ وَالرُّوحُ إِلَيْهِ (2) و قال: {ثُمَّ اسْتَوى إِلَى السَّماءِ وَهِيَ دُخانٌ} (3) و قال: {ثُمَّ اسْتَوى عَلَى الْعَرْشِ الرَّحْمنُ فَسْئَلْ بِهِ خَبِيرًا (59)} (4) و قال: {ثُمَّ اسْتَوى عَلَى الْعَرْشِ ما لَكُمْ مِنْ دُونِهِ مِنْ وَلِيٍّ وَلا شَفِيعٍ} (5) فكل ذلك يدل على أنه تعالى في السماء مستو على عرشه، والسماء بإجماع الناس ليست الأرض؛ فدل على أن الله تعالى منفرد بوحدانيته مستو على عرشه.\rدليل آخر: وقال جل وعز: {وَجاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا} (6) و قال: {هَلْ يَنْظُرُونَ إِلاّ أَنْ يَأْتِيَهُمُ اللهُ فِي ظُلَلٍ مِنَ الْغَمامِ (7) و قال: ثُمَّ دَنا فَتَدَلّى (8) فَكانَ قابَ قَوْسَيْنِ أَوْ أَدْنى (9) فَأَوْحى إِلى عَبْدِهِ ما أَوْحى (10) ما كَذَبَ الْفُؤادُ ما رَأى (11) أَفَتُمارُونَهُ عَلى ما يَرى} (8) إلى قوله: {لَقَدْ رَأى مِنْ آياتِ رَبِّهِ الْكُبْرى} وقال عز وجل لعيسى ابن مريم عليه السّلام: {إِنِّي مُتَوَفِّيكَ وَرافِعُكَ إِلَيَّ} (9)، وقال: {وَما قَتَلُوهُ يَقِينًا (157) بَلْ رَفَعَهُ اللهُ إِلَيْهِ} (10) و أجمعت الأمة على أن الله عز وجل رفع عيسى إلى السماء، ومن دعاء أهل الإسلام جميعا إذا هم رغبوا إلى الله عز وجل في الأمر النازل بهم يقولون جميعا: يا ساكن العرش، ومن حلفهم جميعا: لا والذي\r__________\r(1) النحل: 50.\r(2) المعارج: 4.\r(3) فصلت: 11.\r(4) الفرقان: 59.\r(5) السجدة: 4.\r(6) الفجر: 22.\r(7) البقرة: 210.\r(8) النجم: 8 - 12.\r(9) آل عمران: 55.\r(10) النساء: 157 - 158."], [187, "احتجب بسبع سموات.\rدليل آخر: وقال الله عز وجل: {وَما كانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللهُ إِلاّ وَحْيًا أَوْ مِنْ وَراءِ حِجابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ ما يَشاءُ} وقد خصت الآية البشر دون غيرهم ممن ليس من جنس البشر، ولو كانت الآية عامة للبشر وغيرهم كان أبعد من الشبهة وإدخال الشك على من يسمع الآية أن يقول: ما كان لأحد أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا فيرتفع الشك والحيرة من أن يقول: ما كان لجنس من الأجناس أن أكلمه إلا وحيا أو من وراء حجاب أو أرسل رسولا، وننزل أجناسا لم يعمهم بالآية؛ فدل ما ذكرنا على أنه خص البشر دون غيرهم.\rدليل آخر: وقال عز وجل: {ثُمَّ رُدُّوا إِلَى اللهِ مَوْلاهُمُ الْحَقِّ} (1) و قال: {وَلَوْ تَرى إِذْ وُقِفُوا عَلى رَبِّهِمْ} (2) و قال: {وَلَوْ تَرى إِذِ الْمُجْرِمُونَ ناكِسُوا رُؤُسِهِمْ عِنْدَ رَبِّهِمْ} (3) و قال عز وجل: {وَعُرِضُوا عَلى رَبِّكَ صَفًّا} (4) كل ذلك يدل على أنه ليس في خلقه ولا خلقه فيه، وأنه مستو على عرشه بلا كيف ولا استقرار - وتعالى عما يقول الظالمون علوّا كبيرا، فلم يثبتوا له في وصفهم حقيقة، ولا أوجبوا بذكرهم إياه وحدانية؛ إذ كل كلامم يئول إلى التعطيل، وجميع أوصافهم تدل على النفي؛ يريدون بذلك - زعموا - التنزيه ونفي التشبيه، فنعوذ بالله من تنزيه يوجب النفي أو التعطيل.\r__________\r(1) الأنعام: 62.\r(2) الأنعام: 30.\r(3) السجدة: 12.\r(4) الكهف: 48."], [188, "دليل آخر: قال الله عز وجل: {اللهُ نُورُ السَّماواتِ وَالْأَرْضِ (1) فسمى نفسه نورا، والنور عند الأمة لا يخلو من أن يكون أحد معنيين: إما يكون نورا يسمع أو نورا يرى، فمن زعم أن الله يسمع ولا يرى فقد أخطأ في نفيه رؤية ربه وتكذيبه بكتابه وقول نبيه صلّى الله عليه وسلّم، وروت العلماء عن عبد الله بن عباس أنه قال: تفكروا في خلق الله عز وجل ولا تفكروا في الله عز وجل، فإن بين كرسيه إلى السماء ألف عام، والله عز وجل فوق ذلك (2).\rدليل آخر: وروت العلماء عن النبي صلّى الله عليه وسلّم أنه قال: «إنّ العبد لا تزول قدماه من بين يدي الله عز وجل حتّى يسأله عن علمه» (3)، وروت العلماء أن رجلا أتى النبي صلّى الله عليه وسلّم بأمة سوداء فقال: يا رسول الله! إني أريد أن أعتقها في كفارة فهل يجوز عتقها؟ فقال لها النبي صلّى الله عليه وسلّم: «أين الله؟» قالت: في السماء، قال: «فمن أنا؟» قالت: أنت رسول الله، فقال النبي صلّى الله عليه وسلّم: «أعتقها فإنها مؤمنة» (4)، وهذا يدل على أن الله عز وجل على عرشه فوق السماء.\r***\r__________\r(1) النور: 35.\r(2) أخرجه ابن بطة في الإبانة عن شريعة الفرقة الناجية ح (108) بنحوه.\r(3) أخرجه الترمذي ح (2417) من حديث أبي برزة الأسلمي، وقال: «حديث حسن صحيح». اه‍.\r(4) أخرجه مسلم ح (537) من حديث معاوية بن الحكم السلمي به."]], "pg": [185, 188]}, "إ.3.4": {"x": [[189, "باب الكلام في الوجه والعينين والبصر واليدين\rقال الله تبارك وتعالى: {كُلُّ شَيْءٍ هالِكٌ إِلاّ وَجْهَهُ} (1) و قال عز وجل:\r{وَيَبْقى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالْإِكْرامِ} (2) فأخبر أن له وجها لا يفنى ولا يلحقه الهلاك، وقال عز وجل: {تَجْرِي بِأَعْيُنِنا} (3) و قال: {وَاصْنَعِ الْفُلْكَ بِأَعْيُنِنا وَوَحْيِنا} (4) فأخبرعز وجل أن له وجها وعينا لا يكيف ولا يحد، وقال عز وجل: {وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنا} (5) و قال: {وَلِتُصْنَعَ عَلى عَيْنِي} (6) و قال عز وجل: {وَكانَ اللهُ سَمِيعًا بَصِيرًا} (7) و قال لموسى وهارون: {إِنَّنِي مَعَكُما أَسْمَعُ وَأَرى} (8) فأخبر عن سمعه وبصره ورؤيته، ونفت الجهمية أن يكون لله وجه كما قال، وأبطلوا أن يكون له سمع وبصر وعين، ووافقوا النصارى لأن النصارى لم تثبت الله سميعا بصيرا إلا على معنى أنه عالم، وكذلك قالت الجهمية؛ ففي الحقيقة قول الجهمية أنهم قالوا: نقول: إن الله عالم، ولا نقول: سميع بصير على غير معنى عالم، وكذلك قول النصارى.\rوقالت الجهمية: إن الله لا علم له ولا قدرة ولا سمع له ولا بصر، وإنما قصدوا إلى تعطيل التوحيد والتكذيب بأسماء الله عز وجل؛ فأعطوا ذلك لفظا\r__________\r(1) القصص: 88.\r(2) الرحمن: 27.\r(3) القمر: 14.\r(4) هود: 37.\r(5) الطور: 48.\r(6) طه: 39.\r(7) النساء: 134.\r(8) طه: 46."], [190, "ولم يحصلوا قولا في المعنى، ولو لا أنهم خافوا السيف لأفصحوا بأن الله غير سميع ولا بصير ولا عالم، ولكن خوف السيف منعهم من إظهار زندقتهم.\rوزعم شيخ منهم مقدم أن علم الله هو الله، وأن الله عز وجل علم؛ فنفى العلم من حيث أوهم أنه أثبته حتى ألزم أن يقول: يا علم اغفر لي؛ إذ كان علم الله عنده هو الله، وكان الله على قياسه علما وقدرة - تعالى الله عن ذلك علوّا كبيرا.\rقال أبو الحسن علي بن إسماعيل الأشعري: بالله نستهدي وإياه نستكفي، ولا حول ولا قوة إلا بالله وهو المستعان، أما بعد! فمن سألنا فقال: أتقولون إن لله سبحانه وجها؟ قيل له: نقول ذلك خلافا لما قاله المبتدعون، وقد دل على ذلك قوله عز وجل: {وَيَبْقى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالْإِكْرامِ.\rسؤال: فإن سألنا: أتقولون إن لله يدين؟ قيل: نقول ذلك، وقد دل عليه قوله عز وجل: {يَدُ اللهِ فَوْقَ أَيْدِيهِمْ} (1) و قوله عز وجل: {لِما خَلَقْتُ بِيَدَيَّ} (2)؛ وروي "]], "pg": [189, 190]}, "إ.3.5": {"x": [[190, "عن النبي صلّى الله عليه وسلّم أنه قال: «إنّ الله مسح ظهر آدم بيده فاستخرج منه ذرّيّته» (3)، فثبتت اليد، وقوله عز وجل: {لِما خَلَقْتُ بِيَدَيَّ} وقد جاء في الخبر المأثور عن النبي صلّى الله عليه وسلّم أن الله خلق آدم بيده، وخلق جنة عدن بيده، وكتب التوراة بيده، وغرس شجرة طوبى بيده، وقال عز وجل: {بَلْ يَداهُ مَبْسُوطَتانِ} (4)\r__________\r(1) الفتح: 10.\r(2) ص: 75.\r(3) أخرجه أبو داود ح (4703)، والترمذي ح (3075)، وصححه ابن حبان ح (6166)، والحاكم في المستدرك ح (4001، 3256، 74) من رواية مسلم بن يسار عن عمر به، وقال الترمذي: «حديث حسن، ومسلم بن يسار لم يسمع من عمر، وقد ذكر بعضهم في هذا الإسناد بين مسلم بن يسار وبين عمر رجلا مجهولا». اه‍.\r(4) المائدة: 64."], [191, "وجاء عن النبي صلّى الله عليه وسلّم أنه قال: «"]], "pg": [190, 191]}, "إ.3.6": {"x": [[191, "كلتا يديه يمين» (1)، وقال عز وجل: {لَأَخَذْنا مِنْهُ بِالْيَمِينِ} (2) و ليس يجوز في لسان العرب ولا في عادة أهل الخطاب أن يقول القائل: عملت كذا بيدي، ويعني به النعمة، وإذا كان الله عز وجل إنما خاطب العرب بلغتها وما يجري مفهوما في كلامها ومعقولا في خطابها، وكان لا يجوز في لسان أهل البيان أن يقول القائل: فعلت بيدي، ويعني النعمة، فبطل أن يكون معنى قوله عز وجل: {بِيَدَيَّ} النعمة، وذلك أنه لا يجوز أن يقول القائل: لي عليه يد بمعنى عليه نعمة، ومن دافعنا عن استعمال اللغة ولم يرجع إلى أهل اللسان فيها دفع عن أن يكون اليد بمعنى النعمة؛ إذ كان لا يمكنه أن يتعلق في أن اليد النعمة إلا من جهة اللغة، فإذا دفع اللغة لزمه أن لا يفسر القرآن من جهتها، وأن لا يثبت اليد نعمة من قبلها؛ لأنه إن رجع في تفسير قول الله عز وجل: {بِيَدَيَّ} نعمتي إلى الإجماع فليس المسلمون على ما ادعى متفقين، وإن رجع إلى اللغة فليس في اللغة أن يقول القائل: «بيدي»؛ يعني نعمتي، وإن لجأ إلى وجه ثالث سألناه عنه ولن يجد إليه سبيلا.\rسؤال: ويقال لأهل البدع: لم زعمتم أن معنى قوله: {بِيَدَيَّ} نعمتي؛ أزعمتم ذلك إجماعا أو لغة فلا يجدون ذلك في الإجماع ولا في اللغة، وإن قالوا: قلنا ذلك من القياس، قيل لهم: ومن أين وجدتم في القياس أن قول الله {بِيَدَيَّ} لا يكون معناه إلا نعمتي؟ ومن أين يمكن أن يعلم بالعقل أن يفسر كذا وكذا مع أنا رأينا الله عز وجل قد قال في كتابه الناطق على لسان نبيه الصادق: {وَما أَرْسَلْنا مِنْ رَسُولٍ إِلاّ بِلِسانِ قَوْمِهِ} (3)، وقال: {لِسانُ الَّذِي\r__________\r(1) أخرجه مسلم ح (1827) من حديث عبد الله بن عمرو به.\r(2) الحاقة: 45.\r(3) إبراهيم: 4."], [192, "يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ وَهذا لِسانٌ عَرَبِيٌّ مُبِينٌ} (1) وقال: {جَعَلْناهُ قُرْآنًا عَرَبِيًّا} (2)، وقال: {أَفَلا يَتَدَبَّرُونَ الْقُرْآنَ} (3)، ولو كان القرآن بلسان غير العرب لما أمكن أن نتدبره ولا أن نعرف معانيه إذا سمعناه، فلما كان من لا يحسن لسان العرب لا يحسنه، وإنما يعرفه العرب إذا سمعوه علم أنهم إنما علموه لأنه بلسانهم نزل وليس في لسانهم ما ادعوه.\rسؤال: وقد اعتل معتل بقول الله عز وجل: {وَالسَّماءَ بَنَيْناها بِأَيْدٍ} (4)، قالوا: الأيد القوة؛ فوجب أن يكون معنى قوله: {بِيَدَيَّ} بقدرتي، وقيل لهم: هذا التأويل فاسد من وجوه: أحدها: أن الأيد ليس بجمع لليد؛ لأن جمع يد التي هي نعمة: أيادي، وإنما قال: {لِما خَلَقْتُ بِيَدَيَّ} فبطل بذلك أن يكون معنى قوله: {بِيَدَيَّ} معنى قوله: {بَنَيْناها بِأَيْدٍ} وأيضا فلو كان أراد القوة لكان معنى ذلك: بقدرتي، وهذا ناقض لقول مخالفنا وكاسر لمذاهبهم لأنهم لا يثبتون قدرة واحدة فكيف يثبتون قدرتين؟!.\rوأيضا فلو كان الله عز وجل عنى بقوله: {لِما خَلَقْتُ بِيَدَيَّ} القدرة لم يكن لآدم عليه السّلام على إبليس في ذلك مزية، والله عز وجل أراد أن يري فضل آدم عليه السّلام إذ خلقه بيده دونه، ولو كان خالقا لإبليس بيديه كما خلق آدم عليه السلام بيديه لم يكن لتفضيله عليه بذلك وجه، وكان إبليس يقول محتجّا على ربه: فقد خلقتني بيديك كما خلقت آدم بهما؛ فلما أراد الله عز وجل تفضيله عليه بذلك قال له موبخا على استكباره على آدم أن يسجد له: {ما مَنَعَكَ أَنْ تَسْجُدَ لِما خَلَقْتُ بِيَدَيَّ\r__________\r(1) النحل: 103.\r(2) الزخرف: 3.\r(3) محمد: 24.\r(4) الذاريات: 47."], [193, "أَسْتَكْبَرْتَ} (1) دل على أنه ليس معنى الآية القدرة إذا كان الله عز وجل خلق الأشياء جميعا بقدرته، وإنما أراد إثبات يدين، ولم يشارك إبليس آدم عليه السّلام في أن خلق بهما.\rوليس يخلو قوله عز وجل: {لِما خَلَقْتُ بِيَدَيَّ} أن يكون معنى ذلك إثبات يدين نعمتين، أو يكون معنى ذلك إثبات يدين جارحتين، أو يكون معنى ذلك إثبات يدين قدرتين، أو يكون معناه إثبات يدين ليستا نعمتين ولا جارحتين ولا قدرتين لا يوصفان إلا كما وصف الله عز وجل: فلا يجوز أن يكون معنى ذلك نعمتين؛ لأنه لا يجوز عند أهل اللسان أن يقول القائل: «عملت بيدي»، وهو يعني نعمتي، ولا يجوز عندنا ولا عند خصومنا أن نعني جارحتين، ولا يجوز عند خصومنا أن نعني قدرتين، وإذا فسدت الأقسام الثلاثة صح القسم الرابع وهو أن معنى قوله: {بِيَدَيَّ} إثبات يدين ليستا جارحتين ولا قدرتين ولا نعمتين لا يوصفان إلا بأن يقال: إنهما يدان ليستا كالأيدي خارجتان عن سائر الوجوه الثلاثة التي سلفت.\rسؤال: وأيضا فلو كان معنى قوله عز وجل: {بِيَدَيَّ} نعمتي لكان لا فضيلة لآدم عليه السّلام على إبليس في ذلك على مذاهب مخالفنا؛ لأن الله عز وجل قد ابتدأ إبليس على قولهم كما ابتدأ بذلك آدم عليه السّلام، وليس يخلو النعمتان أن يكون عنى بهما بدن آدم عليه السّلام أو يكونا عرضين خلقا في بدن آدم، فلو كان عنى بدن آدم فالأبدان عند مخالفنا من المعتزلة جنس واحد، وإذا كانت الأبدان عندهم جنسا واحدا فقد حصل في جسد إبليس على مذاهبهم من النعمة ما حصل في جسد آدم عليه السّلام، وكذلك إن عنى عرضين فليس من عرض فعله في بدن آدم من لون أو\r__________\r(1) ص: 75."], [194, "حياة أو قوة أو غير ذلك إلا وقد فعل من جنسه عندهم في بدن إبليس، وهذا يوجب أنه لا فضيلة لآدم عليه السّلام على إبليس في ذلك، والله عزيز، وإنما احتج على إبليس بذلك ليريه أن لآدم عليه السّلام في ذلك الفضيلة؛ فدل ما قلناه على أن الله عز وجل لما قال: {لِما خَلَقْتُ بِيَدَيَّ} لم يعن نعمتي.\rجواب: ويقال لهم: لم أنكرتم أن يكون الله عز وجل عنى بقوله: {بِيَدَيَّ} يدين ليستا نعمتين، فإن قالوا: لأن اليد إذا لم تكن نعمة لم تكن إلا جارحة، قيل لهم: ولم قضيتم أن اليد إذا لم تكن نعمة لم تكن إلا جارحة؟ فإن رجعونا إلى شاهدنا وإلى ما نجده فيما بيننا من الخلق فقالوا: اليد إذا لم تكن نعمة في الشاهد لم تكن إلا جارحة، قيل لهم: إن عملتم على الشاهد وقضيتم به على الله عز وجل فكذلك لم نجد حيّا من الخلق إلا جسما لحما ودما فاقضوا بذلك على الله عز وجل، وإلا كنتم لقولكم تاركين ولاعتلالكم ناقضين، وإن أثبتم حيّا لا كالأحياء منا فلم أنكرتم أن تكون اليدان اللتان أخبر الله عز وجل عنهما يدين ليستا نعمتين ولا جارحتين ولا كالأيدي، وكذلك يقال لهم: لم تجدوا مدبرا حكيما إلا إنسانا ثم أثبتم أن للدنيا مدبرا حكيما ليس كالإنسان وخالفتم الشاهد ونقضتم اعتلالكم فلا تمنعوا من إثبات يدين ليستا نعمتين ولا جارحتين من أجل أن ذلك خلاف الشاهد.\rسؤال: فإن قالوا: إذا أثبتم لله يدين لقوله: {لِما خَلَقْتُ بِيَدَيَّ} فلم لا أثبتم له أيدي لقوله: {مِمّا عَمِلَتْ أَيْدِينا} (1)؟ قيل لهم: قد أجمعوا على بطلان قول من أثبت لله أيدي؛ فلما أجمعوا على بطلان قول من قال ذلك وجب أن يكون الله عز وجل ذكر أيدي ورجع إلى إثبات يدين؛ لأن الدليل قد دل على صحته\r__________\r(1) يس: 71."], [195, "الإجماع، وإذا كان الإجماع صحيحا وجب أن يرجع من قوله أيدي إلى يدين؛ لأن القرآن على ظاهره ولا يزول عن ظاهره إلا بحجة، فوجدنا حجة أزلنا بها ذكر الأيدي عن الظاهر إلى ظاهر، ووجب أن يكون الظاهر الآخر على حقيقة لا يزول عنها إلا بحجة.\rسؤال: فإن قال قائل: إذا ذكر الله الأيدي وأراد يدين فما أنكرتم أن يذكر الأيدي ويريد يدا واحدة؟ قيل له: ذكر الله عز وجل أيدي وأراد يدين لأنهم أجمعوا على بطلان قول من قال: أيدي كثيرة، وقول من قال: يدا واحدة، فقلنا: يدان؛ لأن القرآن على ظاهره إلا أن تقوم حجة بأن يكون على خلاف الظاهر.\rسؤال: فإن قال قائل: ما أنكرتم أن يكون قوله: {مِمّا عَمِلَتْ أَيْدِينا} وقوله: {لِما خَلَقْتُ بِيَدَيَّ} على المجاز؟ قيل له: حكم كلام الله عز وجل أن يكون على ظاهره وحقيقته، ولا يخرج الشيء عن ظاهره إلى المجاز إلا لحجة؛ ألا ترون أنه إذا كان ظاهر الكلام العموم فإذا ورد بلفظ‍ العموم والمراد به الخصوص فليس هو على حقيقة الظاهر، وليس يجوز أن يعدل بما ظاهره العموم عن العموم بغير حجة، كذلك قول الله عز وجل: {لِما خَلَقْتُ بِيَدَيَّ} على ظاهره، وحقيقته من إثبات اليدين، ولا يجوز أن يعدل به عن ظاهر اليدين إلى ما ادعاه خصومنا إلا بحجة، ولو جاز ذلك لجاز لمدع أن يدعي أن ما ظاهره العموم فهو على الخصوص، وما ظاهره الخصوص فهو على العموم بغير حجة، وإذا لم يجز هذا لمدعيه بغير برهان لم يجز لكم ما ادعيتموه أنه مجاز بغير حجة، بل واجب أن يكون قوله: {لِما خَلَقْتُ بِيَدَيَّ} إثبات يدين لله تعالى في الحقيقة غير نعمتين؛ إذ كانت النعمتان لا يجوز عند أهل اللسان أن يقول قائلهم: فعلت بيدي، وهو يعني النعمتين.\r***"]], "pg": [191, 195]}, "إ.3.7": {"x": [[196, "باب الرد على الجهمية في نفيهم علم الله تعالى وقدرته وجميع صفاته\rقال الله عز وجل: {أَنْزَلَهُ بِعِلْمِهِ} (1) و قال: {وَما تَحْمِلُ مِنْ أُنْثى وَلا تَضَعُ إِلاّ بِعِلْمِهِ} (2) و ذكر العلم في خمسة مواضع من كتابه وقال: {فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ فَاعْلَمُوا أَنَّما أُنْزِلَ بِعِلْمِ اللهِ} (3) و قال: {وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلاّ بِما شاءَ} (4)، وذكر القوة فقال: {أَوَلَمْ يَرَوْا أَنَّ اللهَ الَّذِي خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً} (5) و قال: {ذُو الْقُوَّةِ الْمَتِينُ} (6) و قال: {وَالسَّماءَ بَنَيْناها بِأَيْدٍ} (7) و زعمت الجهمية أن الله عز وجل لا علم له ولا قدرة ولا حياة ولا سمع ولا بصر له، وأرادوا أن ينفوا أن الله عالم قادر حي سميع بصير؛ فمنعهم خوف السيف من إظهارهم نفي ذلك فأتوا بمعناه لأنهم إذا قالوا: لا علم لله ولا قدرة له، فقد قالوا: إنه ليس بعالم ولا قادر، ووجب ذلك عليهم، وهذا إنما أخذوه عن أهل الزندقة والتعطيل لأن الزنادقة قال كثير منهم: إن الله ليس بعالم ولا قادر ولا حي ولا سميع ولا بصير، فلم تقدر المعتزلة أن تفصح بذلك فأتت بمعناه، وقالت: إن الله عالم قادر حي سميع بصير من طريق التسمية من غير أن يثبتوا له حقيقة العلم والقدرة والسمع والبصر.\rسؤال: وقد قال رئيس من رؤسائهم وهو أبو الهذيل العلاف: إن علم الله هو\r__________\r(1) النساء: 166.\r(2) فاطر: 11.\r(3) هود: 14.\r(4) البقرة: 255.\r(5) فصلت: 15.\r(6) الذاريات: 58.\r(7) الذاريات: 47."], [197, "الله، فجعل الله عز وجل علما، وألزم فقيل له: إذا قلت: إن علم الله هو الله، فقل: يا علم الله اغفر لي وارحمني! فأبى ذلك فلزمته المناقضة.\rواعلموا - رحمكم الله - أن من قال: عالم ولا علم كان مناقضا كما أن من قال: علم ولا عالم كان مناقضا؛ وكذلك القول في القدرة والقادر والحياة والحي والسمع والبصر والسميع والبصير.\rجواب: ويقال لهم: خبرونا عمن زعم أن الله متكلم قائل لم يزل آمرا ناهيا، لا قول له ولا كلام ولا أمر له ولا نهي؛ أليس هو مناقض خارج عن جملة المسلمين؟ فلا بد من نعم، يقال لهم: فكذلك من قال: «إن الله عالم ولا علم له» كان مناقضا خارجا عن جملة المسلمين، وقد أجمع المسلمون قبل حدوث الجهمية والمعتزلة والحرورية على أن لله علما لم يزل، وقد قالوا: علم الله لم يزل وعلم الله سابق في الأشياء، ولا يمنعون أن يقولوا في كل حادثة تحدث ونازلة تنزل «كل هذا سابق في علم الله» فمن جحد أن لله علما خالف المسلمين وخرج به عن اتفاقهم.\rجواب: ويقال لهم: إذا كان الله مريدا أفله إرادة؟ فإن قالوا: لا، قيل لهم: فإذا أثبتم مريدا لا إرادة له فأثبتوا قائلا لا قول له، وإن أثبتوا الإرادة قيل لهم: فإذا كان المريد لا يكون مريدا إلا بإرادة فما أنكرتم أن لا يكون العالم عالما إلا بعلم، وأن يكون لله علم كما أثبتم له إرادة.\rمسألة: وقد فرقوا بين العلم والكلام فقالوا: إن الله عز وجل علم موسى وفرعون، وكلم موسى ولم يكلم فرعون، فكذلك يقال: علم موسى الحكمة وفصل الخطاب وآتاه النبوة، ولم يعلم ذلك فرعون؛ فإن كان لله كلام لأنه كلم موسى ولم يكلم فرعون فكذلك لله علم لأنه علم موسى ولم يعلم فرعون؛ ثم يقال لهم: إذا وجب أن لله كلاما به كلم موسى دون فرعون؛ إذ كلم موسى دونه، فما أنكرتم إذا علمهما جميعا أن يكون له علم به علمهما جميعا، ثم يقال: قد"], [198, "كلم الله الأشياء بأن قال لها: كوني، وقد أثبتم لله قولا فكذلك، وإن علم الأشياء كلها فله علم.\rجواب: ثم يقال لهم: إذا أوجبتم أن لله كلاما وليس له علم؛ لأن الكلام أخص من العلم والعلم أعم منه فقولوا: إن لله قدرة؛ لأن العلم أعم عندكم من القدرة؛ لأن من مذاهب القدرية أنهم لا يقولون: إن الله يقدر أن يخلق الكفر؛ فقد أثبتوا القدرة أخص من العلم؛ فينبغي لهم أن يقولوا على اعتلالهم: إن لله قدرة.\rجواب: ثم يقال لهم: أليس الله عالما والوصف له بأنه عالم أعم من الوصف بأنه متكلم مكلم ثم لم يجب؛ لأن الكلام أخص من أن يكون الله متكلما غير عالم فلم لا قلتم: إن الكلام وإن كان أخص من العلم أن ذلك لا ينفي أن يكون لله علم كما لم ينف بخصوص الكلام أن يكون الله عالما.\rجواب: ويقال لهم: من أين علمتم أن الله عالم؟ فإن قالوا: بقوله عز وجل: {إِنَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ} (1) قيل لهم: ولذلك فقولوا: إن لله علما بقوله: {أَنْزَلَهُ بِعِلْمِهِ} (2) و بقوله: {وَما تَحْمِلُ مِنْ أُنْثى وَلا تَضَعُ إِلاّ بِعِلْمِهِ} (3) و كذلك قولوا: إن له قوة؛ لقوله: {أَوَلَمْ يَرَوْا أَنَّ اللهَ الَّذِي خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً} (4) و إن قالوا: قلنا إن الله عالم لأنه صنع العالم على ما فيه من آثار الحكمة واتساق التدبير، قيل لهم: فلم لا قلتم: إن لله علما بما ظهر في العالم من حكمه وآثار تدبيره؛ لأن الصنائع الحكمية لا تظهر إلا من ذي علم كما لا تظهر إلا من عالم، وكذلك لا تظهر إلا من ذي قوة كما لا تظهر إلا من قادر.\r__________\r(1) الشورى: 12.\r(2) النساء: 166.\r(3) فاطر: 11.\r(4) فصلت: 15."], [199, "جواب: ويقال لهم: إذا نفيتم علم الله فهلا نفيتم أسماءه؟ فإن قالوا: كيف ننفي أسماءه وقد ذكرها في كتابه؟ قيل لهم: فلا تنفوا العلم والقوة لأنه تبارك وتعالى ذكر ذلك في كتابه.\rجواب آخر: ويقال لهم: قد علّم الله عزّ وجلّ نبيه صلّى الله عليه وسلّم الشرائع والأحكام والحلال والحرام، ولا يجوز أن يعلّمه ما لا يعلمه فكذلك لا يجوز أن يعلم الله نبيه ما لا علم لله به - تعالى الله عن قول الجهمية علوّا كبيرا.\rجواب: ويقال لهم: أليس إذا لعن الله الكافرين فلعنه لهم معنى، ولعن النبي عليه السّلام لهم معنى؛ فمن قولهم: نعم فيقال لهم: فما أنكرتم من أن الله إذا علّم نبيه عليه السّلام شيئا فيكون للنبي عليه السّلام علم، ولله سبحانه علم، وإذا كنا متى أثبتناه غاضبا على الكافرين فلا بد من إثبات غضب، وكذلك إذا أثبتناه راضيا عن المؤمنين فلا بد من إثبات رضا، وكذلك إذا أثبتناه حيّا سميعا بصيرا فلا بد من إثبات حياة وسمع وبصر.\rجواب: ويقال لهم: وجدنا اسم عالم اشتق من علم، واسم قادر اشتق من قدرة، وكذلك اسم حي اشتق من حياة، واسم سميع اشتق من سمع، واسم بصير اشتق من بصر، ولا تخلو أسماء الله عزّ وجلّ من أن تكون مشتقة أو لإفادة معناه أو على طريق التلقيب، فلا يجوز أن يسمى الله عزّ وجلّ على طريق التلقيب باسم ليس فيه إفادة معناه وليس مشتقّا من صفة، فإذا قلنا: إن الله عزّ وجلّ عالم قادر فليس ذلك تلقيبا كقولنا: زيد وعمرو - وعلى هذا إجماع المسلمين، وإذا لم يكن ذلك تلقيبا وكان مشتقّا من علم فقد وجب إثبات العلم، وإن كان ذلك لإفادة معناه فلا يختلف ما هو لإفادة معناه، ووجب إذا كان معنى العالم منا أن له علما أن يكون كل عالم فهو ذو علم، كما إذا كان قولي: «موجود» مفيدا فينا الإثبات كان الباري تعالى واجبا إثباته لأنه سبحانه وتعالى موجود.\rجواب: ويقال للمعتزلة والجهمية والحرورية: أتقولون إن لله علما بالأشياء"], [200, "سابقا فيها وبوضع كل حامل وحمل كل أنثى وبإنزال كل ما أنزل؟ فإن قالوا:\r«نعم» أثبتوا العلم ووافقوا، وإن قالوا: «لا» قيل لهم: هذا جحد منكم لقول الله عزّ وجل: {أَنْزَلَهُ بِعِلْمِهِ ولقوله: وَما تَحْمِلُ مِنْ أُنْثى وَلا تَضَعُ إِلاّ بِعِلْمِهِ} (1) و لقوله: {فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ فَاعْلَمُوا أَنَّما أُنْزِلَ بِعِلْمِ اللهِ} (2) و إذا كان قول وجل: {بِكُلِّ شَيْءٍ عَلِيمٌ} (3) {وَما تَسْقُطُ‍ مِنْ وَرَقَةٍ إِلاّ يَعْلَمُها} (4). أوجب أنه عليم يعلم الأشياء كذلك، فما أنكرتم أن تكون هذه الآيات توجب أن لله علما بالأشياءسبحانه وبحمده.\rجواب: ويقال لهم: لله عزّ وجل علم بالتفرقة بين أوليائه وأعدائه، فهل هو مريد لذلك وهل له إرادة للإيمان إذا أراد الإيمان؟ فإن قالوا: «نعم» وافقوا، وإن قالوا: إذا أراد الإيمان فله إرادة، قيل لهم: وكذلك إذا فرق بين أوليائه وأعدائه فلا بد من أن يكون له علم بذلك، وكيف يجوز أن يكون للخلق علم بذلك وليس للخالق عزّ وجل علم بذلك؟! هذا يوجب أن للخلق مزية في العلم وفضيلة على الخالق - تعالى عن ذلك علوّا كبيرا، ويقال لهم: إذا كان من له علم من الخلق أولى بالمنزلة الرفيعة ممن لا علم له؛ فإذا زعمتم أن الله عزّ وجل لا علم له لزمكم أن الخلق أعلى مرتبة من الخالق - تعالى الله عن ذلك علوّا كبيرا.\rجواب: ويقال لهم: إذا كان من لا علم له من الخلق يلحقه الجهل والنقصان فما أنكرتم من أنه لا بد من إثبات علم الله وإلا ألحقتم به النقصان جل وعز عن قولكم وعلا؛ ألا ترون أن من لا يعلم من الخلق يلحقه الجهل والنقصان، ومن\r__________\r(1) فاطر: 11.\r(2) هود: 14.\r(3) النور: 35.\r(4) الأنعام: 59."], [201, "قال ذلك في الله عزّ وجل وصف الله سبحانه بما لا يليق به، فكذلك إذا كان من قيل له من الخلق: لا علم له لحقه الجهل والنقصان؛ فوجب أن لا ينفى ذلك عن الله عزّ وجل؛ لأنه لا يلحقه جهل ولا نقصان.\rجواب: ويقال لهم: هل يجوز أن تنسق الصنائع الحكمية ممن ليس بعالم؟ فإن قالوا: ذلك محال ولا يجوز في وجود الصنائع التي تجري على ترتيب ونظام إلا من عالم قادر حي، قيل لهم: وكذلك لا يجوز وجود الصنائع الحكمية التي تجري على ترتيب ونظام إلا من ذي علم وقدرة وحياة، فإن جاز ظهورها لا من ذي علم فما أنكرتم من جواز ظهورها لا من عالم قادر حي، وكل مسألة سألناهم عنها في العلم فهي داخلة عليهم في القدرة والحياة والسمع والبصر.\rمسألة: وزعمت المعتزلة أن قول الله عزّ وجل: {سَمِيعٌ بَصِيرٌ} (1) معناه عليم، قيل لهم: فإذا قال عزّ وجل: {إِنَّنِي مَعَكُما أَسْمَعُ وَأَرى} (2) و قال: {قَدْ سَمِعَ اللهُ قَوْلَ الَّتِي تُجادِلُكَ فِي زَوْجِها} (3) فمعنى ذلك عندكم علم؟ فإن قالوا: نعم، قيل لهم: فقد وجب عليكم أن تقولوا معنى قوله: {أَسْمَعُ وَأَرى} أعلم وأعلم؛ إذ كان معنى ذلك العلم.\rمسألة: ونفت المعتزلة صفات رب العالمين وزعمت أن معنى سَمِيعٌ بَصِيرٌ راء بمعنى عليم، كما زعمت النصارى أن السمع هو بصره وهو رؤيته وهو كلامه وهو علمه وهو ابنه - عز الله وجل وتعالى عن ذلك علوّا كبيرا، فيقال للمعتزلة: إذا زعمتم أن معنى سميع وبصير معنى عالم فهلا زعمتم أن معنى قادر معنى عالم؛ فإذا زعمتم أن معنى سميع وبصير معنى قادر فهلا زعمتم أن\r__________\r(1) الحج: 61.\r(2) طه: 46.\r(3) المجادلة: 1."], [202, "معنى قادر معنى عالم، وإذا زعمتم أن معنى حي معنى قادر فلم لا زعمتم أن معنى قادر معنى عالم؟ فإن قالوا: هذا يوجب أن يكون كل معلوم مقدورا، قيل لهم: ولو كان معنى سَمِيعٌ بَصِيرٌ معنى عالم لكان كل معلوم مسموعا، وإذا لم يجز ذلك بطل قولكم.\r***"]], "pg": [196, 202]}, "إ.4.1": {"x": [[203, "باب الكلام في الإرادة\rالرد على المعتزلة في ذلك يقال لهم: ألستم تزعمون أن الله عزّ وجل لم يزل عالما؟ فمن قولهم: «نعم»، قيل لهم: فلم لا قلتم: إن من لم يزل عالما في وقت من الأوقات فلم يزل مريدا أن يكون في ذلك الوقت، وما لم يزل عالما أنه لا يكون فلم يزل مريدا أن لا يكون، وأنه لم يزل مريدا أن يكون ما علم كما علم؟ فإن قالوا: لا نقول إن الله لم يزل مريدا لأن الله مريد بإرادة مخلوقة، يقال لهم: ولم زعمتم أن الله عزّ وجل مريد بإرادة مخلوقة، وما الفصل بينكم وبين الجهمية في زعمهم أن الله عالم بعلم مخلوق، وإذا لم يجز أن يكون علم الله مخلوقا فما أنكرتم أن لا تكون إرادته مخلوقة؟ فإن قالوا: لا يجوز أن يكون علم الله محدثا لأن ذلك يقتضي أن يكون حدث بعلم آخر كذلك لا إلى غاية، قيل لهم: ما أنكرتم أن لا تكون إرادة الله محدثة مخلوقة؛ لأن ذلك يقتضي أن تكون حدثت عن إرادة أخرى ثم كذلك لا إلى غاية، وإن قالوا: لا يجوز أن يكون علم الله محدثا لأن من لم يكن عالما ثم علم لحقه النقصان قيل لهم: ولا يجوز أن تكون إرادة الله محدثة مخلوقة لأن من لم يكن مريدا حتى أراد لحقه النقصان، وكما لا يجوز أن تكون إرادته تعالى محدثة مخلوقة كذلك لا يجوز أن يكون كلامه محدثا مخلوقا.\rجواب آخر: ويقال لهم: إذا زعمتم أنه قد كان في سلطان الله عزّ وجل الكفر والعصيان وهو لا يريده، وأراد أن يؤمن الخلق أجمعون فلم يؤمنوا؛ فقد وجب على قولكم أن أكثر ما شاء الله أن يكون لم يكن، وأكثر ما شاء الله أن لا يكون كان؛ لأن الكفر الذي كان وهو لا يشاؤه الله عندكم أكثر من الإيمان الذي كان وهو يشاؤه، وأكثر ما شاء أن يكون لم يكن، وهذا جحد لما أجمع عليه المسلمون من أن ما شاء الله أن يكون كان وما لا يشاء لا يكون.\rجواب آخر: ويقال لهم: يستفاد من قولكم إن كثيرا مما شاء إبليس أن يكون"], [204, "كان؛ لأن الكفر أكثر من الإيمان، وأكثر ما كان هو شاءه، فقد جعلتم مشيئة إبليس أنفذ من مشيئة رب العالمين جل ثناؤه وتقدست أسماؤه؛ لأن أكثر ما شاءه كان، وأكثر ما كان قد شاءه، وفي هذا إيجاب أنكم قد جعلتم لإبليس مرتبة في المشيئة ليست لرب العالمين - تعالى الله عزّ وجل عن قول الظالمين علوّا كبيرا.\rجواب آخر: ويقال لهم: أيما أولى بصفة الاقتدار: من إذا شاء أن يكون الشيء كان لا محالة وإذا لم يرده لم يكن، أو من يريده أن يكون فلا يكون، ويكون ما لا يريد؟ فإن قالوا: من لا يكون أكثر ما يريده أولى بصفة الاقتدار كابروا، وقيل لهم: إن جاز لكم ما قلتموه جاز لقائل أن يقول: من يكون ما لا يعلمه أولى بالعلم ممن لا يكون إلا ما يعلمه، وإن رجعوا عن هذه المكابرة، وزعموا أن من إذا أراد أمرا كان، وإذا لم يرده لا يكون أولى بصفة الاقتدار لزمهم على مذاهبهم أن يكون إبليس - لعنة الله عليه - أولى بالاقتدار من الله عزّ وجل؛ لأن أكثر ما أراده كان وأكثر ما كان قد أراده، وقيل لهم: إذا كان من إذا أراد أمرا كان، وإذا لم يرده لم يكن أولى بصفة الاقتدار فيلزمكم أن يكون الله عزّ وجل إذا أراد أمرا كان وإذا لم يرده لم يكن؛ لأنه أولى بصفة الاقتدار.\rجواب: ويقال لهم: أيما أولى بالإلهية والسلطان: من لا يكون إلا ما يعلمه ولا يغيب عن علمه شيء ولا يجوز ذلك عليه، أو من يكون ما لا يعلمه ويعزب عن علمه أكثر الأشياء؟ فإن قالوا: من لا يكون إلا ما يعلمه ولا يعزب عن علمه شيء أولى بصفة الإلهية، قيل لهم: فكذلك من لا يريد كون شيء إلا ما كان ولا يكون إلا ما يريده ولا يعزب عن إرادته شيء أولى بصفة الإلهية كما قلتم ذلك في العلم، وإذا قالوا ذلك تركوا قولهم ورجعوا عنه، وأثبتوا الله عزّ وجل مريدا لكل كائن، وأوجبوا أنه لا يكون إلا ما يريد أن يكون.\rجواب: ويقال لهم: إذا قلتم إنه يكون في سلطانه تعالى ما لا يريد فقد كان إذا في"], [205, "سلطانه ما كرهه، فلا بد من نعم، يقال لهم: فإذا كان في سلطانه ما يكرهه فما أنكرتم أن يكون في سلطانه ما يأبى كونه؟ فإن أجابوا إلى ذلك قيل لهم: فقد كانت المعاصي شاء الله أم أبي وهذه صفة الضعف والفقر - تعالى الله عن ذلك علوّا كبيرا.\rجواب: ويقال لهم: أليس مما فعل العباد ما يسخطه تعالى وما يغضب عليهم إذا فعلوه فقد أغضبوه وأسخطوه؟ فلا بد من نعم، يقال لهم: فلو فعل العباد ما لا يريد وما يكرهه لكانوا قد أكرهوه وهذه صفة القهر - تعالى الله عن ذلك علوّا كبيرا.\rجواب: ويقال لهم: أليس قد قال الله تعالى عزّ وجل: {فَعّالٌ لِما يُرِيدُ} (1) فلا بد من نعم، يقال لهم: فمن زعم أن الله تعالى فعل ما لا يريد وأراد أن يكون من فعله ما لا يكون لزمه أن يكون قد وقع ذلك وهو ساه غافل عنه، أو أن الضعف والتقصير عن بلوغ ما لا يريده لحقه؛ فلا بد من نعم، فيقال لهم: فكذلك من زعم أنه يكون في سلطان الله عزّ وجل ما لا يريده من عبيده لزمه أحد أمرين: إما أن يزعم أن ذلك كان عن سهو وغفلة، أو أن يزعم أن الضعف والتقصير عن بلوغ ما يريده لحقه.\rجواب آخر: ويقال لهم: أليس من زعم أن الله عزّ وجل فعل ما لا يعلمه قد نسب الله سبحانه إلى ما لا يليق به من الجهل؟ فلا بد من نعم، يقال لهم: فكذلك من زعم أن عبد الله فعل ما لا يريده لزمه أن ينسب الله سبحانه إلى السهو والتقصير عن بلوغ ما يريده فإذا قالوا: نعم، قيل لهم: وكذلك يلزم من زعم أن العباد يفعلون ما لا يعلم الله نسب الله تعالى إلى الجهل، فلا بد من نعم، يقال لهم:\rفكذلك إذا كان في كل فعل فعله الله وهو لا يريده إيجاب سهو أو ضعف وتقصير عن بلوغ ما يريده فكذلك إذا كان من غيره ما لا يريده وجب إثبات سهو وغفلة أو ضعف وتقصير عن بلوغ ما يريد، لا فرق في ذلك بين ما كان منه\r__________\r(1) البروج: 16."], [206, "وما كان من غيره.\rجواب آخر: ويقال لهم: إذا كان في سلطان الله ما لا يريده وهو يعلمه ولا يلحقه الضعف والتقصير عن بلوغ ما يريده؛ فما أنكرتم أن يكون في سلطانه ما لا يعلمه ولا يلحقه النقصان، فإن لم يجز هذا لم يجز ما قلتموه.\rمسألة أخرى: إن قال قائل: لم قلتم: إن الله مريد لكل كائن أن يكون، ولكل ما لا يكون أن لا يكون؟ قيل له: الدليل على ذلك أن الحجة قد وضحت أن الله عزّ وجل خلق الكفر والمعاصي - وسنبين ذلك بعد هذا الموضع من كتابنا - وإذا وجب أن الله سبحانه خالق لذلك فقد وجب أنه مريد له؛ لأنه لا يجوز أن يخلق ما لا يريده.\rوجواب آخر: أنه لا يجوز أن يكون في سلطان الله عزّ وجل من اكتساب العباد ما لا يريده كما لا يجوز أن يكون من فعله المجمع على أنه فعله ما لا يريده؛ لأنه لو وقع من فعله ما لا يعلمه لكان في ذلك إثبات النقصان، وكذلك القول لو وقع من عباده ما لا يعلمه؛ فكذلك لا يجوز أن يقع من عباده ما لا يريده؛ لأن ذلك يوجب أن يقع عن سهو وغفلة أو عن ضعف وتقصير عن بلوغ ما يريده، كما يجب ذلك لو وقع من فعله المجمع على أنه فعله ما لا يريده، وأيضا فلو كانت المعاصي وهو لا يشاء أن تكون لكان قد كره أن تكون وأبى أن تكون، وهذا يوجب أن تكون المعاصي كائنة شاء الله أم أبى، وهذه صفة الضعف - تعالى الله عن ذلك علوّا كبيرا، وقد أوضحنا أن الله لم يزل مريدا على الحقيقة الذي علمه عليها، فإذا كان الكفر مما يكون وقد علم ذلك فقد أراد أن يكون.\rجواب: ويقال لهم: إذا كان الله عزّ وجل علم أن الكفر يكون وأراد أن لا يكون ما علم على خلاف ما علم، وإذا لم يجز ذلك فقد أراد أن يكون ما علم كما علم.\rجواب: ويقال لهم: لم أبيتم أن يريد الله الكفر الذي علم أنه يكون قبيحا فاسدا متناقضا خلافا للإيمان؟ فإن قالوا: لأن مريد السفه سفيه، قيل لهم: ولم"], [207, "قلتم ذلك؟ أ وليس قد أخبر الله تعالى عن ابن آدم أنه قال لأخيه: {لَئِنْ بَسَطْتَ إِلَيَّ يَدَكَ لِتَقْتُلَنِي ما أَنَا بِباسِطٍ‍ يَدِيَ إِلَيْكَ لِأَقْتُلَكَ إِنِّي أَخافُ اللهَ رَبَّ الْعالَمِينَ (28) إِنِّي أُرِيدُ أَنْ تَبُوءَ بِإِثْمِي وَإِثْمِكَ فَتَكُونَ مِنْ أَصْحابِ النّارِ} (1) فأراد أن لا يقتل أخاه لئلا يعذب وأن يقتله أخوه حتى يبوء بإثم قتله له وسائر آثامه التي كانت عليه؛ فيكون من أصحاب النار؛ فأراد قتل أخيه الذي هو سفه ولم يكن بذلك سفيها؛ فلم زعمتم أن الله سبحانه إذا أراد سفه العباد وجب أن ينسب ذلك إليه؟\rجواب: ويقال لهم: قد قال يوسف عليه السّلام: {رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمّا يَدْعُونَنِي إِلَيْهِ} (2) و كان سجنهم إياه معصية؛ فأراد المعصية التي هي سجنهم إياه دون فعل ما يدعونه إليه ولم يكن بذلك سفيها، فما أنكرتم من أن لا يجب إذا أراد الباري سبحانه سفه العباد بأن يكون قبيحا منهم خلافا للطاعة أن يكون سفيها.\rمسألة أخرى: ويقال لهم: أليس من يرى منا جرم المسلمين كان سفيها، والله سبحانه يراهم ولا ينسب إلى السفه؟ فلا بد من نعم، يقال لهم: فما أنكرتم أن من أراد السفه منا كان سفيها، والله سبحانه يريد سفه السفهاء ولا ينسب إليه أنه عزّ وجل سفيه - تعالى الله عن ذلك.\rمسألة أخرى: ويقال لهم: السفيه منا إنما كان سفيها لما أراد السفه؛ لأنه نهي عن ذلك ولأنه تحت شريعة من هو فوقه، ومن يحد له الحدود ويرسم له الرسوم؛ فلما أتى ما نهي عنه كان سفيها، ورب العالمين جل ثناؤه وتقدست أسماؤه ليس تحت شريعة ولا فوقه من يحد له الحدود ويرسم له الرسوم، ولا فوقه مبيح ولا حاظر ولا آمر ولا زاجر؛ فلم يجب إذا أراد ذلك أن يكون قبيحا\r__________\r(1) المائدة: 28 - 29.\r(2) يوسف: 33."], [208, "أن ينسب إلى السفه سبحانه وتعالى.\rمسألة: ويقال لهم: أليس من خلّى بين عبيده وبين إمائه منا يزني بعضهم ببعض وهو لا يعجز عن التفريق بينهم يكون سفيها، ورب العالمين عزّ وجل قد خلّى بين عبيده وإمائه يزني بعضهم ببعض وهو يقدر على التفريق بينهم، وليس سفيها، وكذلك من أراد السفه منا كان سفيها، ورب العالمين جل وعز يريد السفه وليس سفيها.\rمسألة أخرى: ويقال لهم: من أراد طاعة الله منا كان مطيعا كما أن من أراد السفه كان سفيها، ورب العالمين عزّ وجل يريد الطاعة وليس مطيعا؛ فكذلك يريد السفه وليس سفيها.\rمسألة أخرى: ويقال لهم: قال الله عزّ وجل: {وَلَوْ شاءَ اللهُ مَا اقْتَتَلُوا} (1) فأخبر أنه لو شاء أن لا يقتتلوا ما اقتتلوا؛ قال: {وَلكِنَّ اللهَ يَفْعَلُ ما يُرِيدُ} من القتال فإذا وقع القتال فقد شاءه كما أنه لما قال: {وَلَوْ رُدُّوا لَعادُوا لِما نُهُوا عَنْهُ} (2) فقد أوجب أن الرد لو كان إلى الدنيا لعادوا إلى الكفر، وأنهم إذ لم يردهم إلى الدنيا لم يعودوا، فكذلك لو شاء أن لا يقتتلوا لما اقتتلوا، وإذا اقتتلوا فقد شاء أن يقتتلوا.\rمسألة أخرى: ويقال لهم: قال الله عزّ وجل: {وَلَوْ شِئْنا لَآتَيْنا كُلَّ نَفْسٍ هُداها وَلكِنْ حَقَّ الْقَوْلُ مِنِّي لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنّاسِ أَجْمَعِينَ} (3) و إذا حق القول بذلك فما شاء أن يؤتي كل نفس هداها، لأنه إنما لم يؤتها هداها لما حق القول بتعذيب الكافرين، وإذا لم يرد ذلك فقد شاء ضلالتها، فإن قالوا: معنى ذلك لو شئنا لأجبرناهم على الهدى واضطررناهم إليه، قيل لهم: فإذا أجبرهم على الهدى\r__________\r(1) البقرة: 253.\r(2) الأنعام: 28.\r(3) السجدة: 13."], [209, "واضطرهم إليه أيكونون مهتدين؟ فإن قالوا: نعم، قيل لهم: فإذا كان إذا فعل الهدى كانوا مهتدين فما أنكرتم لو فعل كفر الكافرين لكانوا كافرين، وهذا هدم لقولهم لأنهم زعموا أنه لا يفعل الكفر إلا كافر؛ ويقال لهم أيضا: على أي وجه يؤتيهم الهدى لو آتاهم إياه وشاء ذلك لهم؟ فإن قالوا: على الإلجاء، قيل لهم: وإذا ألجأهم إلى ذلك هل ينفعهم ما يفعلونه على طريق الإلجاء؟ فمن قولهم: نعم، قيل لهم: فإذا أخبر أنه لو شاء لآتاهم الهدى لو لا ما حق منه من القول أنه يملأ جهنم، وإذا كان لو ألجأهم لم يكن نافعا لهم ولا مزيلا للعذاب عنهم كما لم ينفع فرعون قوله الذي قاله عند الغرق والإلجاء؛ فلا معنى لقولكم لأنه لو لا ما حق من القول لأوتيت كل نفس هداها، وإتيان الهدى على الوجه الذي قلتموه لا يزيل العذاب.\rمسألة أخرى: ويقال لهم: قال الله عز وجلّ: {وَلَوْ بَسَطَ‍ اللهُ الرِّزْقَ لِعِبادِهِ لَبَغَوْا فِي الْأَرْضِ} (1) و قال: {وَلَوْ لا أَنْ يَكُونَ النّاسُ أُمَّةً واحِدَةً لَجَعَلْنا لِمَنْ يَكْفُرُ بِالرَّحْمنِ لِبُيُوتِهِمْ سُقُفًا مِنْ فِضَّةٍ} (2) فأخبر أنه لو لا أن يكون الناس مجتمعين على الكفر لبسط‍ للكافرين الرزق، وجعل لبيوتهم سقفا من فضة، لكنه لم يبسط‍ لهم الرزق ولم يجعل للكافرين سقفا من فضة؛ فما أنكرتم من أنه لو لم يرد أن يكفر الكافرون ما خلقهم مع علمه بأنه إذا خلقهم كانوا كافرين كما أنه لو أراد أن يكون الناس على الكفر مجتمعين لجعل للكافرين سقفا من فضة ومعارج عليها يظهرون لكنه لم يجعل للكافرين سقفا من فضة ومعارج عليها يظهرون؛ لئلا يكونوا جميعا على الكفر متطابقين إذا كان في معلومه أنه لو فعل ذلك لكانوا جميعا على الكفر متطابقين.\r***\r__________\r(1) الشورى: 27.\r(2) الزخرف: 33."]], "pg": [203, 209]}, "إ.5.1": {"x": [[210, "باب الكلام في تقدير أعمال العباد والاستطاعة والتعديل والتجوير\rيقال للقدرية: هل يجوز أن يعلم الله عز وجلّ عباده شيئا لا يعلمه؟ فإن قالوا: لا يعلم الله عباده شيئا إلا وهو به عالم، قيل لهم: فكذلك لا يقدرهم على شيء إلا وهو عليه قادر؛ فلا بد من الإجابة إلى ذلك، يقال لهم: فإذا أقدرهم على الكفر فهو قادر على أن يخلق الكفر لهم، وإذا قدر على خلق الكفر لهم فلم أثبتم أن يخلق كفرهم فاسدا متناقضا باطلا، وقد قال تعالى: {فَعّالٌ لِما يُرِيدُ} (1) و إذا كان الكفر مما أراد فقد فعله وقدّره، ويرد عليهم في اللطف؛ يقال لهم: أليس الله عز وجلّ قادرا على أن يفعل بخلقه من بسط‍ الرزق ما لو فعله بهم لبغوا، وأن يفعل بهم ما لو فعله بالكفار لكفروا كما قال: {وَلَوْ بَسَطَ‍ اللهُ الرِّزْقَ لِعِبادِهِ لَبَغَوْا فِي الْأَرْضِ} (2) و كما قال: {وَلَوْ لا أَنْ يَكُونَ النّاسُ أُمَّةً واحِدَةً لَجَعَلْنا لِمَنْ يَكْفُرُ بِالرَّحْمنِ لِبُيُوتِهِمْ سُقُفًا مِنْ فِضَّةٍ} ... الآية؟ فلا بد من نعم، يقال لهم: فما أنكرتم من أنه قادر أن يفعل بهم لطفا لو فعله بهم لآمنوا أجمعون، كما أنه قادر على أن يفعل بهم أمرا لو فعله بهم لكفروا كلهم.\rمسألة أخرى: ويقال لهم: أليس قد قال الله عز وجلّ: {وَلَوْ لا فَضْلُ اللهِ عَلَيْكُمْ وَرَحْمَتُهُ لاَتَّبَعْتُمُ الشَّيْطانَ إِلاّ قَلِيلًا} (3) {وَلَوْ لا فَضْلُ اللهِ عَلَيْكُمْ وَرَحْمَتُهُ ما زَكى مِنْكُمْ مِنْ أَحَدٍ أَبَدًا} (4) و قال: {فَاطَّلَعَ فَرَآهُ فِي سَواءِ الْجَحِيمِ} (5) يعني في وسط‍\r__________\r(1) البروج: 16.\r(2) الشورى: 27.\r(3) النساء: 83.\r(4) النور: 21.\r(5) الصافات: 55."], [211, "الجحيم، قال: {تَاللهِ إِنْ كِدْتَ لَتُرْدِينِ (56) وَلَوْ لا نِعْمَةُ رَبِّي لَكُنْتُ مِنَ الْمُحْضَرِينَ} (1) ما الفضل الذي فعله بالمؤمنين الذي لو لم يفعله لاتبعوا الشيطان، ولو لم يفعله ما زكى منهم من أحد أبدا، وما النعمة التي لو لم يفعلها لكان من المحضرين، وهل ذلك شيء لم يفعله بالكافرين وخص به المؤمنين؟ فإن قالوا: نعم، تركوا قولهم وأثبتوا لله عز وجلّ نعما وفضلا على المؤمنين ابتدأهم بجميعه ولم ينعم بمثله على الكافرين، وصاروا إلى القول بالحق، وإن قالوا: قد فعل الله ذلك أجمع بالكافرين لما فعله بالمؤمنين قيل لهم: فإذا كان الله عز وجلّ قد فعل ذلك أجمع بالكافرين فلم يكونوا زاكين وكانوا للشيطان متبعين وفي النار محضرين، وهل يجوز أن يقول للمؤمنين: لو لا أني خلقت لكم الأيدي والأرجل لكنتم للشيطان متبعين، وهو قد خلق الأيدي والأرجل للكافرين وكانوا للشيطان متبعين؟ فإن قالوا: لا يجوز ذلك، قيل لهم: وكذلك لا يجوز ما قلتموه، وهذا يبين أن الله عز وجلّ اختص المؤمنين من النعم والتوفيق والتسديد بما لم يعط‍ الكافرين وفضل عليهم المؤمنين.\r***\r__________\r(1) الصافات: 56 - 57."], [212, "مسألة في الاستطاعة\rويقال لهم: "]], "pg": [210, 212]}, "إ.5.2": {"x": [[212, "أليست استطاعة الإيمان نعمة من الله عز وجلّ وفضلا وإحسانا؟ فإذا قالوا: نعم، قيل لهم: فما أنكرتم أن يكون توفيقا وتسديدا؟ فلا بد من الإجابة إلى ذلك، يقال لهم: فإذا كان الكافرون قادرين على الإيمان فما أنكرتم أن يكونوا موفقين للإيمان، ولو كانوا موفقين مسددين لكانوا ممدوحين، وإذا لم يجز ذلك لم يجز أن يكونوا على الإيمان قادرين، ووجب أن يكون الله عز وجلّ اختص بالقدرة على الإيمان المؤمنين.\rمسألة أخرى: يقال لهم: ولو كانت القدرة على الكفر قدرة على الإيمان فقد رغب إليه في القدرة على الكفر؛ فلما رأينا المؤمنين يرغبون إلى الله عز وجلّ في قدرة الإيمان ويزهدون في قدرة الكفر علمنا أن الذي رغبوا فيه غير الذي زهدوا فيه.\rمسألة أخرى: ويقال لهم: أخبرونا عن قوة الإيمان أليست فضلا من الله عز وجلّ؟ فلا بد من نعم، فيقال لهم: فالتفضل أليس هو ما للمتفضل أن لا يتفضل به وله أن يتفضل به؟ فلا بد من الإجابة إلى ذلك بنعم؛ لأن ذلك هو الفرق بين الفضل وبين الاستحقاق، ويقال لهم: وللمتفضل إذا أمر بالإيمان أن يرفع التفضل ولا يتفضل به فيأمرهم بالإيمان وإن خذلهم لم يعطهم قدرة على الإيمان، وهذا هو قولنا ومذهبنا.\rجواب: ويقال لهم: هل يقدر الله على توفيق يوفق به الكافرين حتى يكونوا مؤمنين؟ فإن قالوا: «لا» نطقوا بتعجيز الله عز وجلّ - تعالى عن ذلك علوّا كبيرا، وإن قالوا: «نعم، يقدر على ذلك ولو فعل بهم التوفيق لامنوا» تركوا قولهم وقالوا بالحق.\rمسألة: وإن سألوا عن قول الله عز وجلّ: {وَمَا اللهُ يُرِيدُ ظُلْمًا لِلْعِبادِ} (1) و عن\r__________\r(1) غافر: 31."], [213, "قوله: {وَمَا اللهُ يُرِيدُ ظُلْمًا لِلْعالَمِينَ (1) قيل لهم: معنى ذلك أنه لا يريد أن يظلمهم؛ لأنه قال: وما الله يريد ظلما لهم، ولم يقل: لا يريد ظلم بعضهم لبعض فلم يرد أن يظلمهم، وإن كان أراد ظلم بعضهم لبعض أي فلم يرد أن يظلمهم وإن كان أراد أن يتظالموا.\rمسألة: وإن سألوا عن قول الله تعالى: {ما تَرى فِي خَلْقِ الرَّحْمنِ مِنْ تَفاوُتٍ} (2) قالوا: والكفر متفاوت فكيف يكون من خلق الله؟ والجواب عن ذلك أنه عز وجلّ قال: {خَلَقَ سَبْعَ سَماواتٍ طِباقًا ما تَرى فِي خَلْقِ الرَّحْمنِ مِنْ تَفاوُتٍ فَارْجِعِ الْبَصَرَ هَلْ تَرى مِنْ فُطُورٍ (3) ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنْقَلِبْ إِلَيْكَ الْبَصَرُ خاسِئًا وَهُوَ حَسِيرٌ} (3)، فإنما عنى حينئذ: وما ترى في السموات من فطور؛ لأنه ذكر خلق السموات ولم يذكر الكفر، وإذا كان هذا على ما قلنا بطل ما قالوه، والحمد لله رب العالمين.\rجواب: ويقال لهم: هل تعرفون لله عز وجلّ نعمة على أبي بكر الصديق رضي الله عنه خص بها دون أبي جهل ابتداء؟ فإن قالوا: «لا» فحش قولهم، وإن قالوا: «نعم» تركوا مذهبهم، لأنهم لا يقولون: إن الله خص المؤمنين في الابتداء بما لم يخص به الكافرين.\rمسألة: وإن سألوا عن قول الله عز وجلّ: {وَما خَلَقْنَا السَّماءَ وَالْأَرْضَ وَما بَيْنَهُما باطِلًا} (4)، فقالوا: هذه الآية تدل على أن الله عز وجلّ لم يخلق الباطل، والجواب عن ذلك: أن الله عز وجلّ أراد تكذيب المشركين الذين قالوا: لا حشر ولا نشور ولا\r__________\r(1) آل عمران: 108.\r(2) الملك: 3.\r(3) الملك: 3 - 4.\r(4) ص: 27."], [214, "إعادة، فقال تعالى: {ما خلقت ذلك وأنا لا أثيب من أطاعني ولا أعاقب من عصاني كما ظن الكافرون أنه لا حشر ولا نشور ولا ثواب ولا عقاب؛ ألا تراه قال: {ذلِكَ ظَنُّ الَّذِينَ كَفَرُوا فَوَيْلٌ لِلَّذِينَ كَفَرُوا مِنَ النّارِ} (1) و بيّن ذلك بقوله: {أَمْ نَجْعَلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصّالِحاتِ كَالْمُفْسِدِينَ فِي الْأَرْضِ أَمْ نَجْعَلُ الْمُتَّقِينَ كَالْفُجّارِ} (2)، أي لا نسوي بينهم في أن نفنيهم أجمعين ولا نعيدهم فيكون سبيلهم سبيلا واحدا.\rمسألة: وإن سألوا عن قول الله عز وجلّ: {ما أَصابَكَ مِنْ حَسَنَةٍ فَمِنَ اللهِ وَما أَصابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ} (3)، والجواب عن ذلك أن الله عز وجلّ قال: {وَإِنْ تُصِبْهُمْ حَسَنَةٌ} - يعني الخصب والخير - {يَقُولُوا هذِهِ مِنْ عِنْدِ اللهِ وَإِنْ تُصِبْهُمْ سَيِّئَةٌ} - يعني الجدوبة والقحط‍ والمصائب - {يَقُولُوا هذِهِ مِنْ عِنْدِ اللهِ} - أي لشؤمك، قال الله يا محمد: {قُلْ كُلٌّ مِنْ عِنْدِ اللهِ فَما لِهؤُلاءِ الْقَوْمِ لا يَكادُونَ يَفْقَهُونَ حَدِيثًا (78)} (4) في قولهم: {ما أَصابَكَ مِنْ حَسَنَةٍ فَمِنَ اللهِ وَما أَصابَكَ مِنْ سَيِّئَةٍ فَمِنْ نَفْسِكَ}، فحذف قولهم؛ لأن ما تقدم من الكلام يدل عليه؛ لأن القرآن لا يتناقض، ولا يجوز أن يقول في آية: إن الكل من عند الله، ثم يقول في الآية الأخرى التي تليها: إن الكل ليس من عند الله على أن ما أصاب الناس هو غير ما أصابوه، وهذا يبين بطلان تعلقهم بهذه الآية ويوجب عليهم الحجة.\rمسألة: وإن سألوا عن قول الله عز وجلّ: {وَما خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلاّ\r__________\r(1) ص: 27.\r(2) ص: 28.\r(3) النساء: 79.\r(4) النساء: 78."], [215, "لِيَعْبُدُونِ} (1) فالجواب عن ذلك أن الله عز وجلّ إنما عنى المؤمنين دون الكافرين؛ لأنه أخبرنا أنه ذرأ لجهنم كثيرا من خلقه؛ فالذين خلقهم لجهنم وأحصاهم وعدهم وكتبهم بأسمائهم وأسماء آبائهم وأمهاتهم غير الذين خلقهم لعبادته.\r***"], [216, "مسألة في التكليف\rويقال لهم: "]], "pg": [212, 216]}, "إ.5.3": {"x": [[216, "أليس قد كلف الله عز وجلّ الكافرين أن يستمعوا الحق ويقبلوه ويؤمنوا بالله؟ فلا بد من نعم، يقال لهم: فقد قال الله عز وجلّ: {ما كانُوا يَسْتَطِيعُونَ السَّمْعَ} (1) و قال: {وَكانُوا لا يَسْتَطِيعُونَ سَمْعًا} (2) و قد كلفهم استماع الحق.\rجواب: ويقال لهم: أليس قد قال الله عز وجلّ: {يَوْمَ يُكْشَفُ عَنْ ساقٍ وَيُدْعَوْنَ إِلَى السُّجُودِ فَلا يَسْتَطِيعُونَ} (3) أليس قد أمرهم عز وجلّ بالسجود في الآخرة، وجاء في الخبر أن المنافقين يجعل في أصلابهم كالصفائح فلا يستطيعون السجود، وفي هذا تثبيت لما نقوله من أنه لا يجب لهم على الله عز وجلّ إذا أمرهم أن يقدرهم، وهو بطلان قول القدرية.\r***\r__________\r(1) هود: 20.\r(2) الكهف: 101.\r(3) القلم: 42."], [217, "مسألة في إيلام الأطفال\rويقال لهم: "]], "pg": [216, 217]}, "إ.5.4": {"x": [[217, "أليس قد آلم الله عز وجلّ الأطفال في الدنيا بآلام أوصلها إليهم كنحو الجذام الذي يقطع أيديهم وأرجلهم وغير ذلك مما يؤلمهم به، وكان ذلك سائغا جائزا؟ فإذا قالوا: نعم، قيل لهم: فإذا كان هذا عدلا فما أنكرتم أن يؤلمهم في الآخرة ويكون ذلك منه عدلا؟ فإن قالوا: آلمهم في الدنيا ليعتبر بهم الآباء، قيل لهم: فإذا فعل بهم ذلك في الدنيا ليعتبر بهم الآباء وكان ذلك منه عدلا فلم لا يؤلم أطفال الكافرين في الآخرة ليغيظ‍ بذلك آباءهم ويكون ذلك منه عدلا؟ وقد قيل في الخبر: إن أطفال المشركين تؤجج لهم نار يوم القيامة ثم يقال لهم: اقتحموها! فمن اقتحمها أدخله الجنة، ومن لم يقتحمها أدخله النار.\rمسألة: وقد قيل في الأطفال وروي عن النبي صلّى الله عليه وسلّم: «إن شئت أسمعتك ضغاءهم (1) في النّار» (2).\rجواب: ويقال لهم: أليس قد قال الله تعالى: {تَبَّتْ يَدا أَبِي لَهَبٍ وَتَبَّ (1) ما أَغْنى عَنْهُ مالُهُ وَما كَسَبَ (2) سَيَصْلى نارًا ذاتَ لَهَبٍ} (3) و أمره مع ذلك بالإيمان فأوجب عليه أن يعلم أنه لا يؤمن وأن الله صادق في إخباره عنه أنه لا يؤمن، وأمره مع ذلك أن يؤمن، ولا يجتمع الإيمان والعلم بأنه لا يكون، ولا يقدر القادر على أن يؤمن وأن يعلم أنه لا يؤمن، وإذا كان هذا هكذا فقد أمر الله سبحانه أبا لهب بما لا يقدر عليه؛ لأنه أمره أن يؤمن وأنه يعلم أنه لا يؤمن.\r__________\r(1) في مسند أحمد، ومسند ابن الجعد: «تضاغيهم».\r(2) أخرجه أحمد في مسنده (208/ 6)، وابن الجعد كما في مسنده ح (2969) من حديث عائشة به، وقال الهيثمي في المجمع (440/ 7): «رواه أحمد، وفيه أبو عقيل يحيى بن المتوكل، ضعفه جمهور الأئمة أحمد وغيره ويحيى بن معين، ونقل عنه توثيقه في رواية من ثلاثة». اه‍.\r(3) المسد: 1 - 3."], [218, "مسألة: ويقال لهم: أليس أمر الله عز وجلّ بالإيمان من علم أنه لا يؤمن؟ فمن قولهم: «نعم»، يقال لهم: فأنتم قادرون على الإيمان ويتأتى لكم ذلك؟ فإن قالوا: «لا» وافقوا، وإن قالوا: «نعم» زعموا أن العباد يقدرون على الخروج من علم الله - تعالى الله عز وجلّ عن ذلك علوّا كبيرا.\r***"], [219, "الرد على المعتزلة\rقال أبو الحسن الأشعري: ويقال لهم: "]], "pg": [217, 219]}, "إ.5.5": {"x": [[219, "أليس المجوس أثبتوا أن الشيطان يقدر على الشر الذي لا يقدر الله عز وجلّ عليه فكانوا بقولهم هذا كافرين؟ فلا بد من نعم، يقال لهم: فإذا زعمتم أن الكافرين يقدرون على الكفر والله عز وجلّ لا يقدر عليه فقد زدتم على المجوس في قولهم؛ لأنكم تقولون معهم: إن الشيطان يقدر على الشر والله لا يقدر عليه، وهذا مما يبينه الخبر عن رسول الله صلّى الله عليه وسلّم: «إنّ القدريّة مجوس هذه الأمّة» (1)، وإنما صاروا مجوس هذه الأمة لأنهم قالوا بقول المجوس.\rمسألة: وزعمت القدرية أنا نستحق اسم القدر؛ لأنا نقول: إن الله عز وجلّ قدّر الشر والكفر، فمن يثبت القدر كان قدريّا دون من لم يثبته، فيقال لهم: القدري هو من يثبت القدر لنفسه دون ربه عز وجلّ، وأنه يقدر أفعاله دون خالقه، وكذلك هو في اللغة؛ لأن الصائغ هو من زعم أنه يصوغ دون من يقول إنه يصاغ له، والنجار هو من يضيف النجارة إلى نفسه دون من يزعم أنه ينجر له، فلما كنتم تزعمون أنكم تقدرون أعمالكم وتفعلونها دون ربكم وجب أن تكونوا قدرية، ولم نكن نحن قدرية لأنا لم نضف الأعمال إلى أنفسنا دون ربناعز وجلّ، ولم نقل: إنا نقدرها دونه، وقلنا: إنها تقدر لنا.\rجواب: ويقال لهم: إذا كان من أثبت التقدير لله عز وجلّ قدريّا فيلزمكم إذا زعمتم أن الله عز وجلّ قدر السموات والأرض، وقدر الطاعات أن تكونوا قدرية، فإذا لم يلزم هذا فقد بطل قولكم وانتقض كلامكم.\r***\r__________\r(1) تقدم تخريجه."], [220, "مسألة في الختم\rيقال لهم: "]], "pg": [219, 220]}, "إ.5.6": {"x": [[220, "أ ليس قد قال الله عز وجلّ: {خَتَمَ اللهُ عَلى قُلُوبِهِمْ وَعَلى سَمْعِهِمْ وَعَلى أَبْصارِهِمْ غِشاوَةٌ} (1) و قال عز وجلّ: {فَمَنْ يُرِدِ اللهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا} (2)، فخبرونا عن الذين ختم الله على قلوبهم وعلى سمعهم، أتزعمون أنه هداهم وشرح للإسلام صدورهم وأضلهم؟ فإن قالوا: «نعم» تناقض قولهم وقيل لهم: كيف القفل الذي قال الله عز وجلّ: {أَمْ عَلى قُلُوبٍ أَقْفالُها} (3) مع الشرح، والضيق مع السعة، والهدى مع الضلال؛ إن كان هذا جاز أن يجتمع التوحيد والإلحاد الذي هو ضد التوحيد، والكفر والإيمان معا في قلب واحد، وإن لم يجز هذا لم يجز ما قلتموه؛ فإن قالوا: الختم والضيق والضلال لا يجوز أن يجتمع مع شرح الله الصدر، قيل لهم: وكذلك الهدى لا يجتمع مع الضلال، وإذا كان هكذا فما شرح الله صدور الكافرين للإيمان بل ختم على قلوبهم وأقفلها عن الحق وشد عليها، كما دعا نبي الله موسى عليه السّلام على قومه فقال: {رَبَّنَا اطْمِسْ عَلى أَمْوالِهِمْ وَاشْدُدْ عَلى قُلُوبِهِمْ فَلا يُؤْمِنُوا حَتّى يَرَوُا الْعَذابَ الْأَلِيمَ} (4) و قال الله عز وجلّ: {قَدْ أُجِيبَتْ دَعْوَتُكُما} (5) و قال عز وجلّ يخبر عن الكافرين أنهم قالوا: {قُلُوبُنا فِي أَكِنَّةٍ مِمّا تَدْعُونا إِلَيْهِ وَفِي آذانِنا وَقْرٌ وَمِنْ بَيْنِنا وَبَيْنِكَ حِجابٌ} (6) فإذا خلق الله الأكنة في قلوبهم والقفل والزيغ -\r__________\r(1) البقرة: 7.\r(2) الأنعام: 125.\r(3) محمد: 24.\r(4) يونس: 88.\r(5) يونس: 89.\r(6) فصلت: 5."], [221, "لأن الله تعالى قال:} فَلَمّا زاغُوا أَزاغَ اللهُ قُلُوبَهُمْ} (1) - والختم وضيق الصدر ثم أمرهم بالإيمان الذي علم أنه لا يكون فقد أمرهم بما لا يقدرون عليه، وإذا خلق الله في قلوبهم ما ذكرناه من الضيق عن الإيمان؛ فهل الضيق عن الإيمان إلا الكفر الذي في قلوبهم، وهذا يبين أن الله خلق كفرهم ومعاصيهم.\rجواب: ويقال لهم: قال الله عز وجلّ لنبيه عليه السّلام: {وَلَوْ لا أَنْ ثَبَّتْناكَ لَقَدْ كِدْتَ تَرْكَنُ إِلَيْهِمْ شَيْئًا قَلِيلًا} (2) و قال يخبر عن يوسف: {وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِها لَوْ لا أَنْ رَأى بُرْهانَ رَبِّهِ} (3) فحدثونا عن ذلك التثبيت والبرهان هل فعله الله عز وجلّ بالكافرين أو ما هو مثله؟ فإن قالوا: «لا» تركوا القول بالقدر، وإن قالوا: «نعم» قيل لهم: فإذا كان لم يركن إليهم من أجل التثبيت فيجب لو كان فعل ذلك بالكافرين أن لا يثبتوا عن الكفر، وإذا لم يكونوا عن الكفر مفترقين فقد بطل أن يكون فعل بهم مثل ما فعله بالنبي صلّى الله عليه وسلّم من التثبيت الذي لما فعله به لم يركن إلى الكافرين.\r***\r__________\r(1) الصف: 5.\r(2) الإسراء: 74.\r(3) يوسف: 24."], [222, "مسألة في الاستثناء\rيقال لهم: "]], "pg": [220, 222]}, "إ.5.7": {"x": [[222, "خبرونا عن مطالبة رجل بحق، فقال له: والله لأعطينك ذلك غدا إن شاء الله، أليس الله شائيا أن يعطيه حقه؟ فمن قولهم: «نعم» يقال لهم: أفرأيتم إن جاء الغد فلم يعطه حقه أليس لا يحنث؟ فلا بد من نعم، فيقال لهم: فلو كان الله شاء أن يعطيه حقه لحنث إذا لم يعطه كما لو قال: والله لأعطينك حقك إذا طلع الفجر غدا ثم طلع ولم يعطه يكون حانثا.\r***"], [223, "مسألة في الآجال\rيقال لهم: أليس قد قال الله عز وجلّ: {إِذا جاءَ أَجَلُهُمْ فَلا يَسْتَأْخِرُونَ ساعَةً وَلا يَسْتَقْدِمُونَ} (1) و قال: {وَلَنْ يُؤَخِّرَ اللهُ نَفْسًا إِذا جاءَ أَجَلُها} (2)؟ فلا بد من نعم، يقال لهم: فخبرونا عمن قتله قاتل ظلما أتزعمون أنه قتل في أجله أو بأجله؟ فإن قالوا: «نعم» وافقوا وقالوا بالحق وتركوا القدر، وإن قالوا: «لا» قيل لهم: فمتى أجل هذا المقتول؟ فإن قالوا: الوقت الذي علم الله أنه لو لم يقتل لتزوج امرأة علم أنها امرأته، وإن لم يبلغ إلى أن يتزوجها، وإذا كان في معلوم الله أنه لو لم يقتل وبقي لكفر أن تكون النار داره، وإذا لم يجز هذا لم يجز أن يكون الوقت الذي لم يبلغ إليه أجلا له، على أن هذا القول لا يفيد، لقول الله عز وجلّ: {إِذا جاءَ أَجَلُهُمْ فَلا يَسْتَأْخِرُونَ ساعَةً وَلا يَسْتَقْدِمُونَ} (3).\rمسألة أخرى: ويقال لهم: إذا كان القاتل عندكم قادرا على أن لا يقتل هذا المقتول فيعيش، فهو قادر على قطع أجله وتقديمه قبل أجله، وهو قادر على تأخيره إلى أجله؛ فالإنسان على قولكم يقدر أن يقدم آجال العباد ويؤخرها، ويقدر أن يبقي العباد ويبلغهم ويخرج أرواحهم، وهذا إلحاد في الدين.\r***\r__________\r(1) يونس: 49.\r(2) المنافقون: 11.\r(3) يونس: 49."], [224, "مسألة في الأرزاق\rويقال لهم: "]], "pg": [222, 224]}, "إ.5.8": {"x": [[220, "أ ليس قد قال الله عز وجلّ: {خَتَمَ اللهُ عَلى قُلُوبِهِمْ وَعَلى سَمْعِهِمْ وَعَلى أَبْصارِهِمْ غِشاوَةٌ} (1) و قال عز وجلّ: {فَمَنْ يُرِدِ اللهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلامِ وَمَنْ يُرِدْ أَنْ يُضِلَّهُ يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا} (2)، فخبرونا عن الذين ختم الله على قلوبهم وعلى سمعهم، أتزعمون أنه هداهم وشرح للإسلام صدورهم وأضلهم؟ فإن قالوا: «نعم» تناقض قولهم وقيل لهم: كيف القفل الذي قال الله عز وجلّ: {أَمْ عَلى قُلُوبٍ أَقْفالُها} (3) مع الشرح، والضيق مع السعة، والهدى مع الضلال؛ إن كان هذا جاز أن يجتمع التوحيد والإلحاد الذي هو ضد التوحيد، والكفر والإيمان معا في قلب واحد، وإن لم يجز هذا لم يجز ما قلتموه؛ فإن قالوا: الختم والضيق والضلال لا يجوز أن يجتمع مع شرح الله الصدر، قيل لهم: وكذلك الهدى لا يجتمع مع الضلال، وإذا كان هكذا فما شرح الله صدور الكافرين للإيمان بل ختم على قلوبهم وأقفلها عن الحق وشد عليها، كما دعا نبي الله موسى عليه السّلام على قومه فقال: {رَبَّنَا اطْمِسْ عَلى أَمْوالِهِمْ وَاشْدُدْ عَلى قُلُوبِهِمْ فَلا يُؤْمِنُوا حَتّى يَرَوُا الْعَذابَ الْأَلِيمَ} (4) و قال الله عز وجلّ: {قَدْ أُجِيبَتْ دَعْوَتُكُما} (5) و قال عز وجلّ يخبر عن الكافرين أنهم قالوا: {قُلُوبُنا فِي أَكِنَّةٍ مِمّا تَدْعُونا إِلَيْهِ وَفِي آذانِنا وَقْرٌ وَمِنْ بَيْنِنا وَبَيْنِكَ حِجابٌ} (6) فإذا خلق الله الأكنة في قلوبهم والقفل والزيغ -\r__________\r(1) البقرة: 7.\r(2) الأنعام: 125.\r(3) محمد: 24.\r(4) يونس: 88.\r(5) يونس: 89.\r(6) فصلت: 5."], [221, "لأن الله تعالى قال:} فَلَمّا زاغُوا أَزاغَ اللهُ قُلُوبَهُمْ} (1) - والختم وضيق الصدر ثم أمرهم بالإيمان الذي علم أنه لا يكون فقد أمرهم بما لا يقدرون عليه، وإذا خلق الله في قلوبهم ما ذكرناه من الضيق عن الإيمان؛ فهل الضيق عن الإيمان إلا الكفر الذي في قلوبهم، وهذا يبين أن الله خلق كفرهم ومعاصيهم.\rجواب: ويقال لهم: قال الله عز وجلّ لنبيه عليه السّلام: {وَلَوْ لا أَنْ ثَبَّتْناكَ لَقَدْ كِدْتَ تَرْكَنُ إِلَيْهِمْ شَيْئًا قَلِيلًا} (2) و قال يخبر عن يوسف: {وَلَقَدْ هَمَّتْ بِهِ وَهَمَّ بِها لَوْ لا أَنْ رَأى بُرْهانَ رَبِّهِ} (3) فحدثونا عن ذلك التثبيت والبرهان هل فعله الله عز وجلّ بالكافرين أو ما هو مثله؟ فإن قالوا: «لا» تركوا القول بالقدر، وإن قالوا: «نعم» قيل لهم: فإذا كان لم يركن إليهم من أجل التثبيت فيجب لو كان فعل ذلك بالكافرين أن لا يثبتوا عن الكفر، وإذا لم يكونوا عن الكفر مفترقين فقد بطل أن يكون فعل بهم مثل ما فعله بالنبي صلّى الله عليه وسلّم من التثبيت الذي لما فعله به لم يركن إلى الكافرين.\r***\r__________\r(1) الصف: 5.\r(2) الإسراء: 74.\r(3) يوسف: 24."], [222, "مسألة في الاستثناء\rيقال لهم: خبرونا عن مطالبة رجل بحق، فقال له: والله لأعطينك ذلك غدا إن شاء الله، أليس الله شائيا أن يعطيه حقه؟ فمن قولهم: «نعم» يقال لهم: أفرأيتم إن جاء الغد فلم يعطه حقه أليس لا يحنث؟ فلا بد من نعم، فيقال لهم: فلو كان الله شاء أن يعطيه حقه لحنث إذا لم يعطه كما لو قال: والله لأعطينك حقك إذا طلع الفجر غدا ثم طلع ولم يعطه يكون حانثا.\r***"], [223, "مسألة في الآجال\rيقال لهم: أليس قد قال الله عز وجلّ: {إِذا جاءَ أَجَلُهُمْ فَلا يَسْتَأْخِرُونَ ساعَةً وَلا يَسْتَقْدِمُونَ} (1) و قال: {وَلَنْ يُؤَخِّرَ اللهُ نَفْسًا إِذا جاءَ أَجَلُها} (2)؟ فلا بد من نعم، يقال لهم: فخبرونا عمن قتله قاتل ظلما أتزعمون أنه قتل في أجله أو بأجله؟ فإن قالوا: «نعم» وافقوا وقالوا بالحق وتركوا القدر، وإن قالوا: «لا» قيل لهم: فمتى أجل هذا المقتول؟ فإن قالوا: الوقت الذي علم الله أنه لو لم يقتل لتزوج امرأة علم أنها امرأته، وإن لم يبلغ إلى أن يتزوجها، وإذا كان في معلوم الله أنه لو لم يقتل وبقي لكفر أن تكون النار داره، وإذا لم يجز هذا لم يجز أن يكون الوقت الذي لم يبلغ إليه أجلا له، على أن هذا القول لا يفيد، لقول الله عز وجلّ: {إِذا جاءَ أَجَلُهُمْ فَلا يَسْتَأْخِرُونَ ساعَةً وَلا يَسْتَقْدِمُونَ} (3).\rمسألة أخرى: ويقال لهم: إذا كان القاتل عندكم قادرا على أن لا يقتل هذا المقتول فيعيش، فهو قادر على قطع أجله وتقديمه قبل أجله، وهو قادر على تأخيره إلى أجله؛ فالإنسان على قولكم يقدر أن يقدم آجال العباد ويؤخرها، ويقدر أن يبقي العباد ويبلغهم ويخرج أرواحهم، وهذا إلحاد في الدين.\r***\r__________\r(1) يونس: 49.\r(2) المنافقون: 11.\r(3) يونس: 49."], [224, "مسألة في الأرزاق\rويقال لهم: "]], "pg": [220, 224]}, "إ.5.9": {"x": [[224, "خبرونا عمن اغتصب طعاما فأكله حراما هل رزقه الله ذلك الحرام؟ فإن قالوا: «نعم» تركوا القدر، وإن قالوا: «لا» قيل لهم: فمن أكل جميع عمره الحرام فما رزقه الله شيئا اغتذى به جسمه، ويقال لهم: فإذا كان غيره يغتصب له ذلك الطعام ويطعمه إياه إلى أن مات فرازق هذا الإنسان عندكم غير الله، وفي هذا إقرار منهم أن للخلق رازقين: أحدهما يرزق الحلال، والآخر يرزق الحرام، وأن الناس تنبت لحومهم وتشتد عظامهم، والله غير رازق لهم ما اغتذوا به، وإذا قلتم: إن الله لم يرزقه الحرام لزمكم أن الله لم يغذه به ولا جعله قواما لجسمه، وأن لحمه وجسمه قام وعظمه اشتد بغير الله عز وجلّ، وهو من رزقه الحرام، وهذا كفر عظيم إن احتملوا.\r***"], [225, "مسألة أخرى في الأرزاق\rويقال لهم: "]], "pg": [224, 225]}, "إ.5.10": {"x": [[225, "لم أبيتم أن يرزق الله الحرام؟ فإن قالوا: لأنه لو رزق الحرام لملّك الحرام، يقال لهم: خبرونا عن الطفل الذي يتغذى من لبن أمه، وعن البهيمة التي ترعى الحشيش من يرزقهما ذلك؟ فإن قالوا: الله، قيل لهم: هل ملكهما وهل للبهيمة ملك؟ فإن قالوا: «لا» قيل لهم: فلم زعمتم أنه لو رزق الحرام لملك الحرام، وقد يرزق الله الشيء ولا يملّكه، ويقال لهم: هل أقدر الله العبد على الحرام ولم يملكه إياه؟ فمن قولهم: «نعم» يقال لهم: فما أنكرتم أن يرزقه الحرام وإن لم يملكه إياه.\rجواب: يقال لهم: إذا كان توفيق المؤمنين بالله فما أنكرتم أن يكون خذلان الكافرين من قبل الله، وإلا فإن زعمتم أن الله وفق الكافرين للإيمان فقولوا: عصمهم من الكفر، وكيف يعصمهم من الكفر وقد وقع الكفر منهم؛ فإن أثبتوا أن الله خذلهم قيل لهم: فالخذلان من الله أليس هو الكفر الذي خلقه فيهم؟ فإن قالوا: نعم وافقوا، وإن قالوا: «لا» قيل لهم: فما ذلك الخذلان الذي خلقه؟ فإن قالوا: تخليته إياهم والكفر، قيل لهم: أ وليس من قولكم: إن الله عز وجلّ خلّى بين المؤمنين وبين الكفر؟ فمن قولهم: «نعم» قيل لهم: فإذا كان الخذلان التخلية بينهم وبين الكفر فقد لزمكم أن يكون خذل المؤمنين لأنه خلى بينهم وبين الكفر، وهذا خروج عن الدين؛ فلا بد لهم أن يثبتوا لهم الخذلان للكفر الذي خلقه الله فيهم فيتركوا القول بالقدر.\rمسألة: إن سأل سائل من أهل القدر فقال: هل يخلو العبد من أن يكون بين نعمة يجب عليه أن يشكر الله عليها أو بلية يجب عليه الصبر عليها؟ قيل له: العبد لا يخلو من نعمة وبلية، والنعمة يجب على العبد أن يشكر الله عليها، والبلايا على ضربين: منها ما يجب الصبر عليها كالأمراض والأسقام وما أشبه ذلك، ومنها"], [226, "ما يجب عليه الإقلاع عنها كالكفر والمعاصي.\rمسألة: وإن سألوا فقالوا: أيما خير: الخير أو من الخير منه؟ قيل لهم: من كان الخير منه متفضلا به فهو خير من الخير، فإن قالوا: فأيما شر: الشر أو من الشر منه؟ قيل لهم: من كان الشر منه جائرا به فهو شر من الشر، والله عز وجلّ يكون منه الشر خلقا وهو عادل به؛ فلذلك لا يلزمنا ما سألتم عنه على أنكم ناقضون لأصولكم؛ لأنه إن كان من كان الشر منه فهو شر من الشر، وقد خلق الله عز وجلّ إبليس الذي هو شر من الشر الذي يكون منه؛ فقد خلق ما هو شر من الشرور كلها، وهذا نقض دينكم وفساد مذهبكم.\r***"], [227, "مسألة في الهدى\r"]], "pg": [225, 227]}, "إ.5.11": {"x": [[227, "يقال للمعتزلة: أ ليس قد قال الله عز وجلّ: {الم (1) ذلِكَ الْكِتابُ لا رَيْبَ فِيهِ هُدىً لِلْمُتَّقِينَ} (1) فأخبر أن القرآن هدى للمتقين؟ فلا بد من نعم، يقال لهم: أوليس قد ذكر الله عز وجلّ القرآن فقال: {وَالَّذِينَ لا يُؤْمِنُونَ فِي آذانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى} (2) فخبر أن القرآن على الكافرين عمى؟ فلا بد من نعم، ويقال لهم: فهل يجوز أن يكون من أخبر الله عز وجلّ أن القرآن له هدى هو عليه عمى؟ فلا بد من لا، يقال لهم: فكما لا يجوز أن يكون القرآن عمى على من أخبر الله أنه له هدى كذلك لا يجوز أن يكون القرآن هدى لمن أخبر الله أنه عليه عمى.\rمسألة أخرى: ثم يقال لهم: إذا جاز أن يكون دعاء الله إلى الإيمان هدى لمن قبل ولمن لم يقبل، فما أنكرتم دعاء إبليس إلى الكفر إضلالا لمن قبل ولمن لم يقبل؛ فإن كان دعاء إبليس إلى الكفر إضلالا للكافرين الذين قبلوا عنه دون المؤمنين الذين لم يقبلوا عنه؛ فما أنكرتم أن دعاء الله عز وجلّ إلى الإيمان هدى للمؤمنين الذين قبلوا عنه دون الكافرين الذين لم يقبلوا عنه، وإلا فما الفرق بين ذلك.\rمسألة أخرى: ويقال لهم: أليس قال الله عز وجلّ: {يُضِلُّ بِهِ كَثِيرًا} (3) فهل يدل قوله: {يُضِلُّ بِهِ كَثِيرًا} على أنه لم يضل الكل؛ لأنه لو أراد الكل لقال: يضل به الكل؛ فلما قال: {يُضِلُّ بِهِ كَثِيرًا} علمنا أنه لم يضل الكل؛ فلا بد من نعم، فيقال لهم: فما أنكرتم أن قوله: {وَيَهْدِي بِهِ كَثِيرًا} دليل على أنه لم يرد الكل؛ لأنه لو أراد الكل لقال: ويهدي به الكل، فلما قال: {وَيَهْدِي بِهِ كَثِيرًا} علمنا أنه لم يهدا الكل، وفي هذا إبطال قولكم: إن الله هدى الخلق أجمعين.\r__________\r(1) البقرة: 1 - 2.\r(2) البقرة: 26.\r(3) البقرة: 26."], [228, "مسألة أخرى: ويقال لهم: إذا قلتم: إن دعاء الله إلى الإيمان هدى للكافرين الذين لم يقبلوا عن الله أمره، فما أنكرتم أن يكون دعاء الله إلى الإيمان نفعا وصلاحا وتسديدا للكافرين الذين لم يقبلوا عن الله أمره، وما أنكرتم أن يكون عصمة لهم من الكفر وإن لم يكونوا من الكفر معتصمين، وأن يكون توفيقا للإيمان وإن لم يوفقوا للإيمان، وفي هذا ما يجب أن الله سدد الكافرين وأصلحهم وعصمهم ووفقهم للإيمان وإن كانوا كافرين، وهذا مما لا يجوز لأن الكافرين مخذولون، وكيف يكونون موفقين للإيمان وهم مخذولون؟! فإن جاز أن يكون الكافر موفقا للإيمان فما أنكرتم أن يكون الإيمان له متفقا؛ فإن استحال هذا فما أنكرتم أن يستحيل ما قلتموه.\r***"], [229, "مسألة في الضلال\rيقال لهم: "]], "pg": [227, 229]}, "إ.5.12": {"x": [[229, "أضل الله الكافرين عن الإيمان أو عن الكفر؟ فإن قالوا: «عن الكفر» قيل لهم: فكيف يكونون ضالين عن الكفر ذاهبين عنه وهم كافرون؟! فإن قالوا: أضلهم عن الإيمان تركوا قولهم؛ وإن قالوا: نقول: إن الله أضلهم ولم يضلهم عن شيء، قيل لهم: ما الفرق بينكم وبين من قال: إن الله هدى المؤمنين لا إلى شيء؟ فإن استحال أن يهدي المؤمنين لا إلى الإيمان فما أنكرتم من أنه محال أن يضل الكافرين لا عن الإيمان.\rمسألة أخرى: ويقال لهم: ما معنى قول الله عز وجلّ: {وَيُضِلُّ اللهُ الظّالِمِينَ} (1)؟ فإن قالوا: معنى ذلك أنه يسميهم ضالين ويحكم عليهم بالضلال، قيل لهم: أليس خاطب الله العرب بلغتها فقال {بِلِسانٍ عَرَبِيٍّ مُبِينٍ} (2) و قال: {وَما أَرْسَلْنا مِنْ رَسُولٍ إِلاّ بِلِسانِ قَوْمِهِ} (3)؟ فلا بد من نعم، فيقال لهم: فإذا كان أنزل الله القرآن بلسان العرب فمن أين وجدتم في لغة العرب أن يقال: أضل فلان فلانا، أي سماه ضالاّ؟ فإن قالوا: وجدنا القائل يقول: إذا قال رجل لرجل: ضالّ: قد ضللته، قيل لهم: قد وجدنا العرب يقولون: ضلل فلان فلانا إذا سماه ضالاّ، ولم نجدهم يقولون: أضل فلان فلانا بهذا المعنى، فلما قال الله عز وجلّ: {وَيُضِلُّ اللهُ الظّالِمِينَ} (4) لم يجز أن يكون ذلك معنى ذلك الاسم، والحكم إذا لم يجز في لغة العرب أن يقال: أضل فلان فلانا إذا سماه ضالاّ بطل تأويلكم؛ إذ كان خلاف لسان العرب.\rمسألة أخرى: ويقال لهم: إذا قلتم: إن الله أضل الكافرين بأن سماهم: ضالين،\r__________\r(1) إبراهيم: 27.\r(2) الشعراء: 195.\r(3) إبراهيم: 4.\r(4) إبراهيم: 27."], [230, "وليس ذلك في اللغة على ما ادعيتموه فيلزمكم إذا سمى النبي صلّى الله عليه وسلّم قوما ضالين فاسدين بأن يكون قد أضلهم وأفسدهم بأن سماهم: ضالين فاسدين، وإذا لم يجز هذا بطل أن يكون معنى: {وَيُضِلُّ اللهُ الظّالِمِينَ} الاسم والحكم كما ادعيتم.\rجواب: ويقال لهم: أليس قد قال الله تعالى: {مَنْ يَهْدِ اللهُ فَهُوَ الْمُهْتَدِ وَمَنْ يُضْلِلْ فَلَنْ تَجِدَ لَهُ وَلِيًّا مُرْشِدًا} (1) و قال عز وجلّ: {كَيْفَ يَهْدِي اللهُ قَوْمًا كَفَرُوا بَعْدَ إِيمانِهِمْ} (2) فذكر أنه لا يهديهم، وقال: {وَاللهُ يَدْعُوا إِلى دارِ السَّلامِ وَيَهْدِي مَنْ يَشاءُ إِلى صِراطٍ‍ مُسْتَقِيمٍ} (3)؛ فجعل الدعاء عامّا والهدى خاصّا، وقال: {لا يَهْدِي الْقَوْمَ الْكافِرِينَ} (4) فإذا أخبر الله عز وجلّ أنه لا يهدي القوم الكافرين فكيف يجوز لقائل أن يقول: إنه هدى الكافرين مع إخباره أنه لا يهديهم، ومع قوله: {إِنَّكَ لا تَهْدِي مَنْ أَحْبَبْتَ وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ} (5) و مع قوله: {لَيْسَ عَلَيْكَ هُداهُمْ وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ} (5) ومع قوله:\r{لَيْسَ عَلَيْكَ هُداهُمْ وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ} (6) ومع قوله: {وَلَوْ شِئْنا لَآتَيْنا كُلَّ نَفْسٍ هُداها} (7)، وإن جاز هذا جاز أن يقال: أضل المؤمنين مع قوله: {مَنْ يَهْدِ اللهُ فَهُوَ الْمُهْتَدِ} (8) و مع قوله: {هُدىً لِلْمُتَّقِينَ} (9)، فإن لم يكن ذلك فما أنكرتم أنه لا يجوز أنه يهدي الكافرين مع قوله {لا يَهْدِي الْقَوْمَ الْكافِرِينَ} ومع سائر الآيات التي طالبناكم بها.\r__________\r(1) الكهف: 17.\r(2) آل عمران: 86.\r(3) يونس: 25.\r(4) النحل: 107.\r(5) القصص: 56.\r(6) البقرة: 272.\r(7) السجدة: 13.\r(8) الكهف: 17.\r(9) البقرة: 2."], [231, "جواب: ويقال لهم: أليس قد قال الله عز وجلّ: {أَفَرَأَيْتَ مَنِ اتَّخَذَ إِلهَهُ هَواهُ وَأَضَلَّهُ اللهُ عَلى عِلْمٍ وَخَتَمَ عَلى سَمْعِهِ وَقَلْبِهِ وَجَعَلَ عَلى بَصَرِهِ غِشاوَةً} (1)؟\rفلا بد من نعم، فيقال لهم: فأضلهم ليضلوا أو ليهتدوا؟ فإن قالوا: «أضلهم ليهتدوا» قيل لهم: وكيف يجوز أن يضلهم ليهتدوا، وإن جاز هذا جاز أن يهديهم ليضلوا، وإذا لم يجز أن يهدي المؤمنين ليضلوا فما أنكرتم من أنه لا يجوز أن يضل الكافرين ليهتدوا.\rجواب: ويقال لهم: إذا زعمتم أن الله هدى الكافرين فلم يهتدوا فما أنكرتم أن ينفعهم فلا ينتفعون وأن يصلحهم فلا ينصلحون، وإذا جاز أن ينفع من لا ينتفع بنفعه فما أنكرتم من أن يضر من لا تلحقه المضرة؛ فإن كان لا يضر إلا من يلحقه الضرر فكذلك لا ينفع إلا منتفعا، ولو جاز أن ينفع من ليس منتفعا جاز أن يقدر من ليس مقتدرا، وإذا استحال ذلك استحال أن ينفع من ليس منتفعا ويهدي من ليس مهتديا.\rمسألة: تسألوننا عنها تقولون: أليس قد قال الله عز وجل: {شَهْرُ رَمَضانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ هُدىً لِلنّاسِ وَبَيِّناتٍ} (2) فما أنكرتم أن يكون القرآن هدى للكافرين والمؤمنين؟ قيل لهم: الآية خاصة، لأن الله عز وجلّ قد بين لنا أنه {هُدىً لِلْمُتَّقِينَ}، وأخبرنا أنه لا يهدي الكافرين، والقرآن لا يتناقض، فوجب أن يكون قوله: {هُدىً لِلنّاسِ} أراد المؤمنين دون الكافرين.\rسؤال: فإن قال قائل: أليس قد قال الله عز وجلّ: {إِنَّما تُنْذِرُ مَنِ اتَّبَعَ الذِّكْرَ} (3)\r__________\r(1) الجاثية: 23.\r(2) البقرة: 185.\r(3) يس: 11."], [232, "وقال: {إِنَّما أَنْتَ مُنْذِرُ مَنْ يَخْشاها} (1) و قد أنذر النبي صلّى الله عليه وسلّم من اتبع الذكر ومن لم يتبع، ومن خشي ومن لم يخش؟ قيل له: «نعم» فإن قالوا: فما أنكرتم أن يكون قوله: {هُدىً لِلْمُتَّقِينَ} أراد به هدى لهم ولغيرهم؟ قيل لهم: إن معنى قول الله عز وجلّ: {إِنَّما تُنْذِرُ مَنِ اتَّبَعَ الذِّكْرَ} إنما أراد به: ينتفع بإنذارك من اتبع الذكر، وقوله: {إِنَّما أَنْتَ مُنْذِرُ مَنْ يَخْشاها} أراد أن الإنذار ينتفع به من يخشى الساعة ويخاف العقوبة فيها، وأن الله عز وجلّ قد أخبر في موضع آخر من القرآن أنه أنذر الكافرين فقال: {إِنَّ الَّذِينَ كَفَرُوا سَواءٌ عَلَيْهِمْ أَأَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ} (2)، وهذا هو خبر عن الكافرين، وقال: {وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ} (3)، وقال: {أَنْذَرْتُكُمْ صاعِقَةً مِثْلَ صاعِقَةِ عادٍ وَثَمُودَ} (4)، وهذا خطاب للكافرين، فلما أخبر الله عز وجلّ في آيات من القرآن أنه أنذر الكافرين كما أخبر الله في آيات أنه أنذر من يخشاها وأنذر من اتبع الذكر وجب بالقرآن أن الله قد أنذر المؤمنين والكافرين، فلما أخبرنا الله أنه هدى للمتقين وعمى على الكافرين، وأخبرنا أنه لا يهدي الكافرين وجب أن يكون القرآن هدى للمؤمنين دون الكافرين.\rسؤال: إن سأل سائل عن قول الله عز وجلّ: {وَأَمّا ثَمُودُ فَهَدَيْناهُمْ فَاسْتَحَبُّوا الْعَمى عَلَى الْهُدى} (5) فقال: أليس ثمود كانوا كافرين، وقد أخبر الله أنه هداهم؟ قيل له: ليس الأمر كما ظننت، والجواب في هذه الآية على وجهين: أحدهما: أن ثمود على فريقين: كافرين ومؤمنين، وهم الذين أخبر أنه أنجاهم مع\r__________\r(1) النازعات: 45.\r(2) البقرة: 6.\r(3) الشعراء: 214.\r(4) فصلت: 13.\r(5) فصلت: 17."], [233, "صالح بقوله عز وجلّ: {نَجَّيْنا صالِحًا وَالَّذِينَ آمَنُوا مَعَهُ} (1)؛ فالذين عنى الله عز وجلّ من ثمود أنه هداهم هم المؤمنون دون الكافرين؛ لأن الله عز وجلّ قد بيّن لنا في القرآن أنه لا يهدي الكافرين، والقرآن لا يتناقض بل يصدق بعضه بعضا؛ فإذا أخبرنا في موضع أنه لا يهدي الكافرين ثم أخبر في موضع أنه هدى ثمود علمنا أنه إنما أراد المؤمنين من ثمود دون الكافرين.\rوالوجه الآخر: أن الله عز وجلّ عنى قوما من ثمود كانوا مؤمنين ثم ارتدوا؛ فأخبر أنه هداهم فاستحبوا بعد الهداية الكفر على الإيمان، وكانوا في حال هداهم مؤمنين.\rفإن قال قائل معترضا في الجواب الأول: كيف يجوز أن يقول: {فَهَدَيْناهُمْ} ويعني المؤمنين من ثمود، ويقول: {فَاسْتَحَبُّوا} يعني الكافرين منهم وهم غير مؤمنين؟ يقال له: هذا جائز في اللغة التي ورد بها القرآن أن يقول {فَهَدَيْناهُمْ} ويعني المؤمنين من ثمود، ويقال: {فَاسْتَحَبُّوا} يعني الكافرين منهم، وقد ورد القول بمثل هذا؛ قال الله عز وجلّ: {وَما كانَ اللهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ} (2) يعني الكفار، ثم قال: {وَما كانَ اللهُ مُعَذِّبَهُمْ وَهُمْ يَسْتَغْفِرُونَ} يعني المؤمنين، ثم قال: {وَما لَهُمْ أَلاّ يُعَذِّبَهُمُ اللهُ} (3) يعني الكافرين، ولا خلاف عند أهل اللغة في جواز الخطاب بهذا؛ أن يكون ظاهره لجنس والمراد به جنسان، فبطل ما اعترض به المعترض ودل على جهله.\r***\r__________\r(1) هود: 66.\r(2) الأنفال: 33.\r(3) الأنفال: 34."], [234, "باب ذكر الروايات في القدر\rروى معاوية بن عمرو قال: "]], "pg": [229, 234]}, "إ.6.1": {"x": [[234, "ثنا زائدة قال: حدثنا سليمان الأعمش عن زيد بن وهب عن عبد الله بن مسعود قال: أخبرنا رسول الله صلّى الله عليه وسلّم وهو الصادق المصدوق «إنّ خلق أحدكم يجمع في بطن أمه في أربعين ليلة، ثم يكون علقة مثل ذلك، ثم يكون مضغة مثل ذلك، ثم يبعث الله الملك، قال: فيؤمر بأربع كلمات، يقال: اكتب أجله ورزقه وعمله وشقيّ أم سعيد، ثم ينفخ فيه الرّوح؛ قال: فإن أحدكم ليعمل بعمل أهل الجنة حتى ما يكون بينه وبينها إلا ذراع فيسبق عليه الكتاب فيعمل عمل أهل النّار فيدخلها، وإن أحدكم ليعمل بعمل أهل النار حتى ما يكون بينه وبينها إلا ذراع فيسبق عليه الكتاب فيختم له بعمل أهل الجنة فيدخلها» (1).\rوروى معاوية بن عمرو قال: "]], "pg": [234, 234]}, "إ.6.2": {"x": [[234, "ثنا زائدة عن الأعمش عن أبي صالح عن أبي هريرة عن النبي صلّى الله عليه وسلّم قال: «احتجّ آدم وموسى، قال موسى: يا آدم أنت الذي خلقك الله بيده ونفخ فيك من روحه أغويت الناس وأخرجتهم من الجنة، قال: فقال آدم: أنت موسى الذي اصطفاك الله بكلماته تلومني على عمل كتبه الله عليّ قبل أن يخلق السموات؛ قال: فحجّ آدم موسى» (2).\rوروى حديث حج آدم موسى مالك عن أبي الزناد عن الأعرج عن أبي هريرة\r__________\r(1) أخرجه البخاري ح (7454، 6594، 3332، 3208)، ومسلم ح (2643) من طرق عن الأعمش به.\r(2) أخرجه أحمد في مسنده (398/ 2) من طريق معاوية بن عمرو، والترمذي ح (2134) من طريق سليمان التيمي، كلاهما عن الأعمش به. وأخرجه البخاري ح (4738، 4736، 3409، 7515، 6614)، ومسلم ح (2652) من أوجه أخر عن أبي هريرة."], [235, "عن النبي صلّى الله عليه وسلّم (1)، وهذا يدل على بطلان قول القدرية الذين يقولون: إن الله عز وجلّ لا يعلم الشيء حتى يكون؛ لأن الله عز وجلّ إذا كتب ذلك وأمر بأن يكتب فلا يكتب شيئا لا يعلمه - جل عن ذلك وتقدس.\rوقال الله عز وجلّ: {وَما تَسْقُطُ‍ مِنْ وَرَقَةٍ إِلاّ يَعْلَمُها وَلا حَبَّةٍ فِي ظُلُماتِ الْأَرْضِ وَلا رَطْبٍ وَلا يابِسٍ إِلاّ فِي كِتابٍ مُبِينٍ} (2)، وقال {وَما مِنْ دَابَّةٍ فِي الْأَرْضِ إِلاّ عَلَى اللهِ رِزْقُها وَيَعْلَمُ مُسْتَقَرَّها وَمُسْتَوْدَعَها} (3)، وقال: {أَحْصاهُ اللهُ وَنَسُوهُ} (4)، وقال: {لَقَدْ أَحْصاهُمْ وَعَدَّهُمْ عَدًّا} (5)، وقال: {أَحاطَ‍ بِكُلِّ شَيْءٍ عِلْمًا} (6)، {وَأَحْصى كُلَّ شَيْءٍ عَدَدًا} (7)، وقال: {بِكُلِّ شَيْءٍ عَلِيمٌ} (8).\rفذلك يبين أنه يعلم الأشياء كلها، وقد أخبر الله عز وجلّ أن الخلق يبعثون ويحشرون، وأن الكافرين في النار يخلدون، وأن الأنبياء والمؤمنين في الجنان يدخلون، وأن القيامة تقوم، ولم تقم القيامة بعد؛ فذلك يدل على أن الله تعالى يعلم ما يكون قبل أن يكون، وقد قال الله في أهل النار: وَلَوْ رُدُّوا لَعادُوا لِما نُهُوا عَنْهُ (9)، فأخبر عما لا يكون أن لو كان كيف يكون، وقال: {فَما بالُ الْقُرُونِ\r__________\r(1) أخرجه البخاري ح (6614) من طريق سفيان بن عيينة، ومسلم ح (14/ 2652) من طريق مالك، كلاهما عن أبي الزناد به.\r(2) الأنعام: 59.\r(3) هود: 6.\r(4) المجادلة: 6.\r(5) مريم: 94.\r(6) الطلاق: 12.\r(7) الجن: 28.\r(8) البقرة: 29.\r(9) الأنعام: 28."], [236, "اَلْأُولى (51) قالَ عِلْمُها عِنْدَ رَبِّي فِي كِتابٍ لا يَضِلُّ رَبِّي وَلا يَنْسى} (1)، ومن لا يعلم الشيء قبل كونه لا يعلمه بعد تقضيه - تعالى عن قول الظالمين علوّا كبيرا.\rوروى معاوية بن عمرو قال: ثنا زائدة عن سليمان الأعمش عن عمرو بن مرة عن عبد الرحمن بن أبي ليلى عن عبد الله بن ربيعة قال: كنا عند عبد الله قال: فذكروا رجلا فذكروا من خلقه، فقال القوم: أما له من يأخذ على يديه؟ قال عبد الله: أ رأيتم لو قطع رأسه أكنتم تستطيعون أن تجعلوا له يدا؟ قالوا: لا، قال عبد الله: إن النطفة إذا وقعت في المرأة مكثت أربعين يوما ثم انحدرت دما ثم تكون علقة مثل ذلك ثم تكون مضغة مثل ذلك ثم يبعث الله ملكا فيقول: اكتب أجله وعمله ورزقه وأثره وخلقه وشقي أو سعيد، وإنكم لن تستطيعوا أن تغيروا خلقه حتى تغيروا خلقه (2).\rوروى معاوية بن عمرو قال: "]], "pg": [234, 236]}, "إ.6.3": {"x": [[236, "ثنا زائدة عن منصور عن سعد بن عبيدة عن أبي عبد الرحمن عن علي رضي الله عنه قال: كنا في جنازة في بقيع الغرقد فأتى النبي صلّى الله عليه وسلّم فقعد ونحن حوله ومعه مخصرة له فنكت بها ورفع رأسه، فقال: «ما منكم من نفس منفوسة إلا قد كتب مكانها من الجنة أو النار، وإلا قد كتبت شقية أو سعيدة»، فقال رجل من القوم: يا رسول الله أفلا نمكث على كتابنا وندع العمل؛ فمن كان منا من أهل السعادة يصير إلى السعادة، ومن كان من أهل الشقاوة فيصير إلى الشقاوة؟ فقال: «اعملوا فكل ميسر أما أهل الشقاوة فميسرون لعمل الشقاوة وأما أهل السعادة فميسرون لعمل السعادة»، ثم قال: {فَأَمّا مَنْ أَعْطى وَاتَّقى (5) وَصَدَّقَ بِالْحُسْنى (6) فَسَنُيَسِّرُهُ لِلْيُسْرى (7) وَأَمّا مَنْ بَخِلَ وَاسْتَغْنى (8) وَكَذَّبَ\r__________\r(1) 51 - 52.\r(2) أخرجه الطبراني في الكبير (178/ 9) من طريق معاوية بن عمرو به، وقال الهيثمي في المجمع (402/ 7): «رواه الطبراني ورجاله ثقات». اه‍."], [237, "بِالْحُسْنى (9) فَسَنُيَسِّرُهُ لِلْعُسْرى} (1).\rوروى موسى بن إسماعيل قال: "]], "pg": [236, 237]}, "إ.6.4": {"x": [[237, "ثنا حماد قال: أنا هشام بن عروة عن عروة عن عائشة أن رسول الله صلّى الله عليه وسلّم قال: «إنّ الرجل ليعمل بعمل أهل الجنة وإنه مكتوب في الكتاب من أهل النّار؛ فإذا كان قبل موته تحوّل فعمل بعمل أهل النّار فمات فدخل النّار، وإن الرجل ليعمل بعمل أهل النّار وإنه لمكتوب في الكتاب أنه من أهل الجنة، فإذا كان قبل موته تحوّل فعمل بعمل أهل الجنة فمات فدخل الجنة» (2).\rوهذه الأحاديث تدل على أن الله عز وجلّ علم ما يكون أنه يكون وكتبه، وأنه قد كتب أهل الجنة وأهل النار وخلقهم فريقين: فريقا في الجنة وفريقا في السعير، وبذلك نطق كتابه إذ يقول: {فَرِيقًا هَدى وَفَرِيقًا حَقَّ عَلَيْهِمُ الضَّلالَةُ} (3)، وقال: {فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ} (4)؛ وقال: {فَمِنْهُمْ شَقِيٌّ وَسَعِيدٌ} (5)، فخلق الله الأشقياء للشقاوة والسعداء للسعادة، وقال عز وجلّ: {وَلَقَدْ ذَرَأْنا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالْإِنْسِ} (6)، وروي عن النبي صلّى الله عليه وسلّم أن الله عز وجلّ جعل للجنة أهلا وللنار أهلا (7).\r__________\r(1) الليل: 5 - 10. والحديث أخرجه الترمذي ح (3344) من طريق زائدة به، وأخرجه البخاري ح (1362)، ومسلم ح (2647) من طريق جرير عن منصور به.\r(2) أخرجه أحمد في مسنده (107/ 6)، وإسحاق بن راهويه في مسنده ح (837)، وأبو يعلى في مسنده ح (4668) من طرق عن حماد بن سلمة به. وقال الهيثمي في المجمع (429/ 7): «رواه أحمد وأبو يعلى بأسانيد، وبعض أسانيدهما رجاله رجال الصحيح». اه‍.\r(3) الأعراف: 30.\r(4) الشورى: 7.\r(5) هود: 105.\r(6) الأعراف: 179.\r(7) أخرجه مسلم ح (31/ 2662) من حديث عائشة بلفظ‍: «إن الله خلق للجنة أهلا ... وخلق للنار أهلا»."], [238, "دليل في القدر: ومما يدل على بطلان قول القدرية قول الله عز وجلّ: {وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ} (1) الآية! وجاءت الرواية عن رسول الله صلّى الله عليه وسلّم:\rأن الله عز وجلّ مسح ظهر آدم فأخرج ذريته من ظهره كأمثال الذر ثم قررهم بوحدانيته وأقام الحجة عليهم (2)؛ لأنه قال: {وَأَشْهَدَهُمْ عَلى أَنْفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قالُوا بَلى شَهِدْنا} قال الله عز وجلّ: {أَنْ تَقُولُوا يَوْمَ الْقِيامَةِ إِنّا كُنّا عَنْ هذا غافِلِينَ} (3)، فجعل تقريرهم بوحدانيته لما أخرجهم من ظهر آدم حجة عليهم إذا أنكروا في الدنيا ما كانوا عرفوه في الذر الأول ثم من بعد الإقرار جحدوه، وروي عن النبي صلّى الله عليه وسلّم أنه قبض قبضة للجنة وقبض قبضة للنار، ميز بعضا من بعض فغلبت الشقوة على أهل الشقوة، والسعادة على أهل السعادة، قال الله عز وجلّ مخبرا عن أهل النار أنهم قالوا: {رَبَّنا غَلَبَتْ عَلَيْنا شِقْوَتُنا وَكُنّا قَوْمًا ضالِّينَ} (4).\rوكل ذلك بأمر قد سبق في علم الله عز وجلّ ونفذت فيه إرادته وتقدمت فيه مشيئته، و"]], "pg": [237, 238]}, "إ.6.5": {"x": [[238, "روى معاوية بن عمرو قال زائدة قال طلحة بن يحيى القرشي قال: حدثتني عائشة بنت طلحة عن عائشة أم المؤمنين أن النبي صلّى الله عليه وسلّم دعي إلى جنازة غلام من الأنصار ليصلي عليه، فقالت عائشة: طوبى لهذا يا رسول الله عصفور\r__________\r(1) الأعراف: 172.\r(2) أخرجه أحمد في مسنده (272/ 1)، والنسائي في الكبرى ح (11191) من حديث ابن عباس به، وصححه الحاكم في المستدرك ح (4000، 75) فقال: «حديث صحيح الإسناد ولم يخرجاه، وقد احتج مسلم بكلثوم بن جبر»، وأعله النسائي فقال: «كلثوم هذا ليس بقوي، وحديثه ليس بالمحفوظ‍». اه‍. وقد اختلف في رفعه ووقفه، ورجح ابن كثير في التفسير (501/ 3 - 502) الوقف.\r(3) الأعراف: 172.\r(4) المؤمنون: 106."], [239, "من عصافير الجنة لم يعمل سوءا ولم يدركه، قال: «أو غير ذلك يا عائشة إنّ الله عز وجلّ قد جعل للجنة أهلا وهم في أصلاب آبائهم، وللنار أهلا جعلهم لها وهم في أصلاب آبائهم» (1)، وهذا يبين أن السعادة قد سبقت لأهلها والشقاء قد سبق لأهله، وقال النبي صلّى الله عليه وسلّم: «اعملوا فكلّ ميسر لما خلق له» (2).\rدليل آخر: وقد قال الله عز وجلّ: {مَنْ يَهْدِ اللهُ فَهُوَ الْمُهْتَدِ وَمَنْ يُضْلِلْ فَلَنْ تَجِدَ لَهُ وَلِيًّا مُرْشِدًا} (3)، وقال: {يُضِلُّ بِهِ كَثِيرًا وَيَهْدِي بِهِ كَثِيرًا} (4)؛ فأخبر أنه يضل ويهدي، وقال: {وَيُضِلُّ اللهُ الظّالِمِينَ وَيَفْعَلُ اللهُ ما يَشاءُ} (5)؛ ف"]], "pg": [238, 239]}, "إ.6.6": {"x": [[239, "أخبرنا أنه فعال لما يريد، وإذا كان الكفر مما أراده فقد فعله وقدره وأحدثه وأنشأه واخترعه، وقد بيّن ذلك بقوله: {أَتَعْبُدُونَ ما تَنْحِتُونَ (95) وَاللهُ خَلَقَكُمْ وَما تَعْمَلُونَ} (6)، فلو كانت عبادتهم للأصنام من أعمالهم كان ذلك مخلوقا لله، وقد قال الله تعالى: {جَزاءً بِما كانُوا يَعْمَلُونَ} (7) يريد أنه يجازيهم على أعمالهم، فكذلك إذا ذكر عبادتهم للأصنام وكفرهم بالرحمن، ولو كان مما قدروه وفعلوه لأنفسهم لكانوا قد فعلوا وقدروا ما خرج عن تقدير ربهم وفعله، وكيف يجوز أن يكون لهم من التقدير والفعل والقدرة ما ليس لربهم؟ من زعم ذلك فقد عجّز الله عز وجلّ - تعالى عن قول المعجّزين له علوّا كبيرا.\rألا ترى أن من زعم أن العباد يعلمون ما لا يعلمه الله عز وجلّ لكان قد أعطاهم\r__________\r(1) أخرجه مسلم ح (31/ 2662) من طرق عن طلحة بن يحيى به.\r(2) أخرجه البخاري ح (4949)، ومسلم ح (7/ 2647) من حديث علي.\r(3) الكهف: 17.\r(4) البقرة: 26.\r(5) إبراهيم: 27.\r(6) الصافات: 95 - 96.\r(7) الأحقاف: 14."], [240, "من العلم ما لم يدخل في علم الله وجعلهم لله نظراء، فكذلك من زعم أن العباد يفعلون ويقدرون ما لم يقدره الله ويقدرون على ما لم يقدر عليه؛ فقد جعل لهم من السلطان والقدرة والتمكن ما لم يجعله للرحمن - تعالى الله عن قول أهل الزور والبهتان والإفك والطغيان علوّا كبيرا.\rجواب: ويقال لهم: هل فعل الكافر الكفر فاسدا باطلا متناقضا؟ فإن قالوا: نعم، قيل لهم: وكيف يفعله فاسدا متناقضا قبيحا وهو يعتقده حسنا صحيحا أفضل الأديان، وإذا لم يجز ذلك لأن الفعل لا يكون فعلا على حقيقته إلا ممن علمه على ما هو عليه من حقيقته كما لا يجوز أن يكون فعلا ممن لم يعلمه فعلا فقد وجب أن الله عز وجلّ هو الذي قدر الكفر وخلقه كفرا فاسدا باطلا متناقضا خلافا للحق والسداد.\r***"], [241, "باب الكلام في الشفاعة والخروج من النار\r"]], "pg": [239, 241]}, "إ.7.1": {"x": [[241, "ويقال لهم: قد أجمع المسلمون أن لرسول الله صلّى الله عليه وسلّم شفاعة، فلمن الشفاعة؟ أهي للمذنبين المرتكبين الكبائر أو للمؤمنين المخلصين؟ فإن قالوا: للمذنبين المرتكبين الكبائر وافقوا، وإن قالوا: للمؤمنين المبشرين بالجنة الموعودين بها، قيل لهم: فإذا كانوا بالجنة موعودين وبها مبشرين والله عز وجلّ لا يخلف وعده فما معنى الشفاعة لقوم لا يجوز عندكم أن لا يدخلهم الله جناته؟ وما معنى قولكم قد استحقوها على الله واستوجبوها عليه، وإذا كان الله عز وجلّ لا يظلم مثقال ذرة كان تأخيرهم عن الجنة ظلما، وإنما يشفع الشفعاء إلى الله عز وجلّ في أن لا يظلم على مذهبكم - تعالى الله عن افترائكم عليه علوّا كبيرا - فإن قالوا: يشفع النبي صلّى الله عليه وسلّم إلى الله عز وجلّ في أن يزيدهم من فضله لا في أن يدخلهم جناته، قيل لهم: أ وليس قد وعدهم الله ذلك فقال: {فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُمْ مِنْ فَضْلِهِ} (1)، والله عز وجلّ لا يخلف وعده، فإنما يشفع إلى الله عز وجلّ عندكم في أن لا يخلف وعده وهذا جهل من قولكم، وإنما الشفاعة المعقولة فيمن استحق عقابا أن يوضع عنه عقابه أو فيمن لم يعده شيئا أن يتفضل به عليه، فأما إذا كان الوعد بالتفضل سابقا فلا وجه لهذا.\rسؤال: فإن سألوا عن قول الله عز وجلّ {وَلا يَشْفَعُونَ إِلاّ لِمَنِ ارْتَضى} (2).\rفالجواب عن ذلك: إلا لمن ارتضى فهم يشفعون له، وقد روي أن شفاعة النبيّ لأهل الكبائر (3)، وروي عن النبيّ أن المذنبين يخرجون من النار (1).\r__________\r(1) النساء: 173.\r(2) الأنبياء: 28.\r(3) أخرجه أبو داود ح (4739)، والترمذي ح (2435)، وقال: «حديث حسن صحيح غريب من هذا الوجه». اه‍. وصححه ابن حبان ح (6468)، والحاكم في المستدرك ح (229، 228، 230) من حديث أنس به، وأخرجه الترمذي ح (2436)، وقال: «حديث حسن غريب من هذا الوجه». اه‍. وصححه ابن حبان ح (6467)، والحاكم في المستدرك ح (231) من حديث ="], [242, "باب الكلام في الحوض\r"]], "pg": [241, 242]}, "إ.7.2": {"x": [[242, "وأنكرت المعتزلة الحوض وقد روي عن النبي صلّى الله عليه وسلّم من وجوه كثيرة، وروي عن أصحابه بلا خلاف، و"]], "pg": [242, 242]}, "إ.7.3": {"x": [[242, "روى عفان قال: حدثنا حماد بن سلمة عن علي بن زيد عن الحسن عن أنس بن مالك أنه ذكر الحوض عند عبيد الله بن زياد فأنكره، فبلغ أنسا فقال: لا جرم والله لأفعلن به، قال: فأتاه فقال: ما ذكرتم من الحوض؟ قال عبيد الله: هل سمعت النبي صلّى الله عليه وسلّم يذكره؟ قال: سمعت النبي صلّى الله عليه وسلّم أكثر من كذا وكذا مرة يقول: «ما بين طرفيه - يعني الحوض - ما بين أيلة ومكة أو ما بين صنعاء ومكة، وإن آنيته أكثر من نجوم السّماء» (2)، وروى أحمد بن عبد الله بن يونس قال: حدثنا (ابن أبي زائدة) (3) عن عبد الملك بن عمير عن جندب بن سفيان قال: سمعت رسول الله صلّى الله عليه وسلّم يقول: «أنا فرطكم على الحوض» (4) - في أخبار كثيرة.\r***\r__________\r=\rجابر به. ويشهد لهما ما أخرجه البخاري ح (7474، 6304)، ومسلم ح (199) من حديث أبي هريرة: «أختبئ دعوتي شفاعة لأمتي يوم القيامة». (4) (1) أخرجه البخاري ح (22)، ومسلم ح (185) من حديث أبي سعيد الخدري به.\r(2) أخرجه أحمد في مسنده (230/ 3) من طريق عفان به.\r(3) صوابه كما في صحيح مسلم، وتحفة الأشراف (181/ 4): «زائدة».\r(4) أخرجه مسلم ح (2289) من طريق أحمد بن عبد الله بن يونس به، وأخرجه البخاري ح (6589) من طريق شعبة عن عبد الملك بن عمير به."], [243, "باب الكلام في عذاب القبر\r"]], "pg": [242, 243]}, "إ.7.4": {"x": [[243, "وأنكرت المعتزلة عذاب القبر، وقد روي عن النبي صلّى الله عليه وسلّم من وجوه كثيرة، وروي عن أصحابه رضي الله عنهم، وما روي عن أحد منهم أنه أنكره ونفاه وجحده، فوجب أن يكون إجماعا من أصحاب النبي صلّى الله عليه وسلّم، وروى أبو بكر بن أبي شيبة قال: ثنا أبو معاوية عن الأعمش عن أبي صالح عن أبي هريرة قال: قال رسول الله صلّى الله عليه وسلّم: «تعوّذ (1) بالله من عذاب القبر» (2)، وروى أحمد بن إسحاق الحضرمي قال: ثنا وهيب قال: ثنا موسى بن عقبة قال: حدثتني أم خالد بنت خالد بن سعيد بن العاص أنها سمعت رسول الله صلّى الله عليه وسلّم يتعوذ من عذاب القبر (3)، وروى أنس بن مالك عن النبي صلّى الله عليه وسلّم أنه قال: «لو لا أن لا تدافنوا لسألت الله عز وجلّ أن يسمعكم من عذاب القبر ما أسمعني» (4).\rدليل آخر: ومما يبين عذاب الكافرين في القبور قول الله عز وجل: {اَلنّارُ يُعْرَضُونَ عَلَيْها غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ السّاعَةُ أَدْخِلُوا آلَ فِرْعَوْنَ أَشَدَّ الْعَذابِ} (5)؛ فجعل عذابهم يوم تقوم الساعة بعد عرضهم على النار في الدنيا غدوّا وعشيّا، وقال: {سَنُعَذِّبُهُمْ مَرَّتَيْنِ} (6) مرة بالسيف ومرة في قبورهم: {ثُمَّ يُرَدُّونَ إِلى عَذابٍ عَظِيمٍ} في الآخرة، وأخبر الله عز وجلّ أن الشهداء في الدنيا يرزقون\r__________\r(1) في مصنف ابن أبي شيبة: «تعوذوا».\r(2) أخرجه ابن أبي شيبة في مصنفه ح (29136)، وأخرجه الترمذي ح (3604) من طريق أبي كريب عن أبي معاوية به، وقال: «حديث حسن صحيح». اه‍.\r(3) أخرجه البخاري ح (1376) من طريق وهيب به.\r(4) أخرجه مسلم ح (2868).\r(5) غافر: 46.\r(6) التوبة: 101."], [244, "ويفرحون بفضل الله، قال عز وجلّ: {وَلا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْواتًا بَلْ أَحْياءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ (169) فَرِحِينَ بِما آتاهُمُ اللهُ مِنْ فَضْلِهِ وَيَسْتَبْشِرُونَ بِالَّذِينَ لَمْ يَلْحَقُوا بِهِمْ مِنْ خَلْفِهِمْ أَلاّ خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ} (1)، وهذا لا يكون إلا في الدنيا لأن الذين لم يلحقوا بهم أحياء لم يموتوا ولا قتلوا.\r***\r__________\r(1) آل عمران: 169 - 170."]], "pg": [243, 244]}, "إ.7.5": {"x": [], "pg": [null, null]}, "إ.7.6": {"x": [], "pg": [null, null]}, "إ.8.1": {"x": [[245, "باب الكلام في إمامة أبي بكر الصديق رضي الله عنه\rقال الله تبارك وتعالى: {وَعَدَ اللهُ الَّذِينَ آمَنُوا مِنْكُمْ وَعَمِلُوا الصّالِحاتِ لَيَسْتَخْلِفَنَّهُمْ فِي الْأَرْضِ كَمَا اسْتَخْلَفَ الَّذِينَ مِنْ قَبْلِهِمْ وَلَيُمَكِّنَنَّ لَهُمْ دِينَهُمُ الَّذِي ارْتَضى لَهُمْ وَلَيُبَدِّلَنَّهُمْ مِنْ بَعْدِ خَوْفِهِمْ أَمْنًا يَعْبُدُونَنِي لا يُشْرِكُونَ بِي شَيْئًا} (1)، وقال عز وجلّ: {اَلَّذِينَ إِنْ مَكَّنّاهُمْ فِي الْأَرْضِ أَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ وَأَمَرُوا بِالْمَعْرُوفِ وَنَهَوْا عَنِ الْمُنْكَرِ} (2)، وأنثى الله عز وجلّ على المهاجرين والأنصار والسابقين إلى الإسلام وعلى أهل بيعة الرضوان، ونطق القرآن بمدح المهاجرين والأنصار في مواضع كثيرة، وأثنى على أهل بيعة الرضوان فقال عز وجلّ: {لَقَدْ رَضِيَ اللهُ عَنِ الْمُؤْمِنِينَ إِذْ يُبايِعُونَكَ تَحْتَ الشَّجَرَةِ} (3) الآية، قد أجمع هؤلاء الذين أثنى الله عليهم ومدحهم على إمامة أبي بكر الصديق رضي الله عنه وسموه خليفة رسول الله صلّى الله عليه وسلّم وبايعوه وانقادوا له وأقروا له بالفضل، وكان أفضل الجماعة في جميع الخصال التي يستحق بها الإمامة من العلم والزهد وقوة الرأي وسياسة الأمة وغير ذلك.\rدليل آخر من القرآن على إمامة الصديق رضي الله عنه: وقد دل الله على إمامة أبي بكر في سورة براءة، فقال للقاعدين عن نصرة نبيه عليه السّلام والمتخلفين عن الخروج معه: {فَقُلْ لَنْ تَخْرُجُوا مَعِيَ أَبَدًا وَلَنْ تُقاتِلُوا مَعِيَ عَدُوًّا} (4)، وقال في سورة أخرى: {سَيَقُولُ الْمُخَلَّفُونَ إِذَا انْطَلَقْتُمْ إِلى مَغانِمَ لِتَأْخُذُوها ذَرُونا\r__________\r(1) النور: 55.\r(2) الحج: 41.\r(3) الفتح: 18.\r(4) التوبة: 83."], [246, "يُرِيدُونَ أَنْ يُبَدِّلُوا كَلامَ اللهِ} (1) يعني قوله: {لَنْ تَخْرُجُوا مَعِيَ أَبَدًا ثم قال:\rكَذلِكُمْ قالَ اللهُ مِنْ قَبْلُ فَسَيَقُولُونَ بَلْ تَحْسُدُونَنا بَلْ كانُوا لا يَفْقَهُونَ إِلاّ قَلِيلًا} (2)، وقال: {قُلْ لِلْمُخَلَّفِينَ مِنَ الْأَعْرابِ سَتُدْعَوْنَ إِلى قَوْمٍ أُولِي بَأْسٍ شَدِيدٍ تُقاتِلُونَهُمْ أَوْ يُسْلِمُونَ فَإِنْ تُطِيعُوا يُؤْتِكُمُ اللهُ أَجْرًا حَسَنًا وَإِنْ تَتَوَلَّوْا} - يعني: تعرضوا عن إجابة الداعي لكم إلى قتالهم - {كَما تَوَلَّيْتُمْ مِنْ قَبْلُ يُعَذِّبْكُمْ عَذابًا أَلِيمًا} (3).\rوالداعي لهم إلى ذلك غير النبي صلّى الله عليه وسلّم الذي قال الله عز وجلّ له: {فَقُلْ لَنْ تَخْرُجُوا مَعِيَ أَبَدًا وَلَنْ تُقاتِلُوا مَعِيَ عَدُوًّا} (4)، وقال في سورة الفتح: {يُرِيدُونَ أَنْ يُبَدِّلُوا كَلامَ اللهِ} فمنعهم عن الخروج مع نبيه عليه السّلام وجعل خروجهم معه تبديلا لكلامه؛ فوجب بذلك أن الداعي الذي يدعوهم إلى القتال داع يدعوهم بعد نبيه صلّى الله عليه وسلّم، وقد قال الناس: هم أهل فارس، وقالوا: أهل اليمامة، وقالوا: الروم: فإن كانوا أهل اليمامة فقد قاتلهم أبو بكر الصديق رضي الله عنه ودعا إلى قتالهم، وإن كانوا الروم فقد قاتلهم الصديق أيضا، وإن كانوا أهل فارس فقد قوتلوا في أيام أبي بكر وقاتلهم عمر من بعده وفرغ منهم، وإذا وجبت إمامة عمر وجبت إمامة أبي بكر كما وجبت إمامة عمر؛ لأنه العاقد له الإمامة؛ فقد دل القرآن على إمامة الصديق والفاروق رضوان الله عليهما، وإذا وجبت إمامة أبي بكر بعد رسول الله صلّى الله عليه وسلّم وجب أنه أفضل المسلمين رضي الله عنه.\rدليل آخر: الإجماع على إمامة أبي بكر الصديق رضي الله عنه: ومما يدل على إمامة\r__________\r(1) الفتح: 15.\r(2) الفتح: 15.\r(3) الفتح: 16.\r(4) التوبة: 83."], [247, "الصديق رضي الله عنه أن المسلمين جميعا بايعوه وانقادوا لإمامته وقالوا له: يا خليفة رسول الله! ورأينا عليّا والعباس رضي الله عنها بايعاه رضي الله عنه وأقرّا له بالإمامة، وإذا كانت الرافضة يقولون: إن عليّا هو المنصوص على إمامته، والراوندية تقول: العباس هو المنصوص على إمامته.\rولم يكن في الناس في الإمامة إلا ثلاثة أقوال:\rمن قال منهم: إن النبي صلّى الله عليه وسلّم نص على إمامة الصديق وهو الإمام بعد الرسول، وقول من قال: نص على إمامة علي، وقول من قال: الإمام بعده العباس، وقول من قال: هو أبو بكر الصديق، هو بإجماع المسلمين والشهادة له بذلك، ثم رأينا عليّا والعباس قد بايعاه وأجمعا على إمامته فوجب أن يكون إماما بعد النبي صلّى الله عليه وسلّم بإجماع المسلمين.\rولا يجوز لقائل أن يقول: كان باطن علي والعباس خلاف ظاهرهما، ولو جاز هذا لمدعيه لم يصح إجماع، وجاز لقائل أن يقول ذلك في كل إجماع للمسلمين، وهذا يسقط‍ حجية الإجماع لأن الله عز وجلّ لم يتعبدنا في الإجماع بباطن الناس وإنما تعبدنا بظاهرهم، وإذا كان ذلك كذلك فقد حصل الإجماع والاتفاق على إمامة أبي بكر الصديق، وإذا ثبتت إمامة الصديق ثبتت إمامة الفاروق؛ لأن الصديق نص عليه وعقد له الإمامة واختاره لها وكان أفضلهم بعد أبي بكر رضي الله عنه، وثبتت إمامة عثمان رضي الله عنه بعد عمر بعقد من عقد له الإمامة من أصحاب الشورى الذين نص عليهم عمر فاختاروه ورضوا بإمامته وأجمعوا على فضله وعدله.\rوثبتت إمامة علي بعد عثمان رضي الله عنها بعقد من عقد له من الصحابة من أهل الحل والعقد، ولأنه لم يدع أحد من أهل الشورى غيره في وقته وقد أجمع على فضله وعدله، وإن امتناعه عن دعوى الأمر لنفسه في وقت الخلفاء قبله كان حقّا لعلمه أن ذلك ليس بوقت قيامه، فلما كان لنفسه في غير وقت الخلفاء قبله كان"], [248, "حقّا لعلمه أن ذلك وقت قيامه، ثم لما صار الأمر إليه أظهر وأعلن ولم يقصر حتى مضى على السداد والرشاد كما مضى من قبله من الخلفاء وأئمة العدل على السداد والرشاد متبعين لكتاب ربهم وسنة نبيهم.\rهؤلاء الأئمة الأربعة المجمع على عدلهم وفضلهم رضي الله عنهم.\rوقد "]], "pg": [245, 248]}, "إ.8.2": {"x": [[248, "روى سريج بن النعمان قال: ثنا حشرج بن نباتة عن سعيد بن جمهان قال: حدثني سفينة قال: قال رسول الله صلّى الله عليه وسلّم: «الخلافة في أمّتي ثلاثون سنة ثم ملك بعد ذلك»، ثم قال لي سفينة: أمسك خلافة أبي بكر وخلافة عمر وخلافة عثمان! ثم قال: أمسك خلافة علي بن أبي طالب! قال: فوجدتها ثلاثين سنة (1)؛ فدل ذلك على إمامة الأئمة الأربعة رضي الله عنهم، فأما ما جرى بين علي والزبير وعائشة رضي الله عنهم فإنما كان على تأويل واجتهاد، وعلي الإمام وكلهم من أهل الاجتهاد، وقد شهد لهم النبي صلّى الله عليه وسلّم بالجنة والشهادة فدل على أنهم كلهم كانوا على حق في اجتهادهم، وكذلك ما جرى بين علي ومعاوية رضي الله عنها كان على تأويل واجتهاد، وكل الصحابة أئمة مأمونون غير متهمين في الدين، وقد أثنى الله ورسوله على جميعهم وتعبدنا بتوقيرهم وتعظيمهم وموالاتهم والتبري من كل من ينقص أحدا منهم رضي الله عن جميعهم، قد قلنا في الإقرار قولا وخبرا، والحمد لله أولا وآخرا.\rتم الكتاب بعون الله الملك الوهاب وحسن توفيقه، والصلاة والسلام على رسوله محمد وآله وأصحابه أجمعين.\r__________\r(1) أخرجه الترمذي ح (2226) من طريق سريج بن النعمان به، وقال: «حديث حسن». اه‍."], [249, "الملحق الأول والثاني للإبانة\rلمحمد عنايت علي الحيدرآبادي"], [251, "الملحق الأول للإبانة\r"]], "pg": [248, 251]}, "إ.خ.1": {"x": [[251, "اعلم أن الإمام أبا الحسن الأشعري ساق الكلام في كتابه (الإبانة في أصول الديانة) في مجموع العقائد الحقة لأهل السنة ومجموع العقائد الباطلة لأهل البدعة أولا، ثم أتى على إثبات عقيدة عقيدة من عقائد أهل السنة، وإبطال عقيدة عقيدة من عقائد أهل البدع ثانيا، كل ذلك بحجج بلج ودلائل جلائل، كما هو ظاهر من مطالعة كتابه المذكور.\rوإذا علمت هذا فانظر أن الأشعري قال في صدر كتابه في باب إبانة قول أهل الزيغ والبدعة: «وتكلموا بخلق القرآن نظيرا لقول إخوانهم من المشركين الذين قالوا: {إِنْ هذا إِلاّ قَوْلُ الْبَشَرِ} (1)»، ولا يخفى أن هذا القول منه غاية في تشنيع القائلين بخلق القرآن وذمهم، ثم قال في باب إبانة قول أهل الحق والسنة: «ونقول إن كلام الله غير مخلوق»؛ فثبت من هذين القولين للأشعري أن عقيدة خلق القرآن ضلالة وغواية عنده وخروج عن منهج السنة والجماعة ومعتقدها من أهل الشقاوة والغواية، وليس في هذين البابين ما ينسب إلى غيره من نقل عنه أو تحويل عليه بل جملة ما فيهما إنما هو من ترتيبه وترصيفه ووضعه وتركيبه؛ فتكون مقولته المرضية ومسلكه المختار، هذه مقدمة يجب عليك أن تقررها في ذهنك فإنها تنفعك إن شاء الله تعالى.\rاعلم أن الأشعري عقد بابا طويلا لعدم خلق القرآن فأثبته بأبلغ الوجوه من عنده بغير أن ينقل عن أحد، ثم ذيّل هذا الباب بباب ما ذكر الرواة في القرآن،\r__________\r(1) المدثر: 25."], [252, "وظاهر أن هذا الباب من المتممات للباب السابق ولواحقه، وصنيع الأشعري في هذا الباب إنما هو حوالة المنقول على ناقله ونسبة الرواية إلى راويه، وأما تنقيد الرواة والقدح في المرويات أو تصحيحها وإثبات المنقولات أو إنكارها فما تعرض له - كما يظهر من مطالعة هذا الباب - غير أنه ذكر المروي في بعض المواضع بلفظ‍ يعلم منه أنه صحيح عنده، مثل قوله: صحت الرواية، جاء بالروايات، يوردها بألفاظ‍ بعضها أقوى من بعض مثل: قال؛ فإنه أقوى من: روى، وروى فإنه أقوى من ذكر، والحاصل أن مقصود الأشعري في هذا الباب المذيل سرد روايات الباب تأييدا للباب السابق كما قال في آخر هذا الباب بأن فيما ذكرنا من ذلك مقنع، والحمد لله رب العالمين.\rوقد احتججنا لصحة قولنا: «إن القرآن غير مخلوق» من كتاب الله عز وجلّ وما تضمنه من البرهان وأوضحه من البيان انتهى.\rومن المعلوم المقرر أن مجموع الروايات يحصل القوة والاعتضاد وإن كان في بعضه ضعف ووهن؛ لأنه إذا كان المقصود إثبات المطلب من المجموع يكون النظر حينئذ على الحيثية المجموعية دون فرد فرد من المجموع، ففي مثل هذا المقام إذا أوردت الروايات الكثيرة لإثبات مقصد لا يلزم منه صحة كل واحدة من تلك الروايات، وعدم كونها مقدوحة مخدوشة لا سيما إذا لم يكن الكتاب كتاب رواية يبحث فيه عن نفس الروايات، فمن أين يثبت أن تكون رواية خلق القرآن المنسوبة إلى الإمام الهمام المصدرة بلفظ‍: ذكر صحيحه، وبعدم تسليمها يختل ما هو بصدد إثباته، وأيضا ليس هنا لفظ‍ يثبت منه أن هذه الرواية صحيحة عند الأشعري، ولا سياق يتحقق منه أنه ألزم نفسه أن يكون كل ما يورده من الروايات صحيحا لا مجال فيه للقدح، بل هو بصدد أن يثبت منه مقصده ويؤيد به نوع تأييد للباب السابق ويجعل هذا الباب متمما لذلك الباب ومكملا له."], [253, "فعلى هذا إن لم نعتبر تلك الروايات ونتصورها خارجا من الباب يتم مطلبه ويكمل مقصده أيضا، ويثبت ما هو في إثباته كما يتم في صورة اعتبارها وإعتدادها، ومع هذا كله سوق تلك الرواية وذكرها ليس لبيان مذهب الإمام الأعظم بل لإظهار إنكار وقع على مذهب الإمام من الأئمة المعاصرين له، ولتنبيه أن أولئك المنكرين كانوا من أشد الرادين على القائلين بهذا القول المنكر وإن كان بيان مذهب الإمام منطويا في الرواية منتهيا صورتها إليه، ولكنه قد يكون المقصود من الأمور المتعددة المتضمنة للرواية أمرا واحدا فقط‍ لما يقتضيه المقام ولما يقصر المورد على هذا الأمر الواحد فحسب.\rفظهر من هذا التقرير أن الأشعري ليس في إثبات نسبة هذه العقيدة إلى الإمام ولا أنه ثابت عنده بل يحتمل أن تكون نسبة هذا القول إلى الإمام غير ثابتة عنده من مقتضى تلك الروايات نفسها أو من أمور أخرى، ولكنه ذكرها مضمومة ملحوظة مع الروايات الأخرى لكونها مثبتة للمطلب بصورتها الإنكارية المقتضية لإثبات عدم خلق القرآن؛ فإدراجها في روايات أخرى إنما هو لكونها على تلك الصورة، وكل هذا أمور نفسية للروايات توهن الروايات وتجعلها ساقطة من الاعتبار لا يمكن أن تنسب معها هذه العقيدة إلى الإمام، أما الأمور التي هي خارجة من الرواية تقلع بنيانها فتجعلها خاوية على عروشها، فمن جملتها أن الأشعري ذكر الإمام أحمد والشافعي ومالكا وابن المبارك فيمن يقولون بعدم خلق القرآن، ويكفرون القائل بخلقه، وقال بعده: ولم نجد أحدا ممن تحمل عنه الآثار وتنقل عنه الأخبار ويأتم به المؤتمون من أهل العلم يقول بخلق القرآن، وإنما قال ذلك رعاع الناس وجهال من جهالهم لا موقع لهم - انتهى.\rوالأئمة المذكورون كلهم يبالغون في منقبة الإمام الدينية ومدحه وشدة ورعه وتقواه وكمال إيمانه وإيقانه، وهذا ينافي كفره الذي يلزمه من هذه العقيدة ويفضي"], [254, "إلى كفر الأئمة المذكورين، حيث بالغوا في مدح مثل هذا الرجل كأنهم رضوا بعقيدته - أعاذنا الله من هذا القول فيهم وسوء الظن في الأكابر.\rوإذا تأملنا وأعمقنا النظر فيما مدحوا به الإمام لم نجده إلا من باب قول الأشعري المذكور آنفا بأنه لم نجد أحدا ممن تحمل ... إلخ، أليس موجب تلك المدائح ومقتضاها أن يكون الإمام ممن تحمل عنهم الآثار وتنقل عنهم الأخبار ويستفاض ويستمد منهم ويقتدى بهم في الدين؟\rبلى هو منهم بل رأسهم ورئيسهم، أو لم يقف الأشعري على مدحهم للإمام أو وقف ولكنه لم يقدر على أن يفهم من ذلك المدح أنه ينفي نسبة أمثال هذه الأمور إلى الإمام ويوضح كون أمثال هذه الروايات كذبا مختلقا، وإن في نسبة هذا الأمر إلى الإمام يقع مادحوه في ورطة عظيمة لا ينجون منها ويردون موردا لا يتخلصون منه، حاشا الأشعري أن يظن أمثال هذه الظنون في حقه فإنه إمام الأئمة لأهل السنة ومقتدى هذه الأمة، وأيضا إيراد هذه الرواية التي أصل سياقها وصورتها إنما هو القصة المحكية والحكاية الواقعة، وإن كان قصة هذا المطلب في الباب الذي ذكرت فيه روايات تدل بأصلها ورأسها على عدم خلق القرآن بغير أن يحصل هذا المعنى في ضمن أمر آخر مخالف للباب غير مأنوس له، ولهذا لا يكون احتمال وضعها وإدخالها واقعا في غير موقعه لا سيما إذا كانت الأمور المذكورة معاضدة له فإنه حينئذ يتعين وضعها وإلحاقها.\rثم العلماء الحنفية متفقون على عدم خلق القرآن وعلى تكفير القائلين بخلقه وكتبهم مشحونة بذمهم ونقض دلائلهم، مملوءة بمثالبهم وتوهين حججهم، ومن أكابرهم من يذبون عن الإمام ويدفعون عنه كالعلامة القاري وغيره، ولم يذكروا شيئا من هذه الرواية، ودأبهم أنهم يذكرون الأمور المفتراة على الإمام ومطاعنه ثم يدفعونها دفعا بليغا ويوضحون تبرئته بحيث لا تبقى معه ريبة،"], [255, "فكيف يتصور أن يتركوا دفع هذه القبيحة عن الإمام وتبرئته عنها مع أنها من أعظم ما يهتم في دفعها، فهذا من أجل الأمارات على افتراء هذه الروايات واختلافها، والشافعية كلهم - خصوصا من ألف منهم في مناقب الإمام وأحواله - لم ينسبوا هذه العقيدة إلى الإمام قاطبة، وذكر المتكلمون من الحنفية أن هذه المسألة - أعني عدم خلق القرآن - وقعت بوضع يثبت منه أن هذه العقيدة كانت عرضا لازما لمنع مذهب حضرة الإمام أبي حنيفة رضي الله تعالى عنه، وأن مبدأ المذهب ومنتهاه ونشوءه ونماه ثم استمراره بغير الانفكاك في حين من الأحيان على هذه العقيدة؛ فرواية الاستتابة بغير الإنابة ثم رواية رجوعه عن عقيدة الخلق في أي حساب وأي عداد؟\rقال البيهقي في كتاب (الأسماء والصفات) (1) قال: سمعت سليمان يقول: سمعت الحارث بن إدريس يقول: سمعت محمد بن الحسن الفقيه يقول: من قال: القرآن مخلوق فلا تصلّ خلفه، وقرأت في كتاب أبي عبد الله محمد بن يوسف بن إبراهيم الدقاق رواية عن القاسم بن أبي صالح الهمداني عن محمد بن أيوب الرازي قال: سمعت محمد بن سابق يقول: سألت أبا يوسف فقلت: أكان أبو حنيفة يقول: القرآن مخلوق؟ فقال: معاذ الله! ولا أنا أقوله، فقلت: أكان يرى رأي جهم؟ فقال: معاذ الله، ولا أنا أقوله، رواته ثقات.\rوأنبأني أبو عبد الله الحافظ‍ إجازة قال: أنا أبو سعيد أحمد بن يعقوب الثقفي قال: ثنا عبد الله بن أحمد بن عبد الرحمن بن عبد الله الدشتكي قال: سمعت أبي يقول: سمعت أبا يوسف القاضي يقول: كلمت أبا حنيفة سنة جرداء في أن القرآن مخلوق أم لا، فاتفق رأيه ورأيي على أن من قال «القرآن مخلوق» فهو كافر.\r__________\r(1) الأسماء والصفات (610/ 1 - 611)."], [256, "قال أبو عبد الله: رواة هذا الكلام ثقات - انتهى.\rاعلم - أرشدك الله تعالى - أنه يثبت من هذه الروايات للبيهقي أمران: الأول: عدم قول الإمام بخلق القرآن، والثاني: كون روايات الإبانة واهية بل موضوعة مختلقة، أما الأول فبوجهين:\rأحدهما: أن تلك الروايات تدل بألفاظها وعباراتها على أن هذه العقيدة القبيحة ما خطرت في قلب الإمام وقلوب أصحابه قط‍. وثانيهما: أننا إذا أصرفنا النظر عن تلك الدلالة للروايات ورفعناها من البين فوقوعه في ذلك المقام يؤيد المقصد تأييدا بليغا، بيانه أن تلك الروايات في باب هو موضوع لسرد الروايات عن الصحابة والتابعين وأئمة المسلمين رضي الله تعالى عنهم في كون القرآن غير مخلوق كما عنونه البيهقي فقال: (باب ما روي عن الصحابة والتابعين وأئمة المسلمين رضي الله عنهم في أن القرآن كلام الله غير مخلوق) (1)، وغرض البيهقي من ذكر الروايات بجميعها في هذا الباب إنما هو إثبات المطلب والاحتجاج على المقصد الذي هو عدم كون القرآن مخلوقا، فيلزم أن من روى عنه البيهقي أو نقل قوله واعتقاده في هذا الباب أن يكون من أئمة المسلمين، ولما روى البيهقي في هذا الباب عن الإمام وأصحابه لزم أن يكون الإمام وأصحابه من أئمة المسلمين، ومن كان من أئمة المسلمين لا يكون قائلا بخلق القرآن قط‍؛ لأن القول بخلقه كفر وضلالة، ومحال أن يكون الكافر من أئمة المسلمين، والحاصل أن محض وقوع الروايات عن الإمام وأصحابه في هذا الباب بغير أن ينظر إلى أن تلك الروايات تنفي نسبة هذه العقيدة القبيحة إلى الإمام - يدل دلالة بليغة على أن الإمام لم يكن معتقدا بخلق القرآن قط‍، ومفاد المحضية أنه وإن لم تكن تلك الروايات في عدم خلق القرآن فمحض\r__________\r(1) الأسماء والصفات (585/ 1)."], [257, "وقوعه في مثل هذا المقام يكفي لإثبات المرام.\rوأما الثاني فبوجوه متعددة: الأول: أنه يتضح من رواية محمد بن سابق وضوحا تامّا أن الإمام لم يكن معتقدا بخلق القرآن في حين من الأحيان وما كان قائلا به في زمن من الأزمان؛ فإن محمد بن سابق سأل الإمام أبا يوسف بلفظ‍ (كان) وهو للاستمرار في الزمان الماضي، وأجاب أبو يوسف بنفيه فدل دلالة ظاهرة قوية على أن الإمام لم يكن قائلا بخلق القرآن في الأزمنة كلها، وأما الرواية الأخيرة لأبي يوسف حيث قال فيها: كلمت أبا حنيفة سنة جرداء ... إلخ، فليس فيها دلالة على أن الإمام كان قائلا بخلق القرآن قبل المباحثة كما يظهر من روايات الإبانة ثم رجع عنه، كما يعلم من الرواية الأخيرة المذكورة فيه أيضا، بل إنما يظهر من عبارة هذه الرواية أن الإمام باحث أبا يوسف - رحمهما الله تعالى - في هذه المسألة لكي يجعل عدم الخلق محققا مدللا؛ فإن بالبحث يصير الأمر محكما منقحا حتى عين الكفر للقائل بالخلق بعد ما بذل أقصى جهده في تحقيق المسألة.\rوالثاني: أن البيهقي هو إمام المحدثين، وكتابه (الأسماء والصفات) خزانة للروايات المسندة، والأشعري هو إمام أهل السنة في الكلام، وكتابه هذا مخزن للاستدلالات الكلامية، ومن المقررات المسلمات أن اتباع كل أحد والأخذ بقوله وترجيحه على الآخر في هذا الاتباع والأخذ إنما يكون في فن غلب عليه فهو غواص بحاره وسيار قفاره؛ فعلى هذا لا يكون ما رواه بسنده معادلا لما نقله البيهقي، فكيف يرجح ما نقله الأشعري من مرويات الناس بغير أن يوثق رواته وبدون أن يوجد من غيره توثيقهم كما في هذا المقام على ما رواه البيهقي بسنده أو نقله ووثق رواته وعدلهم، ومعناه يخالف معنى ما نقله الأشعري ويناقضه؟.\rوالثالث: أنه ليس في هذا الباب من كتاب البيهقي شمة من هذه الروايات ورائحة منها مع أنه يحسن إيرادها وإدراجها في أخواتها وأمثالها اللاتي ذكرت في"], [258, "كتاب البيهقي مسندا، فعدم ذكرها في موضعها من ذلك الكتاب أقوى ما يدل على كونها موضوعة مختلقة لا يلتفت إليها ولا يصغى إلى ما لديها، أما أخوات هذه الروايات وأمثالها من كتاب البيهقي فمنها ما قال: أخبرنا أبو عبد الله قال: أخبرني أبو أحمد بن أبي الحسن قال: أنا عبد الرحمن يعني محمد بن إدريس الرازي، قال: في كتابي عن الربيع بن سليمان، قال: حضرت الشافعي رضي الله عنه وحدثني أبو شعيب إلا أني أعلم أنه حضر عبد الله بن عبد الحكم ويوسف بن عمرو بن يزيد وحفص الفرد، وكان الشافعي رضي الله عنه يسميه المنفرد، فسأل حفص عبد الله بن عبد الحكم فقال: ما تقول في القرآن؟ فأبى أن يجيبه، فسأل يوسف بن عمرو فلم يجبه، وكلاهما أشارا إلى الشافعي رضي الله عنه؛ فسأل الشافعي فاحتج الشافعي وطالت المناظرة وغلب الشافعي بالحجة عليه بأن القرآن كلام الله غير مخلوق وكفّر حفص الفرد، قال الربيع: فلقيت حفص الفرد فقال: أراد الشافعي قتلي.\rأخبرنا أبو عبد الرحمن السلمي قال: سمعت عبد الله بن محمد بن علي بن زياد يقول: سمعت محمد بن إسحاق بن خزيمة يقول: سمعت الربيع يقول: لما كلم الشافعي حفص الفرد فقال حفص: القرآن مخلوق، فقال الشافعي: كفرت بالله العظيم (1). وقال عبد الرحمن بن عفان: سمعت سفيان بن عيينة في السنة التي ضرب فيها المريسي قال: ويحكم، القرآن كلام الله قد صحبت الناس وأدركتهم هذا عمرو بن دينار ... إلخ، قال ابن عيينة: فما نعرف القرآن إلا كلام الله عز وجلّ، ومن قال غير هذا فعليه لعنة الله، لا تجالسوهم ولا تسمعوا كلامهم (2) - انتهى.\rوالرابع: أن البيهقي كان متعصبا في مذهبه ومتصلبا في مسلكه تشهد عليه\r__________\r(1) الأسماء والصفات (612/ 1 - 613).\r(2) الأسماء والصفات (616/ 1)."], [259, "(سننه الكبرى) فإن فيه اعتراضات فقهية على الإمام ردها، وأجاب عنها العلامة المارديني في كتابه (الجوهر النقي في الرد على البيهقي)؛ فلو كان لهذه الروايات أصل لذكرها البيهقي في كتاب الأسماء والصفات وما تركها وغفل عنها ألبتة، ولما لم يذكرها في كتابه بل ذكر ما ينافيها ويناقضها دل على أنه لا أصل لهذه الروايات.\rوالخامس: أن البيهقي احتج عن الإمام وأصحابه في عدم خلق القرآن، واحتج الأشعري عمن أنكر على الإمام عقيدته الخلق؛ فالإمام ممدوح في كتاب البيهقي ومحتج به بخلاف هذا الكتاب، فإنه غير محتج به فيه، بل هو مذموم بمقتضى هذه الروايات ومنكر عليه؛ فهذان الصنيعان للبيهقي والأشعري متضادان متدافعان، فتكون روايات البيهقي دافعة لهذه الروايات للأشعري للقاعدة التي ذكرناها في الوجه الثاني.\rالوجه السادس: أنه قال البيهقي في آخر كتابه (1): وقد تركت من الأحاديث التي رويت في أمثال ما أوردته ما دخل معناه فيما نقلته أو وجدته بإسناد ضعيف لا يثبت مثله - انتهى؛ فثبت من قوله هذا أن ما ترك من الروايات لا يخلو تركه من أحد هذين الوجهين، ولما كانت هذه الروايات متروكا ذكرها في كتاب البيهقي ولا يمكن أن يكون تركها لدخول معناها في روايات البيهقي - وهذا ظاهر جدّا - تعين أن وجه تركها إنما هو شدة ضعف في إسنادها بحيث لا يثبت بمثل هذا الضعف شيء.\rوالسابع: أن رواية محمد بن الحسن توهن هذه الروايات وتجعلها مخدوشة وتقوي افتراءها وتجعلها مقدوحة، وذلك بوجهين:\rالأول: أنه ليست هذه الرواية في الإبانة مع أن من عادتهم أنهم يذكرون في\r__________\r(1) الأسماء والصفات (495/ 2)."], [260, "معرض الاحتجاج وموضع الاستدلال غالب أقوال العلماء الذين يتقاربون ويتماثلون في العلم، ونقل في هذا الباب ممن هو متقارب في الزمان ومماثل في العلم للإمام محمد محتجّا بهم ومستدلاّ عنهم، وما ذكر قوله هذا مع أنه أبلغ في تشنيع القائلين بخلق القرآن مبلغا عظيما، والمخالفة من القوم في عادتهم والأجنبية منهم في صنيعهم يخدش الأمر ويخل فيه؛ فاحتمل أنه كانت هذه الرواية في هذا الكتاب ولكنه أخرجت حين ألحقت هذه الروايات فيه لكونها قادحة فيها ناقضة لها كما يومئ إليه في الوجه الثاني وواقع في موقعه وحال في محله.\rوالثاني: أن مقتضى قول الإمام محمد هو أن تشنعوا وتفظعوا على قائل هذا القول غاية تشنيع وتفظيع، واجتنبوه وتحذروا منه نهاية تحذر وتجنب؛ فإن كان الإمام قائلا به كيف تلمذ محمد بن الحسن واقتدى به في الدين اقتداء كليّا وهما مما يوجب التكريم والاختلاط‍ الأتمين الأكملين لمن يتلمذ ويقتدى به وإن كان محمد بن الحسن كرم الإمام واختلط‍ به اختلاطا تامّا مع هذه العقيدة له صار قابلا للذم وسقط‍ الاحتجاج بأقواله، وحيث احتج به البيهقي يكون هو مطعونا ملاما حقيقا بأن يشنع في أنه كيف احتج بمثل هذا العالم الذي يعود عليه الذم شرعا ويدخل في وعيد قوله تعالى: {لِمَ تَقُولُونَ ما لا تَفْعَلُونَ (2) كَبُرَ مَقْتًا عِنْدَ اللهِ أَنْ تَقُولُوا ما لا تَفْعَلُونَ} (1)، فانظر إلى أنه أين صار الأمر وإلى أي قبيحة انتهى، والعياذ بالله وإليه المشتكى! ولما لم توجد هذه الأمور ومحال أن توجد؛ فمحال أن توجد هذه العقيدة في الإمام، ولله الحمد.\rواعلم أن مما يبطل معنى هذه الروايات ويثبت أنه ما قال الإمام هذا القول وما اعتقده قط‍ بل كان بريئا منه مدة عمره ما روى البيهقي عن محمد بن\r__________\r(1) الصف: 2 - 3."], [261, "إسماعيل البخاري أن القرآن كلام الله تعالى ليس بمخلوق عليه أدركنا علماء الحجاز أهل مكة والمدينة وأهل الكوفة والبصرة وأهل الشام ومصر وعلماء أهل خراسان (1) - انتهى.\rوهذا لأنه إذا أخبر أحد من إدراكه لشخص أو جماعة على حالة مخصوصة بدون أن يعين زمان إدراكه ويقيدها في زمان مخصوص وكان المدرك - بالكسر - متأخرا في الزمان عن المدرك - بالفتح - أو معاصرا له، ينبغي أن يعلم منه أن إدراكه عام وشامل للكل ولا يقيد بزمان دون زمان، وأن الحالة المذكورة حالة دائمة للمدرك غير منفكة عنه لا سيما إذا ذكر هذا الإدراك استشهادا على المقصد وتقوية للمطلب.\rإذا تقررت هذه المقدمة وارتسمت في الذهن فنرجع إلى المقصد ونقول: إن البخاري ذكر في هذه الرواية إدراكه مطلقا بغير أن يقيد أن جماعة معينة أو فردا معينا من تلك الجماعة كان يعتقد أولا خلق القرآن ثم رجع عنه؛ فيجب أن يكون الإمام الأعظم والمجتهد الأفخم أبو حنيفة الكوفي في مدركي أهل الكوفة دخولا أوليّا أولويّا، وأن يكون ابتداء وانتهاء على أن القرآن غير مخلوق.\rلا يخفى على النفوس الخبيرة أنه اتفق المحدثون وحفاظ‍ الشرع المنيف، وأجمعت الفقهاء وأئمة الدين الشريف أن الإمام الأعظم كان عالما زاهدا عاملا وإماما متورعا كاملا، وما تفوهت الشرذمة القليلة بطعنه وجرحه لا يمكن أن يكون ناقضا لذلك الإجماع خارقا له، بل يضرب بطعنهم في وجوههم فينقلبون خاسرين، لا سيما إذا كانت الأئمة الثلاثة الذين اتبعهم جمع كثير وجم غفير من أكابر العلماء في كل عصر، وما زال كل قطر من أقطار العالم يقلدهم يمدحون الإمام ويثنون عليه، فإنه لما كان الطاعنون أكثرهم من مقلدي هذه الأئمة\r__________\r(1) الأسماء والصفات (615/ 1 - 616)."], [262, "ومتبعيهم ينسبون إلى أحد منهم لا بد أن تكون هذه الأئمة فوق الطاعنين في العلم والفهم؛ فطعن تلك الطاعنين فيمن أثنى عليه أئمتهم ثناء كليّا ومدحوه مدحا دينيّا باطل ومن الحق عاطل، تضمحل مطاعنهم في مدائحهم وتتلاشى فتصير هباء منثورا ويعود كل منهم ملوما مدحورا.\rقال الإمام الشافعي أفقههم وأعلمهم: بأن الناس في الفقه عيال على أبي حنيفة (1)، وقال مالك عالم المدينة وإمام الأئمة فيما روى الخطيب (2) عن أحمد بن الصباغ قال: سمعت الشافعي محمد بن إدريس قال: قيل لمالك بن أنس: هل رأيت أبا حنيفة؟ قال: نعم رأيت رجلا لو كلمك في هذه السارية أن يجعلها ذهبا لقام بحجته - كذا في تبييض الصحيفة في مناقب الإمام أبي حنيفة للسيوطي، إلى غير ذلك مما يطول شرحه، وسيأتي منه نبذة هي كرشفة من اليم أو قطرة من البحر، وقد نطق الشرع بثنائه وأفصح عن بهائه يقف عنده من عنده الرشد والدهاء، ولا يتجاوز عنه إلا من اتبع الهوى وركب متن عشواء، وهو حديث الثريا، خرجه جهابذة المحدثين كالبخاري ومسلم وغيرهما بألفاظ‍ مختلفة متقاربة لا يختلف معها المعنى؛ فهو أصل في البشارة بالإمام بالغ المحل الأسنى.\rقال المحقق المحدث العلامة السيوطي في تبييض الصحيفة في مناقب الإمام أبي حنيفة: إن هذا أصل صحيح معتمد عليه في البشارة بأبي حنيفة، وخلاصة الكلام في هذا المقام أن الإمام أبا حنيفة ممدوح بلسان الشريعة ولسان الجماهير من علمائها، ومن كان ممدوحا بلسان الشرع ولسان علمائه ما يقول بخلق القرآن قط‍، فينتج من هاتين المقدمتين أن الإمام أبا حنيفة ما كان قائلا بخلق القرآن قط‍\r__________\r(1) رواه الخطيب في تاريخ بغداد (364/ 13).\r(2) في تاريخ بغداد (337/ 13 - 338)."], [263, "أما الصغرى فأثبتناها، وأما الكبرى فإثباتها أن القول بخلق القرآن كفر وشرك بالله تعالى، وهما مذمومان عند الشرع وعند كلّ من علمائه؛ فالإمام ممدوح من جهة الشرع، والكفر مذموم من تلك الجهة أيضا، فإذا اتحدت جهتهما فهما متناقضان فلا يجتمعان.\rواعلم أنه قد ألف العلماء من أهل المذاهب الأربعة كتبا ورسائل في مناقب الإمام وشهدوا بجلالة شأنه وعظم مكانه في الدين، ولما لم يكن مقصودنا جمع الروايات والإحاطة بها بل المطلوب إنما هو تقرير أمر من الأمور وإثبات مطلب من المطالب؛ فنورد من تلك الروايات ما يكفينا في إثبات مقصدنا وإقراره على مركزه، ومن أراد الإحاطة بها فعليه بتلك الكتب وهو روايتان:\rالأولى منهما: هي ما أورده الحافظ‍ السيوطي في تبييض الصحيفة فقال: وروي أيضا عن أبي بكر بن عياش قال: مات عمر بن سعيد أخو سفيان فأتيناه نعزيه فإذا المجلس غاصّ بأهله وفيهم عبد الله بن إدريس إذ أقبل أبو حنيفة في جماعة معه، فلما رآه سفيان تحول من مجلسه ثم قام فاعتنقه وأجلسه في موضعه وقعد بين يديه، فقلت له: يا أبا عبد الله رأيتك اليوم فعلت شيئا أنكرته وأنكر أصحابنا عليك، قال: وما هو؟ قلت: جاءك أبو حنيفة فقمت إليه وأجلسته في موضعك وصنعت به صنيعا بليغا، فقال: وما أنكرت من ذاك؟ هذا رجل من العلم بمكان فإن لم أقم لعلمه قمت لسنه، وإن لم أقم لسنه قمت لفقهه، وإن لم أقم لفقهه قمت لورعه، فأفحمني فلم يكن له عندي جواب (1) - انتهى.\rأقول: يظهر من هذه الرواية أن الرواية الأولى من روايات الإبانة مفتراة على سفيان الثوري لأنه لا تخلو واقعة هذه الرواية إما أن تكون قبل واقعة تلك\r__________\r(1) رواه الخطيب في تاريخ بغداد (341/ 13)."], [264, "الرواية من الإبانة أو بعدها؛ فعلى الأول: تضمحل هذه المنقبة السابقة المسطورة في هذه الرواية من المنقصة اللاحقة المذكورة في تلك الرواية بحيث لا يبقى لتلك المنقبة اعتبار بعد وجود هذه المنقصة، مع أن المعتبرين من العلماء كالحافظ‍ السيوطي وغيره أوردوا هذه الرواية في مناقب الإمام وأثبتوا بها علو مكانه في الدين، فيظهر من اعتبار هذه الرواية بإيرادها في مناقبه والاحتجاج بها كون تلك الرواية مفتراة على الثوري منسوبة إليه.\rوعلى الثاني: كيف يتصور أن يصدر من مثل سفيان نحو هذه المبالغة في مدح الإمام وتكريمه، وترديد من أنكر هذه المبالغة المدح له مع أنه سبق بتهجينه بما أعلن من كفره وما وافق معه بل ثبت منه التكفير لقائل الخلق، وغاية الاهتمام فيه كما أخرج اللالكائي في السنة (1)، نا المخلص نا أبو الفضل شعيب بن محمد بن علي بن حرب بن بسام سمعت شعيب بن جرير (2) يقول: قلت لسفيان الثوري:\rحدث بحديث السنة ينفعني الله به، فإذا وقفت بين يديه قلت: يا رب حدثني بهذا سفيان فأنجو أنا وتؤخذ، قال: اكتب «بسم الله الرحمن الرحيم، القرآن كلام الله غير مخلوق، منه بدأ وإليه يعود، من قال غير هذا فهو كافر، والإيمان قول وعمل ونية يزيد وينقص، وتقدمة الشيخين - إلى أن ختم هذا الكلام على قوله: إذا وقفت بين يدي الله فسألك من قال هذا؟ فقل: يا رب حدثني بهذا سفيان الثوري ثم خل بيني وبين الله عز وجلّ».\rهذا ثابت عن سفيان أورده الحافظ‍ الذهبي في تذكرة الحفاظ‍ (3) في ترجمة سفيان الثوري؛ فإن كان الثوري كرم الإمام وأثنى عليه بمثل هذا التكريم\r__________\r(1) شرح أصول اعتقاد أهل السنة (314).\r(2) صوابه كما في شرح أصول اعتقاد أهل السنة، وتذكرة الحفاظ‍: «حرب».\r(3) تذكرة الحفاظ‍ (206/ 1)."], [265, "والثناء البالغين إلى أقصى مدارجهما مع كونه على هذه العقيدة التي يستحق معها صاحبها غاية اللوم ونهاية الطرد يكون هو مطعونا حقيقا بأن يجعل هدفا لسهام الملامة، وثبت من استقراء أحواله وأقواله وتتبع أعماله وأفعاله أن شأنه أرفع من أن تتجه إليه المطاعن القادحة وأن تلحقه موجبات الملامة.\rوالثانية: ما روى الخطيب (1) عن محمد بن بشير (2) قال: كنت أختلف إلى أبي حنيفة وإلى سفيان فيقول: لقد جئت من عند رجل لو أن علقمة والأسود حضر الاحتاجا إلى مثله، فآتي سفيان فيقول: من أين جئت؟ فأقول: من عند أبي حنيفة، فيقول: لقد جئت من عند أفقه أهل الأرض - انتهى، ورواه السيوطي أيضا في تبييض الصحيفة.\rقلت: يظهر أيضا مما قال في الرواية المذكورة قبل هذا: وأن الوصف في مقام المدح بأنه أفقه أهل الأرض يكون منقبة دينية، والمنقبة الدينية لا تجتمع مع المنقصة الدينية، مفاده أنه متى تحققت المنقبة الدينية لا تتصور المنقصة الدينية هنا، ومتى تقررت المنقصة الدينية لا تجتمع معها المنقبة الدينية، ولما قال سفيان للإمام: إنه أفقه أهل الأرض كان هذا منقبة بليغة ومديحة عظيمة في حقه، وعلى صدق هذه الروايات من الإبانة كان الإمام قائلا بخلق القرآن ولا شك أنه منقصة تامة، فكيف تستقر تلك المنقبة مع هذه المنقصة؟ وكيف كان يجوز مثل الثوري تلك المنقبة لمن فيه مثل هذه المنقصة؟ وكيف يرضى لنفسه هذا الصنيع الفظيع؟ حاشاهم عن ذلك ونكف ألسنتنا عن أن نقول فيهم ما هم بريئون عنه، ويثبت تجدد المقولة على تجدد الإتيان مما قال الراوي في هذه الرواية بأن «كنت أختلف فآتي فيقول»، فانتفى احتمال أن ما قال الثوري في حق الإمام بأنه أفقه\r__________\r(1) رواه الخطيب في تاريخ بغداد (344/ 13)، ومن طريقه المزي في تهذيب الكمال (423/ 29).\r(2) صوابه في تاريخ بغداد وتهذيب الكمال: «بشر»."], [266, "أهل الأرض كان بعدما رجع الإمام عن هذه العقيدة؛ لأنه لما كان تجدد هذه المقولة الواحدة للثوري وتعددها حسب تجدد الإتيان وتعدده؛ فتعيين مقولة من تلك المقولات للبعدية يقتضي تعيين إتيان من الإتيانات المتعددة لها، وتعيينها بلا دليل يدل عليه ترجيح بغير مرجح، وأما أن تسلسل هذا الإتيان يؤخذ ابتداؤه بعد رجوع الإمام عن هذه العقيدة أو يحتمل ذلك فيقتضي دليلا مرجحا وبرهانا معينا حتى يعين أن سلسلة الإتيان ابتداؤها من وقت كذا أو ليس فليس، فالمقصد على حاله، وإن صرفنا النظر عن كل هذا فتكون الرواية الأولى من روايات الإبانة مخدوشة وغير مسموعة مجروحة غير مقبولة أيضا على قاعدة المحدثين.\rقال شيخ الإسلام التاج السبكي في الطبقات: قد عرفناك أن الجارح لا يقبل منه الجرح وإن فسره في حق من غلبت طاعاته على معصيته ومادحوه على ذاميه ومزكوه على جارحيه، إذا كانت هناك قرينة يشهد العقل بأن مثلها حامل على الوقيعة فيه من تعصب مذهبي أو منافسة دنيوية وغير ذلك كما يكون بين النظراء، وحينئذ فلا يلتفت إلى كلام الثوري وغيره في أبي حنيفة ... إلى آخر ما قال.\rوالذهبي عدل الإمام بأعلى مدارجه حيث لم يذكر الإمام في كتابه (ميزان الاعتدال في نقد الرجال) لجلالته الباهرة وعظمته الظاهرة التي لا تخفى على أحد ولا يشك فيه فرد كما قال: وكذا لا أذكر في كتابي من الأئمة المتبوعين في الفروع أحدا لجلالتهم في الإسلام وعظمتهم في النفوس مثل أبي حنيفة والشافعي والبخاري (1) - انتهى.\rوظاهر أن الذهبي محك الرجال وإمام النقادين بصير متيقظ‍ لا يتغافل، متصلب متعصب يبالغ في الجرح لا يتساهل، بل هو لشدته في الجرح عن الحق\r__________\r(1) ميزان الاعتدال (2/ 1)."], [267, "قد يتمايل، فإن كان الإمام قائلا بخلق القرآن يستحيل عادة أن يخفى على مثل هذا الخبير ولا يقف عليه، وإن كان يعلم فبعيد أن يعدله هكذا مع وجود ما يوجب الجرح القوي فيه، وأما الاستتابة المخصوصة المذكورة في هذه الروايات فهي وإن أبطلناها من الأصل بحيث لا يكون لداخل فيه دخل، ولكن تقوي هذا الإبطال وتؤيده حكاية الاستتابة المطلقة التي كذبها وأبطلها القاضي أبو اليمن في كتابه (مختار المختصر) وأبو المؤيد في (جامع المسانيد)، وإذا بطل العام بطل الخاص ضرورة؛ فإن الخاص داخل في العام، قال القاضي أبو اليمن في (مختار المختصر): إن أبا حنيفة استتيب من الزندقة مرتين، وذلك كذب، وفي رواية: من الكفر مرارا.\rقال أبو المؤيد في (جامع المسانيد): أما قول الخطيب حاكيا عن سفيان الثوري أنه قال: «استتيب أبو حنيفة مرتين من الكفر» له وجوه ثلاثة: أحدها: أن سفيان كان بينه وبين أبي حنيفة عداوة لأن أبا حنيفة كان يباحثهم فلا يقدرون على أن يتكلموا؛ فكان سفيان وأمثاله من البشر تأمرهم النفس الأمارة بالسوء على الوقيعة فيه بحكم البشرية كإخوة يوسف أولاد يعقوب، ثم يتذكرون فإذا هم مبصرون.\rالثاني: أن أبا يوسف فسر ذلك فقال: لما دعا ابن هبيرة أبا حنيفة إلى القضاء فامتنع، وكان مذهب ابن هبيرة أن من خرج عن طاعة الإمام كفر، فقال له: كفرت يا أبا حنيفة تب إلى الله تعالى، فقال: أتوب إلى الله من كل سوء، ثم دعاه الثانية، ففعل ذلك ثلاث مرات إلى أن قال: فهذا معنى قول سفيان: استتيب أبو حنيفة من الكفر مرتين.\rالثالث: ما قيل: إن الخوارج دخلوا الكوفة فقصدوا أبا حنيفة بالسيوف المشهرة فقالوا: تزعم أنه لا يكفر أحد بذنب - والحكاية مشهورة - إلى أن قال أبو حنيفة: أتوب إلى الله من كل ذنب، فقال أعداؤه: استتيب أبو حنيفة."], [268, "ذكرها أيضا المحدث الجليل المتكلم النبيل المتضلع في العلوم بضلع قوي ابن حجر المكي الهيتمي الشافعي فقال في كتابه «الخيرات الحسان في مناقب الإمام الأعظم أبي حنيفة النعمان»: إنه وقع لبعض حساد أبي حنيفة الذين ينقصونه مما هو بريء منه أنه ذكر في مثالبه أنه كفر مرتين واستتيب مرتين، وإنما وقع له ذلك مع الخوارج فأرادوا انتقاصه به وليس بنقص بل غاية في رفعه؛ إذ لم يوجد أحد يحاجهم غيره رحمة الله عليه - انتهى.\rثم من مؤيدات هذا الافتراء كثرة معاندي الإمام من معاصريه وغيرهم من أهل الأهواء والزندقة، وما حكي من سعيهم في إيذائه وإيلامه، ومن جهدهم في إلزامه واتهامه فكبهم الله تعالى على وجوههم فانقلبوا خاسرين ورجعوا خائبين، وكانوا من الذين ضل سعيهم في الحياة الدنيا وهم يحسبون أنهم يحسنون صنعا، لأنهم أرادوا إطفاء نور الله في الأرض والله متم نوره على رغم المفسدين.\rاعلم أن الإبانة ليس فيها رواية الاستتابة عن سفيان الثوري كما هي في (جامع المسانيد) بل الذي عنه في هذا الكتاب أن الإمام كان يقول بخلق القرآن، والاستتابة فيه إنما هي مروية من غيره، إلا أنه تئول جميع الروايات إلى جرح سفيان في الإمام بأي وجه كان؛ فتكون مدفوعة بروايات أخرى منه كما ذكرنا، وبفرض ألا تكون مدفوعة منها فالجرح من سفيان في حق الإمام سواء كان بالاستتابة أو نسبة هذه العقيدة إليه مردود على قاعدة المحدثين لا يلتفت إليه كما نقلنا من الطبقات للسبكي، وإن كان الجرح منه بالاستتابة فمؤولة كما هي معنى الوجه الثاني من (جامع المسانيد) أو محرفة كما يعلم من الوجه الثالث من هذا الكتاب أيضا، وإن لم نعتبر تلك الأمور التي ذكرناها بل نقدرها مرفوعة غير مذكورة، وتأملنا في مسلك الإمام وطريقته وتتبعنا مذهبه ومشربه فنعلم منه وحده علما جازما أن الإمام بريء عن القول بخلق القرآن وأمثاله من العقائد الزائغة."], [269, "قال أبو أسامة: سمعت سفيان يقول: ليس طلب الحديث من عدة الموت لكنه علة يتشاغل بها الرجل، قلت: صدق والله، إن طلب الحديث شيء غير الحديث؛ فطلب الحديث اسم عرفي لأمور زائدة على ما تحصل ماهية الحديث وكثير منها مراق إلى العلم وأكثرها أمور يشغف بها المحدث، كتحصيل النسخ المليحة، وطلب المعالي، وتكثير الشيوخ ... إلخ، فإذا كان طلبك للعلم النبوي محفوظا بهذه الآفات فمتى خلاصك إلى الإخلاص؟ وإذا كان علم الآثار مدخولا فما ظنك بعلم المنطق والجدل، وحكمة الأوائل التي تسلب الإيمان وتورث الشكوك والحيرة التي لم تكن - والله - من علم الصحابة ولا التابعين ولا علم الأوزاعي والثوري ومالك وأبي حنيفة وابن أبي ذئب وشعبة، وهكذا عدّ الآخرين من العلماء ثم قال بعده: بل كانت علومهم القرآن والحديث والفقه والنحو وشبه ذلك - كذا في تذكرة الحفاظ‍ للذهبي الحافظ‍ الناقد صفحة (168) و (169) من المجلد الأول.\rقلت: في هذا غاية تبرئة للإمام الأعظم ونهاية تطهير له من هذه العقيدة وأمثالها وأشباهها وأنه من الأئمة الأجلة وقدوة هذه الأمة، وأن طريقه طريق مرضي ومنهجه منهج سوي برغم أنف كل غادر غوي بقوة الله القادر القوي، أفمن يقول بخلق القرآن يجعل من الأئمة المتبوعين للمسلمين ومن الذين قام بهم منار الدين واستنارت بهم مناهج اليقين؟ ولتضم هذه العبارة للذهبي مع قوله الذي نقلناه من (ميزان الاعتدال) لأنها تجرح الجرائح وتورد عليها القبائح وتوقع الجارحين في الفضائح وتثبت للإمام مديحة هي أم المدائح.\rوقال فخر الإسلام والمسلمين البزدوي الذي هو إمام الأئمة للأصوليين في كتابه (في أصول الفقه) يمدح الإمام ويبين أحواله السنية: وكان في علم الأصول إماما صادقا، وقد صح عن أبي يوسف أنه قال: ناظرت أبا حنيفة في مسألة خلق"], [270, "القرآن ستة أشهر فاتفق رأيي ورأيه على أن من قال بخلق القرآن فهو كافر، وصح هذا القول عن محمد رحمه الله، ودلت المسائل المتفرقة عن أصحابنا في المبسوط‍ وغير المبسوط‍ على أنهم لم يميلوا إلى شيء من مذاهب الاعتزال وإلى سائر الأهواء - انتهى.\rوقال شارحه في شرح هذا المقام: ومما يدل على تبحره فيه ما روى يحيى بن شيبان عن أبي حنيفة رحمه الله أنه قال: كنت رجلا أعطيت جدلا في الكلام فمضى دهر فيه أتردد وبه أخاصم وعنه أناضل، وكان أكثر أصحاب الخصومات بالبصرة فدخلتها نيفا وعشرين مرة أقيم سنة وأقل وأكثر، وكنت قد نازعت طبقات الخوارج من الإباضية وغيرهم، وطبقات المعتزلة وسائر طبقات أهل الأهواء وكنت بحمد الله أغلبهم وأقهرهم، ولم يكن في طبقات أهل الأهواء أحد أجدل من المعتزلة؛ لأن ظاهر كلامهم مموه تقبله القلوب وكنت أزيل تمويهم بمبدأ الكلام - انتهى.\rأقول: إن قوله قد صح عن أبي يوسف أنه قال: ناظرت أبا حنيفة ... إلى آخر ما قال مفسرا للدعوى المتقدمة المذكورة في قوله: «كان في علم الأصول إماما صادقا» ومثبت لها: ينبغي أن تنزل هذه العبارة المتقدم ذكرها منزل الدعوى ويفهم ما بعدها دليلها، فتقديم الدليل الذي هو مناظرة الإمام في مسألة الخلق على دلائل أخرى وذكره بصورة القصة والواقعة دون ما سواه من الدلائل يعلم منه أنه كان للإمام وأصحابه جهد عظيم في إنكار خلق القرآن واهتمام بليغ فيه، حيث باحث معه أفضل تلامذته وأذكاهم وأجودهم بحثا طويلا بالغا، فصار كأن الإمام أزال بشمس تحقيقه الظلمة المظلمة التي أحاطت الأمر من كل جانب فصارت مستنيرة منيرة مستضيئة مضيئة لا يستريب معها في كفر قائله كل أريب لبيب، ولا يدب في الصدور من الشك فيه دبيب."], [271, "وحيث قدم البزدوي هذا الدليل على دلائل أخرى وذكرها بصورة مخصوصة مخالفة لقصور تلك الدلائل دالة على اهتمام الإمام فيه، فهو من أعظم الأدلة عنده على دعواه وهي كون الإمام إماما صادقا في علم الأصول، فبقول البزدوي هذا يكشف القناع عن روايات الإبانة بجملتها بإثبات افترائها ووضعها، ثم ينظر إلى عبارة الشارح فإنه يتضح منها صنيع الإمام ودأبه ومخاصمته أهل الأهواء عامتهم وإلزامه وإفحامه لهم؛ فإن كانت عقيدة الخلق متمكنة في الإمام وهي من أشهد المنكرات وقائلها من أعظم أهل الأهواء وأجل المبتدعين كيف يستقيم عليه صنيعه هذا؟\rومما يوضح مسلك الإمام ويبينه بحيث لا يتردد بعده متردد هو ما روى فلان عن نعيم بن حماد قال: سمعت عبد الله بن المبارك يقول: قال أبو حنيفة: إذا جاء الحديث عن النبي صلّى الله عليه وآله وسلّمو اله وسلم فعلى الرأس والعين، وإذا كان عن أصحاب النبي صلّى الله عليه وآله وسلّمو اله وسلم اخترنا ولم نخرج من قولهم، وإذا كان عن التابعين زاحمناهم - أوردها الحافظ‍ السيوطي في تبييض الصحيفة في مناقب الإمام أبي حنيفة.\rأقول: إنه يبعد على هذا المسلك للإمام غاية البعد أن تتمكن هذه العقيدة في الإمام أشد التمكن بحيث انتهى الأمر باستتابته وهي متمكنة بعدها أيضا غير زائلة مع أنه يعلم قبحها من أول النظر في الأحاديث والآثار، فكيف يخفى على من قصر نظره عليهما بعد كتاب الله تعالى في الليل والنهار - أعاذنا الله من هذا القول في الأكابر.\rوإذا انتهى الأمر إلى هذا المقام فلنمسك القلم ولنختم الكلام فإن الأمور التي تكون بهيئتها الإجماعية موجبة لتزييد اليقين وتأكيده كثيرة وما أتينا بها فهي منها نبذة يسيرة، وهي تكفي العاقل؛ فإن له تكفي الإشارة والجاهل لا تفيده العبارة.\r***"], [272, "تنبيهات\r"]], "pg": [251, 272]}, "إ.خ.2": {"x": [[272, "الأول منها: أن القول بمناظرة الإمام في مسألة الخلق مذكور في ثلاثة كتب:\rأحدها الإبانة، وثانيها كتاب الأسماء والصفات، وثالثها كتاب البزدوي، وهي متفقة على أصل المناظرة ولكنها مختلفة متناقضة في بيان مآلها، ففي الأول منها أن الإمام رجع بعد المناظرة عن عقيدة خلق القرآن، وظاهر أن الرجوع من أمر يقتضي سبق المرجوع عنه، وأيضا يتضح من عبارته أن أبا يوسف ما ناظر الإمام إلا لإبطال عقيدته وإرجاعه عنها، وفي الأخيرين أن الإمام وأبا يوسف اتفقا بعد المناظرة على تكفير قائل الخلق، ولا يخفى أن مقتضى هذا هو أن المناظرة ما كانت إلا لتقرير حكم المسألة بعد تحقيقها التام، وأما أن عقيدة الإمام كانت هكذا قبل المناظرة فأين هو في الرواية المذكورة في هذين الكتابين؟ بل يثبت منها نفيه ويظهر منها خلافه، فالعبارة التي وردت بها رواية المناظرة في الكتابين الآخرين يظهر منها كذب رواية الإبانة بعبارتها الكذائية.\rوالثاني: أن رواية المناظرة بأي عبارة كانت تدل على أن البحث في هذه المسألة إنما كان مبتدأ من الإمام أبي يوسف لا الإمام الأعظم؛ فإن المروي في كتاب الأسماء والصفات هو لفظ‍: «كلمت أبا حنيفة»، وفي كتاب البزدوي هو: «ناظرت أبا حنيفة» لا كلمني وناظرني، فيظهر منه أن الإمام كان قبل المناظرة على يقين تام بعدم الخلق، وأما بعد المناظرة فزاد يقينا بعد يقين - فانتهى إلى أقصى مراتبها التي ليست بعدها مرتبة فوقها.\rوالثالث: أنه يتفطن الخبير ويتخبر البصير مما ذكر لمجال التحريف والوضع، ومحال الافتراء والاختلاق في هذا الأمر أنه من أين حصل لهم السعة لهذا الافتراء، فإنهم يكفي لهم أدنى سعة وإن كانت أوهن من بيت العنكبوت.\rتم بحمد الله الملحق الأول لمحمد عنايت علي، كان الله له."], [273, "الملحق الثاني للإبانة\rبسم الله الرّحمن الرّحيم\r"]], "pg": [272, 273]}, "إ.خ.3": {"x": [[273, "ومن أقوى الدلائل وأوضح البراهين على كون هذه الروايات مفتريات على الأشعري مدخولة في كتابه هذا هو أنه ما ذكر في كتابه (مقالات الإسلاميين) أن الإمام كان قائلا بخلق القرآن مع أنه جمع فيه مقالات الفرق الإسلامية سالكا في جمعه مسلكا قويما ومنهجا مرضيّا خاليا عن الإفراط‍ والتفريط‍، مضيفا إلى كل فرقة أو قائل ما هو قائله ومعتقده، كما ذكر هو في مفتتحه حيث قال: أما بعد! فإنه لا بد لمن أراد معرفة الديانات والتمييز بينها من معرفة المذاهب والمقالات، ورأيت الناس في حكاية ما يحكون من ذكر المقالات ويصنفون في النّحل والديانات من بين مقصر فيما يحكيه وغالط‍ فيما يذكره من قول مخالفيه، ومن بين متعمد للكذب في الحكاية إرادة التشنيع على من يخالفه ومن بين تارك للتقصي في روايته لما يرويه من اختلاف المختلفين ومن بين من يضيف إلى قول مخالفيه ما يظن أن الحجة تلزمهم به، وليس هذا سبيل الربانيين ولا سبيل الفطناء المميزين، فحداني ما رأيت من ذلك على شرح ما التمست شرحه من أمر المقالات واختصار ذلك وترك الإطالة والإكثار، وأنا مبتدئ شرح ذلك بعون الله وقوته (1) - انتهى.\rفهذه الروايات التي تنبئ بعباراتها عن مذهب الإمام وتفصح عن اعتقاده لو كانت صحيحة لذكر الأشعري في كتابه (المقالات) هذه العقيدة للإمام، وكيف يتصور أن يتركها مع قوله المذكور آنفا المؤدي معناه إلى أنه ليس بمقصر فيما يحكيه غالط‍ فيما يذكره وتارك للتقصي فيما يرويه من اختلاف المختلفين؟ وذكر أيضا هذه الروايات مع أنه ذكر عقيدة الخلق في مواضع من كتابه (المقالات)\r__________\r(1) مقالات الإسلاميين (ص 1)."], [274, "ونسبها إلى الفرق المتعددة، كما قال في ذكر القول في القرآن: قالت المعتزلة والخوارج وأكثر الزيدية والمرجئة وكثير من الرافضة: إن القرآن كلام الله سبحانه وأنه مخلوق لله لم يكن ثم كان (1). وقال بفاصلة قليلة بعده: إنه حكي عن ابن الماجشون أن نصف القرآن مخلوق، ونصفه غير مخلوق، وحكى بعض من يخبر عنه في (المقالات) أن قائلا من أصحاب الحديث قال: ما كان علما من علم الله سبحانه في القرآن فلا نقول مخلوق ولا نقول غير الله، وما كان فيه من أمر ونهي فهو مخلوق، وحكاه هذا الحاكي عن سليمان بن جرير وهو غلط‍ عندي، وحكى محمد بن شجاع أن فرقة قالت: إن القرآن هو الخالق وأن فرقة قالت: هو بعضه، وحكى زرقان أن القائل بهذا وكيع بن الجراح (2) - انتهى.\rأقول: لو كانت الروايات واقعة صحيحة معلومة للأشعري لذكرها في هذا المقام اللائق بذكره - كما لا يخفى على العاقل، وقال في ذكر الخوارج: والخوارج جميعا يقولون بخلق القرآن، وقال في ذكر المرجئة: والفرقة التاسعة من المرجئة أبو حنيفة وأصحابه يزعمون أن الإيمان المعرفة بالله، والإقرار بالله والمعرفة بالرسول والإقرار بما جاء من عند الله في الجملة دون التفسير، وذكر أبو عثمان الآدمي أنه اجتمع أبو حنيفة وعمر بن أبي عثمان الشمزي بمكة فسأله عمر فقال له: أخبرني عمن زعم أن الله سبحانه حرم أكل الخنزير غير أنه لا يدري لعل الخنزير الذي حرمه الله سبحانه ليس هي هذه العين، فقال: مؤمن، فقال له عمر: إنه قد زعم أن الله قد فرض الحج إلى الكعبة غير أنه لا يدري لعلها كعبة غير هذه بمكان كذا، فقال: هذا مؤمن، قال: فإن قال: أعلم أن الله سبحانه بعث محمدا\r__________\r(1) مقالات الإسلاميين (ص 582).\r(2) مقالات الإسلاميين (ص 586)."], [275, "وأنه رسول الله غير أنه لا يدري لعله هو الزنجي، قال: هذا مؤمن.\rولم يجعل أبو حنيفة شيئا من الدين مستخرجا إيمانا وزعم أن الإيمان لا يتبعض ولا يزيد ولا ينقص ولا يتفاضل الناس فيه، وأما غسان وأكثر أصحاب أبي حنيفة فإنهم يحكون عن أسلافهم أن الإيمان هو الإقرار والمحبة لله والتعظيم له والهيبة منه وترك الاستخفاف بحقه وأنه يزيد ولا ينقص (1) - انتهى.\rأقول: إن هذا أيضا من مواضع ذكر هذه الروايات وهذه العقيدة للإمام، وما ذكر فيه شيئا منها، وأما كون الإمام من المرجئة فسيأتي دفعه من كتاب (الملل والنحل) للشهرستاني، ومن كتاب (أبكار الأفكار) للآمدي.\rنعم، هذا المقام جرّأ الواضعين والمفترين على وضع تلك الروايات وافترائها واختلاقها من عند أنفسهم ونسبتها إلى الأشعري، وأيدهم على ذلك ما قاله الأشعري بعد ما ختم ذكر فرق المرجئة: أنه اختلف المرجئة في القرآن هل هو مخلوق أم لا؟ على ثلاث مقالات، فقال قائلون منهم: إنه مخلوق، وقال قائلون منهم بالوقف، وإنا نقول: كلام الله سبحانه لا نقول إنه مخلوق ولا غير مخلوق؛ فهذا مما أوسع لهم مجالا وأمكن لهم محالا لأمنيتهم التي تمنى لهم الشيطان، وليعلم أن الأشعري حينما عد فرق المرجئة واحدة واحدة لم يذكر عقيدة الخلق أو عدمه لواحد منهم حتى ختم عدهم فأخذ في ذكر ما اختلفوا فيه من أمور أخرى حتى انتهى إلى اختلافهم في أن القرآن هل هو مخلوق أو لا فذكر ما نقلناه آنفا، ويظهر منه أنهم ليسوا بخارجين في هذه العقيدة عما ذكر، ولكن لا يتعين أنه أي فرقة من الفرق المعدودة قائل بخلقه وأيهم منكر له وواقف فيه، بل دار الأمر\r__________\r(1) مقالات الإسلاميين (ص 138 - 139)."], [276, "بينهم واحتمل لكل منهم ولم يوجد مرجح ومخصص في عبارته حتى يرجح ويخصص فرقة من الفرق لمقالة من المقالات الثلاثة، ولا يخفى على ذوي البصائر أن الإبهام والإجمال لا يضران عند الأمن من الاختلاط‍ والالتباس أما حينما يخاف منهما فلا يرخص عند ذلك في الإبهام والإجمال، ولما كانت المرجئة مقابلة لأهل السنة مخالفة لهم فعلى أي منهم ورد هذا الاعتقاد القبيح فهم أهل لهذا الاعتقاد يصلحون له فحينئذ لا يضر عدم التعيين.\rوأما الإمام الأعظم فهو أعظم مجتهدي أهل السنة وأجل فقهائهم وقع به القدوة العظمى في الإسلام، وهذا معلوم للأشعري وليس بمستور عليه؛ فإن كان الإمام قائلا بخلق القرآن - وحاشاه عن ذلك - فما كان يجوز للأشعري أن يدخله في المبهمين ويترك التصريح به؛ فإن الظاهر عدم دخول الإمام فيمن يعتقد الخلق؛ فدخوله فيهم خلاف الظاهر، وفي مثل ما هو خلاف الظاهر لا بد من التصريح والتأكيد؛ لأن الجري على الظواهر والمشي على الصرائح لا زال ديدنا للعقلاء من كل طائفة، فإذا لم يصرح الأشعري في هذا الموضع وحين ذكر الفرقة التاسعة من المرجئة أن الإمام قال بخلق القرآن، على أنهما من مواضع تصريحه بذلك - وأيضا لم يذكر بل لم يشر إليه في موضع جاء فيه الذكر عن الكلام في هذه المسألة من كتاب المقالات - ثبت كون هذه الروايات مفتريات، كيف وقد ألزم الأشعري في هذا الكتاب نفسه كما يظهر مما نقلناه أنه لا يقصر فيما يحكيه ولا يترك التقصي في رواية ما يرويه؛ فكيف يقصر بعدم تصريح ما يلزم فيه التصريح، ولا يتقصى فيما لا بد فيه من التقصي، ويكون به مطعونا؟ أ ليس هذا تقصيرا وتركا للتقصي؟ فحيث لم يأت عن الإمام بخلق القرآن صدق فيما ألزمه نفسه كما يفهم مما نقلناه أيضا أنه ليس بغالط‍ فيما يذكره من قول مخالفيه، ولا بمتعمد للكذب في الحكاية إرادة التشنيع على من يخالفه، ولكنه بشر يخطئ"], [277, "وينسى ويزل ويسهو ويقع فيما يقع فيه الإنسان فيعفى، ولذا خطأه من متبعي مذهبه وسالكي طريقته من هم الأعيان في البعض من الأمور كما بين في الكتب بواضح البيان.\rولعل عده الإمام من المرجئة من خطاياه التي لا تتبع لها بل تدفع من كل مكان في كل زمان، ولعمري الغالب على الظن إنما هو تصرف المفترين المقبوحين في عبارته؛ فإن كتابه هذا ليس مما تداولته الأيدي في كل زمان، وما بلغ في الشهرة مثابة المشهورات من الكتب كما هو حال الإبانة أيضا، وهذا مما يتوسع فيه المفترون لصنائعهم القبيحة ودسائسهم الفظيعة، ويتفطن لهذا التصرف مما في (الملل والنحل) للعلامة الشهرستاني الشافعي، فإنه قال فيما عد فرق المرجئة الغسانية أصحاب غسان الكوفي: زعم أن الإيمان هو المعرفة بالله تعالى وبرسوله والإقرار بما أنزل الله مما جاء به الرسول في الجملة دون التفصيل، والإيمان يزيد ولا ينقص، وزعم أن قائلا لو قال: «أعلم أن الله قد حرم أكل الخنزير ولا أدري هل الخنزير الذي حرمه هذه الشاة أم غيرها» كان مؤمنا، ولو قال: «إن الله قد فرض الحج إلى الكعبة غير أن لا أدري أين الكعبة ولعلها بالهند» كان مؤمنا، ومقصوده أن أمثال هذه الاعتقادات أمور وراء الإيمان لا أنه كان شاكّا في هذه الأمور؛ فإن عاقلا لا يستجيز من عقله أن يشك في أن الكعبة في أي جهة وأن الفرق بين الخنزير والشاة ظاهر.\rومن العجب أن غسان كان يحكي عن أبي حنيفة رحمه الله تعالى مثل مذهبه ويعده من المرجئة، ولعله كذب، ولعمري كان يقال لأبي حنيفة وأصحابه: مرجئة السنة، وعده كثير من أصحاب المقالات من جملة المرجئة، ولعل السبب فيه أنه لما كان يقول: «الإيمان هو التصديق بالقلب وهو لا يزيد ولا ينقص» ظنوا به أنه يؤخر العمل عن الإيمان، والرجل مع تحريه في العمل كيف يفتي بترك العمل؟"], [278, "وله سبب آخر، وهو أنه كان يخالف القدرية والمعتزلة الذين ظهروا في الصدر الأول، والمعتزلة كانوا يلقبون كل من خالفهم في القدر: مرجئا، وكذلك الوعيدية من الخوارج؛ فلا يبعد أن اللقب إنما لزمه من فريقي المعتزلة والخوارج والله أعلم (1) - انتهى.\rفانظر إلى هذه العبارة للشهرستاني وقابلها مع العبارة التي نقلناها من المقالات ترشدك إلى ما قلنا من أن الغالب على الظن أنهم تصرفوا في عبارة الأشعري، وأيضا الناقل للحكاية في المقالات هو الآدمي، وقال الشهرستاني في (الملل والنحل) (2): إنه من المعتزلة وإنه صاحب أبي الهذيل من مقدميهم وأئمتهم، وسبق من الشهرستاني أنه لا يبعد أن اللقب إنما لزمه من فريقي المعتزلة والخوارج، فعلى هذا لا يخلو عد الأشعري الإمام في المرجئة إما أن يكون خطأ منه فعفا الله عنه، وإما أن يكون مدخولا في كتابه مفترى عليه وهو الغالب، فقبح الله مفتريه ولا رحم مدخله.\rقال الآمدي في (أبكار الأفكار): أما حكاية ذلك عن أبي حنيفة فلعل الناقل كاذب فيه لقصد الاستئناس فيما قاله إلى أن قال: وليس كذلك مع ما عرف من مبالغته في العمل والاجتهاد فيه، هذا وإن الافتراء والتدليس لم يزلا جاريين على أعاظم العلماء وأكابر الأئمة كما لا يخفى على من أعطاه الله تعالى الخبرة والاطلاع، فقال الشهرستاني في (الملل والنحل) (3): رأيت رسالة نسبت إلى الحسن البصري كتبها إلى عبد الملك بن مروان وقد سأله عن القول بالقدر والجبر، فأجابه بما يوافق مذهب القدرية، واستدل فيها بآيات من الكتاب ودلائل من العقل، ولعلها\r__________\r(1) الملل والنحل للشهرستاني (141/ 1 - 142).\r(2) (30/ 1).\r(3) (47/ 1)."], [279, "لواصل بن عطاء؛ فما كان الحسن ممن يخالف السلف في أن القدر خيره وشره من الله تعالى؛ فإن هذه الكلمة كالمجمع عليها عندهم - انتهى.\rوأما ما وقع في الغنية المنسوبة لحضرة الحضرات وسيد السادات الغوث الأعظم والقطب الأفخم سلطان الأولياء السيد عبد القادر الجيلاني رضي الله تعالى عنه وأرضاه عنا من أن الحنفية من المرجئة فكشف العلماء عن حال هذه النسبة، ولهم في كشفها وجوه اختاروها تعلم من مطالعة كتبهم، جمعها الفاضل عبد الحي اللكهنوي في رسالة (الرفع والتكميل في الجرح والتعديل) بإطناب وتطويل، ومع ذلك لم يأت بما يفيد أو يقطع ويقع عليه التعويل، لأنه لم يرض إلا على واحد منها، وهذا الرضا أيضا يعلم من سكوته عليه لا من قوله: إنه صحيح أو مرضي أو مثل ذلك مما يدل على رضاه مع أن بعض الأجوبة منها وقع موقعا حسنا يظهر من مطالعة ذلك المقام والتأمل فيه، والذي اختاره في هذا الباب ومشى عليه أنه لا يعتد بقول الشيخ رضي الله تعالى عنه في هذا الباب، وكتب الإمام وزير (1) الحنفية المقلدة له مخالفة له حيث قال: فإن مخالفة الواحد ولو كان من أعظم المشاهير أهون من مخالفة الجماهير، وأي مضايقة في عدم اعتداد قول غوث الثقلين في هذا الباب لكونه مخالفا لجميع أولي الألباب لا سيما إذا وجد منه بنفسه ما يعارضه ويخالفه (2)، إلى آخر ما قال.\rوالعجب أن هذا الذي ارتضاه في الجواب ليس بصحيح وسالم من النقض لأنه إذا وجد منه رضي الله تعالى عنه ما يعارض هذا القول ويخالفه فإثبات هذا القول له يوقع في مضيق التناقض، وهو لا يصدر من العقلاء، فكيف ممن هو\r__________\r(1) في الرفع والتكميل: «وزبر».\r(2) الرفع والتكميل (ص 378)."], [280, "أعقل العقلاء وأكمل العلماء الذي عقله موهبي وعلمه لدني، ولسنا هاهنا في صدد هذا البحث وإلا بينا ما يرد على هذا الفاضل فيما سلك عليه في هذا الباب وقررنا الأمر حسب ما يقتضيه المقام مقترنا بالإنصاف متجنبا عن الاعتساف، ومن مواضع ذكر هذه العقيدة للإمام الكتب المؤلفة في الملل والنحل، ومن أشهرها وأحسنها كتاب (الملل والنحل) للعلامة الشهرستاني الشافعي، وليس فيه شمة منه بل فيه ما يناقضه ويذهب رونق هذه الروايات ويكذبها، بيانه أن الشهرستاني شرط‍ على نفسه أن يورد مذهب كل فرقة على ما وجده في كتبهم من غير تعصب لهم ولا كسر عليهم حيث قال في المقدمة الثانية من كتاب (الملل والنحل) (1): وشرطي على نفسي أن أورد مذهب كل فرقة على ما وجدته في كتبهم من غير تعصب لهم ولا كسر عليهم - انتهى.\rفإذا لم يذكر الشهرستاني أن الإمام كان قائلا بخلق القرآن بل أتى بما يظهر منه تبرئة الإمام وتزكيته من أمثال هذه العقائد الزائغة ظهور الشمس في رابعة النهار - كما علمت مما نقلنا منه سابقا، وتعلم أيضا مما ننقله عن قريب إن شاء الله تعالى - كان آية واضحة على كذب هذه الروايات، كيف والشهرستاني علامة خاض فيما ألفه من الملل والنحل وغاص في لجج بحاره، ومن المحالات أن يخفى على مثل هذا الغائص الخائض ما لا يحتاج إلى خوض وغوص أفيتصور أن يستر بعدما وضح عليه أن الإمام كان قائلا بخلق القرآن ويخرج مما شرطه على نفسه وينقض ما ألزمه على ذمته؟\rإذا علمت هذا فاعلم أنه لما فرغ من كتابه (الملل والنحل) عن تمهيد المقدمات وتوطئة التمهيدات وقرب من المطلب قال أهل الأصول المختلفون في التوحيد\r__________\r(1) (16/ 1)."], [281, "والعدل والوعد والوعيد والسمع والعقل: تكلم هاهنا في معنى الأصول والفروع وسائر الكلمات، قال بعض المتكلمين: الأصول معرفة الباري تعالى بوحدانيته وصفاته ومعرفة الرسل بآياتهم وبيناتهم، وبالجملة كل مسألة يتعين الحق فيها بين المتخاصمين فهي من الأصول، ومن المعلوم أن الدين إذا كان منقسما إلى معرفة وطاعة، والمعرفة أصل والطاعة فرع؛ فمن تكلم في المعرفة والتوحيد كان أصوليّا، ومن تكلم في الطاعة والشريعة كان فروعيّا، والأصول هو موضوع علم الكلام، والفروع هو موضوع علم الفقه ... إلى آخر ما قال.\rثم أخذ في ذكر أهل الأصول الباطلة التي هي فرق كثيرة، والفرقة الحقة التي هي الأشعرية، ثم بعده ذكر أهل الفروع وقسمهم على قسمين لا ثالث لهما وهما أصحاب الحديث وأصحاب الرأي، وقال في أصحاب الحديث: إنهم أهل الحجاز الذين هم أصحاب مالك بن أنس وأصحاب محمد بن إدريس الشافعي وأصحاب سفيان الثوري وأصحاب أحمد بن حنبل وأصحاب داود بن علي بن محمد الأصفهاني، وبين وجه تسميتهم بأهل الحديث، وقال في أصحاب الرأي: إنهم أهل العراق وهم أصحاب أبي حنيفة النعمان بن ثابت، ومن أصحابه محمد بن الحسن وأبو يوسف يعقوب بن محمد القاضي وزفر بن هذيل والحسن بن زياد اللؤلؤي وابن سماعة وعافية القاضي وأبو مطيع البلخي وبشر المريسي، وبين وجه تسميتهم بأصحاب الرأي وقال في آخره عند ما ختم ذكر الفرق الإسلامية: إن بين الفريقين - يعني أصحاب الحديث وأصحاب الرأي - اختلافات كثيرة في الفروع ولهم فيها تصانيف وعليها مناظرات، وقد بلغت النهاية في مناهج الظنون حتى كأنهم أشرفوا على القطع واليقين، وليس يلزم بذلك تكفير ولا تضليل بل كل"], [282, "مجتهد مصيب (1) - انتهى ما أردنا نقله من هذا الكتاب.\rفظهر من هذا التقرير للشهرستاني أن الإمام أبا حنيفة رضي الله تعالى عنه وأصحابه ليس إلى تضليلهم طريق فضلا عن تكفيرهم إلا من نازع منهم في الأصول كالمريسي بل هم مجتهدون مصيبون، أفيكون من يعتقد الخلق مؤمنا لا يلزم تكفيره وتضليله فضلا عن أن يكون مجتهدا ويعده مصيبا؟ ولعمري كيف يتصور أن يشيع نسبة الإرجاء إلى الإمام مع أنه أخف من القول بخلق القرآن ولا يوجد رائحة من نسبة عقيدة الخلق إليه رضي الله تعالى عنه مع كونه من أقبح العقائد ومع كون تكفيره على عقيدته هذه من معاصريه نعوذ بالله منه؛ فإن هذا شأنه أن يشيع ويشتهر وأن لا يخفى ولا يستتر، وبعد حصل لي الاطلاع على كتاب (سيف السنة الرفيعة في قطع رقاب الجهمية والشيعة) لمحمد بن موصلي الأصفهاني من معاصري ابن تيمية الحنبلي، فرأيته قال في هذا الكتاب: قد صرح البخاري في كتابه خلق الأفعال (2)، وفي آخر الجامع بأن القرآن كلام الله غير مخلوق.\rوقال: قال الحكم بن محمد: حدثنا سفيان بن عيينة قال: أدركت مشيختنا (3) منذ سبعين سنة منهم عمرو بن دينار، يقولون: القرآن كلام الله غير مخلوق (4).\rقال البخاري: وقال أحمد بن الحسن: حدثنا أبو نعيم حدثنا سليم القاري قال: سمعت سفيان الثوري يقول: قال حماد بن أبي سليمان: أبلغ أبا فلان المشرك أني بريء من دينه وكان يقول: القرآن مخلوق (5). ثم ساق قصة خالد بن عبد الله\r__________\r(1) الملل والنحل للشهرستاني (206/ 1 - 207).\r(2) (ص 45).\r(3) صوابه كما في خلق أفعال العباد: «مشايخنا».\r(4) أخرجه البخاري في خلق أفعال العباد (1).\r(5) أخرجه البخاري في خلق أفعال العباد (2)."], [283, "القسري وأنه ضحى بالجعد بن درهم، وقال: إنه زعم أن الله لم يتخذ إبراهيم خليلا ولم يكلم موسى تكليما، ثم نزل فذبحه (1) - انتهى.\rثم رأيت البخاري افتتح كتابه خلق أفعال العباد بباب ما ذكر أهل العلم للمعطلة الذين يريدون أن يبدلوا كلام الله عز وجلّ، وقال متصلا به: حدثني الحكم بن محمد الطبري: كتبت عنه بمكة، قال: ثنا سفيان بن عيينة قال: أدركت مشيختنا منذ سبعين سنة منهم عمرو بن دينار يقولون: القرآن كلام الله وليس بمخلوق، وقال أحمد بن الحسن: نا أبو نعيم ثنا سليمان القاري: سمعت سفيان الثوري يقول: قال لي حماد بن أبي سليم: أبلغ أبا فلان المشرك أني بريء من دينه وكان يقول: القرآن مخلوق.\rحدثنا قتيبة حدثني القاسم بن محمد حدثنا عبد الرحمن بن حبيب بن أبي حبيب عن أبيه عن جده قال: شهدت خالد بن عبد الله القسري بواسط‍ في يوم أضحى. وقال: ارجعوا فضحوا تقبل الله منكم فإني مضحّ بالجعد بن درهم، زعم أن الله لم يتخذ إبراهيم خليلا ولم يكلم موسى تكليما، تعالى الله علوّا كبيرا عما يقول الجعد بن درهم ثم نزل فذبحه (2) - انتهى.\rاعلم أن هذه الرواية التي ذكرها البخاري عن أحمد بن الحسن ونقلها عن البخاري محمد بن موصلي في كتابه (سيف السنة) هي الرواية الأولى من روايات الإبانة تخالفها في أمرين: (أحدهما) أن في هذه الرواية أحمد بن الحسن - على ما رأيته في نسختين حاضرتين عندي من خلق أفعال العباد - موضع هارون بن إسحاق في رواية الإبانة. (وثانيهما) أنه أبهم في هذه الرواية موضع البحث\r__________\r(1) أخرجه البخاري في خلق أفعال العباد (3).\r(2) خلق أفعال العباد (ص 2 - 3)."], [284, "وموقع الرد فقيل: أبا فلان، وفي الرواية الواقعة في الإبانة تصريح بالإمام الأعظم أبي حنيفة، ويزاد على هذين الاثنين بالنظر إلى ما نقله في (سيف السنة) إن كان صحيحا وما كان من سهو الناسخ فيقال: ثالثها: سليم القاري، وفي الإبانة سليمان بن عيسى القاري موضعه؛ فهذه الرواية الواقعة في كتاب (خلق الأفعال) لما أبهم فيها ما يقع عليه البحث ويتوجه إليه الرد لا تصلح لأن يبحث عنها مع أنه سبق الرد البليغ لروايات الإبانة التي فيها تصريح بما يقع فيه البحث ويتوجه إليه الرد، وهذه الرواية الواقعة في كتاب (خلق الأفعال) لما جهل فيها موقع الرد ومحل البحث وما تعين فإلام يوجه الرد وفي أي أمر يقع البحث؟ ولا يأتي الإبهام في مثل هذا المقام الذي يجب فيه الإكشاف عن المتقين المخلصين لا سيما من البخاري المتصلب في دين الله الذي لا يبالي في الله بأحد كما هو الظاهر من تتبع أحواله، وقد نقل التكفير صريحا في كتابه خلق الأفعال فقال: وسئل وكيع عن مثنى الأنماطي فقال: كافر (1)، وقال عبد الله بن داود: لو كان لي على المثنى الأنماطي سبيل لنزعت لسانه من قفاه، وكان جهميّا (2).\rوقال أيضا: حدثني أبو جعفر قال: ثنا أحمد بن خلال قال: سمعت يزيد بن هارون وذكر أبا بكر الأصم والمريسي فقال: هما والله زنديقان كافران بالرحمن حلالا الدم (3). مع أن إيراداته على الإمام الأعظم واعتراضاته عليه رضي الله تعالى عنه محصورة في الفروعات الفقهية أجاب عنها علماؤنا رحمهم الله تعالى، ورأيت فيها رسالة حسنة مسماة ب‍ (بعض الناس في دفع الوسواس) دفع فيها ما أورده الإمام البخاري على الإمام الأعظم أبي حنيفة وعلى الحنفية مصدرا بقوله:\r__________\r(1) أخرجه البخاري في خلق أفعال العباد (56).\r(2) أخرجه البخاري في خلق أفعال العباد (57).\r(3) أخرجه البخاري في خلق أفعال العباد (74)."], [285, "قال بعض الناس مدللا مفصلا فجزاه الله خيرا، وما وجد من البخاري فيما تصفحنا إلزام على الإمام في أصول الدين، وهذا البيهقي واسع العلم ما نقل عن البخاري هذه الرواية في كتابه (الأسماء والصفات) (1) و قد ذكر الرواية السابقة المتصلة عنها وهي رواية البخاري عن سفيان بن عيينة في كتابه هذا، فقال:\rأخبرنا أبو منصور عبد القاهر بن طاهر بن محمد الفقيه قال: ثنا أبو أحمد الحافظ‍ النيسابوري قال: أنا أبو عروبة السلمي قال: ثنا سلمة بن شبيب قال: ثنا الحكم بن محمد قال: ثنا سفيان بن عيينة عن عمرو بن دينار قال: سمعت مشيختنا منذ سبعين سنة يقولون (ح) قال أبو أحمد الحافظ‍: وأخبرنا أبو أحمد محمد بن سليمان بن فارس - واللفظ‍ له - قال: ثنا محمد بن إسماعيل البخاري قال الحكم بن محمد أبو مروان الطبري حدثناه سفيان بن عيينة قال: أدركت مشيختنا منذ سبعين سنة منهم عمرو بن دينار يقولون: القرآن كلام الله ليس بمخلوق.\rكذا قال البخاري عن الحكم بن محمد. ورواه غير الحكم عن سفيان بن عيينة نحو رواية سلمة بن شبيب عن الحكم بن محمد.\rوذكر أيضا قصة ذبح خالد بن عبد الله القسري للجعد بن درهم في كتابه (الأسماء والصفات) (2) بسنده، وقال: رواه البخاري في كتاب التاريخ (3) عن قتيبة عن القاسم (بن) (4) عبد الرحمن بن محمد بن حبيب بن أبي حبيب عن أبيه عن جده هكذا، يشير إلى ما قبل حيث ذكر فيه القصة بسنده كما أومأنا إليه، وهذه القصة قد رواها البخاري في كتابه (خلق أفعال العباد) وذكرها متصلة مما\r__________\r(1) الأسماء والصفات (531).\r(2) الأسماء والصفات (563).\r(3) التاريخ الكبير (64/ 1).\r(4) صوابه كما في الأسماء والصفات: «عن»."], [286, "نقله - والله أعلم - عن أحمد بن الحسن عن أبي نعيم عن سليمان القاري عن سفيان الثوري؛ فيبعد عن البيهقي رحمه الله تعالى أن يذكر الرواية السابقة واللاحقة ويترك الوسطى مع كونها أبلغ في ذم القائل بخلق القرآن؛ فدلنا على عدم ثبوت هذه الرواية، ولو تتبعنا الأمر حق تتبعه لوجدنا كثيرا من الدلائل تدل على ما قلنا ولكنه أغنانا مزيد التتبع ما ذكرنا سابقا فإن فيه كفاية لأولي النهى.\rثم لما كانت الرواية منقولة عن البخاري في كتاب (سيف السنة الرفيعة) على إبهامها لا بد لنا من التأمل في هذا الكتاب ليعلم أن الإمام الأعظم في أي منزلة عند مؤلفه محمد بن موصلي، وما العقيدة له فيه حتى يظهر أن الرجل المبهم في الرواية هل يترجح الإمام الأعظم في كونه مرادا منه عنده أم لا؟.\rفاعلم أنا إذا نظرنا في هذا الكتاب وجدنا مؤلفه محمد بن موصلي من المتشددين زهقى اللسان لا يمسك عن تشنيع أحد وذمه إذا ثبت في زعمه أنه يستحقه لكونه متحرفا عن الطريق المستقيم فضلا عن أن يكف عن نسبة أمر إلى أحد ثبت عنده نسبة ذلك الأمر إليه، قال في الوجه السادس والخمسين من وجوه تزييف العقل وتسخيفه في مقابلة النقل وحصول اليقين من النقل: أم ترضون بعقول المتأخرين الذين هذبوا العقليات ومخضوا زبدتها واختاروا لأنفسهم ولم يرضوا بعقول سائر من تقدم؟ فهذا أفضلهم عندكم محمد بن عمر الرازي فبأي معقولاته تزنون نصوص الوحي وأنتم ترون اضطرابه فيها في كتبه أشد الاضطراب فلا يثبت على قول - انتهى.\rوشنع على المؤولين في الصفات والمتكلمين؛ فقال في الوجه الخامس والعشرين من وجوه الإبطال لتقديم العقل على النقل: إن غاية ما ينتهي إليه من ادعى معارضة العقل للوحي أحد أمور أربعة لا بد له منها: إما تكذيبها وجحدها، وإما اعتقاد أن الرسل خاطبوا الخلق خطابا جمهوريّا لا حقيقة له وإنما"], [287, "أرادوا منهم التخييل وضرب الأمثال، وإما الاعتقاد أن المراد تأويلها وصرفها عن حقائقها بالمجازات والاستعارات، وإما الإعراض عنها وعن فهمها وتدبرها واعتقاد أنه لا يعلم ما أريد إلا الله، فهذه أربع مقامات ثم قال حينما فصل المقام الثالث من هذه المقامات الأربعة:\rالمقام الثالث مقام أهل التأويل قالوا: لم يرد منا اعتقاد حقائقها وإنما أريد منا تأويلها بما يخرجها عن ظاهرها وحقائقها فتكلفوا لها وجوه التأويلات المستكرهة والمجازات المستنكرة التي يعلم العقلاء أنها أبعد شيء عن احتمال ألفاظ‍ النصوص لها وأنها بالتحريف أشبه منها بالتفسير، ثم قال: فالطائفتان - يعني أصحاب التخييل وأصحاب التأويل - اتفقتا على أن ظاهر خطاب الرسول صلّى الله عليه وسلّم ضلال وباطل وأنه لم يبين الحق ولا هدى إليه الخلق.\rوقال في الثلاثين من تلك الوجوه: إن الطرق التي سلكها هؤلاء المعارضون بين الوحي والعقل في إثبات الصانع هي بعينها تنفي وجوده لزوما؛ فإن المعارضين صنفان: الفلاسفة والجهمية، ثم بين طرق الفلاسفة والمتكلمين في إثبات الصانع جل شأنه فقال فيما يذكر طرق المتكلمين في إثبات الصانع: وأما المتكلمون فلما رأوا بطلان هذا الطريق - يعني به طريق الفلاسفة - عدلوا عنها إلى آخر ما قال، ثم قال - بعد ما ذكر طريق المتكلمين: فلزمهم من سلوك هذا الطريق إنكار كون الرب فاعلا في الحقيقة، وإن سموه فاعلا بألسنتهم إلى آخر ما قال.\rوقال في الوجه الثامن والثلاثين: ثم ظهر مع هذا الشيخ المتأخر المعارض - يعني به نصير الدين الطوسي الذي ذكره قبل ملقبا له بنصير الشرك والكفر الطوسي - أشياء لم تكن تعرف قبله حست (1) العميدي وحقائق ابن عربي\r__________\r(1) كذا."], [288, "وتشكيكات الرازي، وشنع على الأشعري إمام أهل السنة، فقال في الوجه الثالث والأربعين: قالت الفرقة الجامعة بين التجهم ونفي القدر معطلة الصفات: صدق الرسول موقوف على قيام المعجزة الدالة على صدقه، وقيام المعجزة موقوف على العلم بأن الله لا يؤيد الكذاب بالمعجزة الدالة على صدقه، والعلم بذلك موقوف على العلم بقبحه، وعلى أن الله تعالى لا يفعل القبيح، وتنزيهه عن فعل القبيح موقوف على العلم بأنه غني عنه عالم بقبحه، وغناه عنه موقوف على أنه ليس بجسم، وكونه ليس بجسم موقوف على عدم قيام الأعراض والحوادث به، وهي الصفات والأفعال - إلى أن قال مضيفا إليهم:\rقالوا: بهذا الطريق أثبتنا حدوث العالم ونفي كون الصانع جسما وإمكان المعاد.\rثم قال: فصار العلم بإثبات الصانع وصدق الرسول وحدوث العالم وإمكان المعاد موقوفا على نفي الصفات؛ فإذا جاء في السمع ما يدل على إثبات الصفات والأفعال لم يكن القول بموجبه، ويعلم أن الرسول لم يرد إثبات ذلك لأن إرادته لإثباته تنافي تصديقه ثم إما أن يكذب الناقل وإما أن يتأول المنقول وإما أن يعرض عن ذلك جملة ويقول: لا يعلم المراد؛ فهذا أصل ما بنى عليه القوم دينهم وإيمانهم، ولم يقيض لهم ما بين لهم فساد هذا الأصل ومخالفته لصريح العقل إلى أن قال: وهذا الطريق من الناس من يظنها من لوازم الإيمان وأن الإيمان لا يتم إلا بها، ومن لم يعرف ربه بهذا الطريق لم يكن مؤمنا به ولا بما جاء به رسوله، وهذا يقوله الجهمية والمعتزلة ومتأخر والأشعرية بل أكثرهم، وكثير من المنتسبين إلى الأئمة الأربعة وكثير من أهل الحديث والصوفية.\rومن الناس من يقول: ليس الإيمان موقوفا عليها ولا هي من لوازمه، وليست طريق الرسل، ويحرم سلوكها لما فيها من الخطر والتطويل وإن لم يعتقد بطلانها، وهذا قول أبي الحسن الأشعري نفسه فإنه صرح بذلك في رسالته إلى"], [289, "أهل الثغر، وقال في الوجه السادس والأربعين: أن يقال لهؤلاء المعارضين للوحي بعقولهم: إن من أئمتكم من يقول: إنه ليس في العقل ما يوجب تنزيه الرب سبحانه عن النقائص ولم يقم على ذلك دليل عقلي أصلا كما صرح به الرازي وتلقاه عن الجويني وأمثاله، قالوا: وإنما نفينا عنه النقائص بالإجماع، وقد قدح الرازي وغيره من النفاة في دلالة الإجماع وبينوا أنها ظنية لا قطعية؛ فالقوم ليسوا قاطعين بتنزيه الله تعالى عن النقائص بل غاية ما عندهم في ذلك الظن إلى آخره، وأيضا شنع في الوجه السابع والأربعين على الإمام الأشعري والحارث المحاسبي والقاضي أبي بكر الباقلاني وغيرهم تركناه مخافة التطويل.\rوقال في الخمسين: أما الصفاتية الذين يؤمنون ببعض ويجحدون بعضا إلى آخر ما قال، وهذا تشنيع منه على المتكلمين المخالفين للمعتزلة والجهمية، وقال فيما بين فيه اختلاف أهل الأرض في كلام الله تعالى: {المذهب الخامس مذهب الأشعري ومن وافقه: أنه معنى واحد قائم بذات الرب، وهو صفة قديمة أزلية ليس بحرف ولا صوت ولا ينقسم، ولا له أبعاض ولا له أجزاء، وهو عين الأمر وعين النهي وعين الاستخبار الكل من واحد، وهو عين التوراة والإنجيل والقرآن والزبور، وكونه أمرا ونهيا وخبرا واستخبارا صفات لذلك المعنى الواحد لا أنواع له؛ فإنه لا ينقسم بنوع ولا جزء، وكونه قرآنا وتوراة وإنجيلا تقسيم للعبارات عنه لا لذاته - إلى أن قال: وعنده لم يتكلم الله بهذا الكلام العربي ولا سمع من الله، وعنده ذلك المعنى سمع من الله حقيقة، ويجوز أن يرى ويشم ويذاق ويلمس ويدرك بالحواس الخمس؛ إذ المصحح عنده لإدراك الحواس هو الوجود، وكل موجود يصح تعلق الإدراكات كلها به كما قرره في مسألة رؤية من ليس في جهة من الرائي وأنه يرى حقيقة وليس مقابلا للرائي، هذا قولهم في الرؤية، وذلك قولهم في الكلام، والبلية العظمى نسبة ذلك إلى الرسول وأنه جاء"], [290, "بهذا أو دعا إليه الأمة، وأنهم أهل الحق ومن عداهم أهل الباطل.\rوجمهور العقلاء يقولون: إن تصور هذا المذهب كاف في الجزم ببطلانه وهو لا يتصور إلا كما يتصور المستحيلات الممتنعات إلى آخر ما قال، وهذا - كما ترى - غاية منه في تشنيع الإمام الأشعري وذمه.\rثم قال: المذهب السابع مذهب السالمية ومن وافقهم من أتباع الأئمة الأربعة وأهل الحديث: إنه صفة قديمة قائمة بذات الرب تعالى لم يزل ولا يزال لا يتعلق بقدرته ومشيئته، ومع ذلك هو حروف وأصوات وسور وآيات سمعه جبرئيل منه، وسمعه موسى بلا واسطة.\rثم قال: وجمهور العقلاء قالوا: تصور هذا المذهب كاف في الجزم ببطلانه، والبراهين العقلية والأدلة القطعية شاهدة ببطلان هذه المذاهب كلها وأنها مخالفة لصريح العقل والنقل، والعجب أنها هي الدائرة بين فضلاء العالم لا يكادون يعرفون غيرها - انتهى.\rهذه تشنيعاته لأئمة الإسلام - أعلى الله مقامهم في دار السلام - لا يبالي بهم ولا يراعي جانب أحد منهم؛ فلو كان المبهم في رواية البخاري يترجح عنده أنه أريد به الإمام الأعظم لذكره وصرح به بل شنع عليه كما شنع على غيره؛ فإنه يستحيل من مثل هذا المتشدد المتصلب المتعصب الذي يرد بأقصى جهده على من هو مخالف لمسلكه ويدفعهم بأبلغ ما يمكنه من الدفع، ولا يتساهل في الرد أن يعرض عن ترجيح ذلك المبهم وتعيينه بعد ما ثبت عنده الترجيح، وحيث لم يتعرض لهذا الأمر أصلا ولم يشنع على الإمام في موضع من كتابه في شيء من المعتقدات وأصول الدين، بل احتج به في موضع الاستدلال على مطالبه الدينية وسماه إماما في مثل هذه المواضع التي تشعر تسميته هكذا فيها بمدحه الدينية وبسلب الذمائم والنقائص عنه، وإثبات المدائح والمكارم له لزم أنه بريء من"], [291, "هذه العقيدة عنده براءة كاملة.\rقال في كسر الطاغوت الذي وضعته الجهمية لتعطيل حقائق الأسماء والصفات وهو طاغوت المجاز، فنقول: تقسيمكم الألفاظ‍ ومعانيها أو استعمالها فيها إلى حقيقة ومجاز إما أن يكون عقليّا أو شرعيّا أو لغويّا أو اصطلاحيّا؛ فأخذ في إبطال الأقسام الثلاثة الأول واحدا واحدا.\rوقال حينما يبطل التقسيم اللغوي: وأهل اللغة لم يصرح أحد منهم بأن العرب قسمت لغاتها إلى حقيقة لا مجاز، ولا قال أحد من العرب قط‍: هذا اللفظ‍ حقيقة وهذا مجاز، ولا يوجد في كلام من نقل لغتهم عنهم مشافهة ولا بواسطة ذلك، ولهذا لا يوجد في كلام الخليل وسيبويه والفراء وأبي عمرو بن العلاء والأصمعي وأمثالهم كما لم يوجد ذلك في كلام رجل واحد من الصحابة ولا من التابعين ولا تابعي التابعين، ولا في كلام أحد من الأئمة الأربعة، وهذا الشافعي وكثرة مصنفاته ومباحثه مع محمد بن الحسن وغيره لا يوجد فيها ذكر المجاز ألبتة إلى أن قال: وكلام الأئمة مدون بحروفه لم يحفظ‍ عن أحد منهم تقسيم اللغة إلى حقيقة ومجاز.\rثم قال بعد فاصلة قليلة: إذا علم أن تقسيم الألفاظ‍ إلى حقيقة ومجاز ليس تقسيما شرعيّا ولا عقليّا ولا لغويّا فهو اصطلاح محض، وهو اصطلاح حدث بعد القرون الثلاثة المفضلة - انتهى.\rفاحتجاجه في هذا المقام الجليل خطره العظيم أمره على الجهمية بالإمام الأعظم مع الأئمة الثلاثة، وجعله من أهل القرون المفضلة بالنص هل هو إلا منقبة للإمام عظيمة ومديحة للإمام فخيمة توضح أن مثل هذا الرجل المتشدد المتجسس والمتعصب المتعمق لم يجد أيضا ما يقدح في شأنه إلا رفع، وقال في هذا البحث أيضا في مقام الاحتجاج على أنه إذا خص من العموم شيء لم يصر اللفظ‍ مجازا فيما بقي أنه لا"], [292, "نزاع بين الصحابة والتابعين والأئمة الأربعة أنه حجة، ومن نقل عن أحد منهم أنه لا يحتج بالعام المخصوص فهو غالط‍ أقبح غلط‍ وأفحشه، وإذا لم يحتج بالعام المخصوص ذهب أكثر الشريعة وبطل أعظم أصول الفقه - انتهى.\rوهذا - كما ترى - ذب عن الإمام الأعظم مع الأئمة الثلاثة وتوضيح لسداد طريقته، وهكذا قال في الوجه الحادي والأربعين من هذا البحث: إن العام المخصوص حجة بإجماع الصحابة والتابعين وتابعيهم، وإنما حدث الخلاف في ذلك بعد انقراض العصور المفضلة التي شهد لها رسول الله صلّى الله عليه وسلّم بأنها خير القرون.\rوقال في الوجه السادس عشر من وجوه إبطال المجاز في لفظ‍ الوجه: إن الصحابة والتابعين وجميع أهل السنة والأئمة الأربعة وأهل الاستقامة من أتباعهم متفقون على أن المؤمنين يرون وجه ربهم تعالى في الجنة إلى آخر ما قال، وهذا توضيح منه بأن الإمام الأعظم أبا حنيفة من أهل الاستقامة عنده فإن الأتباع إذا كانوا من أهل الاستقامة يكون المتبوع من أهل الاستقامة بالضرورة، وهو ظاهر.\rوقال في الوجه الثالث عشر من وجوه الرد على من أنكر حقيقة الفوقية لله تعالى وحملها على المجاز: ولم يزل السلف الصالح يطلقون مثل هذه العبارة إطلاقا لا يحتمل غير الحقيقة، فأخذ يبين إطلاقاتهم حتى قال: وقصة أبي يوسف صاحب أبي حنيفة مشهورة في استتابته لبشر المريسي لما أنكر أن يكون الله فوق العرش، رواها عبد الرحمن بن أبي حاتم وغيره، وبشر لم ينكر أن الله أفضل من العرش وإنما أنكر ما أنكرته المعطلة أن ذاته فوق العرش.\rثم قال بعد فاصلة قليلة: وقال أبو مطيع الحكم بن عبد الله البلخي: سألت أبا حنيفة عمن يقول: لا أعرف ربي في السماء أم الأرض، فقال: قد كفر لأن الله"], [293, "يقول: {الرَّحْمنُ عَلَى الْعَرْشِ اسْتَوى} (1) و عرشه فوق سبع سموات، فقلت: إنه يقول: على العرش استوى، ولكن لا يدري العرش في السماء أم الأرض، فقال:\rإذا أنكر أنه في السماء فقد كفر - انتهى، فظهر من هذا القول أن الإمام الأعظم عنده من السلف الصالح، أفيدخله في السلف الصالح مع ثبوت عقيدة الخلق منه عنده؟ ولما أدخله في السلف الصالح ثبت أنه ما كان قائلا بالخلق أبدا.\rوقال في بحث طويل يرد به على الذين قالوا: لا يحتج بكلام رسول الله صلّى الله عليه وسلّم على شيء من صفات ذي الجلال قالوا: الأخبار قسمان: متواتر وآحاد، فالمتواتر وإن كان قطعي السند لكنه غير قطعي الدلالة؛ فإن الأدلة اللفظية لا تفيد اليقين، وبهذا قدحوا في دلالة القرآن على الصفات، والآحاد لا يفيد العلم فهذا الذي اعتمده نفاة العلم عن أخبار رسول الله صلّى الله عليه وسلّم خرقوا به إجماع الصحابة المعلوم بالضرورة وإجماع التابعين وإجماع أئمة الإسلام، ووافقوا به المعتزلة والجهمية والرافضة والخوارج بل هم الذين انتهكوا هذه الحرمة، وتبعهم بعض الأصوليين والفقهاء وإلا فلا يعرف لهم سلف من الأئمة بذلك بل صرح الأئمة بخلاف قولهم، فممن نص على أن خبر الواحد يفيد العلم مالك والشافعي وأحمد وأصحاب أبي حنيفة - انتهى، فظهر من قوله هذا أن الإمام عنده من أئمة الإسلام، وكيف يكون من أئمة الإسلام إذا كان قائلا بخلق القرآن؟ وحيث كان من أئمة الإسلام لم يكن من القائلين بالخلق.\rوقال ناقلا عن ابن تيمية: إن الخبر الواحد يفيد العلم اليقيني عند جماهير أمة محمد صلّى الله عليه وسلّم من الأولين والآخرين، أما السلف فلم يكن بينهم في ذلك نزاع، وأما الخلف فهذا مذهب الفقهاء الكبار من أصحاب الأئمة الأربعة إلى آخر ما قال،\r__________\r(1) طه: 5."], [294, "وقال فيمن رد الأحاديث بالعذر الذي أقاموه عذرا لرد الأحاديث: وطائفة عاشرة ردته فيما يعم به البلوى وقبلته فيما عداه، وحكوه عن أبي حنيفة وهو كذب عليه وعلى أبي يوسف ومحمد؛ فلم يقل ذلك أحد منهم ألبتة وإنما هذا قول متأخريهم، وأقدم من قال به عيسى بن أبان وتبعه أبو الحسن الكرخي وغيره - انتهى.\rانظر في هذا المقام كيف دفع الأمر من أن يكون منسوبا إلى الإمام وصاحبيه، وقد أطال محمد بن موصلي الأصفهاني مؤلف هذا الكتاب مبحث كلام الله تعالى؛ فبين جميع مذاهب الأرض في كلام الله تعالى كما يدل عليه قوله حين ابتدأ في هذا البحث: اختلف أهل الأرض في كلام الله تعالى إلخ فبين مذاهب الاتحادية والفلاسفة والجهمية والمعتزلة وغيرها من المذاهب، وبين مذهب السلف وأئمة السنة والحديث فيه حتى قال: فالقرآن عندهم جميعه كلام الله حروفه ومعانيه وأصوات العباد وحركاتهم وأداؤهم وتلفظهم، كل ذلك مخلوق بائن عن الله.\rفإن قيل: فإذا كان الأمر كما قررتم فكيف أنكر الإمام أحمد على من قال: «لفظي بالقرآن مخلوق»، وبدّعه ونسبه إلى التجهم؟ وهل كانت محنة أبي عبد الله البخاري إلا على ذلك حتى هجره أهل الحديث ونسبوه إلى القول بخلق القرآن؟ قيل: معاذ الله أن يظن بأئمة الإسلام هذا الظن الفاسد، وقد صرح البخاري في كتابه (خلق الأفعال)، وفي آخر الجامع بأن القرآن كلام الله غير مخلوق، وقال: ... حدثنا سفيان بن عيينة إلى آخر ما قال، وقد نقلناه في صدر المبحث.\rثم قال: فخفي تعريف البخاري وتمييزه على جماعة من أهل السنة والحديث ولم يفهم بعضهم مراده وتعلقوا بالمنقول عن أحمد نقلا مستفيضا أنه قال: من قال: لفظي بالقرآن مخلوق فهو جهمي، ومن قال: غير مخلوق فهو مبتدع، وساعد ذلك نوع حسد بالظن للبخاري لما كان الله نشر له من الصيت إلى أن قال: فوافق الهوى الباطن الشبهة الناشئة من القول المجمل، وتمسكوا بإطلاق"], [295, "الإمام أحمد وإنكاره على من قال: لفظي بالقرآن مخلوق وأنه جهمي؛ فتركب من مجموع هذه الأمور فتنة وقعت بين أهل الحديث في مسألة اللفظ‍، ثم ذكر مخالفة محمد بن يحيى للبخاري؛ فإن محمد بن يحيى كان يعتقد ما يحكيه عن أحمد بن حنبل من الإنكار على من قال: لفظي بالقرآن مخلوق، والبخاري وقف عنه فتكلم محمد بن يحيى فيه، وقال: قد أظهر هذا البخاري قول اللفظية، واللفظية شر من الجهمية، ثم نقل عن أبي عبد الله الحاكم قصتهما.\rقلت: وقد ذكرها أيضا البيهقي في كتابه (الأسماء والصفات) ثم ذب عن البخاري، وبين لقول الإمام أحمد محامل فقال: فالبخاري أعلم بهذه المسألة وأولى بالصواب فيها من جميع من خالفه، وكلامه فيها أوضح وأمتن من كلام أبي عبد الله؛ فإن الإمام أحمد سد الذريعة حيث منع إطلاق لفظ‍ المخلوق نفيا وإثباتا على اللفظ‍، فقالت طائفة: أراد سد باب الكلام في ذلك إلى آخر ما قال: وقد أحسن في بيان ما هو المحمل لقول أحمد رحمه الله تعالى وما هو مراده، ثم قال بعده: وأبو عبد الله البخاري ميز وفصل وأشبع الكلام في ذلك، وفرق بين ما قام بالرب وبين ما قام بالعبد وأوقع المخلوق على تلفظ‍ العباد وأصواتهم إلخ، ونفى اسم الخلق عن الملفوظ‍ وهو القرآن إلخ، وقد شفى في هذه المسألة في كتاب خلق الأفعال، ثم نقل عن البخاري أن المعروف عن أحمد وأهل العلم أن كلام الله تعالى غير مخلوق وما سواه فمخلوق، وأنهم لم يفهموا دقة مذهب الإمام أحمد.\rقلت: لو كان الإمام قائلا بخلق القرآن لذكرها في هذا المبحث الطويل البسيط‍، وما غفل عن ذكره قط‍ مع ما علم من دأبه فيمن يزعم أنه ليس على الطريقة القويمة.\rوالحاصل من كل ما نقلنا من كتاب (سيف السنة) إنما هو إظهار أمرين:\r(أحدهما): تشديد مؤلفه في العلماء المقبولين وتعصبه وإرسال لسانه فيهم وتجسسه للمذاهب كلها وتخبره عن جملتها فيبعد من مثل هذا المتعصب المتصلب"], [296, "المتشدد والمتعمق المتجسس المتخبر كل بعد أن لا يذكر نسبة هذه العقيدة إلى الإمام مع كونه معتقدا بها، وحيث لم يذكرها بل لم يوجد شمة منها في كتابه، ووجد ما ينفيها دل دلالة بليغة على أن الإمام كانت ساحة قلبه الشريف طاهرة عن هذه العقيدة وأمثالها.\rو (ثانيهما): إقراره بكون الإمام من أئمة الدين والسلف الصالح ومن أهل القرون المفضلة بالنص، واللازم منه عدم كون الإمام قائلا بالخلق؛ فإن هذه الألقاب لا تطلق على قائلي خلق القرآن قط‍؛ لأن بين مفاهيم هذه الألقاب وبين القول بخلق القرآن تناقضا لا يجتمعان أبدا، ثم إن كتاب خلق الأفعال محفوظ‍ مروي عن البخاري، نبه عليه الحافظ‍ ابن حجر في مقدمة (فتح الباري لشرح صحيح البخاري) فقال بعد ما عد كتبا من تصانيفه فيها (خلق الأفعال)، وهذه التصانيف موجودة مروية لنا بالسماع أو بالإجازة (1) - انتهى.\rوابن حجر هذا من المادحين للإمام أبي حنيفة رحمه الله تعالى؛ فإن كانت الرواية موجودة في النسخة من (خلق الأفعال) المروية لابن حجر بالسماع أو بالإجازة فلا تخلو إما أن تكون على هذا الإبهام أو تكون صرح فيها بالاسم؛ فعلى الأول يجب الفحص والبحث حتى يتعين ويترجح ويحصل العلم؛ فإن الإبهام جهالة لا تفيد شيئا ولا تقطع أمرا؛ فإذا بحث عن الإبهام فإما أن يتعين الإمام أو يترجح أو يتعين غيره أو يترجح؛ فعلى الأول لا يستقيم مدحه للإمام بل يعيد هذا المدح ذمّا عليه ويوجه طعنا إليه، وعلى الثاني يتضح حال الروايات المذكورة في الإبانة، ولا يتصور منهم أن لا يفحصوا عن هذا الإبهام ويتركوه مع أن عقولهم بعيدة الغور وبحور فهومهم لها قعور بحثوا عن المشتبهات فأكشفوها وأحكموها، وفحصوا\r__________\r(1) هدي الساري (ص 493)."], [297, "عن المجملات ففصلوها وقرروها، وأما إذا لم يجدوا سبيلا إلى التعيين أو الترجيح من بحثهم العميق وفحصهم البليغ - وهو شاذ ونادر - فيفوض الأمر إلى علام الغيوب؛ فإن كانت في رواية أخرى مماثلة لها تصريح يزيل الإبهام لا تكون المصرحة فيها مفسرة للمبهمة؛ لأنهم مع فحصهم الشديد وتجسسهم البليغ لم يجدوها، ولو كانت صحيحة لوجدوها وفسروا بها الإبهام، ولا يعقل أن مثل هذه الرواية تخفى عليهم فمنهم وصلت إلينا الروايات، وعنهم حصلت لنا الدرايات؛ فإن وجدنا رواية ولم نجدها فيهم ولا في واحد منهم دائرة فهي واهية، وإن اطلعنا على دراية وهي تخالف درايتهم فهي لاهية.\rوأما على الثاني فإما أن يكون فيها التصريح بالإمام الأعظم أو بغيره؛ فلو كان الأول لشاع وذاع لا سيما بين المحدثين وخصوصا بين من اعتنى بكتب الإمام أبي عبد الله البخاري، ولم نجد أحدا منهم نسب عقيدة الخلق إلى الإمام، هذا ابن حجر حافظ‍ عصره وحافظ‍ كتب البخاري مادح للإمام معترف بفضله، وهذا الذهبي الحافظ‍ الناقد البالغ في تنقيده حتى قالوا: هو مجاز في توهينه وتسخيفه وتجريحه وتضعيفه يزكي الإمام في ميزانه وتذكرته فيبلغها على أقصى مدارجها - وقد ذكرناه.\rوقال في كتابه (العرش والعلو) (1) قال أبو جعفر أحمد بن سلامة الطحاوي في العقيدة التي له، ذكر في بيان السنة والجماعة على مذهب فقهاء الملة أبي حنيفة وأبي يوسف ومحمد بن الحسن رحمهم الله تعالى: أن القرآن كلام الله منه بدأ بلا كيفية قولا وأنزله على نبيه صلّى الله عليه وآله وسلّمو اله وسلم وحيا، وصدقه المؤمنون على ذلك حقّا وأيقنوا أنه كلام الله بالحقيقة ليس بمخلوق، فمن سمعه فزعم أنه كلام البشر فقد كفر - إلى آخر ما قال: ذكره الذهبي احتجاجا على مطلبه هذا.\r__________\r(1) العلو للعلي الغفار (ص 215 - 216)."], [298, "والإمام الطحاوي هو الحافظ‍ الجليل والفقيه النبيل السائر ذكره في الآفاق والأقطار لم يخلف مثله، شهد به الحفاظ‍ الأيقاظ‍ والنقدة ذوو الاعتبار؛ فقوله هذا يبرئ الإمام بغاية التبرئة وينقض الرواية التي ذكرها البخاري في (خلق الأفعال) بتقدير أن يكون فيها التصريح بالإمام، ويؤيده ذكر الذهبي له في كتابه المذكور في معرض الاحتجاج، ويؤيده أيضا قوله في الإمام وصاحبيه أنهم فقهاء الملة؛ أفلم يحصل لهذا الخبير البصير العلم على تلك الرواية المذكورة في (خلق الأفعال) مع أنها كانت موجودة فيهم مروية لهم، وهذا الحافظ‍ الدولابي أبو بشر محمد بن أحمد بن حماد الراوي عن البخاري كتابه (الضعفاء) قاله ابن حجر في مقدمة شرح البخاري (1)، وقد ذكر الإمام أبا حنيفة رضي الله عنه في كتاب (الكنى) وروى عنه فتياه في مسألة، وما ذكر شيئا من الجرح فيه.\rوذكر أيضا حماد بن أبي سليمان أبو إسماعيل، وقال: إنه أستاذ أبي حنيفة الفقيه، وفي رواية الإبانة: أن حمادا هذا هو القائل للثوري: بلغ أبا حنيفة إلخ، وفي الرواية الواقعة في خلق الأفعال: أبلغ أبا فلان؛ فلو كانت الرواية المذكورة في خلق الأفعال مصرحا فيها باسم الإمام - كما هو في الإبانة - أو لم تكن هكذا ولكن كان الإمام هو المرجح لكونه مرادا من المبهم عندهم لذكرها في ترجمة حماد بن أبي سليمان؛ فإن السكوت عن موجبات القدح ليس من شأنهم لا سيما في تصانيفهم التي صنفوها في الرجال.\rوهذا الخطيب المتعصب العنيد أبو بكر أحمد بن علي بن ثابت صاحب (تاريخ بغداد) طعان في الإمام عياب له، قد هذى بمثالب الإمام ومعايبه في تاريخه (2)،\r__________\r(1) هدي الساري (ص 493).\r(2) تاريخ بغداد (370/ 13 - 451)."], [299, "وردها الأئمة بأبلغ الوجوه منهم: الحافظ‍ ابن يوسف سبط‍ ابن الجوزي في (كتاب الانتصار) لإمام أئمة الأمصار وحافظ‍ خوارزم في (مسند الإمام الأعظم) فإنه أجاب عنها أولا بالإجمال ثم أتى بمطاعنه واحدا واحدا، وأجاب عن كلها تفصيلا، وقد نقل أكثرها في رسالة (بعض الناس في دفع الوسواس) السابق ذكره؛ فلله درهم حيث أبطلوا المطاعن وضربوا بها وجه الطاعن ذي الضغائن، وأكثر مطاعنه في الإمام ومعايبه له إنما هو في الفروعات الفقهية.\rوملخصها: أنه يقدم قياسه على الأحاديث، وبعضها في أمور أخرى سواها وليس في جملتها طعن على الإمام بأنه كان يقول بخلق القرآن؛ فلو كانت الرواية المذكورة في خلق الأفعال صحيحة ثابتة واضحة مشروحة غير مبهمة، وهكذا الروايات الواقعة في الإبانة لو كانت صحيحة ثابتة لجعلها الخطيب الحسود من أعظم مطاعن الإمام المحسود، وإذ لم توجد في مطاعنه شمة من نسبة هذه العقيدة إلى الإمام دل دلالة واضحة على بطلان هذه الروايات؛ لأن العادة جارية على أن الطاعن الحسود والعائب العنود الواقف بمسالك الطعن والماهر بطرائقه لا يزال يتجسس المناهج والمداخل لطعنه تجسسا بليغا؛ فإذا وجد طريقا للطعن سلكها.\rوالرواية التي وجدناها في كتاب خلق الأفعال لو كانت صريحة غير مبهمة لا كما هي عندنا أو كانت مبهمة ولكن الإمام يكون المراد المرجح من المبهم لدلائل أخرى لكانت مسلكا واضحا للطاعنين، وما ارتضى صنيع الخطيب هذا ووقيعته في الإمام القاضي شمس الدين ابن خلكان الشافعي فقال في تاريخه (وفيات الأعيان) في ترجمة الإمام أبي حنيفة النعمان: إن مناقبه وفضائله كثيرة، وقد ذكر الخطيب في تاريخه منها شيئا كثيرا ثم أعقب ذلك بذكر ما كان الأليق تركه والإضراب عنه، فمثل هذا"], [300, "الإمام لا يشكّ في دينه ولا في ورعه وتحفظه (1) - انتهى موضع الضرورة.\rثم إني وقفت على (طبقات الشافعية الكبرى) للعلامة تاج الدين عبد الوهاب بن السبكي الشافعي فرأيته ذكر فيها للإمام أبي الحسن الأشعري ترجمة طويلة، وأتى فيها بما يقطع عرق الريب ويبين الأمر بواضح البيان بحيث لا يحتاج منه الإنسان إلى الآخر من البيان؛ فإنه أوضح فيها أن معتقد الأشعري في أصول الدين هو معتقد إمامنا الأعظم أبي حنيفة النعمان، وأن ما خالف فيها الأشعري من الحنفية لا يقتضي تبديع أحدهما فضلا عن التكفير، وأن الأشعري لا يبدع الإمام ولا يتفوه بتنقيصه ولا يخالفه في الأصول، وأن الحنفية أكثرهم أشعريون إلا من لحق منهم بالمعتزلة.\rونحن نذكر من هذا الكتاب ما يتعلق بمبحثنا ومطلبنا على فوائد بلفظ‍: قلت: فنقول: قال ابن السبكي: ولقد قلت مرة للشيخ الإمام رحمه الله: أنا أعجب من الحافظ‍ ابن عساكر في عدة طوائف من أتباع الشيخ ولم يذكر إلا نزرا يسيرا وعددا قليلا، ولو وفى الاستيعاب حقه لاستوعب غالب علماء المذاهب الأربعة فإنهم برأي أبي الحسن يدينون الله تعالى، فقال: إنما ذكر من اشتهر بالمناضلة عن أبي الحسن، وإلا فالأمر على ما ذكرت من أن غالب علماء المذاهب معه، وقد ذكر شيخ الإسلام عز الدين بن عبد السلام أن عقيدته اجتمع عليها الشافعية والمالكية والحنفية وفضلاء الحنابلة، ووافق على ذلك من أهل عصره شيخ المالكية في زمانه أبو عمرو بن الحاجب وشيخ الحنفية جمال الدين الحصيري.\rقلت: وسنعقد لهذا الفصل فصلا فيما بعد، وذكر قاضي القضاة الدامغاني الحنفي وقاضي القضاة أبو بكر القاصحي الحنفي من الطبقة الرابعة وقاضي\r__________\r(1) وفيات الأعيان (413/ 5)."], [301, "القضاة شمس الدين السروجي الحنفي والقاضي شمس الدين الحريري الحنفي من الطبقة السابعة في الآخذين عن الأشعري والمتبعين له.\rوقال في بيان طريقة الشيخ أبي الحسن الأشعري: هي التي عليها المعتبرون من علماء الإسلام المتميزون من المذاهب الأربعة في معرفة الحلال والحرام، والقائمون بنصرة دين سيدنا محمد عليه أفضل الصلاة والسلام، قد قدمنا في تضاعيف الكلام ما يدل على ذلك، وحكينا لك مقالة الشيخ ابن عبد السلام ومن سبقه على مثلها وتلاه على قولها؛ حيث ذكروا أن الشافعية والمالكية والحنفية وفضلاء الحنابلة أشعريون، هذه عبارة ابن عبد السلام شيخ الشافعية وابن الحاجب شيخ المالكية والحصيري شيخ الحنفية.\rومن كلام ابن عساكر حافظ‍ هذه الأمة الثقة الثبت: هل من الفقهاء الحنفية والمالكية والشافعية إلا موافق للأشعري ومنتسب إليه وراض بجهد سعيه في دين الله، ومثن بكثرة العلم عليه غير شرذمة قليلة تظهر التشبيه وتعادي كل موحد يعتقد التنزيه؟ قلت: كمحمد بن موصلي الأصفهاني الشافعي المتقدم ذكره صاحب كتاب (سيف السنة الرفيعة) أو يضاهي قول المعتزلة في ذمه ويباهي لكم بإظهار جهلها بقدرة سعة علمه.\rقلت: أيتصور من الحنفية أن ينتسبوا إلى الأشعري ويرضوا عنه ويثنوا عليه مع ذكره القدح العظيم الموجب للكفر للإمام أبي حنيفة في (كتاب الإبانة) الذي هو آخر كتبه على ما ذكره محمد بن موصلي في كتاب (سيف السنة) ومع تثبته عليه وعدم رجوعه عنه حيث ذكره في آخر كتبه، وإذا انتسبوا إليه ورضوا عنه وأثنوا عليه علم أن الأشعري ما ذكر هذه الروايات في الإبانة ولا في كتاب آخر من كتبه، وأنه ليس بمنقص للإمام ولا بذامّ له بوجه من الوجوه.\rثم ذكر ابن السبكي استفتاءات وأسئلة وقعت في الأشعري، منها استفتاء"], [302, "وقع ببغداد، وهذه صورته:\rما قول السادة الأئمة الجلة في قوم اجتمعوا على لعن فرقة الأشعري وتكفيرهم ما الذي يجب عليهم؟\rفأجاب قاضي القضاة أبو عبد الله الدامغاني الحنفي: قد ابتدع وارتكب ما لا يجوز، وعلى الناظر في الأمور - أعز الله أنصاره - الإنكار عليه وتأديبه بما يرتدع به هو وأمثاله عن ارتكاب مثله - كتبه محمد بن علي الدامغاني.\rقلت: وفي هذا دلالة ظاهرة على أن الأشعري ما ثبت منه شيء من القدح في الإمام والطعن فيه فضلا عن نسبة هذه العقيدة القبيحة الموجبة للتكفير إليه؛ لأنه إذا ثبت من الأشعري الطعن الموجب للتكفير في الإمام الأعظم لرماه الحنفية من كل جانب وشنعوا عليه غاية التشنيع فضلا عن أن ينصروه ويحكموا على اللاعنين لفرقة الأشعري أنهم ابتدعوا، وارتكبوا ما لا يجوز ارتكابه، فيجب تأديبهم والإنكار عليهم حتى لا يعودوا إلى ارتكاب مثله.\rثم نقل استفتاء آخر وقع ببغداد فيه أيضا كتب تحته جماعة من الشافعية والحنفية والمالكية والحنابلة منتصرين له رادين على من أنكره.\rثم قال ابن السبكي: ذكر كلام أبي العباس قاضي العسكر الحنفي: كان أبو العباس هذا رجلا من أئمة أصحاب الحنفية ومن المتقدمين في علم الكلام، وكان يعرف بقاضي العسكر.\rوقد حكى الحافظ‍ أبو القاسم في كتاب (التبيين) جملة من كلامه فمنه قوله:\rوقد وجدت لأبي الحسن الأشعري كتبا كثيرة في هذا الفن - يعني أصول الدين - وهي قريب من مائتي كتاب، و (الموجز الكبير) يأتي على عامة ما في كتبه، وقد صنف الأشعري كتابا كبيرا لتصحيح مذهب المعتزلة فإنه كان يعتقد مذهبهم، ثم بين الله له ضلالتهم فتاب عما اعتقده من مذهبهم، وصنف كتابا ناقضا لما"], [303, "صنف للمعتزلة، وقد أخذ عامة أصحاب الشافعي بما استقر عليه مذهب أبي الحسن الأشعري، وصنف أصحاب الشافعي كتبا كثيرة على وفق ما ذهب إليه الأشعري إلا أن بعض أصحابنا من أهل السنة والجماعة خطئوا أبا الحسن في بعض المسائل مثل قوله: التكوين والمكون واحد، ونحوها - على ما نبين في خلال المسائل إن شاء الله تعالى - فمن وقف على المسائل التي أخطأ فيها أبو الحسن وعرف خطأه فلا بأس له بالنظر في كتبه؛ فقد أمسك كتبه كثير من أصحابنا من أهل السنة والجماعة ونظروا فيها (1) - انتهى.\rقلت: وهكذا قال البزدوي في عقائده: هؤلاء علماؤنا رحمهم الله تعالى المختبرون بمسلك الأشعري والمطلعون على كتبه؛ فإن كانت الروايات الواقعة في (الإبانة) صحيحة ذكرها الأشعري يبعد من مثل هؤلاء المختبرين المتبحرين أن لا يطلعوا عليها، وإن اطلعوا فيستحيل منهم أن يذكروا تخطئة أصحابنا للأشعري في مسائل يسيرة غير موجبة للتشنيع ويتركوا ما يوجب التخطئة العظيمة بل التشنيع القبيح للأشعري، وأن يجوزوا النظر في كتبه مع كون الموجب القوي للنفرة عنه خصوصا للحنفيين، وحيث لم يشنعوا عليه وأجازوا النظر في كتبه وأمسكوها دل على أن هذه الروايات مفتراة مختلقة ما ذكرها الأشعري في (الإبانة) ثم أخذ في ذكر المسائل الخلافية فقال: ذكر البحث عن تحقيق ذلك: سمعت الشيخ الإمام رحمه الله يقول: ما تضمنته عقيدة الطحاوي هو ما يعتقده الأشعري لا يخالف إلا في ثلاث مسائل.\rقلت: أنا أعلم أن المالكية كلهم أشاعرة لا أستثني واحدا، والشافعية غالبهم أشاعرة لا أستثني إلا من لحق منهم بتجسيم أو اعتزال ممن لا يعبأ الله به.\r__________\r(1) تبيين كذب المفتري (ص 140)."], [304, "والحنفية أكثرهم أشاعرة - أعني يعتقدون عقيدة الأشعري - لا يخرج منهم إلا من لحق منهم بالمعتزلة.\rوالحنابلة أكثر فضلاء متقدميهم أشاعرة لم يخرج منهم إلا من لحق بأهل التجسيم، وهم في هذه الفرقة من الحنابلة أكثر من غيرهم، وقد تأملت عقيدة الطحاوي فوجدت الأمر على ما قال الشيخ الإمام، وعقيدة الطحاوي زعم أنها التي عليها أبو حنيفة وأبو يوسف ومحمد ولقد أجاد فيها، ثم تصفحت كتب الحنفية فوجدت جميع المسائل التي بيننا وبين الحنفية خلاف فيها ثلاثة عشر مسألة منها: معنوي ست مسائل، والباقي لفظي، وتلك الست المعنوية لا يقتضي مخالفتهم لنا ولا مخالفتنا لهم فيها تكفيرا ولا تبديعا، صرح بذلك الأستاذ أبو منصور البغدادي وغيره من أئمتنا وأئمتهم، وهو غني عن التصريح لظهوره.\rومن كلام الحافظ‍: الأصحاب مع اختلافهم في بعض المسائل كلهم أجمعوا على منع تكفير بعضهم بعضا مجتمعون بخلاف من عداهم من سائر الطوائف وجميع الفرق إلى أن قال: وما مثل هذه المسائل إلا مثل مسائل كثيرة اختلفت الأشاعرة فيها، وكلهم عن حمى أبي الحسن يناضلون وبسيفه يقاتلون، أفتراهم يبدع بعضهم بعضا؟ ثم هذه المسائل الثلاثة عشر لم يثبت جميعها عن الشيخ ولا عن أبي حنيفة رضي الله تعالى عنهما كما حكي لك ولكن الكلام بتقدير الصحة.\rولي قصيدة نونية جمعت فيها هذه المسائل وضممت إليها مسائل اختلفت الأشاعرة فيها مع تصويب بعضهم بعضا في أصل العقيدة، ودعواهم أنهم أجمعون على السنة، وقد ولع كثير من الناس بحفظ‍ هذه القصيدة لا سيما الحنفية.\rقلت: في ولوع الحنفية بحفظها دليل ظاهر على أن علماءنا الحنفية لم يجدوا من الأشعري شيئا يعود منه الطعن على الإمام، ثم قال: وأنا أذكر لك قصيدتي في هذا المكان لتستفيد منها مسائل الخلاف وما اشتملت عليه، فأولها أقول:"], [305, "الورد خدّك صيغ من إنسان ... أم في الخدود شقائق النّعمان\rوالسيف لحظك سلّ من أجفانه ... فسطا كمثل مهنّد وسنان\rتالله ما خلقت لحاظك باطلا ... وسدى تعالى الله عن بطلان\rإلى آخرها، ومنها:\rكذب ابن فاعلة يقول بجهله ... الله جسم ليس كالجسمان\rلو كان جسما كان كالأجسام يا ... مجنون فاصغ وعد عن البهتان\rواتبع صراط‍ المصطفى في كل ما ... يأتي وخلّ وساوس الشيطان\rواعلم بأنّ الحق ما كانت علي‍ ... ـه صحابة المبعوث من عدنان\rمن أكمل الدين القويم وبيّن ال‍ ... ـحجج التي يهدى بها الثقلان\rقد نزهوا الرحمن عن شبه وقد ... دانوا بما قد جاء في الفرقان\rومضوا على خير وما عقدوا مجا ... لس في صفات الخالق الدّيان\rكلا ولا ابتدعوا ولا قالوا البنا ... ء مشابه في شكله للباني\rوأتت على أعقابهم علماؤنا ... غرسوا ثمارا يجتنيها الجاني\rكالشافعي ومالك وكأحمد ... وأبي حنيفة والرضى سفيان\rوكمثل إسحاق وداود ومن يقفو طرائقهم من الأعيان\rوأتى أبو الحسن الإمام الأشعر ... ـي مبينا للحقّ أيّ بيان\rومناضلا عما عليه أولئك ال‍ ... ـأسلاف بالتحرير والإتقان\rقلت: فيه تصريح بأنه كان الإمام على ما كان عليه الصحابة فلزم منه أنه ما كان قائلا بالخلق ثم قال بعده:"], [306, "ما أن يخالف مالكا والشافعيّ ... وأحمد بن محمد الشيباني\rلكن يوافق قولهم ويزيده ... حسنا بتحقيق وفضل بيان\rيقفو طرائقهم ويتبع حارثا ... أعني محاسب نفسه بوزان\rفلقد تلقّى حسن منهجه عن ال‍ ... ـأشياخ أهل الدين والعرفان\rفلذاك تلقاه لأهل الله ين‍ ... ـصر قولهم بمهنّد وسنان\rمثل ابن أدهم والفضيل وهكذا ... معروف المعروف في الإخوان\rوهكذا عد الشيوخ إلى أن قال:\rوكذاك أصحاب الطريقة بعده ... ضبطوا عقائده بكلّ عنان\rوتتلمذ الشبليّ بين يديه واب‍ ... ـن خفيف والثقفيّ والكتاني\rوخلائق كثروا فلا أحصيهم ... وربوا على الياقوت والمرجان\rالكلّ معتقدون أنّ إلهنا ... متوحد فرد قديم دان\rإلى أن قال بعد ما ذكر العقائد:\rهذا اعتقاد مشايخ الإسلام وه‍ ... ـوالدين فلتسمع له الأذنان\rوالأشعريّ عليه ينصره ولا ... يألو جزاه الله بالإحسان\rوكذاك حالته مع النعمان ... لم ينقض عليه عقائد الإيمان\rيا صاح إن عقيدة النعمان ... والأشعري حقيقة الإتقان\rفكلاهما والله صاحب سنة ... بهدى نبيّ الله مقتديان\rلا ذا يبدّع ذا ولا هذا وإن ... تحسب سواه وهمت في الحسبان\rمن قال إنّ أبا حنيفة مبدع ... رأيا فذلك قائل الهذيان"], [307, "أو ظن أن الأشعريّ مبدّع ... فلقد أساء وباء بالخسران\rكلّ إمام مقتدى ذو سنة ... كالسيف مسلولا على الشيطان\rوالخلف بينهما قليل أمره ... سهل بلا بدع ولا كفران\rفيما يقلّ من المسائل عدّة ... ويهون عند تطاعن الأقران\rقلت: هذا غاية البيان في تزكية الإمام أبي حنيفة النعمان ونهاية المدح له والذب عنه، وهو من الذين لا يقلدونه في الفروع، ولو كان الإمام قائلا بخلق القرآن معتقدا به ما كان الخلف بينه وبين الأشعري قليلا سهلا غير موجب للبدعة والكفر، وما أصدق قول هذا المتخبر المتبحر:\rالخلف بينهما قليل أمره ... سهل بلا بدع ولا كفران\rإلى آخر ما قال ثم قال:\rوكذاك أهل الرأي مع أهل الحدي‍ ... ـث في الاعتقاد الحق متفقان\rما أن يكفّر بعضهم بعضا ولا ... أزرى عليه وسامه بهوان\rإلا الذين تمعزلوا منهم فهم ... فئة تنحّت عنهم الفئتان\rهذا الصواب فلا تظنّن غيره ... واعقد عليه بخنصر وبنان\rورأيت ممن قاله حبرا له ... نبأ عظيم سار في البلدان\rأعني أبا منصور الأستاذ عب‍ ... ـد القاهر المشهور في الأكوان\rهذا صراط‍ الله فاتبعه تجد ... في القلب برد حلاوة الإيمان\rوتراه يوم الحشر أبيض واضحا ... يهدي إليك رسائل الغفران\rوعليه كان السابقون عليهم ... حلل الثناء وملبس الرضوان"], [308, "والشافعيّ ومالك وأبو حني‍ ... ـفة وابن حنبل الكبير الشان\rدرجوا عليه وخلّفونا إثرهم ... إن نتّبعهم نجتمع بجنان\rأو نبتدع فلسوف نصلى النّار مذ ... مومين مأخوذين بالعصيان\rإلى آخر ما قال.\rقلت: فلقد ثبت من قول ابن السبكي الشافعي أن الإمام الأعظم كان على صراط‍ الله تعالى، ومن كان على صراط‍ الله تعالى لا يكون قائلا بخلق القرآن قط‍، ثم ينبغي أن يعلم أن هذه الدلائل كلها إنما هي لمزيد التأكيد وزيادة التوضيح، وإلا فعدم كون الإمام قائلا بخلق القرآن ومعتقدا به وكونه معتقدا بعدم خلقه ومكفرا لقائل الخلق يثبت من كلامه رضي الله عنه ثبوتا لا يستريب معه من له أدنى مسكة من العقل، ويتضح وضوحا لا يشك بعده من له قليل من الفهم، وهو يكفي لإثبات المرام ويغني عن دلائل أخرى للذب عن الإمام، ولكن الكلام يشد بعضه بعضا فيصير بنيانا مرصوصا، هذا الفقه الأكبر من كلام إمامنا الأعظم شرحه جماعة من الحنفية عمدتهم علي القاري العلامة، وهذا كتابه الوصية صرح فيهما بعدم خلق القرآن وكرره تأكيدا واهتماما؛ فقال رضي الله تعالى عنه: والقرآن في المصاحف مكتوب وفي القلوب محفوظ‍ وعلى الألسن مقروء، وعلى النبي صلّى الله عليه وسلّم منزل، لفظنا بالقرآن مخلوق وكتابتنا له وقراءتنا له مخلوقة، والقرآن غير مخلوق.\rقال العلامة القاري في شرحه: قد قال الإمام الأعظم في كتابه الوصية: نقر بأن كلام الله ووحيه وتنزيله وصفته لا هو ولا غيره بل هو صفته على التحقيق مكتوب في المصاحف مقروء بالألسن محفوظ‍ في الصدور غير حالّ فيها،"], [309, "والحروف والحركة والكاغذ والكتابة كلها مخلوقة؛ لأنها أفعال العباد، وكلام الله سبحانه وتعالى غير مخلوق لأن الكتابة والحروف والكلمات والآيات كلها آلة القرآن لحاجة العباد إليها، وكلام الله تعالى قائم بذاته ومعناه مفهوم بهذه الأشياء؛ فمن قال بأن كلام الله تعالى مخلوق فهو كافر بالله العظيم، ثم قال العلامة القاري: وقال فخر الإسلام: قد صح عن أبي يوسف رحمه الله تعالى أنه قال: ناظرت أبا حنيفة رحمه الله تعالى في مسألة خلق القرآن فاتفق رأيي ورأيه على أن من قال بخلق القرآن فهو كافر، وصح هذا القول أيضا عن محمد رحمه الله تعالى، وقال رضي الله تعالى عنه في الفقه الأكبر أيضا: وما ذكره الله تعالى في القرآن عن موسى وغيره من الأنبياء عليهم السّلام فإن ذلك كله كلام الله تعالى إخبارا عنهم، وكلام الله تعالى غير مخلوق، وكلام موسى وغيره من المخلوقين مخلوق، وقال أيضا بفاصلة يسيرة بعده: ويتكلم لا ككلامنا ونحن نتكلم بالآلات والحروف، والله يتكلم بلا آلة وحروف، والحروف مخلوقة، وكلام الله تعالى غير مخلوق، قال العلامة القاري تحته: بل قديم بالذات.\rقال الطحاوي: فمن سمعه فزعم أنه كلام البشر فقد كفر، وقد ذمه الله وأوعده بسقر حيث قال الله تعالى: {سَأُصْلِيهِ سَقَرَ} (1) فلما أوعده الله بسقر لمن قال: {إِنْ هذا إِلاّ قَوْلُ الْبَشَرِ (25)} (2) علمنا وأيقنا أنه قول خالق البشر ولا يشبه قول البشر - انتهى.\rوقال شارحه: قد افترق الناس في مسألة الكلام على تسعة أقوال، ثم نقل المذاهب التسعة عن شارح عقيدة الطحاوي، وقال بعد ما نقل المذهب التاسع -\r__________\r(1) المدثر: 26.\r(2) المدثر: 25."], [310, "وهو أنه تعالى لم يزل متكلما إذا شاء ومتى شاء وكيف شاء: وهو يتكلم بصوت يسمع، وإن نوع الكلام قديم وإن لم يكن الصوت المعين قديما - انتهى؛ إن هذا يؤيد ما قدمناه انتهى، يشير إلى ما قال قبل هذا بأن كلام الطحاوي يرد قول من قال: إنه معنى واحد لا يتصور سماعه منه، وأن المسموع المنزل المقروء المكتوب ليس بكلام الله وإنما هو عبارة.\rثم قال العلامة القاري: وهذا - يعني المذهب التاسع - المأثور عن أئمة الحديث والسنة، ولعل تكرار هذه المسألة في تأليف الإمام لكمال الاهتمام في مقام المرام - انتهى، وحقق رحمه الله تعالى هذا البحث وفصله وختمه بقوله: وبالجملة فأهل السنة كلهم من أهل المذاهب الأربعة وغيرهم من السلف والخلف - رحمهم الله - متفقون على أن القرآن غير مخلوق، ولكن بعد ذلك تنازع المتأخرون في أن كلام الله هل هو معنى واحد قائم بالذات أو أنه حروف وأصوات، تكلم الله بعد أن لم يكن متكلما أو أنه لم يزل متكلما إذا شاء ومتى شاء وكيف شاء، وأن نوع الكلام قديم، وهو مختار الإمام والطحاوي، والنزاع بين أهل القبلة إنما هو في كونه مخلوقا خلقه الله أو هو كلامه الذي تكلم به وقائم بذاته - انتهى كلام القاري عليه الرحمة من الله الباري.\rوقد صرح في (سيف السنة الرفيعة) أيضا أن المذهب التاسع الذي نقلناه من شرح الفقه الأكبر للعلامة القاري هو المأثور عن أئمة السنة والحديث، ثم إطباق الحنفية كلهم على عدم خلق القرآن، وعلى تقبيح قائل الخلق - كما يظهر من كتبهم الكلامية - ينبغي أن يضم إلى كلام الإمام في هذه المسألة؛ فإنه يفيد قوة فوق قوة ويزيد علما إلى علم؛ لأنهم يدينون الله تعالى في الأصول والفروع بأقواله المستمدة من كتاب الله تعالى وسنة نبيه صلّى الله عليه وآله وسلّمو اله وسلم ويقاتلون بسيفه.\rهذا ومما جرأ الواضعين والمفترين على وضع تلك الروايات ونسبتها إلى"], [311, "الأشعري هو الفتنة التي وقعت بمدينة نيسابور قاعدة بلاد خراسان إذ ذاك في العلم وصارت سببا لخروج إمام الحرمين والحافظ‍ البيهقي والأستاذ أبي القاسم القشيري من نيسابور وآلت إلى أن ضيقت الدائرة على من رام مذهب الأشعري بسوء كما قال العلامة تاج الدين ابن السبكي في طبقاته الكبرى في ترجمة الأشعري: كان سلطان الوقت إذ ذاك السلطان طغرل بك السلجوقي وكان رجلا حنفيّا سنيّا خيرا عادلا محبّا لأهل العلم من كبار الملوك وعظمائهم، وهو أول ملوك السلجوقية، وكان يصوم الإثنين والخميس، وهو الذي أرسل الشريف ناصر الدين بن (1) إسماعيل رسولا إلى ملكة الروم فاستأذنها بالصلاة في جامع القسطنطينية جماعة يوم الجمعة، فصلى وخطب للإمام القائم بأمر الله، وتمهدت البلاد لطغرل بك، وسمت نفسه بحيث وصل أمره إلى أن سير إلى الخليفة القائم يخطب ابنته، وذلك في ذلك الزمان مقام مهول، فشق ذلك على الخليفة واستعفى ثم لم يجد بدّا من ذلك لعظمة طغرل بك، وكونه ملكا قاهرا لا يطاق فزوجه بها.\rوقدم بغداد في سنة خمس وخمسين وأربعمائة وأرسل يطلبها، وحمل مائة ألف دينار برسم نقل جهازها فعمل العرس في صفر بدار المملكة، وأجلست على سرير ملبس بالذهب، ودخل السلطان وقبل الأرض بين يديها ولم يكشف البرقع عن وجهها إذ ذاك، وقدم لها تحفا وخدما، وانصرف مسرورا.\rوكان لهذا السلطان وزير سوء وهو الوزير أبو نصر منصور بن محمد الكندري كان معتزليّا رافضيّا خبيث العقيدة لم يبلغنا أن أحدا جمع له من خبث العقيدة ما اجتمع له؛ فإنه على ما ذكر كان يقول بخلق الأفعال وغيره من قبائح\r__________\r(1) في الطبقات: ناصر بن إسماعيل."], [312, "القدرية، وسب الشيخين وسائر الصحابة وغير ذلك من قبائح أشرار الروافض وتشبيه الله بخلقه، وغير ذلك من قبائح الكرامية، وكان له مع ذلك تعصب عظيم، وانضم إلى كل هذا أن رئيس البلد أبا سهل الموفق (1) - الذي سنذكر إن شاء الله ترجمته في الطبقة الرابعة - كان ممدوحا جوادا ذا أموال جزيلة وصدقات دائرة وهبات هائلة ربما وهب ألف دينار لسائل، وكان مرموقا بالوزارة، وداره مجتمع العلماء وملتقى الأئمة من الفريقين الحنفية والشافعية في داره يتناظرون وعلى سماطه يلتقون، وكان عارفا بأصول الدين على مذهب الأشعري قائما في ذلك مناضلا في الذب عنه، فعظم ذلك على الكندري لما في نفسه من المذهب، ومن بغض ابن الموفق بخصومة (2) و خشية منه أن يثب على الوزارة، فحسن للسلطان لعن المبتدعة على المنابر.\rفعند ذلك أمر السلطان بلعن المبتدعة على المنابر فاتخذ الكندري ذلك ذريعة إلى ذكر الأشعرية، وصار يقصدهم بالإهانة والأذى والمنع عن الوعظ‍ والتدريس وعزلهم عن خطابة الجامع، واستعان بطائفة من المعتزلة الذين زعموا أنهم يقلدون مذهب أبي حنيفة أشربوا في قلوبهم فضائح القدرية، واتخذوا التمذهب بالمذهب الحنفي سياجا عليهم، فحببوا (3) إلى السلطان الإزراء بمذهب الشافعي عموما والأشعرية خصوصا.\rوهي هذه الفتنة التي طار شررها فملأ الآفاق وطال ضررها فشمل خراسان والشام والحجاز إلى آخر ما قال، ثم ذكر كتاب البيهقي إلى عميد الملك وفيه: فألقوا إلى سمعه - أي سمع طغرل بك المذكور - ما فيه مساءة أهل السنة والجماعة\r__________\r(1) الطبقات: ابن الموفق.\r(2) الطبقات: بخصوصه.\r(3) الطبقات: فحسنوا."], [313, "كافة ومصيبتهم عامة من الحنفية والمالكية والشافعية الذين لا يذهبون في التعطيل مذاهب المعتزلة، ولا يسلكون في التشبيه طرق المجسمة إلخ، ثم قال: وكأنه خفي عليه - أدام الله عزه - حال شيخنا أبي الحسن الأشعري رحمه الله وما يرجع إليه من شرف الأصل وكبر المحل في العلم والفضل وكثرة الأصحاب من الحنفية والمالكية والشافعية الذين رغبوا في علم الأصول وأحبوا معرفة دلائل المعقول.\rثم قال: إلى أن بلغت النوبة إلى شيخنا أبي الحسن الأشعري فلم يحدث في دين الله حدثا ولم يأت فيه ببدعة بل أخذ أقاويل الصحابة والتابعين ومن بعدهم من الأئمة في أصول الدين فنصرها بزيادة شرح وتبيين، وأن ما قالوا وجاء به الشرع في الأصول صحيح في العقول بخلاف ما زعم أهل الأهواء من أن بعضه لا يستقيم في الآراء، فكان في بيانه وثبوته ما لم يدل عليه أهل السنة والجماعة، ونصرة أقاويل من مضى من الأئمة كأبي حنيفة وسفيان الثوري من الكوفة، والأوزاعي وغيره من أهل الشام، ومالك والشافعي من أهل الحرمين ومن نحا نحوهما من أهل الحجاز وغيرهما من سائر البلاد - إلخ.\rثم نقل رسالة القشيري المسماة ب‍ (شكاية أهل السنة بحكاية ما نالهم من المحنة) أي في هذه الفتنة كتبها القشيري إلى البلاد، ووافق القشيري على هذه الرسالة جم من العلماء وكتبوا عليها، منهم القاضي الدامغاني من الحنفية، وفي آخر هذه الرسالة: ولما ظهر ابتداء هذه الفتنة بنيسابور، وانتشر في الآفاق خبره وعظم على قلوب كافة المسلمين من أهل السنة والجماعة أثره لم يبعد أن يخامر قلوب أهل السنة توهم في بعض هذه المسائل لعل أبا الحسن علي بن إسماعيل الأشعري رحمة الله عليه قال ببعض هذه المقالات في بعض كتبه، ولقد قيل: (من يسمع يخل) أثبتنا هذه الفصول في شرح هذه الحالة، وأوضحنا صورة الأمر بذكر هذه الجملة ليضرب كل أهل السنة إذا وقف عليها بسهمه إلى آخر ما قال:"], [314, "اعلم أن الروافض لا زال قصدهم تفريق جمع أهل السنة وكسر شوكتهم وإزالة دولتهم، ورثوه من إمامهم اليهودي المنافق المتسلم المؤسس المؤصل لمذهبهم ابن سبأ المتعلم من أبي الشياطين المعلم الذي أراد التفريق بين المسلمين بكيده ووسوسته لما رأى عزتهم وشوكتهم، ورأى ذلة اليهود ومهانتهم حتى صار رجالهم عبيدا ونساؤهم إما تخدمهم؛ فزخرف هذا المذهب وروّجه على الجهلة من العجم والعرب.\rولما كان الله حافظا لدينه وناصرا لأهله ما أعقب كيدهم إلا الذلة والخيبة لهم، وإلا الهوان والكرب وما زادوا إلا التعب والنصب، ضرب الله عليهم الذلة والمسكنة وباءوا بغضب؛ فالكندري السوء أقام هذه الفتنة لدسيسته الخبيثة الرافضية؛ فأوسعت للفئة الطاغية معتزلة كانت أو رافضية مجالا للبهتان والفرية؛ فالغالب أنهم افتروا هذه الروايات وألحقوها في الإبانة التي هي آخر كتب الأشعري كي تدوم بينهم الفرقة ولا تزول؛ فإن آخر الكلام يكون عليه اللزام، ولكن الله حفظ‍ دينه وأقام من كل جانب عباده العلماء حتى بذلوا جهدهم وصرفوا وسعهم في الذب عن الأشعري قدوة هذه الأمة - كما سبق ذكره - فتنبه أهل السنة لذلك وأعادوا على الكندري فتنته الوقيحة والمصيبة وأحاطت عليه منها الرزية والبلية.\rوقول القشيري في رسالته السابق ذكرها بأنه لما ظهر ابتداء هذه الفتنة بنيسابور، وانتشر في الآفاق خبره إلى آخر ما قال: وقد ذكرناه تنبيها ونصيحة منه لكافة أهل السنة حتى لا يظنوا بالإمام الأشعري سوءا إذا وجدوا أمرا يوهم السوء في حقه، ويتأملوا إلى شأنه الأرفع أولا، وإلى أصحابه السالكين على مسلكه الشريف من الحنفية والشافعية والمالكية والفضلاء من قدماء الحنابلة ثانيا؛ فإن الأمرين يكفيان لنفي الذمائم عنه وإثبات المدائح له، فيجب علينا أهل"], [315, "السنة الوقوف على هذا التنبيه والنصيحة، واعتقاد أن هذه الروايات مفتراة على الأشعري موضوعة ملحقة في كتابه (الإبانة).\rوحيث أتينا بفضل الله تعالى بما يوضح ظلمة متن هذه الروايات وإبطالها بحيث لا يشك معه العاقل في بطلانها نتكلم الآن فيما يتعلق بسندها، وإن كان فيما ذكرنا غنية من النظر في السند لأن الأصل المقصود هو المتن، والسند ذريعة للوصول إليه، فإذا بطل أصل المقصود بالذات لم يكن للذريعة اعتبار حتى ينظر إليها إثباتا ونفيا، ولكن نتكلم فيه تتميما للكلام وتكميلا للمقام على مجرى عادتهم وممر دأبهم، فنبحث أولا عن سند الروايات الواقعة في (الإبانة) ونقول:\rإن الرواية الأولى في سندها انقطاع؛ فإن هارون مات بعد خمسين ومائتين، وولد الأشعري سنة ستين ومائتين؛ فليس الأشعري الراوي معاصرا لهارون المروي عنه؛ فحذف الراوي الذي روى للأشعري عن هارون، وهذا القسم مردود عند المحدثين لا يقبلونه، وقد يحكم بصحته إذا عرف أنه جاء مسمى من وجه آخر ذكره الحافظ‍ ابن حجر في شرح نخبة الفكر، وما جاء هذه الرواية بوجه آخر سمي فيه المحذوف فتصير الرواية مردودة ساقطة من جهة السند أيضا، وإنما جعل هذا القسم مردودا للجهل بحال المحذوف ذكره الحافظ‍ ابن حجر أيضا، هذا حال مبدأ السند.\rوأما هارون بن إسحاق نفسه فثقة ذكره ابن حبان في كتاب (الثقات) فقال:\rهارون بن إسحاق بن محمد بن مالك بن زيد الهمداني أبو القاسم من أهل الكوفة يروي عن وكيع وعبدة بن سليمان حدثنا عنه عمر بن سعيد بن سنان وغيره، مات بعد الخمسين والمائتين (1) - انتهى.\r__________\r(1) الثقات (241/ 9)."], [316, "وفي (خلاصة تذهيب تهذيب الكمال في أسماء الرجال) إنه عن ابن عيينة والمعتمر وخلق، وعنه البخاري في جزء القراءة له والترمذي في جامعه والنسائي في سننه ووثقه وابن ماجه في سننه: قال مطين: مات سنة ثمان وخمسين ومائتين - انتهى.\rوالعجب أن هارون بن إسحاق مع كونه معروف الرواية عن وكيع يروي عن أبي نعيم هذا، ووكيع يتبع أبا حنيفة رحمه الله تعالى ويفتي بقوله، ويكفر قائل الخلق، قال الذهبي في (تذكرة الحفاظ‍) في ترجمة وكيع: وقال يحيى: ما رأيت أفضل منه، يقوم الليل، ويسرد الصوم، ويفتي بقول أبي حنيفة (1).\rثم قال الذهبي: وروى أبو هشام وغيره عن وكيع قال: من زعم أن القرآن مخلوق فقد كفر (2)؛ أفيتصور من فضل وكيع في الدين وورعه في الشريعة أن يكفر قائل الخلق ثم يتبع قائله ويفتي بقوله؟ لا يتصور من مثل هذا الرجل مثل هذا الأمر الذي يعيد عليه الذم أبدا، وحيث اتبعه وكان يفتي بقوله، وذكر الأئمة هذا الإفتاء والاتباع في مقام المدح له ظهر أن الإمام ما كان قائلا بالخلق، وأنه كان ثابتا محققا عند وكيع، ويبعد أن لا يعلم هارون هذا فإن هارون ثقة ووكيع شيخه المعروف، والرواة لا سيما إذا كانوا ثقات أيقاظا يكون لهم علم بحال شيوخهم قضّا وقضيضا ونقيرا وقطميرا، وخصوصا إذا كانوا يسكنون في بلد واحد؛ فهارون كوفي ووكيع شيخه كوفي، واتباع وكيع لأبي حنيفة بإفتائه بقوله كان ظاهرا مستمرا.\rواللازم من كل ذلك أن يعلم هارون من شيخه وكيع أن الإمام ما كان قائلا بالخلق فكيف يتصور أن لا يذكره، ويروى عن أبي نعيم الذي لا يعرف له سماع\r__________\r(1) تذكرة الحفاظ‍ (307/ 1).\r(2) تذكرة الحفاظ‍ (308/ 1 - 309)."], [317, "منه ما يخالفه لأنه إذا وجد عند الراوي روايتان تناقض إحداهما الأخرى فلا أقل من أن يذكرهما جميعا، وهذا على سبيل التنزل، وإلا فالاقتضاء الظاهر أن يذكر هارون ما علمه من وكيع من أن الإمام ما كان قائلا بالخلق ويترك ما وجد من أبي نعيم بخلافه أو يذكر ما وجده من أبي نعيم ويذكر معه ما علمه من وكيع ناقضا له، وهذا لأن أبا نعيم ثلاثة: عبد الرحمن بن هانئ الكوفي الراوي عن الثوري، وشريك الذي روى عنه الكوفيون مات سنة إحدى أو اثنتي عشرة ومائتين على ما ذكره ابن حبان أو ست عشرة ومائتين على ما قاله الذهبي ذكره ابن حبان في (كتاب الثقات) (1)، وقال: ربما أخطأ لروايته عن الثوري عن أبي الزبير عن جابر عن النبي صلّى الله عليه وسلّم: «من قتل ضفدعا فعليه شاة محرما كان أو حلالا» (2)، والذهبي في (ميزان الاعتدال) (3): فقال عبد الرحمن بن هانئ أبو نعيم النخعي عن سفيان الثوري قال أحمد: ليس بشيء، ورماه يحيى بالكذب، وقال ابن عدي: عامة ما يرويه لا يتابع عليه، ومن مناكيره حديثه عن سفيان عن أبي الزبير، فذكر مثل ما ذكره ابن حبان وحديثا آخر.\rوفي (خلاصة تذهيب تهذيب الكمال): أنه روى عن الحسن بن الحكم النخعي وفطر بن خليفة، وعنه عباس بن عبد العظيم، وأبو حاتم وقال: لا بأس به، وقال ابن حبان في (الثقات): ربما أخطأ، وضعفه أبو داود والنسائي وكذبه ابن معين.\rوضرار بن صرد الطحان الكوفي الراوي عن إبراهيم بن سعد مات سنة تسع وعشرين ومائتين ليس بثقة، فما ذكره ابن حبان في كتاب (الثقات): قال الذهبي\r__________\r(1) الثقات لابن حبان (377/ 8).\r(2) أخرجه ابن عدي في الكامل (315/ 4) في ترجمة عبد الرحمن بن هانئ.\r(3) ميزان الاعتدال (595/ 2)."], [318, "في ميزانه (1): ضرار بن صرد أبو نعيم الطحان عن إبراهيم بن سعد قال أبو عبد الله البخاري وغيره: متروك، وقال يحيى بن معين: كذابان بالكوفة هذا وأبو نعيم النخعي، ثم ساق حديثه ثم قال: يروي عنه مطين وجماعة، قال النسائي: ليس بثقة، وقال أبو حاتم: صدوق لا يحتج به، وقال الدارقطني: ضعيف، وهكذا في (تهذيب تهذيب الكمال) (2) للحافظ‍ ابن حجر فإنه نقل فيه جرحه عن أئمة الحديث بالتفصيل. وفضل بن دكين الكوفي عن الأعمش وزكريا بن أبي زائدة وجعفر بن برقان وأفلح بن حميد وخلق، وعنه البخاري وأحمد وإسحاق ويحيى بن معين وخلق، قال أحمد: ثقة يقظان عارف بالحديث، وقال الفسوي:\rأجمع أصحابنا على أن أبا نعيم كان في غاية الإتقان، قال يعقوب بن شيبة: مات سنة تسع عشرة ومائتين كذا في (خلاصة تذهيب تهذيب الكمال).\rفأبو نعيم كنية هؤلاء الثلاثة؛ فإن كان الراوي لهارون هو الأول فهو متكلم فيه مختلف في شأنه؛ هذا أحمد بن حنبل رئيس المحدثين يقول فيه: ليس بشيء، وهذا يحيى المتيقظ‍ الخبير البصير الثبت الحجة الرحال الجوال القافز من الجانب الشرقي إلى الجانب الغربي يرميه بالكذب، ويسميه: الكذاب، وهذا ابن عدي المحدث الجليل يقول: إن عامة ما يرويه لا يتابع عليه، وابن حبان مع توثيقه يعترف بأنه يخطئ.\rولعمري إن كان أبو نعيم هذا هو الراوي لهذه الرواية فيتأكد جرحه ويظهر كذبه ويتضح نكارة الرواية نكارة فيها فضيحة له وقباحة عليه؛ فإنك لا تجد أحدا تابع عليها بل تجد جملة من الروايات تكذبها.\r__________\r(1) ميزان الاعتدال (327/ 2 - 328).\r(2) تهذيب التهذيب (400/ 4)."], [319, "سر في مشارق الأرض ومغاربها وطف في أقاصي الأرض وأكنافها فانظر هل تجد أحدا يتابعها؟ ألا من شذّ كبّه الله في النار، وأحله دار البوار، وليس بشيء من الاعتبار، وليس له في شذوذه من قرار، يستقر عليه أمره ويدار.\rهذا ومن قواعدهم تقديم الجرح على التعديل لا سيما إذا كان الجرح مفسرا مبينا، وإن كان المعدلون أكثر، وقد وجد هاهنا كل هذا؛ فإن الجرح مفسر مبين لخطائه ونكارة مروياته، والجارحون أكثر فتسقط‍ روايته خصوصا على قول ابن عدي: إن عامة ما يرويه لا يتابع عليه، ومع كل ذلك فما ذكروا صريحا أن لهارون سماعا أو رواية عن أبي نعيم هذا غير ما قاله ابن حبان: إن الكوفيين رووا عن عبد الرحمن بن هانئ عن أبي نعيم؛ فهذا ينشئ الاحتمال بأن هارون لعله سمع من أبي نعيم ولكن لا يفيد القطع، ولا بد من القطع في مثل هذا المقام المهول؛ فجهل اللقاء بينهما، وإن كان الثاني فهو ليس بثقة - كما سبق ذكره - بل قدح فيه الأئمة الذين وقع بهم القدوة في هذا الفن، وتختلف في قدحه عباراتهم فأردأ ما قيل فيه: إنه كذاب، وقد سبقت كلها فلا نعيدها.\rوأيضا لا يعلم أن لهارون سماعا منه أم لا، غير ما تحتمله معاصرته وهو احتمال محض، وإن كان الثالث فهو حافظ‍ ثقة يروي كثيرا عن الإمام أبي حنيفة، كما قاله الحافظ‍ الخوارزمي في (جامع المسانيد)، وهو من كبار شيوخ البخاري ومسلم، ولم يرو أحدهما منه نفسه أن الإمام كان يقول بخلق القرآن؛ فإذا كان أبو نعيم هذا يروي عن الإمام، وكان البخاري ومسلم يرويان عنه فيبعد أن يروي عن سليمان وهو يروي عن سفيان ولا يروي عن الإمام نفسه، وأن يروي عنه البخاري بالواسطة ولا يروي عنه نفسه، وأيضا ليس لهارون سماع معروف من أبي نعيم هذا غير ما تحتمله المعاصرة.\rوأما أبو نعيم عن سليمان بن عيسى القاري عن سفيان الثوري؛ فسليمان"], [320, "اثنان: أحدهما: ابن عيسى بن نجيح السجزي، وثانيهما: ابن عيسى بن موسى، فالثاني ثقة ذكره ابن حبان في (الثقات) (1) فقال: سليمان بن عيسى يروي عن جده موسى بن طلحة عن علي روى عنه يحيى بن سعيد الأموي، والأول مقدوح مجروح، قال الذهبي: سليمان بن عيسى بن نجيح السجزي عن ابن عون وغيره: هالك، قال الجوزجاني: كذاب مصرح، وقال أبو حاتم: كذاب، وقال ابن عدي: يضع الحديث (2)؛ فهذا متفق على جرحه بأردأ ما يكون.\rهذا أبو حاتم بن حبان يكذبه؛ فما علم أن سليمان الواقع في هذه الرواية أي سليمان، وأيّا من كان فما يعرف لأبي نعيم سواء كان عبد الرحمن بن هانئ أو ضرار بن صرد أو فضل بن دكين سماع منه.\rوأما سماع سليمان من سفيان فيعلم مما ذكره الذهبي أن لسليمان بن عيسى بن نجيح سماعا من سفيان، قال الذهبي في ترجمته (3): وله عن سفيان عن منصور عن إبراهيم عن علقمة فساق حديثه، وأما سليمان بن عيسى بن موسى الثقة فما عرف له السماع من سفيان، فإن كان سليمان هذا ذاك الهالك الواضع فردّه ظاهر، وإن كان ذاك الثقة فهو في منتهى السند، والمنتهى موقوف على المبدأ، ومبدأ السند قد علمت حاله.\rوأما سفيان الثوري القائل: إنه قال لي حماد بن أبي سليمان: بلغ أبا حنيفة المشرك أني منه بريء؛ فهو وإن كان ثقة ثبتا حجة إلا أن قدحه في الإمام وسوء قوله فيه لا يقبل أصلا؛ لأنه من معاصري الإمام وأقرانه، وقدح الأقران والمعاصرين بعضهم بعضا لا يقبل، صرح بذلك غير واحد من الأئمة منهم:\r__________\r(1) الثقات لابن حبان (394/ 6).\r(2) ميزان الاعتدال (218/ 2).\r(3) ميزان الاعتدال (218/ 2 - 219)."], [321, "التاج السبكي في طبقاته الكبرى فإنه صرح فيها أنه لا يقبل كلام الثوري وغيره في أبي حنيفة ولا يلتفت إليه، وهذا كلام على وضع المقام؛ لأن المقام مقام البحث عن السند وإلا فالثوري ثبت عنه التزكية البليغة للإمام، وهو ينقض هذه الرواية ويهدم بنيانها، وقد ذكرناه فارجع وتذكر.\rوهاهنا أعجوبة أخرى وهي أن حماد بن أبي سليمان القائل لسفيان: بلغ أبا حنيفة هو شيخ إمامنا أبي حنيفة النعمان، وقد ثبت ما يدل على غاية الموافقة الدائمة ونهاية المؤانسة المستمرة بينهما.\rقال الحافظ‍ محمد بن محمود الخوارزمي في (جامع المسانيد) للإمام الأعظم في ذكر حماد بن أبي سليمان: هو أستاذ أبي حنيفة رضي الله عنه لزمه إلى آخر عمره وأخذ عنه الفقه، وقال علي الهروي العالي المقام في شرح مسند الإمام: وكان - أي حماد - يقول: ربما اتهمت رأيي برأي أبي حنيفة وأقول بقوله، وفي نسخة: انتهت آرائي برأي أبي حنيفة وأقوالي بقوله؛ فهذا غاية موافقة منه مع الإمام، ونهاية محبة منه له، وفي هذه الرواية ما يدل على غاية المنافرة بينهما، والموافقة بينهما هي المعروف المشهور المعلوم عندهم، ولو كانت بينهما منافرة ولو بغير الوجه المذكور في هذه الرواية لعرفت ولرويت، وقد ذكر الذهبي حمادا هذا في (ميزان الاعتدال) (1) و قال: روى عنه سفيان وشعبة وأبو حنيفة وخلق.\rوالدولابي في (الكنى) فقال في ذكر من كنيته أبو إسماعيل: حماد بن أبي سليمان الفقيه أستاذ أبي حنيفة الفقيه، وحماد بن زيد البصري، وحماد بن عمر النصيبي، وحماد بن نافع - إلى آخر ما قال وما ذكر، أما يوجد منه منافرتهما مع أن المنافرة الواقعة بين الأستاذ والتلميذ تذكر في موضع يذكر أحدهما وينسب بتلمذه\r__________\r(1) ميزان الاعتدال (595/ 1)."], [322, "وأخذه إلى الآخر إن كان المذكور آخذا وتلميذا لغير المذكور؛ أو بمشيخة له إن كان المذكور شيخا لغير المذكور لأن هذه النسبة يذكرونها لشهرتها المشعرة للارتباط‍ بين المشاهير؛ فإذا كانت المنافرة التي هي مضادة للازم من هذه النسبة واقعة مستقرة - كما هي مقتضى هذه الرواية - صارت مقابلة للشهرة الحاصلة من تلك النسبة ومساوية لها، فذكروها وما تركوها، إذا لم يذكروا المنافرة بقيت هذه النسبة على أصلها، والأصل فيها هو إشعارها بالموافقة والمرافقة والمحبة والمؤانسة ثم هذا السند أتى من مبدئه إلى مختتمه على أضعف صيغ الأداء المحتمل للسماع وغيره وهو ذكر (وعن) كما ذكره الحافظ‍ ابن حجر في (نخبة الفكر في مصطلحات أهل الحديث والأثر) هذا خلاصة الكلام في سند الرواية الأولى من روايات الإبانة.\rوأما الرواية الثانية - وهي ذكر سفيان بن وكيع قال: سمعت عمر بن حماد بن أبي حنيفة إلخ، فمدارها على سفيان بن وكيع، وهو ليس بمعاصر للأشعري لأنه مات سنة سبع وأربعين ومائتين ذكره الذهبي عن ابن حبان - ففيه الانقطاع أيضا؛ فلا يدرى من هو بين الأشعري وبين سفيان بن وكيع؛ فالرواية ساقطة مردودة، وهكذا الرواية الثالثة وهي ذكر هارون بن إسحاق قال: سمعت إسماعيل بن أبي الحكم يذكر إلخ.\rوأما الرواية الرابعة وهي: ذكر عن أبي يوسف قال: ناظرت إلخ ففيه الانقطاع الكامل الموجب للرد والإسقاط‍؛ لأنه حذف السند من الأشعري إلى أبي يوسف كله.\rوأما سفيان بن وكيع وهو سفيان بن وكيع بن الجراح أبو محمد الرواسي، قال الذهبي: قال البخاري: يتكلمون فيه لأشياء لقنوه إياها، وقال أبو زرعة: يتهم بالكذب، وقال ابن أبي حاتم: أشار أبي عليه أن يغير ورّاقه فإنه أفسد حديثه،"], [323, "وقال له: لا تحدث إلا من أصولك، فقال: سأفعل ثم تمادى وحدث بأحاديث أدخلت عليه، وقد ساق له أبو أحمد خمسة أحاديث منكرة السند لا المتن، ثم قال: وله حديث كثير، وإنما بلاؤه أنه كان يتلقن يقال: كان له ورّاق يلقنه من حديث موقوف فيرفعه أو مرسل يوصله أو يبدل رجلا برجل، وقال ابن حبان: مات سنة سبع وأربعين ومائتين، وكان شيخا فاضلا صدوقا إلا أنه ابتلي بوراق سوء كان يدخل عليه فكلّم في ذلك فلم يرجع.\rقلت: وتلقنه أيضا يوجب سقوط‍ رواية هذا.\rثم العجب أن والده وكيع بن الجراح يتبع أبا حنيفة ويعتقده وهو يروي في أبي حنيفة خلاف ما كان يعتقد فيه أبوه؛ فإن الأقرب في الأبناء أن يعتمدوا على آبائهم ويبطلوا ما كان خلاف أقوالهم ومعتقداتهم؛ فبعيد من سفيان أن يروي هذا ولا يعتمد على ما كان يعتقد أبوه في الإمام مع أنه يروي عن أبيه، كما ذكره الحافظ‍ ابن حجر في (تهذيب التهذيب) (1) اللهم إلا أن يكون هذا من ملقنه السوء، وأما عمر بن حماد بن أبي حنيفة فذكره العلامة القرشي في (الجواهر المضية في طبقات الحنفية) فقال: عمر بن حماد بن أبي حنيفة روى عن أخيه إسماعيل قوله: أنا إسماعيل بن حماد بن أبي حنيفة ثم قال: تفقه على أبيه حماد.\rقلت: يبعد غاية البعد أن يروي عمر عن أبيه هكذا ولا يرويه عنه أخوه إسماعيل - رحمهما الله تعالى - فإن إسماعيل رحمه الله تعالى من كبار الفقهاء ومشاهيرهم روى عنه كثير من الأعيان، فعدم رواية إسماعيل لهذه الرواية بل عدم وجدان شمة من معناها فيما نقلوا عنه يوضح أن هذه الرواية موضوعة على عمر - قبح الله واضعها - كيف وقد ثبت عن عمر بن حماد بن أبي حنيفة ما\r__________\r(1) تهذيب التهذيب (109/ 4)."], [324, "يناقض هذه الرواية المروية عنه نقضا ظاهرا.\rقال في (مفتاح السعادة) في المطلب الرابع الذي بين فيه مذهب الإمام في أصول الدين: قال عمر بن حماد بن أبي حنيفة - رحمهم الله: أقمت عند مالك مدة فلما أردت الرجوع قلت: لعل بعض الحساد ذكروا جدي عندك على خلاف ما كان عليه فأذكر لك مذهبه فإن رضيت فذاك وإلا فعظني، قلت: كان لا يخرج أحدا من الإيمان بذنب، قال: أصاب، قلت: وإن أصاب الفواحش، قال: أصاب، قلت: وكان لا يكفر قاتل النفس، قال: أصاب فمن قال غير هذا فقد أخطأ.\rقال: بلغني أنه كان يقول: إيماني مثل إيمان جبرئيل، قلت: بلغك الباطل، كان يقول: إن الله تعالى بعث جبرئيل إلى النبي صلّى الله عليه وسلّم كما بعثه إلى من قبله؛ فأمره أن يدعو الناس إلى الإيمان إيمان واحد لا إيمانان أو ثلاثة، ولا إيمان هذا وإقرار هذا غير إيمان هذا وإقرار ذا، فتبسم كالراضي به ولم يقل شيئا، قلت: وكان ينكر الشك في الإيمان، قال: وما الشك فيه؟ قلت: عندنا أقوام لا يقولون: أنا مؤمن حتى يستثني إيمانه أو يقول أحدهم: لا أدري أنا مؤمن أم لا، فأنكره وقال: من يقول هذا - انتهى.\rفذب عمر بن حماد رضي الله تعالى عنه عن جده، وبيّن ما كان عليه من الطريقة المستقيمة في الدين، وذكر في سبب بيان مذهبه لمالك رضي الله تعالى عنه أنه لعل بعض الحساد ذكروا جدي عندك على خلاف ما كان عليه؛ فأذكر لك مذهبه؛ فإن كان الحساد اتهموا الإمام بعقيدة الخلق وافتروها عليه لذكرها ألبتة وما تركها قط‍، ولما لم يذكر أن الإمام كان قائلا بالخلق، والموضع موضع ذكر كل ما نسب إلى الإمام وهو بريء منه أو طعن فيه بسببه ولا يعود عليه الطعن بسببه بل هو الحق والصواب وخلافه الخطأ والانحراف - ظهر أن هذه العقيدة ما اتهمه بها الحساد أيضا ما وجدوا مجالا لاتهامه بها وافترائها عليه لكونه مشهورا"], [325, "معروفا بخلافها؛ أفيكون للاستتابة المروية عن عمر المذكورة في (الإبانة) قرار بعد هذه الرواية المذكورة في (مفتاح السعادة).\rوأما ابن أبي ليلى الذي ذكر في هذه الرواية أنه استتاب الإمام في قوله بالخلق فهو ممن يقع في الإمام تارة ويمدحه أخرى - قاله الحافظ‍ الخوارزمي في (مسنده)، فوسع حسده للإمام مجالا للواضعين فوضعوا الرواية منسوبة إليه.\rوأما إسماعيل بن أبي الحكم الواقع في الرواية الثالثة فلا يعرف؛ فإن ابن حبان ذكر إسماعيل بن أبي حكيم الراوي عن سعيد بن المسيب روى عنه مالك وابن إسحاق؛ قال ابن حبان: هو مولى عثمان بن عفان عداده في أهل المدينة، وقيل:\rهو مولى لآل الزبير يروي عن سعيد بن المسيب روى عنه مالك وابن إسحاق مات سنة ثلاثين ومائة بالمدينة، وليس فيه إسماعيل بن أبي الحكم، وذكره الحافظ‍ ابن حجر في (تهذيب التهذيب) (1).\rوذكر الذهبي في (ميزانه) (2) في ذكر من عرف بأبيه: فقال ابن أبي الحكم الغفاري عن جدته عن عم أبيها رافع قال: كنت غلاما أرمي نخل الأنصار لا يكاد يعرف، روى عنه معتمر بن سليمان فما علم اسم ابن أبي الحكم هذا الذي ذكره الذهبي؛ فجهل إسماعيل بن أبي الحكم الواقع في هذه الرواية.\rوأما عمر بن عبيد الطنافسي فذكره ابن حبان في (ثقاته) (3)، والعلامة القرشي في (طبقات الحنفية)، قال ابن حبان: عمر بن عبيد الطنافسي الحنفي من أهل الكوفة كنيته أبو حفص، يروي عن أبي إسحاق السبيعي وسماك بن حرب، روى عنه\r__________\r(1) تهذيب التهذيب (253/ 1).\r(2) ميزان الاعتدال (591/ 4).\r(3) الثقات لابن حبان (189/ 7)."], [326, "إسحاق بن إبراهيم الحنظلي وأهل العراق، مات سنة سبع وثمانين ومائة، وقال القرشي: وله أخ اسمه محمد بن عبيد وثقهما الدارقطني، ووثقه الذهبي في (ميزانه) (1) فقال في ذكر عمر بن عبيد الخزاز: أما عمر بن عبيد الله الطنافسي فثقة لا جرح فيه.\rقلت: لم يذكر هذا عن عمر بن عبيد واحد من الثلاثة المذكورين لا ابن حبان ولا القرشي ولا الذهبي، ولو كان هذا روي عنه لذكره هؤلاء الثلاثة وما خفي عليهم؛ خصوصا الأول والثالث؛ فإنهما محدثان متيقظان ومع ذلك فليسا حنفيين، ولعمري الكذب واضح على هذه الرواية فإن عمر بن عبيد حنفي أفيتصور منه أن يقلد أبا حنيفة ويتبعه مع علمه بعقيدته التي موجبها الترك والهجران، ففي السند انقطاع وجهالة وظلمة.\rوأما الرواية الرابعة وهي: ذكر عن أبي يوسف إلخ فمر أن فيه انقطاع تام فهي مردودة، مع أنه روى الثقات عن أبي يوسف ما يناقضه ويخالفه - وقد مر - وبالجملة الروايات كلها قد حوتها الظلمة في سندها ومتنها وأحاطتها الغرابة والنكارة؛ فهي مردودة مجهولة منقطعة ساقطة مظلمة.\rوإذا تكلمنا في إسناد الروايات الواقعة في (الإبانة) فنتكلم الآن في الرواية الواقعة في خلق أفعال العباد للبخاري بتقدير أن لا يكون فيها الإبهام، وإلا فعلى ما وجدناها مبهمة فلا يوجه إليه البحث للجهالة الواقعة فيها فنقول أولا: إن هذه الرواية ليست مسندة عن البخاري بل التعويل فيها على أحمد بن الحسن فإن كان أحمد بن الحسن هذا هو الذي ذكره ابن حبان في كتاب (الثقات) (2) فقال:\rأحمد بن الحسن بن جندب (3) الترمذي صاحب أحمد بن حنبل يروي عن يزيد بن\r__________\r(1) ميزان الاعتدال (213/ 3).\r(2) الثقات لابن حبان (27/ 8).\r(3) في الثقات، وتهذيب التهذيب: «جنيدب»."], [327, "هارون ثنا عنه الحسن بن سفيان ومحمد بن إسحاق بن خزيمة وغيرهما، والحافظ‍ ابن حجر في (تهذيب التهذيب) (1) و صفي الدين في (خلاصة التهذيب) وقالا: روى عنه البخاري والترمذي فهو الذي ذكره الحافظ‍ الخوارزمي في رد مطاعن الخطيب ناقلا عن الخطيب.\rفقال: وأما قوله حاكيا عن أحمد بن الحسن الترمذي أنه قال: رأيت رسول الله صلّى الله عليه وسلّم في المنام فقلت له: يا رسول الله صلّى الله عليه وسلّم ما ترى ما فيه الناس من الاختلاف؟ قال: «في أي شيء»؟ قلت: فيما بين أبي حنيفة ومالك والشافعي، فقال: «أما أبو حنيفة فلا أعرفه وأما مالك فكتب العلم وأما الشافعي فمني إلي» والجواب عنه من وجهين: أحدهما: أن في متنه ما يدل على وهنه وكذبه؛ لأنه صح في الحديث أنه يعرض على رسول الله صلّى الله عليه وسلّم أعمال أمته يوم الإثنين والخميس، فكيف لا يعرفه وإنه عليه السّلام يعرف كل بر وفاجر بعرض أعماله عليه، فكيف لا يعرف أبا حنيفة وأعمال أكثر أمته على مذهبه - إلى آخر ما قال.\rفأحمد بن الحسن هذا من الطاعنين في الإمام فلا يعتمد على روايته التي موجبها الجرح في الإمام، ثم لو كان أحمد بن الحسن هذا يروي ذلك بسنده لذكره الخطيب ألبتة، كيف وقد حكي عنه ما يوجب الطعن في الإمام، وإذا ظهر من أحمد بن الحسن رؤياه الموجبة لطعنه فيظهرها بالضرورة لأنهما يشتركان في الطعن، لا سيما إذا اطلع عليها البخاري فلا يتصور قط‍ أن يخفى مثل هذه الرواية على الخطيب، وهذا من أقوى الأدلة على كذب الرواية، وعلى أنه ما ذكرها البخاري في (كتاب خلق الأفعال).\rوأيضا لا يجيء من مثل أحمد بن الحسن المتكلم بما يوجب الطعن في الإمام\r__________\r(1) تهذيب التهذيب (21/ 1)."], [328, "بعد أن ثبت عنده من رؤياه الطعن في الإمام أن يبهم، وأما سماعه من أبي نعيم فما عرف، ومع كل ذلك فيبعد من البخاري بعد كونه يروي عن أحمد بن الحسن هذا أن لا يروي عنه بصيغة التحديث بل يروي عنه بصيغة تحتمل السماعي وغيره، وإن كان غيره فإما أن يكون أحمد بن الحسن بن خراش الخراساني البغدادي ذكره في (التهذيب) (1) و (خلاصة تذهيب التهذيب)، وقال في (خلاصة التذهيب): إنه يروى عن أبي نعيم وطبقته وثقه الخطيب مات سنة اثنتين وأربعين ومائتين عن ستين سنة إلا عشرين يوما، وقال ابن حجر في (تهذيب التهذيب) قلت: وذكره ابن حبان في الثقات.\rأقول: ليس أحمد بن الحسن هذا من رجال البخاري في شيء من كتبه بل روى عن مسلم والترمذي كما هو في (تهذيب التهذيب) و (خلاصة التذهيب) فلا اعتبار بروايته إن كان أحمد بن الحسن الواقع في خلق الأفعال هو لا سيما إذا نقل عنه البخاري بصيغة ضعيفة محتملة للسماع وغيره، وهو لفظ‍: قال، وإما أن يكون غيره، وليس لغيرهما ذكر في الكتب المصنفة في الرجال.\rوأما الكلام فيمن وقع بعد أحمد بن الحسن إلى سفيان فقد سبق الكلام فيهم، ولم يقع أحمد بن الحسن في غير هذا الموضع من كتاب خلق الأفعال ثم هذه الروايات كلها معارضة بالروايات الصحيحة التي رواتها ثقات وبلغت التواتر - وقد مر ذكرها - فتكون مردودة لأن هذه الروايات واهيات ساقطات منقطعات فلا تصلح لأن تعارض تلك الروايات المحكمات الصحيحات المتصلات؛ لأن القوي لا تؤثر فيه مخالفة الضعيف قاله الحافظ‍ ابن حجر في (شرح نخبة الفكر في مصطلح أهل الأثر) في بحث المقبول من الخبر إذا عورض؛ فإذا كان الضعيف\r__________\r(1) تهذيب التهذيب (21/ 1)."], [329, "الذي له أصل لا يؤثر في القوى ولا يعارضه فما ظنك بهذه الروايات التي آثار الوضع عليها لائحة وأمارات الافتراء فيها واضحة، فالحمد لله الذي أبان الحق ودمغ الباطل، فجاء الحق وزهق الباطل إن الباطل كان زهوقا."]], "pg": [273, 329]}}, "units": {"2": {"tit": "كتاب الإبانة عن أصول الديانة", "lvl": 1, "pg": [135, 141]}, "7": {"tit": "باب في إبانة قول أهل الزيغ والبدعة", "lvl": 2, "pg": [141, 144]}, "10": {"tit": "باب في إبانة قول أهل الحق والسنة", "lvl": 2, "pg": [144, 150]}, "16": {"tit": "باب الكلام في إثبات رؤية الله تعالى بالأبصار في الآخرة", "lvl": 2, "pg": [150, 159]}, "25": {"tit": "باب في الرؤية", "lvl": 2, "pg": [159, 163]}, "29": {"tit": "باب الكلام في أن القرآن كلام الله غير مخلوق", "lvl": 2, "pg": [163, 165]}, "31": {"tit": "فصل: الجهينة", "lvl": 3, "pg": [165, 166]}, "32": {"tit": "فصل قول الجهمية: إن كلام الله مخلوق", "lvl": 3, "pg": [166, 171]}, "37": {"tit": "الرد على الجهمية", "lvl": 4, "pg": [171, 172]}, "38": {"tit": "الرد على الجهمية", "lvl": 4, "pg": [172, 174]}, "40": {"tit": "باب ما ذكر من الرواية في القرآن", "lvl": 2, "pg": [174, 180]}, "46": {"tit": "باب الكلام على من وقف في القرآن وقال: لا أقول إنه مخلوق ولا أقول إنه غير مخلوق", "lvl": 2, "pg": [180, 183]}, "49": {"tit": "باب ذكر الاستواء على العرش", "lvl": 2, "pg": [183, 189]}, "55": {"tit": "باب الكلام في الوجه والعينين والبصر واليدين", "lvl": 2, "pg": [189, 196]}, "62": {"tit": "باب الرد على الجهمية في نفيهم علم الله تعالى وقدرته وجميع صفاته", "lvl": 2, "pg": [196, 203]}, "69": {"tit": "باب الكلام في الإرادة", "lvl": 2, "pg": [203, 210]}, "76": {"tit": "باب الكلام في تقدير أعمال العباد والاستطاعة والتعديل والتجوير", "lvl": 2, "pg": [210, 212]}, "78": {"tit": "مسألة في الاستطاعة", "lvl": 2, "pg": [212, 216]}, "82": {"tit": "مسألة في التكليف", "lvl": 2, "pg": [216, 217]}, "83": {"tit": "مسألة في إيلام الأطفال", "lvl": 2, "pg": [217, 219]}, "85": {"tit": "الرد على المعتزلة", "lvl": 2, "pg": [219, 220]}, "86": {"tit": "مسألة في الختم", "lvl": 2, "pg": [220, 222]}, "88": {"tit": "مسألة في الاستثناء", "lvl": 2, "pg": [222, 223]}, "89": {"tit": "مسألة في الآجال", "lvl": 2, "pg": [223, 224]}, "90": {"tit": "مسألة في الأرزاق", "lvl": 2, "pg": [224, 225]}, "91": {"tit": "مسألة أخرى في الأرزاق", "lvl": 2, "pg": [225, 227]}, "93": {"tit": "مسألة في الهدى", "lvl": 2, "pg": [227, 229]}, "95": {"tit": "مسألة في الضلال", "lvl": 2, "pg": [229, 234]}, "100": {"tit": "باب ذكر الروايات في القدر", "lvl": 2, "pg": [234, 241]}, "107": {"tit": "باب الكلام في الشفاعة والخروج من النار", "lvl": 2, "pg": [241, 242]}, "108": {"tit": "باب الكلام في الحوض", "lvl": 2, "pg": [242, 243]}, "109": {"tit": "باب الكلام في عذاب القبر", "lvl": 2, "pg": [243, 245]}, "111": {"tit": "باب الكلام في إمامة أبي بكر الصديق رضي الله عنه", "lvl": 2, "pg": [245, 249]}, "115": {"tit": "الملحق الأول والثاني للإبانة", "lvl": 1, "pg": [249, 251]}, "116": {"tit": "الملحق الأول للإبانة", "lvl": 2, "pg": [251, 272]}, "137": {"tit": "تنبيهات", "lvl": 3, "pg": [272, 273]}, "138": {"tit": "الملحق الثاني للإبانة", "lvl": 2, "pg": [273, 329]}}};
